INSERT INTO public.bd VALUES (298, 'Toriko', '1', 'Toriko, chasseur de saveurs!!', 'Shimabukuro, Mitsutoshi', '9782820301987', '07/2011', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_144505.jpg', NULL);
INSERT INTO public.bd VALUES (299, 'Toriko', '2', 'Tome 2', 'Shimabukuro, Mitsutoshi', '9782820302311', '11/2011 (Parution le 10/11/2011)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_144510.jpg', 'Une fois tous les dix ans, les “fugu-baleines”, de mystérieuses créatures possédant une poche venimeuse, se rendent dans les hauts-fonds afin d’y frayer. Pour mettre la main sur ces “délices des profondeurs”, Toriko, accompagné de Komatsu, décide de faire appel à un autre des quatre légendaires Gourmet Hunters : Coco, l’une des seules personnes sur Terre capable de préparer les fugu-baleines sans mourir empoisonné.');
INSERT INTO public.bd VALUES (300, 'Toriko', '3', 'Tome 3', 'Shimabukuro, Mitsutoshi', '9782820302731', '01/2012 (Parution le 25/01/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_152614.jpg', 'Grâce au talent de Komatsu, nos chasseurs de saveurs finissent par se délecter des fugu-baleines ! Mais alors qu''ils profitent tranquillement de leur pêche, une chose terrifiante remonte à la surface de la plage de sable souterraine. Une chose à laquelle même deux des Quatre Rois ne sont pas préparés. À l''extérieur de la grotte, la paix et l''ordre de la Gastronomie sont menacés par l''organisation ennemie de l''OIG : la terrible Gourmet Corp…');
INSERT INTO public.bd VALUES (301, 'Toriko', '4', 'Tome 4', 'Shimabukuro, Mitsutoshi', '2820303110', '03/2012 (Parution le 14/03/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_155582.jpg', NULL);
INSERT INTO public.bd VALUES (302, 'Toriko', '5', 'Tome 5', 'Shimabukuro, Mitsutoshi', '9782820303684', '05/2012 (Parution le 09/05/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_162908.jpg', NULL);
INSERT INTO public.bd VALUES (303, 'Toriko', '6', 'Tome 6', 'Shimabukuro, Mitsutoshi', '2820303994', '07/2012 (Parution le 04/07/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_165919.jpg', NULL);
INSERT INTO public.bd VALUES (445, 'Slam Dunk', '28', 'Tome 28', 'Inoue, Takehiko', '2871296278', '06/2004 (Parution le 19/06/2004)', 192, 'https://www.bedetheque.com/media/Couvertures/SlamDunk28_18062004.jpg', 'L''équipe de Sannô creuse l''écart. L''entraîneur de Shôhoku, Mr Anzai est-il le seul à encore croire à une victoire possible. Non ! Il réussit à convaincre Sakuragi qui lance fièrement: "Je vais battre Sanaô!" Les dés sont jetés et tous les participants sont dans l''arène.');
INSERT INTO public.bd VALUES (304, 'Toriko', '7', 'Tome 7', 'Shimabukuro, Mitsutoshi', '9782820304742', '09/2012 (Parution le 05/09/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_170523.jpg', 'Grâce au talent de Komatsu, nos chasseurs de saveurs finissent par se délecter des fugu-baleines ! Mais alors qu’ils profitent tranquillement de leur pêche, une chose terrifiante remonte à la surface de la plage de sable souterraine. Une chose à laquelle même deux des Quatre Rois ne sont pas préparés. À l’extérieur de la grotte, la paix et l’ordre de la Gastronomie sont menacés par l’organisation ennemie de l’OIG : la terrible Gourmet Corp…');
INSERT INTO public.bd VALUES (305, 'Toriko', '8', 'Century soup !!', 'Shimabukuro, Mitsutoshi', '9782820305305', '11/2012 (Parution le 07/11/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_175872.jpg', NULL);
