INSERT INTO public.bd VALUES (437, 'Slam Dunk', '20', 'Tome 20', 'Inoue, Takehiko', '2871294445', '01/2003', 192, 'https://www.bedetheque.com/media/Couvertures/slamdunk20pg_17122003.jpg', NULL);
INSERT INTO public.bd VALUES (438, 'Slam Dunk', '21', 'Tome 21', 'Inoue, Takehiko', '2871295050', '03/2003', 192, 'https://www.bedetheque.com/media/Couvertures/slamdunk21pg_17122003.jpg', NULL);
INSERT INTO public.bd VALUES (439, 'Slam Dunk', '22', 'Tome 22', 'Inoue, Takehiko', '2871295204', '05/2003', 192, 'https://www.bedetheque.com/media/Couvertures/slamdunk22_25042003.jpg', NULL);
INSERT INTO public.bd VALUES (440, 'Slam Dunk', '23', 'Tome 23', 'Inoue, Takehiko', '287129531X', NULL, 184, 'https://www.bedetheque.com/media/Couvertures/slamdunk23pg_17122003.jpg', NULL);
INSERT INTO public.bd VALUES (441, 'Slam Dunk', '24', 'Tome 24', 'Inoue, Takehiko', '2871295492', NULL, 181, 'https://www.bedetheque.com/media/Couvertures/Slamdunk24_30112003.jpg', NULL);
INSERT INTO public.bd VALUES (442, 'Slam Dunk', '25', 'Tome 25', 'Inoue, Takehiko', '287129559X', NULL, 192, 'https://www.bedetheque.com/media/Couvertures/slamdunk25pg_17122003.jpg', NULL);
INSERT INTO public.bd VALUES (443, 'Slam Dunk', '26', 'Tome 26', 'Inoue, Takehiko', '2871296049', '01/2004 (Parution le 07/02/2004)', 192, 'https://www.bedetheque.com/media/Couvertures/SlamDunk26_03042004.jpg', 'Lors du 1er tour du tournoi interdépartemental, Shôhoku parvient à vaincre l''équipe de Toyotama, la meilleure du département d''Osaka. Elle doit ensuite affronter, dès le 2nd tour, la meilleure équipe lycéenne du Japon, celle du lycée technique Sannô. D''entrée de jeu, le duo Miyagi-Hanamichi épate le public par une offensive fulgurante qui se conclut par un alley oop !!');
INSERT INTO public.bd VALUES (444, 'Slam Dunk', '27', 'Tome 27', 'Inoue, Takehiko', '2871295417', '04/2004 (Parution le 17/04/2004)', 192, 'https://www.bedetheque.com/media/Couvertures/SlamDunk27_16042004.jpg', 'Shôhoku est en plein match contre la redoutable équipe de Sannô. Grâce en partie, au formidable duo Miyagi-Hanamichi qui épate le public, Shôhoku prend le match à son compte en concluant la première mi-temps par une avance de deux points. Tout se jouera donc durant la seconde période.');
INSERT INTO public.bd VALUES (495, 'Captain Tsubasa / Olive & Tom', '26', 'Les Joueurs pros !', 'Takahashi, Yôichi', '2290313335', '10/2001', 189, 'https://www.bedetheque.com/media/Couvertures/captain26r_38613.jpg', NULL);
INSERT INTO public.bd VALUES (446, 'Slam Dunk', '29', 'Tome 29', 'Inoue, Takehiko', '2871296375', '08/2004 (Parution le 28/08/2004)', 192, 'https://www.bedetheque.com/media/Couvertures/SlamDunk29_28082004.jpg', '2e mi-temps de la finale du grand tournoi interlycée de basket-ball. Les chiffres sont là, lycée technique Sannô : 63 et Shôhoku : 53. Sawakita, le champion de Sannô s''apprête à lancer sa contre-offensive... Il ne lâchera pas Rukawa !! Les épaules des joueurs de Shôhoku se font de plus en plus lourdes...');
INSERT INTO public.bd VALUES (447, 'Slam Dunk', '30', 'Tome 30', 'Inoue, Takehiko', '2871296499', '10/2004', 189, 'https://www.bedetheque.com/media/Couvertures/SlamDunk30_01102004.jpg', NULL);
INSERT INTO public.bd VALUES (448, 'Slam Dunk', '31', 'Tome 31', 'Inoue, Takehiko', '287129660X', '12/2004', 179, 'https://www.bedetheque.com/media/Couvertures/SlamDunk31_04122004.jpg', NULL);
INSERT INTO public.bd VALUES (449, 'Slam Dunk', 'HS', 'Slam Dunk Illustrations 2 plus', 'Inoue, Takehiko', '9782505088011', '11/2020 (Parution le 06/11/2020)', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_407950.jpg', 'Cet ouvrage au format atypique, presque carré, propose pas moins de 130 illustrations à travers 96 pages. Parmi les visuels utilisés, tous ceux ayant servi aux 38 tomes de l''édition simple, aux 24 tomes de l''édition deluxe (inédite en France), et aux 20 tomes de la réédition... sans compter plusieurs illustrations inédites.');
INSERT INTO public.bd VALUES (450, 'Slam Dunk', 'INT01', 'Tome 1', 'Inoue, Takehiko', '9782505076506', '03/2019 (Parution le 01/03/2019)', 304, 'https://www.bedetheque.com/media/Couvertures/Couv_361578.jpg', 'Au collège, Hanamichi Sakuragi s''est fait jeter par 50 filles. Il est ensuite entré au lycée, mais il est resté sous le choc du refus de la 50ème fille qui lui a répondu : "Je suis amoureuse d''Oda du club de basket. " C''est alors qu''est apparue l''âme salvatrice : Haruko Akagi. Il a suffit que, dans le couloir de l''école, elle lui demande : "Tu aimes le basket ? " pour que son coeur s''enflamme. Les choses ne sont malheureusement pas si simples puisqu''elle est amoureuse d''un garçon qui ne le sait pas : Kaede Rukawa. Ce garçon, véritable as du basket-ball,...');
INSERT INTO public.bd VALUES (451, 'Slam Dunk', 'INT02', 'Tome 2', 'Inoue, Takehiko', '9782505076513', '03/2019 (Parution le 01/03/2019)', 304, 'https://www.bedetheque.com/media/Couvertures/Couv_361579.jpg', 'Le défi de sélection réussi, Hanamichi Sakuragi a intégré le club de basket et se pense en bon chemin pour gagner les faveurs de Haruko, même s’il est cantonné à répéter des exercices de base et même si Kaede Rukawa l’énerve prodigieusement.');
INSERT INTO public.bd VALUES (452, 'Slam Dunk', 'INT03', 'Tome 3', 'Inoue, Takehiko', '9782505076520', '07/2019 (Parution le 05/07/2019)', 272, 'https://www.bedetheque.com/media/Couvertures/Couv_370520.jpg', 'Sakuragi se lance dans le basket-ball ! Même si au départ, il le fait pour épater la belle Haruko, il va se prendre au jeu et découvrir que se dépasser est la plus belle des motivations !');
INSERT INTO public.bd VALUES (453, 'Slam Dunk', 'INT04', 'Tome 4', 'Inoue, Takehiko', '9782505076537', '07/2019 (Parution le 05/07/2019)', 272, 'https://www.bedetheque.com/media/Couvertures/Couv_370521.jpg', NULL);
INSERT INTO public.bd VALUES (454, 'Slam Dunk', 'INT05', 'Tome 5', 'Inoue, Takehiko', '9782505076544', '11/2019 (Parution le 15/11/2019)', 272, 'https://www.bedetheque.com/media/Couvertures/Couv_379576.jpg', NULL);
INSERT INTO public.bd VALUES (455, 'Slam Dunk', 'INT06', 'Tome 6', 'Inoue, Takehiko', '9782505076551', '11/2019 (Parution le 15/11/2019)', 272, 'https://www.bedetheque.com/media/Couvertures/Couv_379577.jpg', 'Hisashi Mitsui débarque au club de basket. Il s''avère être un ancien membre. Entré au lycée Shôhoku plein d''espoir, il avait abandonné !!');
INSERT INTO public.bd VALUES (456, 'Slam Dunk', 'INT07', 'Tome 7', 'Inoue, Takehiko', '9782505078487', '01/2020 (Parution le 31/01/2020)', 368, 'https://www.bedetheque.com/media/Couvertures/Couv_384610.jpg', 'Voici enfin de retour, dans une toute nouvelle édition, les aventures de Sakuragi qui se lance dans le basket-ball ! Même si au départ, il le fait pour épater la belle Haruko, il va se prendre au jeu et découvrir que se dépasser est la plus belle des motivations ! Slam dunk est devenue la référence ultime du manga de basket-ball pour ne pas dire la référence du manga de sport ! Parfait mélange d''action, d''humour, de romance, de rivalités dans un contexte sportif, jamais lourd, le tout servi par un dessin sublime de Takehiko Inoue. Cette édition...');
INSERT INTO public.bd VALUES (457, 'Slam Dunk', 'INT08', 'Tome 8', 'Inoue, Takehiko', '9782505078494', '01/2020 (Parution le 31/01/2020)', 352, 'https://www.bedetheque.com/media/Couvertures/Couv_384611.jpg', 'Voici enfin de retour, dans une toute nouvelle édition, les aventures de Sakuragi qui se lance dans le basket-ball ! Même si au départ, il le fait pour épater la belle Haruko, il va se prendre au jeu et découvrir que se dépasser est la plus belle des motivations ! Slam dunk est devenue la référence ultime du manga de basket-ball pour ne pas dire la référence du manga de sport ! Parfait mélange d''action, d''humour, de romance, de rivalités dans un contexte sportif, jamais lourd, le tout servi par un dessin sublime de Takehiko Inoue. Cette édition...');
INSERT INTO public.bd VALUES (458, 'Slam Dunk', 'INT09', 'Tome 9', 'Inoue, Takehiko', '9782505078500', '03/2020 (Parution le 15/05/2020)', 352, 'https://www.bedetheque.com/media/Couvertures/Couv_388206.jpg', NULL);
INSERT INTO public.bd VALUES (459, 'Slam Dunk', 'INT10', 'Tome 10', 'Inoue, Takehiko', '9782505078517', '03/2020 (Parution le 15/05/2020)', 352, 'https://www.bedetheque.com/media/Couvertures/Couv_388207.jpg', NULL);
INSERT INTO public.bd VALUES (460, 'Slam Dunk', 'INT11', 'Tome 11', 'Inoue, Takehiko', '9782505078524', '07/2020 (Parution le 28/08/2020)', 246, 'https://www.bedetheque.com/media/Couvertures/Couv_401911.jpg', NULL);
INSERT INTO public.bd VALUES (461, 'Slam Dunk', 'INT12', 'Tome 12', 'Inoue, Takehiko', '9782505078630', '07/2020 (Parution le 28/08/2020)', 244, 'https://www.bedetheque.com/media/Couvertures/Couv_401990.jpg', 'Shôhoko aborde la deuxième mi-temps en ayant réussi à remonter à six point d''écart. A partir de là, Rukawa qui était resté silencieux pendant toute la première mi-temps va déployer toute sa puissance ! Hanamichi, acculé par Fukuda, retrouve également ses marques !! Shôhoku mène de peu et continue d''attaquer sans relâche ! La participation au tournoi interlycées est maintenant à portée des doigts !!');
INSERT INTO public.bd VALUES (462, 'Slam Dunk', 'INT13', 'Tome 13', 'Inoue, Takehiko', '9782505078555', '12/2020 (Parution le 27/11/2020)', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_409130.jpg', 'Il ne reste plus que cinq minutes avant de savoir si Shôhoku participera ou pas au tournoi inter-lycées.');
INSERT INTO public.bd VALUES (463, 'Slam Dunk', 'INT14', 'Tome 14', 'Inoue, Takehiko', '9782505078562', '12/2020 (Parution le 27/11/2020)', 229, 'https://www.bedetheque.com/media/Couvertures/Couv_409129.jpg', 'La finale très mouvementée des présélections du tournoi interlycées de Kanagawa est terminée et, dans tout le pays, les lycées participant au tournoi se préparent.');
INSERT INTO public.bd VALUES (464, 'Slam Dunk', 'INT15', 'Tome 15', 'Inoue, Takehiko', '9782505078579', '02/2021 (Parution le 05/02/2021)', 322, 'https://www.bedetheque.com/media/Couvertures/Couv_416512.jpg', 'Shôhoku participe pour la première fois au tournoi interlycées ! Leur premier adversaire est le lycée Toyotoma qui représente Osaka.');
INSERT INTO public.bd VALUES (465, 'Slam Dunk', 'INT16', 'Tome 16', 'Inoue, Takehiko', '9782505078586', '02/2021 (Parution le 05/02/2021)', 268, 'https://www.bedetheque.com/media/Couvertures/Couv_416513.jpg', 'Le deuxième adversaire de Shôhoku au tournoi interlycées n''est autre que le lycée technique Sannô, soit la meilleure équipe lycéenne de basket-ball au Japon.');
INSERT INTO public.bd VALUES (496, 'Captain Tsubasa / Olive & Tom', '27', 'Encore un autre joueur de talent !', 'Takahashi, Yôichi', '2290313351', '11/2001', 191, 'https://www.bedetheque.com/media/Couvertures/captain27r_38614.jpg', NULL);
INSERT INTO public.bd VALUES (466, 'Slam Dunk', 'INT17', 'Tome 17', 'Inoue, Takehiko', '9782505078593', '04/2021 (Parution le 23/04/2021)', 350, 'https://www.bedetheque.com/media/Couvertures/Couv_422905.jpg', 'Voici enfin de retour, dans une toute nouvelle édition, les aventures de Sakuragi qui se lance dans le basket-ball ! Même si au départ, il le fait pour épater la belle Haruko, il va se prendre au jeu et découvrir que se dépasser est la plus belle des motivations ! Slam dunk est devenue la référence ultime du manga de basket-ball pour ne pas dire la référence du manga de sport ! Parfait mélange d''action, d''humour, de romance, de rivalités dans un contexte sportif, jamais lourd, le tout servi par un dessin sublime de Takehiko Inoue. Cette édition...');
INSERT INTO public.bd VALUES (467, 'Slam Dunk', 'INT18', 'Tome 18', 'Inoue, Takehiko', '9782505078609', '04/2021 (Parution le 23/04/2021)', 350, 'https://www.bedetheque.com/media/Couvertures/Couv_422906.jpg', 'Voici enfin de retour, dans une toute nouvelle édition, les aventures de Sakuragi qui se lance dans le basket-ball ! Même si au départ, il le fait pour épater la belle Haruko, il va se prendre au jeu et découvrir que se dépasser est la plus belle des motivations ! Slam dunk est devenue la référence ultime du manga de basket-ball pour ne pas dire la référence du manga de sport ! Parfait mélange d''action, d''humour, de romance, de rivalités dans un contexte sportif, jamais lourd, le tout servi par un dessin sublime de Takehiko Inoue. Cette édition...');
INSERT INTO public.bd VALUES (468, 'Slam Dunk', 'INT19', 'Tome 19', 'Inoue, Takehiko', '9782505078616', '07/2021 (Parution le 09/07/2021)', 350, 'https://www.bedetheque.com/media/Couvertures/Couv_426163.jpg', 'Voici enfin de retour, dans une toute nouvelle édition, les aventures de Sakuragi qui se lance dans le basket-ball ! Même si au départ, il le fait pour épater la belle Haruko, il va se prendre au jeu et découvrir que se dépasser est la plus belle des motivations ! Slam dunk est devenue la référence ultime du manga de basket-ball pour ne pas dire la référence du manga de sport ! Parfait mélange d''action, d''humour, de romance, de rivalités dans un contexte sportif, jamais lourd, le tout servi par un dessin sublime de Takehiko Inoue. Cette édition...');
INSERT INTO public.bd VALUES (469, 'Slam Dunk', 'INT20', 'Tome 20', 'Inoue, Takehiko', '9782505078623', '07/2021 (Parution le 09/07/2021)', 350, 'https://www.bedetheque.com/media/Couvertures/Couv_426164.jpg', 'Voici enfin de retour, dans une toute nouvelle édition, les aventures de Sakuragi qui se lance dans le basket-ball ! Même si au départ, il le fait pour épater la belle Haruko, il va se prendre au jeu et découvrir que se dépasser est la plus belle des motivations ! Slam dunk est devenue la référence ultime du manga de basket-ball pour ne pas dire la référence du manga de sport ! Parfait mélange d''action, d''humour, de romance, de rivalités dans un contexte sportif, jamais lourd, le tout servi par un dessin sublime de Takehiko Inoue. Cette édition...');
