INSERT INTO public.bd VALUES (564, 'Bleach', '14', 'White Tower Rocks', 'Kubo, Tite', '2723451321', '01/2006', 200, 'https://www.bedetheque.com/media/Couvertures/Bleach14_17012006.jpg', NULL);
INSERT INTO public.bd VALUES (565, 'Bleach', '15', 'Beginning of the Death of Tomorrow', 'Kubo, Tite', '2723453847', '03/2006', 182, 'https://www.bedetheque.com/media/Couvertures/Bleach15_02032006.jpg', NULL);
INSERT INTO public.bd VALUES (566, 'Bleach', '16', 'Night of Wijnruit', 'Kubo, Tite', '2723453855', '05/2006', 180, 'https://www.bedetheque.com/media/Couvertures/Bleach16_19052006.jpg', NULL);
INSERT INTO public.bd VALUES (567, 'Bleach', '17', 'Rosa Rubicundior, Lilio Candidior', 'Kubo, Tite', '2723453863', '07/2006', 211, 'https://www.bedetheque.com/media/Couvertures/Bleach17_12072006.jpg', NULL);
INSERT INTO public.bd VALUES (568, 'Bleach', '18', 'The Deathberry Returns', 'Kubo, Tite', '2723455041', '09/2006', 204, 'https://www.bedetheque.com/media/Couvertures/Bleach18_05092006.jpg', NULL);
INSERT INTO public.bd VALUES (569, 'Bleach', '19', 'The Black Moon Rising', 'Kubo, Tite', '2723455963', '11/2006', 202, 'https://www.bedetheque.com/media/Couvertures/Bleach19_21112006.jpg', NULL);
INSERT INTO public.bd VALUES (570, 'Bleach', '20', 'End of Hypnosis', 'Kubo, Tite', '9782723456272', '02/2007', 221, 'https://www.bedetheque.com/media/Couvertures/Bleach20_24022007.jpg', NULL);
INSERT INTO public.bd VALUES (571, 'Bleach', '21', 'Be my Family or Not', 'Kubo, Tite', '9782723458061', '04/2007', 191, 'https://www.bedetheque.com/media/Couvertures/bleach21.jpg', NULL);
INSERT INTO public.bd VALUES (572, 'Bleach', '22', 'Conquistadores', 'Kubo, Tite', '9782723458023', '06/2007', 198, 'https://www.bedetheque.com/media/Couvertures/Bleach22_24062007_102342.jpg', NULL);
INSERT INTO public.bd VALUES (573, 'Bleach', '23', 'Mala Suerte!', 'Kubo, Tite', '9782723458139', '08/2007 (Parution le 16/08/2007)', 189, 'https://www.bedetheque.com/media/Couvertures/Bleach23_18082007_143710.jpg', 'Adolescent de quinze ans, Ichigo Kurosaki possède un don particulier : celui de voir les esprits. Un jour, il croise la route d''une belle shinigami (un être spirituel) en train de pourchasser une "âme perdue", un esprit maléfique qui hante notre monde et n''arrive pas à trouver le repos. Mise en difficulté par son ennemi, la jeune fille décide alors de prêter une partie de ses pouvoirs à Ichigo, mais ce dernier hérite finalement de toute la puissance d''un shinigami. Contraint d''assumer son nouveau statut, Ichigo va devoir gérer ses deux vies : celle...');
INSERT INTO public.bd VALUES (574, 'Bleach', '24', 'Immanent God Blues', 'Kubo, Tite', '9782723459532', '10/2007', 184, 'https://www.bedetheque.com/media/Couvertures/bleach24_69790.jpg', NULL);
INSERT INTO public.bd VALUES (575, 'Bleach', '25', 'No Shaking Throne', 'Kubo, Tite', '9782723461641', '01/2008', 189, 'https://www.bedetheque.com/media/Couvertures/bleach25_71315.jpg', NULL);
INSERT INTO public.bd VALUES (576, 'Bleach', '26', 'The Mascaron Drive', 'Kubo, Tite', '9782723461658', '03/2008', 192, 'https://www.bedetheque.com/media/Couvertures/bleach26_72910.jpg', 'Alors que les service secrets du Seireitei ont enfin trouvé l''ultime but d''Aizen, à Karakura, Orihime commence à douter de son pouvoir, craignant qu''elle ne soit pas assez puissante pour participer aux combats féroces contre les Arrancars, d''autant plus que Kisuke Urahara lui à interdit de prendre part aux affrontements, malgré les protestations de ses amis. Alors que ces derniers s''entrainent en prévision de la grande bataille décisive de l''hiver, les Arrancars attaquent...');
INSERT INTO public.bd VALUES (577, 'Bleach', '27', 'Goodbye halcyon days.', 'Kubo, Tite', '9782723463805', '05/2008 (Parution le 21/05/2008)', 192, 'https://www.bedetheque.com/media/Couvertures/bleach27_74731.jpg', 'Adolescent de quinze ans, Ichigo Kurosaki possède un don particulier : celui de voir les esprits. Un jour il croise la route d''une belle shinigami (un être spirituel) en train de pourchasser une "âme perdue", un esprit maléfique qui hante notre monde et n''arrive pas à trouver le repos. Mise en difficulté par son ennemi, la jeune fille décide alors de prêter une partie de ses pouvoirs à Ichigo, mais ce dernier hérite finalement de toute la puissance de la shinigami. Contraint d''assumer son nouveau statut, Ichigo va devoir gérer ses deux vies : celle...');
INSERT INTO public.bd VALUES (578, 'Bleach', '28', 'Baron''s Lecture Full-Course', 'Kubo, Tite', '9782723464390', '07/2008 (Parution le 09/07/2008)', 191, 'https://www.bedetheque.com/media/Couvertures/Bleach28_16072008_003848.jpg', 'Ichigo, Ishida et Sado continuent leur avancée au Hueco Mundo pour tenter de libérer leur amie Orihime des mains d''Aizen. Ce dernier est bien décidé à profiter de l''étrange pouvoir de la jeune fille, capable de régénérer n''importe quelle entité, pour atteindre son ambition de domination absolue. En chemin, Ichigo se retrouve bientôt confronté à un adversaire redoutable : un Espada déchu qui ne rêve que de pousser notre héros dans ses derniers retranchements pour retrouver grâce auprès d''Aizen !');
INSERT INTO public.bd VALUES (579, 'Bleach', '29', 'The Slashing Opera', 'Kubo, Tite', '9782723464437', '09/2008 (Parution le 24/09/2008)', 189, 'https://www.bedetheque.com/media/Couvertures/Couv_78403.jpg', 'Ichigo a finalement vaincu Dordoni en libérant ses pouvoirs de Hollow, mais celui-ci lui réserve encore une ultime fourberie ! Chad et Uryu affrontent également chacun un Privaron Espada : Cirucci, une jeune fille hystérique manipulant une sorte de Yo-yo gigantesque, et Gantenbein, dont la force herculéenne surpasse celle de Chad. Mais qui a donc donné l’ordre, en haut lieu, de supprimer les Espada déchus ? Ce volume riche en combats verra aussi l’apparition de nouveaux pouvoirs chez nos héros !');
INSERT INTO public.bd VALUES (581, 'Bleach', '31', 'Don''t Kill my Volupture', 'Kubo, Tite', '9782723466226', '03/2009 (Parution le 25/03/2009)', 208, 'https://www.bedetheque.com/media/Couvertures/83821_c.jpg', 'chigo se retrouve face à Ulquiora, l’Espada numéro 4 venu pour lui apprendre la mort de Rukia, mais surtout le défi er en combat singulier ! Afi n d’écourter le duel, Ichigo met toutes ses forces dans la bataille, mais même ses pouvoirs de Hollow ne peuvent rien face à l’ennemi, qui lui transperce le coeur ! Pendant ce temps, Orihime subit les tortures de ses geôlières, avant d’être secourue par Grimmjow. Ce dernier décide de se servir d’elle pour guérir Ichigo afi n de régler ses comptes avec lui…');
INSERT INTO public.bd VALUES (582, 'Bleach', '32', 'Howling', 'Kubo, Tite', '9782723466240', '05/2009 (Parution le 20/05/2009)', 192, 'https://www.bedetheque.com/media/Couvertures/bleach32_85767.jpg', 'Ichigo a été réanimé par Inoue à la demande de Grimmjow, qui souhaite l’affronter en duel ! L’ultime combat prend place entre les deux ennemis jurés, mais au fur et à mesure de l’affrontement, poussé dans ses derniers retranchements, Ichigo réalise qu’il est à deux doigts de perdre son humanité. Un volume 100% action dans lequel on découvre enfi n les origines et le passé du charismatique Grimmjow ! Le suspens est total, sans compter qu’un personnage très attendu apparaît dans les dernières pages !');
INSERT INTO public.bd VALUES (583, 'Bleach', '33', 'The Bad Joke', 'Kubo, Tite', '9782723470216', '07/2009 (Parution le 01/07/2009)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_88464.jpg', 'Dépassé en force par Noitora, l’Espada numéro 5, Ichigo voit ses chances de survie plus que jamais compromises. Pendant ce temps, Ishida et Renji découvrent la nouvelle transformation d’Apollo et ses horribles tours de passe-passe vaudous... Ce volume va surtout révéler les origines de Nell, la petite Hollow pleurnicheuse qui accompagne courageusement Ichigo, et qui va s’avérer être un ancien Espada parmi les plus puissants qui soient. Mais fera-t-elle le poids face à la faucheuse de Noitora ?');
INSERT INTO public.bd VALUES (584, 'Bleach', '34', 'King of the Kill', 'Kubo, Tite', '9782723470223', '09/2009 (Parution le 23/09/2009)', 224, 'https://www.bedetheque.com/media/Couvertures/Couv_91683.jpg', 'Nell parvient ? terrasser Noitora, mais ses pouvoirs s’av?rent ?tre de courte dur?e ! Ce volume marque un tournant spectaculaire du r?cit, avec l’arriv?e inopin?e des anciens ennemis de nos h?ros, venus leur pr?ter main forte ! Le foudre de guerre Kenpachi Zaraki affronte donc ? son tour Noitora, pendant que Byakuya tente de sauver sa soeur Rukia des griffes d’un nouvel Espada et que Mayuri s’oppose ? son alter ego Apollo… La confrontation ultime entre les Shinigami et les sbires d’Aizen commence !');
INSERT INTO public.bd VALUES (585, 'Bleach', '35', 'Higher than the Moon', 'Kubo, Tite', '9782723472647', '02/2010 (Parution le 17/02/2010)', 208, 'https://www.bedetheque.com/media/Couvertures/103290_c.jpg', 'Kenpachi Zaraki livre un combat titanesque face à Nnoitra, l''Espada assoiffé de sang, sous le regard impuissant d''Ichigo. Mais au terme du duel, Orihime se fait à nouveau capturée et reconduire auprès d''Aizen ! Celui-ci met en oeuvre son plan diabolique : réduire en poussière la ville de Karakura afin de créer un chemin le menant à la « clef du Roi ». Mais se dressent alors tous les capitaines des 13 divisions, venus directement de Soul Society pour livrer leur ultime bataille !');
INSERT INTO public.bd VALUES (586, 'Bleach', '36', 'Turn Back the Pendulum', 'Kubo, Tite', '9782723472654', '04/2010 (Parution le 21/04/2010)', 208, 'https://www.bedetheque.com/media/Couvertures/106470_c.jpg', 'Cent dix ans auparavant à Soul Society, Kisuke Urahara vient d’être choisi comme nouveau capitaine de la 12e division ! Tout en faisant face à l’opposition de son vice-capitaine, Hiyori Sarugaki, il commence son action à ce poste. Neuf ans après, une étrange affaire se produit à Soul Society ! Plongeons-nous dans le passé, où tout a commencé !');
INSERT INTO public.bd VALUES (587, 'Bleach', '37', 'Beauty is so Solitary', 'Kubo, Tite', '9782723472661', '06/2010 (Parution le 16/06/2010)', 224, 'https://www.bedetheque.com/media/Couvertures/109752_c.jpg', 'Alors qu’Aizen pratique des expériences de transformation d’Hollow sur son propre capitaine, il est surpris par Urahara. Mais ce dernier ne parvient pas à le stopper, et il se retrouve même accusé à sa place ! De retour dans le présent, la lutte contre les Espada reprend de plus belle, avec notamment un duel mémorable opposant deux adeptes de la “beauté” que tout oppose : Hayasegawa et Charlotte !');
INSERT INTO public.bd VALUES (588, 'Bleach', '38', 'Fear for Fight', 'Kubo, Tite', '9782723474559', '08/2010 (Parution le 25/08/2010)', 208, 'https://www.bedetheque.com/media/Couvertures/113253_c.jpg', 'Afin de faire revenir la vraie ville de Karakura, les fraccion de Barragan prévoient de détruire 4 piliers ! Pour les contrer, la fleur des Shinigamis : Yumichika, Kira, Hisagi et Ikkaku ! Ils écrasent l''ennemi les uns après les autres, mais soudain le pilier défendu par Ikkaku s''écroule ! Que va devenir le guerrier à terre, et que va-t-il advenir de Karakura ?!');
INSERT INTO public.bd VALUES (589, 'Bleach', '39', 'El Verdugo', 'Kubo, Tite', '9782723474566', '10/2010 (Parution le 20/10/2010)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_115652.jpg', 'Les duels à morts s''enchaînent lors de la bataille de Karakura ! Les 13 divisions affrontent les fraccion de leur puissant ennemi, Barragan ! Rangiku en difficulté est sauvée par Hinamori, mais devant une contre-attaque inattendue, toutes deux se retrouvent en danger de mort ! Puis, confronté à l''arrivée d''un ennemi à la forme monstrueuse, le capitaine-général Yamamoto passe enfin à l''action !');
INSERT INTO public.bd VALUES (590, 'Bleach', '40', 'The Lust', 'Kubo, Tite', '9782723474573', '01/2011 (Parution le 05/01/2011)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_119488.jpg', 'Ichigo contre Ulquiorra : c''est reparti ! Autrefois, Ichigo avait été vaincu par sa force écrasante ! Mais pour tirer Orihime du camp ennemi, Las Noches, il se lance dans la bataille avec une combativité indomptable ! Devant ce changement, Ulquiorra montre enfin la libération de son pouvoir, mais…');
INSERT INTO public.bd VALUES (591, 'Bleach', '41', 'Heart', 'Kubo, Tite', '9782723478762', '03/2011 (Parution le 02/03/2011)', 192, 'https://www.bedetheque.com/media/Couvertures/122101_c.jpg', 'Ichigo est mis hors de combat lors de son duel contre Ulquiorra ! À bout mentalement, Orihime sombre dans le désespoir. Mais linstant suivant, une scène incroyable se déroule devant ses yeux : Ichigo est rétabli, sous une forme ressemblant à celle dun Hollow, et défie de nouveau Ulquiorra ! Ainsi transformé, il nentend plus la voix dOrihime et des autres');
INSERT INTO public.bd VALUES (592, 'Bleach', '42', 'Shock of the Queen', 'Kubo, Tite', '9782723478779', '05/2011 (Parution le 04/05/2011)', 192, 'https://www.bedetheque.com/media/Couvertures/125255_c.jpg', 'Les meilleurs officiers supérieurs des 13 divisions lancent lassaut sur les 3 premiers Espada ! Au plus fort de la bataille, voilà que souvre le Garganta ! À quoi peut bien ressembler leur plus terrible ennemi ? Pire, alors quils affrontent un danger sans précédent, voilà que de nouvelles forces arrivent ! Amies ou ennemies ? La bataille entre dans une nouvelle phase !');
INSERT INTO public.bd VALUES (593, 'Bleach', '43', 'Kingdom of Hollows', 'Kubo, Tite', '9782723481632', '06/2011 (Parution le 29/06/2011)', 208, 'https://www.bedetheque.com/media/Couvertures/129729_c.jpg', 'Lapparition de leur ennemi commun, Aizen, a convaincu les 13 divisions et les Vizards de se battre ensemble. Ils affrontent celui qui régnait comme roi du Hueco Mundo, Barragan, et le premier Espada, Stark ! Mais quelle fin cruelle attend ceux qui ont enchaîné les combats à mort ?!');
INSERT INTO public.bd VALUES (674, 'Donjon de Naheulbeuk (Le)', '1', 'Première saison, partie 1.', 'Lang, John', '2913714676', '01/2005', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_42675.jpg', NULL);
INSERT INTO public.bd VALUES (594, 'Bleach', '44', 'Vice it', 'Kubo, Tite', '9782723481649', '09/2011 (Parution le 21/09/2011)', 192, 'https://www.bedetheque.com/media/Couvertures/137359_c.jpg', 'Rukia, qui combat au Hueco Mundo, est impuissante devant l''Espada Zéro, Yammy ! Mais voilà Ichigo !  Celui-ci, qui a achevé sa transformation, sauve Rukia sans aucune difficulté ! Puis, afin de vaincre Aizen, le pire de leur ennemis, il se hâte vers le champ de bataille de Karakura, dans le monde physique !');
INSERT INTO public.bd VALUES (595, 'Bleach', '45', 'The Burnout Inferno', 'Kubo, Tite', '9782723481656', '11/2011 (Parution le 30/11/2011)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_144699.jpg', 'Ichigo, qui est retourné à Karakura au bon moment, rejoint les 13 divisions et les Vizards qui combattent ensemble ! Toutefois, les pouvoirs dAizen dépassent de très loin ce qu''il avait imaginé. Compagnons abattus par de cruelles attaques, de la haine à l''horreurINSERT INTO public.bd VALUES (596, 'Bleach', '46', 'Back from Blind', 'Kubo, Tite', '9782723486637', '01/2012 (Parution le 04/01/2012)', 183, 'https://www.bedetheque.com/media/Couvertures/Couv_150614.jpg', 'Le capitaine général Yamamoto a lancé sa dernière attaque ! Profitant de cette chance unique, Ichigo attaque enfin Aizen ! Mais les blessures que ce dernier était censé avoir reçu disparaissent à vue d''il. Il révèle alors une vérité bouleversante, et un personnage inattendu fait irruption sous les yeux d''Ichigo !');
INSERT INTO public.bd VALUES (597, 'Bleach', '47', 'End of the Chrysalis Age', 'Kubo, Tite', '9782723486644', '03/2012 (Parution le 07/03/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_154640.jpg', 'Sous les yeux d''Ichigo, Aizen, ayant pris une forme étrange par la sujétion du hôgyoku, abat en un instant Urahara, Yoruichi et Isshin ! Puis il déchire la chose qui l''enveloppait et subit une nouvelle transformation ! Laissant Ichigo désespéré par sa puissance écrasante, Aizen se dirige vers Soul Society, où Karakura a été transférée !');
INSERT INTO public.bd VALUES (598, 'Bleach', '48', 'God is Dead', 'Kubo, Tite', '9782723486651', '05/2012 (Parution le 09/05/2012)', 224, 'https://www.bedetheque.com/media/Couvertures/Couv_161737.jpg', 'Aizen écrase Karakura ! Pendant ce temps, il se passe quelque chose danormal chez Gin, qui a suivi son chef après avoir vaincu Rangiku. Et enfin, ayant confronté "lultime Getsuga Tenshô", Ichigo revient et défie Aizen, qui continue son évolution ! Quel sera le destin de Karakura, de ses amis, de ses compagnons ? Larc des Arrancar atteint son apogée !');
INSERT INTO public.bd VALUES (599, 'Bleach', '49', 'The Lost Agent', 'Kubo, Tite', '9782723486668', '09/2012 (Parution le 05/09/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_171488.jpg', 'Au bout dun combat héroïque, Ichigo a perdu ses pouvoirs de shinigamiINSERT INTO public.bd VALUES (600, 'Bleach', '50', 'The Six Fullbringers', 'Kubo, Tite', '9782723491068', '11/2012 (Parution le 07/11/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_175848.jpg', 'Le but pour lequel Ginjô a approché Ichigo était de lui transférer ses pouvoirs et ceux des siens afin qu''ils redeviennent humains. Ce dernier n''ayant pas d''objection à récupérer ses pouvoirs de shinigami, il accepte le marché et commence son entraînement pour acquérir un fullbring ! Mais pendant ce temps, une ombre s''approche d''Orihime...');
INSERT INTO public.bd VALUES (601, 'Bleach', '51', 'Love me Bitterly Love me Sweetly', 'Kubo, Tite', '9782723492218', '01/2013 (Parution le 03/01/2013)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_178977.jpg', 'Ginjô, désormais certain quIchigo est la cible de Tsukishima, lui évite tout contact avec ce dernier et lui fait poursuivre lentraînement au fullbring dans une base secrète. Mais alors quIchigo commence à acquérir ce pouvoir avec une rapidité stupéfiante, voilà que Tsukishima fait irruption ! Ichigo va-t-il défier ce dernier, alors quil est en cours dapprentissage ?!');
INSERT INTO public.bd VALUES (602, 'Bleach', '52', 'End of Bond', 'Kubo, Tite', '9782723493079', '03/2013 (Parution le 06/03/2013)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_183703.jpg', 'Lentraînement de Ginjô dépassant les bornes, Ichigo commence à avoir des soupçons. De plus, il nen croit pas ses oreilles en entendant les révélations de son adversaire alors que le fullbring est juste à portée de sa main ! Achèvera-t-il son fullbring ?! Et alors que son entraînement sest achevé, cest une réalité à peine croyable qui lattend !');
INSERT INTO public.bd VALUES (603, 'Bleach', '53', 'The Deathberry Returns 2', 'Kubo, Tite', '9782723493086', '05/2013 (Parution le 08/05/2013)', 224, 'https://www.bedetheque.com/media/Couvertures/Couv_189054.jpg', 'Transpercé par Rukia, Ichigo recouvre ses pouvoirs de shinigami ! Le sabre de Rukia contenait en effet toute la puissance de lélite des 13 divisions. Entièrement remis sur pied, Ichigo affronte Ginjô, face à face. Et la bataille se change en affrontement général, shinigamis contre fullbringers !');
INSERT INTO public.bd VALUES (604, 'Bleach', '54', 'Goodbye to Our Xcution', 'Kubo, Tite', '9782723493093', '07/2013 (Parution le 03/07/2013)', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_192816.jpg', 'Le combat intense des shinigamis contre les fullbringers entre lui aussi dans sa dernière phase ! Alors quancien et nouveau représentant shinigami saffrontent, Ginjô révèle soudain une vérité cachée dans leur insigne ! Sachant tout, quelle option va finalement choisir Ichigo ?! Le rideau se baisse sur larc du représentant shinigami disparu !');
INSERT INTO public.bd VALUES (605, 'Bleach', '55', 'The Blood Warfare', 'Kubo, Tite', '9782723493246', '10/2013 (Parution le 09/10/2013)', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_199164.jpg', 'Une sonnerie dalarme retentit à Soul Society, comme pour annoncer quelque chose. Des habitants de Rukongai ont soudain disparu. Pendant ce temps, à Karakura où se trouvent Ichigo et les autres, une ombre suspecte sest approchée sans bruitINSERT INTO public.bd VALUES (606, 'Bleach', '56', 'March of the StarCross', 'Kubo, Tite', '9782723498197', '01/2014 (Parution le 22/01/2014)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_206598.jpg', 'Sétant rendus au Hueco Mundo à la demande de Nel, Ichigo et les siens découvrent larmée de chasse des Quincy ! Ichigo se porte au secours des Arrancar mais Quilge, le superviseur des chasses, se dresse devant lui avec son pouvoir répugnant ! De plus, le Vandenreich a lancé une invasion de Soul Society !');
INSERT INTO public.bd VALUES (607, 'Bleach', '57', 'Out of Bloom', 'Kubo, Tite', '9782723498203', '03/2014 (Parution le 05/03/2014)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_211447.jpg', 'Quilge a emprisonné Ichigo dans sa prison inviolable ! Pendant ce temps, les Shinigamis tombent sans pouvoir rien faire contre la puissance écrasante des Stern Ritter. Alors que, depuis Soul Society, les voix de ses compagnons s’éteignent les unes après les autres, les flammes d’un homme se mettent à brûler haut…');
INSERT INTO public.bd VALUES (608, 'Bleach', '58', 'The Fire', 'Kubo, Tite', '9782723499088', '05/2014 (Parution le 07/05/2014)', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_215678.jpg', 'Pour les shinigamis tombés au combat, et pour la Soul Society, Genryûsai brandit la lame de sa colère ! Le moment est-il venu pour la confrontation avec le chef des Quincy Yhwach, longue de mille ans, de trouver sa fin ? Pendant ce temps, quel spectacle s’offre aux yeux d’Ichigo, qui est arrivé à la Soul Society ?');
INSERT INTO public.bd VALUES (609, 'Bleach', '59', 'The Battle', 'Kubo, Tite', '9782723499262', '07/2014 (Parution le 02/07/2014)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_219781.jpg', 'Leurs blessures guéries, Ichigo et Renji se rendent au Hôôden, où les attend le prochain membre de la Division Zéro. Pendant ce temps, sur ordre de Kyôraku désormais capitaine général, Zaraki se rend au Muken, la prison située au sous-sol de Chuô. Il y trouve Unohana, un sourire calme aux lèvres…');
INSERT INTO public.bd VALUES (610, 'Bleach', '60', 'Everything but the Rain', 'Kubo, Tite', '9782344000717', '09/2014 (Parution le 03/09/2014)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_224875.jpg', 'Un hollow noir est apparu alors que la pluie tombe sur Karakura. Bien que létrangeté de la créature lui donne une sensation de malaise, Isshin sapprête à lanéantir. Or, une seconde plus tard, il est attaqué par derrière et gravement blessé ! Alors que le hollow se jette sur Isshin en difficulté, une flèche transperce les cieux');
INSERT INTO public.bd VALUES (611, 'Bleach', '61', 'The Last 9 Days', 'Kubo, Tite', '9782344004883', '01/2015 (Parution le 07/01/2015)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_233397.jpg', 'Il avait toujours veillé sur lui, avait toujours été à ses côtésINSERT INTO public.bd VALUES (612, 'Bleach', '62', 'Heart of Wolf', 'Kubo, Tite', '9782344006429', '03/2015 (Parution le 04/03/2015)', 183, 'https://www.bedetheque.com/media/Couvertures/Couv_236838.jpg', 'Hitsugaya et Soi Fon, dépourvus de bankai, ont été vaincus par leur adversaire Quincy. Mais la situation se retourne dun coup, quand Urahara transmet soudain à Mayuri une information incroyable ! Cependant cela donne aussi aux Quincy loccasion dengendrer une nouvelle vague de désespoir');
INSERT INTO public.bd VALUES (613, 'Bleach', '63', 'Hear, Fear, Here', 'Kubo, Tite', '9782344006740', '05/2015 (Parution le 06/05/2015)', 181, 'https://www.bedetheque.com/media/Couvertures/Couv_245022.jpg', 'Au nom de la justice, Masculine veut écraser Kensei et les autres ! Quand ses prunelles brillent derrière son masque, il va éradiquer le malINSERT INTO public.bd VALUES (614, 'Bleach', '64', 'Death in Vision', 'Kubo, Tite', '9782344009413', '07/2015 (Parution le 01/07/2015)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_247973.jpg', 'Un nouveau Stern Ritter nommé Gremmy se dresse devant Yachiru, qui a libéré son sabre. Pire, la véritable nature que dissimule le sourire du Quincy se met peu à peu à affecter la petite fille ! C''est alors que celui qui vient d''hériter d''un titre sans égal fait irruption sur le champ de bataille...');
INSERT INTO public.bd VALUES (615, 'Bleach', '65', 'Marching out the Zombies', 'Kubo, Tite', '9782344010280', '10/2015 (Parution le 14/10/2015)', 224, 'https://www.bedetheque.com/media/Couvertures/Couv_257609.jpg', 'La mort rôde autour de Kenpachi, gravement blessé après son violent combat contre Gremmy, sous la forme d''un groupe de guerrières Quincy ! Kenpachi étant un élément décisif dans l''issue de la bataille, de nombreux shinigamis se portent à son secours. C''est alors que ses compagnons perçoivent une pression spirituelle venant... des cieux ?!');
INSERT INTO public.bd VALUES (616, 'Bleach', '66', 'Sorry I am strong', 'Kubo, Tite', '9782344012888', '01/2016 (Parution le 06/01/2016)', 181, 'https://www.bedetheque.com/media/Couvertures/Couv_264960.jpg', 'Changé en pantin par Gigi, Hitsugaya attaque ses camarades shinigamis. Mais quand son regard vide se pose sur Mayuri, celui-ci a un sinistre sourire aux lèvres. Pendant ce temps, les soldats de la division Zéro, gardiens du palais royal, brandissent sans pitié leurs armes afin de tuer Yhwach, qui y a pénétré !');
INSERT INTO public.bd VALUES (617, 'Bleach', '67', 'Black', 'Kubo, Tite', '9782344012895', '03/2016 (Parution le 02/03/2016)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_274397.jpg', 'Le palais royal tremble sous la violence de la bataille entre les Quincy et la Division Zéro. Leurs chefs respectifs se retrouvent face à face, et le combat s''intensifie encore. Le leader de la Division Zéro, Ichibei Hyôsube, passe calmement à l''action. Son sabre recouvre tout d''un noir profond..');
INSERT INTO public.bd VALUES (618, 'Bleach', '68', 'The ordinary peace', 'Kubo, Tite', '9782344012901', '05/2016 (Parution le 04/05/2016)', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_280208.jpg', 'Avec la mort du roi spirituel, le monde commence à s’écrouler… Pour faire face à cette crise au Seireitei, Ukitake avait déclenché le pouvoir d’un mystérieux rituel, le Kamikake ! Pendant ce temps, Kyôraku avance dans des ténèbres d’un noir absolu. Il est venu y rencontrer une certaine personne… Mais avec quelles intentions ?!');
INSERT INTO public.bd VALUES (619, 'Bleach', '69', 'Against the judgement', 'Kubo, Tite', '9782344012918', '06/2016 (Parution le 06/07/2016)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_284270.jpg', 'Les Shinigami vont décidément s''allier avec tous leurs ennemis ! Après Aizen, ce sont Bazz-B, Liltotto et Giselle qui vont les aider à créer un portail dimensionnel vers le Palais. Les trois Stern Ritter survivants n''ont désormais plus qu''une chose en tête : tuer Yhwach, qui les a trahis en volant leurs pouvoirs et volant la vie de leurs camarades moins chanceux. De son côté, le groupe d''Ichigo, qui a survécu à la chute, retrouve de vieux ennemis : Grimmjow Jaggerjack et les Fullbringers ! Il faudra bien cela car Yhwach a absorbé tous les pouvoirs...');
INSERT INTO public.bd VALUES (620, 'Bleach', '70', 'Friend', 'Kubo, Tite', '9782344017425', '09/2016 (Parution le 07/09/2016)', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_287935.jpg', 'Bazz-B a confronté Jugram Hashwalth. Il s''avère que les deux hommes sont amis d''enfance et ont intégré les Stern Ritter dans l''unique but de tuer Yhwach pour se venger des massacres qu''il a commis il y a plusieurs siècles lors de ses conquêtes dans le monde réel. Cependant, Jugram a été choisi par Yhwach comme son successeur car tout comme lui, son pouvoir repose sur le don aux autres et depuis ne vit que pour servir celui qu''il était censé éliminer. Malgré tous ses efforts, Bazz-B ne parvient pas à l''emporter et meurt de la main de son ancien...');
INSERT INTO public.bd VALUES (621, 'Bleach', '71', 'Baby, hold your hand', 'Kubo, Tite', '9782344017432', '11/2016 (Parution le 02/11/2016)', 179, 'https://www.bedetheque.com/media/Couvertures/Couv_291424.jpg', 'Mayuri Kurotsuchi affronte Pernida Parknjas, qui n''est autre que le bras gauche du Roi des Esprits ! Pernida évolue en un temps record, peut contrôler l''adversaire avec ses nerfs et se régénère rapidement. Pour sauver son capitaine, Nemu se sacrifie afin d''éliminer Pernida une bonne fois pour toutes... Mais ce dernier se régénère et tue Nemu. Mayuri est désespéré, sa création parfaite est anéantie. Il faut qu''une vision de son ancien adversaire Szayel Apporo Grantz lui remette les idées en place pour qu''il se reprenne. Mayuri récupère le cerveau...');
INSERT INTO public.bd VALUES (622, 'Bleach', '72', 'My last words', 'Kubo, Tite', '9782344019863', '02/2017 (Parution le 01/02/2017)', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_297343.jpg', 'Lille, Gerard, Askin. Alors que les shinigamis combattent ces membres de l''escadron de protection, Nanao se jette dans la bataille à la place de Kyôraku, qui est gravement blessé. Pendant ce temps, Ichigo, arrivé au Wahrwelt en renfort de ses compagnons, tombe par hasard sur...');
INSERT INTO public.bd VALUES (642, 'Magi (The labyrinth of magic)', '6', 'Tome 6', 'Ohtaka, Shinobu', '9782351426791', '03/2012 (Parution le 08/03/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_161279.jpg', NULL);
INSERT INTO public.bd VALUES (623, 'Bleach', '73', 'Battlefield burning', 'Kubo, Tite', '9782344020388', '05/2017 (Parution le 05/05/2017)', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_303936.jpg', 'Alors qu''on le pensait vaincu par Yoruichi, Askin Nakk le Vaar est toujours vivant et a activé son Völlstandig. Poussé dans ses derniers retranchements, Kisuke Urahara n''a pas d''autre choix que d''activer son Bankai ! Pendant ce temps, Byakuya, Tôshirô et Kenpachi sont totalement impuissants face à Gerard Valkyrie, immortel et qui gagne en puissance sans arrêt ! Quant à Uryû, ses véritables intentions sont découvertes par Hashwalth : il veut tuer Yhwach pour venger sa mère, morte lors de l''Aüshwalen. Face à celui doté des pouvoirs d''Yhwach lorsque...');
INSERT INTO public.bd VALUES (624, 'Bleach', '74', 'The Death and the strawberry', 'Kubo, Tite', '9782344021910', '09/2017 (Parution le 06/09/2017)', 227, 'https://www.bedetheque.com/media/Couvertures/Couv_310583.jpg', 'Ichigo et Orihime parviennent jusqu''à Yhwach ! Le jeune homme combine ses pouvoirs de Shinigami et de Hollow pour affronter l''Empereur Quincy dont le réel pouvoir est de modifier l''avenir ! Qui sortira vainqueur de l''ultime combat ?');
INSERT INTO public.bd VALUES (625, 'Bleach', 'HS1', 'All Colour but the black', 'Kubo, Tite', '9782723466158', '11/2008 (Parution le 18/11/2008)', 108, 'https://www.bedetheque.com/media/Couvertures/79762_c.jpg', 'Sous-titré « All colour but the black » voici LE art book de la série emblématique de Tite Kubo. Attendu avidement par les fans, cet ouvrage a bénéficié d''une impression en Asie respectant les 5 couleurs, et se proposera donc dans une version française totalement fidèle à l''originale. Proposé à un prix très accessible pour un art book de cette qualité, et par ailleurs agrémenté d''un poster dépliant, le Bleach Illustrationsest un cadeau parfait pour Noël. On y retrouve ainsi les personnages de la série, mais aussi des délires de l''auteur et un commentaire...');
INSERT INTO public.bd VALUES (626, 'Bleach', 'HS2', 'Souls - Official Character Book', 'Kubo, Tite', '9782723467841', '11/2009 (Parution le 11/11/2009)', 328, 'https://www.bedetheque.com/media/Couvertures/Couv_96761.jpg', 'Véritable bible, "Souls" comporte une hallucinante quantité d''informations concernant l’œuvre culte de Tite Kubo. Outre des interviews rares de l''auteur, cet ouvrage de près de 320 pages contient également des fiches descriptives de tous les personnages qui apparaissent dans la série (bons ou méchants) et ce depuis le premier chapitre. Tous les arcs narratifs y sont abordés avec minutie, mais vous y retrouverez aussi des chapitres inédits et surtout le pilote original qui n''avait encore jamais été publié en librairie ! Ce qui ne gâche rien, un...');
INSERT INTO public.bd VALUES (627, 'Bleach', 'HS3', 'Masked - Official Character Book 2', 'Kubo, Tite', '9782723485487', '11/2011 (Parution le 30/11/2011)', 278, 'https://www.bedetheque.com/media/Couvertures/144705_c.jpg', 'Après Bleach Souls, découvrez Bleach Masked ! Dans ce nouveau guide book, vous en apprendrez plus sur les personnages, leurs attaques, les lieux et tous les petits détails qui émaillent le manga. Vous pourrez également profiter d''une interview de l''auteur ainsi que des pages couleurs et d''un poster.Un régal à ne pas manquer pour tous les fans de Bleach !');
INSERT INTO public.bd VALUES (628, 'Bleach', 'HS4', 'Memories of Nobody - Anime Comics', 'Kubo, Tite', '9782723487283', '07/2012 (Parution le 04/07/2012)', 352, 'https://www.bedetheque.com/media/Couvertures/167029_c.jpg', 'Une histoire complète en 352 pages ! Avis aux fans de Tite Kubo, voici une aventure inédite de Bleach en un seul volume et tout en couleurs ! En effet, après One Piece, Glenat Manga se lance dans l''édition des anime comics issus des quatre films de Bleach. Chacun représente une histoire inédite, où l''on retrouve tous les héros de la série culte, face à de nouveaux adversaires ! Le dispositif d''alerte de Soul Society est à son niveau maximum et toutes les équipes sont mobilisées. Le monde est tout simplement menacé de destruction par un mystérieux...');
INSERT INTO public.bd VALUES (629, 'Bleach', 'HS5', 'Official Bootleg', 'Kubo, Tite', '9782723487290', '07/2012 (Parution le 04/07/2012)', 184, 'https://www.bedetheque.com/media/Couvertures/Couv_167766.jpg', 'Un guide book très personnel Glénat Manga célèbre la série Bleach cette année ! Dans ce contexte, nous sommes heureux de proposer le Bleach Official Bootleg. Ce livre donne le détail des différents acteurs de Soul Society et des 13 divisions à l''instar d''un guide book. Mais, il contient aussi 72 pages couleurs de séquences bonus où l''auteur joue avec son univers et ses personnages. Sorti en 2007 au Japon, cet ouvrage indispensable est un recueil drôle et plein de fraîcheur qui amène finalement à considérer Tite Kubo sous un jour totalement nouveau...');
INSERT INTO public.bd VALUES (630, 'Bleach', 'HS6', 'Unmasked - Official Character Book 3', 'Kubo, Tite', '9782723491075', '11/2012 (Parution le 28/11/2012)', 232, 'https://www.bedetheque.com/media/Couvertures/Couv_177109.jpg', 'La nouvelle bible de l’univers Bleach ! Dans la lignée des databooks Bleach Souls et Bleach Masked, voici la nouvelle bible incontournable pour tout comprendre et connaître de lunivers de Bleach : Bleach Unmasked. Tous les secrets de Tite Kubo sont ainsi dévoilés, on revient sur les personnages, leurs capacités et leurs destinées ; on y détaille leurs pouvoirs, leur hiérarchisation, etc. Tout ce que lon a besoin de savoir pour naviguer dans lunivers de Bleach sans se perdre est réuni dans les quelques 200 pages de cette bible absolue.Les fans...');
INSERT INTO public.bd VALUES (631, 'Bleach', 'HS7', 'The DiamondDust Rebellion - Anime Comics', 'Kubo, Tite', '9782344003442', '02/2015 (Parution le 04/02/2015)', 350, 'https://www.bedetheque.com/media/Couvertures/Couv_236798.jpg', NULL);
INSERT INTO public.bd VALUES (632, 'Bleach', 'HS8', '13 blades.', 'Kubo, Tite', '9782334020661', '07/2017', 233, 'https://www.bedetheque.com/media/Couvertures/Couv_325935.jpg', 'La nouvelle bible de l’univers Bleach ! Dans la lignée des databooks Bleach Souls et Bleach Masked, voici la nouvelle bible incontournable pour tout comprendre et connaître de l?univers de Bleach : Bleach Unmasked. Tous les secrets de Tite Kubo sont ainsi dévoilés, on revient sur les personnages, leurs capacités et leurs destinées ; on y détaille leurs pouvoirs, leur hiérarchisation, etc. Tout ce que l?on a besoin de savoir pour naviguer dans l?univers de Bleach sans se perdre est réuni dans les quelques 200 pages de cette bible absolue.Les fans...');
INSERT INTO public.bd VALUES (633, 'Bleach', 'HS9', 'Fade to Black', 'Kubo, Tite', '9782344019856', '08/2017', 233, 'https://www.bedetheque.com/media/Couvertures/Couv_526375.jpg', 'Le 3e anime comics');
INSERT INTO public.bd VALUES (634, 'Bleach', 'Rom1', 'Can''t fear your own world (I)', 'Narita, Ryohgo', '9782344053829', '09/2022', 233, 'https://www.bedetheque.com/media/Couvertures/Couv_528775.jpg', NULL);
