INSERT INTO public.bd VALUES (651, 'Magi (The labyrinth of magic)', '15', 'Tome 15', 'Ohtaka, Shinobu', '9782351429556', '02/2014 (Parution le 13/02/2014)', 182, 'https://www.bedetheque.com/media/Couvertures/Couv_211355.jpg', 'Un combat attend Ali baba dès son arrivée à Rehm ! Et quelle aventure Morgiane s''apprête-t-elle à vivre dans le continent obscur ? Se révèle devant nous un univers plus immense que jamais !');
INSERT INTO public.bd VALUES (652, 'Magi (The labyrinth of magic)', '16', 'Tome 16', 'Ohtaka, Shinobu', '9782351429631', '07/2014 (Parution le 03/07/2014)', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_212738.jpg', NULL);
INSERT INTO public.bd VALUES (653, 'Magi (The labyrinth of magic)', '17', 'Tome 17', 'Ohtaka, Shinobu', '9782351429648', '11/2014 (Parution le 13/11/2014)', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_225657.jpg', 'La guerre éclate finalement entre l’Empire de Rehm et Magnostadt ! Pris dans les tourments de la première guerre de leur vie, que verront Aladin et ses jeunes amis ? Qu’apprendront-ils ?!');
INSERT INTO public.bd VALUES (654, 'Magi (The labyrinth of magic)', '18', 'Tome 18', 'Ohtaka, Shinobu', '9782368521021', '02/2015 (Parution le 12/02/2015)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_237433.jpg', NULL);
