INSERT INTO public.bd VALUES (657, 'Magi (The labyrinth of magic)', '21', 'Tome 21', 'Ohtaka, Shinobu', '9782368521052', '12/2015 (Parution le 10/12/2015)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_261144.jpg', NULL);
INSERT INTO public.bd VALUES (658, 'Magi (The labyrinth of magic)', '22', 'Tome 22', 'Ohtaka, Shinobu', '9782368522523', '04/2016 (Parution le 14/04/2016)', 191, 'https://www.bedetheque.com/media/Couvertures/Couv_279027.jpg', 'La concertation mondiale démarre.');
INSERT INTO public.bd VALUES (659, 'Magi (The labyrinth of magic)', '23', 'Tome 23', 'Ohtaka, Shinobu', '9782368522530', '08/2016 (Parution le 25/08/2016)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_287151.jpg', NULL);
INSERT INTO public.bd VALUES (660, 'Magi (The labyrinth of magic)', '24', 'Tome 24', 'Ohtaka, Shinobu', '9782368522547', '12/2016 (Parution le 08/12/2016)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_294508.jpg', NULL);
INSERT INTO public.bd VALUES (661, 'Magi (The labyrinth of magic)', '25', 'Tome 25', 'Ohtaka, Shinobu', '9782368524596', '04/2017 (Parution le 13/04/2017)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_301903.jpg', 'L''apparition du "Magi noir" bouleverse l''ordre du monde!');
INSERT INTO public.bd VALUES (662, 'Magi (The labyrinth of magic)', '26', 'Tome 26', 'Ohtaka, Shinobu', '9782368524602', '08/2017 (Parution le 24/08/2017)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_309552.jpg', 'Sauvée par l''armée de la résistance que dirige Salomon, la petite sorcière Shiva ouvre petit à petit son cœur aux autres. La présence de la nouvelle venue devient indispensable tant pour la résistance que pour Salomon...');
INSERT INTO public.bd VALUES (663, 'Magi (The labyrinth of magic)', '27', 'Tome 27', 'Ohtaka, Shinobu', '9782368524619', '12/2017 (Parution le 07/12/2017)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_317499.jpg', NULL);
INSERT INTO public.bd VALUES (664, 'Magi (The labyrinth of magic)', '28', 'Tome 28', 'Ohtaka, Shinobu', '9782368526064', '04/2018 (Parution le 12/04/2018)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_329239.jpg', NULL);
INSERT INTO public.bd VALUES (665, 'Magi (The labyrinth of magic)', '29', 'Tome 29', 'Ohtaka, Shinobu', '9782368526071', '08/2018 (Parution le 23/08/2018)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_341961.jpg', NULL);
INSERT INTO public.bd VALUES (666, 'Magi (The labyrinth of magic)', '30', 'Tome 30', 'Ohtaka, Shinobu', '9782368526088', '12/2018 (Parution le 06/12/2018)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_353769.jpg', 'Sindbad a créé un nouveau monde sans conflits ! Cependant, l''empire Kô s''y retrouve impuissant.');
INSERT INTO public.bd VALUES (667, 'Magi (The labyrinth of magic)', '31', 'Tome 31', 'Ohtaka, Shinobu', '9782368527207', '03/2019 (Parution le 14/03/2019)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_362082.jpg', 'Ali Baba fait le tour du monde afin de créer un réseau de transport qui ferait revivre l’empire Kô. Ses efforts sont cependant gâchés par Sindbad, un ami qui peut pourtant sembler peu digne de confiance.');
INSERT INTO public.bd VALUES (668, 'Magi (The labyrinth of magic)', '32', 'Tome 32', 'Ohtaka, Shinobu', '9782368527399', '06/2019 (Parution le 13/06/2019)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_368441.jpg', 'Après la rupture avec Sindbad, Aladin et ses amis affrontent la magie d''Alma Torran incarnée : Alba !');
INSERT INTO public.bd VALUES (669, 'Magi (The labyrinth of magic)', '33', 'Tome 33', 'Ohtaka, Shinobu', '9782368527573', '09/2019 (Parution le 12/09/2019)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_374519.jpg', 'Voyant le monde s’éloigner de plus en plus de son idéal, Sindbad s’impatiente et part, direction le Palais Sacré ! Il affronte Hugo, puis... ?!');
INSERT INTO public.bd VALUES (670, 'Magi (The labyrinth of magic)', '34', 'Tome 34', 'Ohtaka, Shinobu', '9782368527580', '12/2019 (Parution le 05/12/2019)', 190, 'https://www.bedetheque.com/media/Couvertures/Couv_380067.jpg', 'Sindbad s''est emparé du Palais sacré et a modifié les rokhs dans le monde entier.');
INSERT INTO public.bd VALUES (671, 'Magi (The labyrinth of magic)', '35', 'Tome 35', 'Ohtaka, Shinobu', '9782368529133', '03/2020 (Parution le 12/03/2020)', 190, 'https://www.bedetheque.com/media/Couvertures/Couv_388271.jpg', 'La traversée des sept labyrinthes.');
INSERT INTO public.bd VALUES (672, 'Magi (The labyrinth of magic)', '36', 'Tome 36', 'Ohtaka, Shinobu', '9782368529140', '07/2020 (Parution le 09/07/2020)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_400244.jpg', 'Fort de ses expériences dans le monde post-mortem, Ali Baba parvient à convaincre Sindbad.');
INSERT INTO public.bd VALUES (673, 'Magi (The labyrinth of magic)', '37', 'Tome 37', 'Ohtaka, Shinobu', '9782368529157', '07/2020 (Parution le 09/07/2020)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_400467.jpg', 'Tandis que le monde s''avance vers l''extinction par l''entremise des pouvoirs du Palais sacré, Aladin et Ali Baba résistent au destin. Dans le Palais sacré, David et Sindbad se livrent un combat acharné.');
INSERT INTO public.bd VALUES (678, 'Donjon de Naheulbeuk (Le)', '5', 'Deuxième saison - Partie 3', 'Lang, John', '9782353250851', '11/2008', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_80419.jpg', NULL);
INSERT INTO public.bd VALUES (679, 'Donjon de Naheulbeuk (Le)', '6', 'Deuxième saison - Partie 4', 'Lang, John', '9782353251704', '11/2009', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_99797.jpg', NULL);
