INSERT INTO public.bd VALUES (681, 'Donjon de Naheulbeuk (Le)', '8', 'Troisième saison - Partie 2', 'Lang, John', '9782353252985', '03/2011', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_125066.jpg', NULL);
