INSERT INTO public.bd VALUES (1031, 'Ippo - La rage de vaincre', '14', 'Tome 14', 'Morikawa, George', '9782351422304', '09/2008', 181, 'https://www.bedetheque.com/media/Couvertures/IppoLaRageDeVaincre14_19092008_084602.jpg', NULL);
