INSERT INTO public.bd VALUES (1419, 'Alix', 'HS1992', 'Alixorama I - images d''Alix', 'Rivière, François', '2873530383', '11/1992', 50, 'https://www.bedetheque.com/media/Couvertures/Couv_21283.jpg', NULL);
INSERT INTO public.bd VALUES (1420, 'Alix', 'HS1999', 'La voie d''Alix', 'Robert, Michel', '2205047620', '01/1999', 105, 'https://www.bedetheque.com/media/Couvertures/Alix8_04032007.jpg', NULL);
INSERT INTO public.bd VALUES (1421, 'Alix', 'HS1999', 'L''Odyssée d''Alix - 2', 'Martin, Jacques', '2205046675', '02/1999', 56, 'https://www.bedetheque.com/media/Couvertures/Couv_21284.jpg', NULL);
INSERT INTO public.bd VALUES (1422, 'Alix', 'HS2007 TL', 'Les Expéditions d''Alix', '<Collectif>', '2930196742', '01/2007 (Parution le 05/02/2007)', 77, 'https://www.bedetheque.com/media/Couvertures/Alix_18012009_191247.jpg', NULL);
INSERT INTO public.bd VALUES (1423, 'Alix', 'HS2010', 'Rome - Itinéraires avec Alix', 'De Chérisey, Thérèse', '9782203022867', '02/2010', 160, 'https://www.bedetheque.com/media/Couvertures/Couv_106146.jpg', 'Un grand nom de la bande dessinée et un grand nom du livre de voyage unissent leur expérience éditoriale et le talent de leurs auteurs pour inventer, ensemble, une nouvelle génération de city guides. Idée force de cette nouvelle collection Lonely Planet / Casterman : conjuguer la force des textes et l’impact des images dessinées pour donner à voir et à découvrir autrement de grandes métropoles du monde, à travers des choix d’itinéraires délibérément subjectifs ou éminemment personnels. L’identité des auteurs joue évidemment un rôle central dans...');
INSERT INTO public.bd VALUES (1424, 'Alix', 'HS2018', 'Alix 70 ans d''aventures', '<Collectif>', '9782756933238', '01/2018', 32, 'https://www.bedetheque.com/media/Couvertures/Couv_344503.jpg', 'Fascicule de présentation de l''exposition  consacrée à Alix à la Cité internationale de la bande dessinée d''Angoulême du 25 janvier au 13 mai 2018.');
INSERT INTO public.bd VALUES (1425, 'Alix', 'HS2021', 'Alix: Destination Vesunna', 'Goumand, Christophe', '9791095077039', '07/2021 (Parution le 01/01/1965)', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_430681.jpg', 'Catalogue de l''exposition organisée à Vesunna, musée gallo-romain de Périgueux à l''occasion du centenaire de la naissance de Jacques Martin');
INSERT INTO public.bd VALUES (1426, 'Alix', 'INT en Cof', 'Les Premières Aventures', 'Martin, Jacques', '9782203119864', '11/2016 (Parution le 16/11/2016)', 834, 'https://www.bedetheque.com/media/Couvertures/Couv_295321.jpg', 'Découvrez ou redécouvrez les premières aventures d’Alix à l''époque de Jules César, réalisées par Jacques Martin. Des intrigues à couper le souffle et un héros emblématique nommé Alix, un jeune homme courageux tiraillé entre son origine gauloise et son adoption romaine.');
INSERT INTO public.bd VALUES (1427, 'Alix', 'INT1', 'La trilogie Cléopâtre', 'Martin, Jacques', '9782203022911', '05/2009', 144, 'https://www.bedetheque.com/media/Couvertures/Couv_176368.jpg', NULL);
