INSERT INTO public.bd VALUES (1434, 'Iznogoud', '3', 'Les vacances du Calife', 'Goscinny, René', '2953844279', '07/1968', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_296774.jpg', NULL);
INSERT INTO public.bd VALUES (1435, 'Iznogoud', '4', 'Iznogoud l''infâme', 'Goscinny, René', '2938489331', '04/1969', 42, 'https://www.bedetheque.com/media/Couvertures/Couv_3847.jpg', NULL);
INSERT INTO public.bd VALUES (1436, 'Iznogoud', '5', 'Des astres pour Iznogoud', 'Goscinny, René', '2796699471', '10/1969', 40, 'https://www.bedetheque.com/media/Couvertures/iznogoudtome05.jpg', NULL);
INSERT INTO public.bd VALUES (1437, 'Iznogoud', '6', 'Iznogoud et l''ordinateur magique', 'Goscinny, René', '2219747220', '10/1970', 40, 'https://www.bedetheque.com/media/Couvertures/iznogoud06_3849.jpg', NULL);
INSERT INTO public.bd VALUES (1438, 'Iznogoud', '7', 'Une carotte pour Iznogoud', 'Goscinny, René', '270531816X', '10/1971', 44, 'https://www.bedetheque.com/media/Couvertures/iznogoudtome07.jpg', NULL);
INSERT INTO public.bd VALUES (1439, 'Iznogoud', '8', 'Le jour des fous', 'Goscinny, René', '2205006452', '07/1972', 44, 'https://www.bedetheque.com/media/Couvertures/iznogoudtome08.jpg', NULL);
INSERT INTO public.bd VALUES (1440, 'Iznogoud', '9', 'Le tapis magique', 'Goscinny, René', '2881594344', '10/1973', 42, 'https://www.bedetheque.com/media/Couvertures/Couv_3852.jpg', NULL);
INSERT INTO public.bd VALUES (1441, 'Iznogoud', '10', 'Iznogoud l''acharné', 'Goscinny, René', '2279109042', '10/1974', 44, 'https://www.bedetheque.com/media/Couvertures/iznogoudtome10.jpg', '5 histoires dans cet album. 1. La marelle maléfique : Un enchanteur rend visite à Iznogoud et lui révèle le secret d''un jeu de marelle qui transforme les adultes en enfants. Or, la loi en vigueur interdit à un Calife de régner s''il est mineur. 2. L''île des souvenirs : Iznogoud doit offrir au calife son cadeau annuel comme le demande la coutume. Il part à la recherche d''un cadeau et tombe sur un objet aux propriétés particulières. 3. Le marchand de l''oubli : Iznogoud rend visite avec Dilat Larath à un marchand qui vend un parfum faisant perdre la...');
INSERT INTO public.bd VALUES (1442, 'Iznogoud', '11', 'La tête de Turc d''Iznogoud', 'Goscinny, René', '2205008951', '10/1975', 44, 'https://www.bedetheque.com/media/Couvertures/iznogoudtome11.jpg', '4 histoires dans cet album. 1. La tête de turc : Iznogoud apprend par Dilat Larath l''existence d''un marchand de farces et attrapes : ce marchand lui vend un puzzle de 10 000 pièces représentant une tête de turc, un puzzle qui a le pouvoir d''émietter en 10 000 morceaux la personne à laquelle on pense lorsque l''on place la dernière pièce pour le terminer. 2. Le chant qui fige : Iznogoud, lors d''une promenade sur le port, rencontre un équipage mystérieusement figé. L''un des marins lui présente une sirène dont le chant fige tous ceux qui l''écoutent....');
INSERT INTO public.bd VALUES (1443, 'Iznogoud', '12', 'Le conte de fées d''Iznogoud', 'Goscinny, René', '220501031X', '10/1976', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_3855.jpg', NULL);
INSERT INTO public.bd VALUES (1444, 'Iznogoud', '13', 'Je veux être Calife à la place du Calife', 'Goscinny, René', '2850710725', '04/1978', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_201.jpg', NULL);
INSERT INTO public.bd VALUES (1445, 'Iznogoud', '14', 'Les cauchemars d''Iznogoud', 'Goscinny, René', '2904799044', '10/1979', 118, 'https://www.bedetheque.com/media/Couvertures/iznogoud14.jpg', NULL);
INSERT INTO public.bd VALUES (1446, 'Iznogoud', '15', 'L''enfance d''Iznogoud', 'Tabary, Jean', '2723402347', '07/1981', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_5722.jpg', 'Iznogoud décide de retourner au temps de son enfance afin de tuer Haroun el Poussah avant que celui-ci ne devienne calife, pensant qu''il est plus facile de se débarrasser d''un enfant que d''un adulte.');
INSERT INTO public.bd VALUES (1447, 'Iznogoud', '16', 'Iznogoud et les femmes', 'Tabary, Jean', '2904799001', '10/1983', 44, 'https://www.bedetheque.com/media/Couvertures/iznogoud16.jpg', 'Le moment était venu pour le calife de Bagdad de signer à nouveau le traité de paix qui le liait au belliqueux voisin le sultan Pullmankar. Seulement voilà, le message que ce dernier avait fait porter se terminait par une phrase codée... il ne s’agissait donc pas de signer les yeux fermés un documents qui mettrait par la suite dans l’embarras le califat. La phrase codée fut vite décryptée. Avec quelque honte, le sultan demandait ainsi qu’une femme lui soit réservée au califat ! Il voulait être, comme qui dirait, comme le marin est dans chaque port......');
INSERT INTO public.bd VALUES (1448, 'Iznogoud', '17', 'Les cauchemars d''Iznogoud (bis)', 'Buhler, Alain', '2904799028', '04/1984', 90, 'https://www.bedetheque.com/media/Couvertures/iznogoud17.jpg', NULL);
INSERT INTO public.bd VALUES (1449, 'Iznogoud', '18', 'Le complice d''Iznogoud', 'Tabary, Jean', '2904799036', '01/1985', 44, 'https://www.bedetheque.com/media/Couvertures/iznogoudcouv18.JPG', 'Le grand maître de l’enfer fixe un ultimatum à Iznogoud. Il a 10 jours pour devenir Calife à la place du Calife. Passé ce délai, il lui promet enfer et damnation. Iznogoud fait appel à toute une ribambelle de complices…un médecin au visage diabolique, à l’expression fourbe, au sourire sardonique sensé achever le Calife souffrant…mais va finalement le guérir ; N.D.M. le plus grand magicien de tous les temps qui se révèle être un voleur de diamants ; Al Ehmeri-le-Boucher assassin professionnel qui manque de trucider Iznogoud ; un vendeur de masques...');
INSERT INTO public.bd VALUES (1450, 'Iznogoud', '19', 'L''Anniversaire d''Iznogoud', 'Tabary, Jean', '2904799109', '01/1987', 44, 'https://www.bedetheque.com/media/Couvertures/iznogoud19.jpg', 'Dans Bagdad la magnifique c’est le monde à l’envers. Iznogoud offre des cadeaux le jour de son anniversaire. Comme le veut la tradition, c’est le vizir qui doit faire un cadeau au calife Haroun El Poussah sous peine de se faire décapiter par le bourreau du palais. Par chance, le syndicat des magiciens de Bagdad, pour le remercier d’être l’un des plus fidèles clients, offre à Iznogoud une douche en kit : « Vous ferez prendre une douche à votre calife, le produit mystérieux qui est à l’intérieur mêlé à l’eau le fera disparaître à tout jamais. Mais...');
INSERT INTO public.bd VALUES (1451, 'Iznogoud', '20', 'Enfin Calife !', 'Tabary, Jean', '2904799206', '01/1989', 44, 'https://www.bedetheque.com/media/Couvertures/iznogoudcouv20.JPG', NULL);
INSERT INTO public.bd VALUES (1452, 'Iznogoud', '21', 'Le piège de la sirène', 'Tabary, Jean', '290479929X', '10/1992', 44, 'https://www.bedetheque.com/media/Couvertures/iznogoudcouv21.JPG', '3 histoires dans cet album : 1. Le piège de la sirène – 14 planches Le piège de la sirène est une baignoire qui expédie sur une île déserte celui qui prend un bain. La sirène nymphomane apprécie particulièrement les gros. Mais après usage, elle jette sa victime épuisée aux requins. Iznogoud a alors une obsession : faire prendre un bain au bon Calife Haroun El Poussah. Pour une fois il y parvient…et le Calife adore ! 2. Les babouches galopantes – 16 planches Un nouveau visiteur propose à Iznogoud une paire de babouches magiques. Celui qui les porte...');
INSERT INTO public.bd VALUES (1453, 'Iznogoud', '22a1994', 'Les Cauchemars d''Iznogoud (tome 2)', 'Goscinny, René', '2904799303', '10/1993', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_409959.jpg', NULL);
INSERT INTO public.bd VALUES (1454, 'Iznogoud', '23', 'Les cauchemars d''Iznogoud (Tome 3)', 'Buhler, Alain', '2904799311', '01/1994', 45, 'https://www.bedetheque.com/media/Couvertures/iznogoud23.jpg', NULL);
INSERT INTO public.bd VALUES (1455, 'Iznogoud', '24', 'Les retours d''Iznogoud', 'Tabary, Jean', '290479932X', '09/1994', 44, 'https://www.bedetheque.com/media/Couvertures/iznogoudcouv24.JPG', 'Les retours d’Iznogoud sont de courtes séquences en deux planches qui forment un épilogue comique de certaines des histoires. René Goscinny présentait ainsi cette nouvelle rubrique dans le magazine Record où paraissaient les histoires : « Nos lecteurs ont remarqué qu’à la fin de chaque récit des aventures du bon calife Haroun El Poussah, il arrivait à l’ignoble, immonde et infâme grand vizir Iznogoud des tas de choses désagréables. Rappelez-vous : il a été enfermé dans un cachot, perdu dans un labyrinthe, enrhumé, mis en cage, rendu invisible,...');
INSERT INTO public.bd VALUES (1456, 'Iznogoud', '25', 'Qui a tué le Calife ?', 'Tabary, Jean', '2904799400', '10/1998', 44, 'https://www.bedetheque.com/media/Couvertures/iznogoud25.jpg', 'Tous les cinq ans, le calife doit faire des conquêtes et agrandir le califat. Le grand chambellan déploie une carte du désert et le calife, les yeux bandés, pointe du doigt la terre à envahir. Grâce à un magicien, Iznogoud fait en sorte que cette fois-ci le calife affronte le terrible sultan Pullmankar.');
INSERT INTO public.bd VALUES (1457, 'Iznogoud', '26', 'Un monstre sympathique', 'Tabary, Jean', '2904799435', '10/2000', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_5731.jpg', 'Le sultan Pullmankar et le calife El Poussah de Bagdad sont tant en odeur de sainteté que le destin même du grand vizir Iznogoud est en danger : les deux souverains doivent en effet se voir et décider de la manière de supprimer, tout bonnement, l’irascible aspirant calife !!! Il reste donc très très peu de temps à Iznogoud pour aller contre le noir destin qui lui est promis, la solution étant de tuer son calife ; une solution (du déjà-vu, dites-vous ?!) qu’il trouvera peut-être au salon de la magie qui se tient justement à Bagdad à ce moment-là...');
INSERT INTO public.bd VALUES (1458, 'Iznogoud', '27', 'La faute de l''ancêtre', 'Tabary, Jean', '2904799575', '04/2004', 44, 'https://www.bedetheque.com/media/Couvertures/Iznogoud27_16042004.jpg', 'Notre cher Iznogoud a toujours a la même idée: devenir calife a la place du calife. Cet fois-ci il est aidé dans sa tâche par un homme du 20ème siècle qui prétend grâce à l''arbre généalogique du calife de remonter le temps jusqu''à la préhistoire et supprimer l''ancêtre d''Haroun El Poussah.');
INSERT INTO public.bd VALUES (1517, 'Doraemon, le Chat venu du Futur', '29', 'Tome 29', 'Fujiko F. Fujio', '9782505065685', '02/2016 (Parution le 19/02/2016)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_269071.jpg', NULL);
INSERT INTO public.bd VALUES (1461, 'Iznogoud', '30', 'De Père en Fils !', 'Vassilian, Laurent', '9782915732887', '10/2015 (Parution le 08/10/2015)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_254762.jpg', 'Pour le plus grand plaisir sadique des lecteurs, Iznogoud revient avec de nouveaux stratagèmes... tous voués à l''échec. Vil, bas, mesquin, méchant, bête et brutal, l''ignoble vizir ne renonce jamais : Il veut être calife à la place du calife Plus déterminé que jamais, Iznogoud va cette fois se retrouver confronté à... son père ! C''est le 30ème album de cette série culte créée par deux humoristes de génie, Goscinny et Tabary Fidèle à l''esprit des créateurs, Laurent Vassilian (scénario) et Nicolas Tabary (dessin), auteurs du précédent album (Iznogoud...');
INSERT INTO public.bd VALUES (1462, 'Iznogoud', '31', 'Moi, calife...', 'Jul (1)', '9782365901581', '10/2021 (Parution le 21/10/2021)', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_434309.jpg', 'L''ignoble vizir Iznogoud revient dans une forme éblouissante, prêt à toutes les ignominies pour enfin devenir calife à la place du calife ! N''hésitant pas à s''entourer de tout ce que Bagdad la somptueuse compte de mages interlopes, de charlatans véreux et d''hommes de main sans scrupules, il ne recule devant rien pour piéger le bon Haroun El-Poussah : de l''échiquier enchanté qui escamote le perdant de la partie, aux toiles magiques de Dali Baba, Iznogoud multiplie les stratagèmes tordus pour arriver à ses fins.');
INSERT INTO public.bd VALUES (1463, 'Iznogoud', '32', 'Des bougies pour Iznogoud', 'Andrieu, Olivier', '9782365901680', '10/2022 (Parution le 20/10/2022)', 42, 'https://www.bedetheque.com/media/Couvertures/Couv_457489.jpg', NULL);
INSERT INTO public.bd VALUES (1464, 'Iznogoud', '33', 'Iznogoud et la sœur du calife', 'Andrieu, Olivier', '9782365901734', '10/2025 (Parution le 30/10/2025)', 41, 'https://www.bedetheque.com/media/Couvertures/Couv_530427.jpg', 'Dans cet album : 5 histoires courtes en 8 planches, efficaces et surprenantes. Indémodable, inoxydable, indestructible : Iznogoud est de retour ! L''ignoble vizir veut plus que jamais : devenir calife à la place du calife ! Pour la première fois, la grande soeur du calife entre en scène : elle veut honorer une ancienne promesse et prendre la tête du califat à la place de son frère. S''il l''épouse, Iznogoud pourrait alors accéder au trône tant convoité ! Iznogoud complote et imagine des stratagèmes toujours plus machiavéliques : un massage si relaxant...');
INSERT INTO public.bd VALUES (1465, 'Iznogoud', 'HS077', 'Une carotte pour Iznogoud', 'Goscinny, René', '2292423251', '02/1971', 39, 'https://www.bedetheque.com/media/Couvertures/Couv_193031.jpg', NULL);
INSERT INTO public.bd VALUES (1466, 'Iznogoud', 'HS1', 'L''ignoble Iznogoud commente l''actualité - 1', 'Goscinny, René', '2205008846', '01/1976', 45, 'https://www.bedetheque.com/media/Couvertures/iznogoudactualite01couv.jpg', NULL);
INSERT INTO public.bd VALUES (1467, 'Iznogoud', 'HS2', 'L''ignoble Iznogoud commente l''actualité - 2', 'Goscinny, René', '2205010441', '01/1977', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_3843.jpg', NULL);
INSERT INTO public.bd VALUES (1468, 'Iznogoud', 'INT1', '25 histoires de Goscinny et Tabary de 1962 à 1978', 'Goscinny, René', '9782915732405', '02/2012 (Parution le 23/02/2012)', 276, 'https://www.bedetheque.com/media/Couvertures/Couv_156773.jpg', NULL);
INSERT INTO public.bd VALUES (1469, 'Iznogoud', 'INT2', '6 histoires de Jean Tabary de 1978 à 1989', 'Tabary, Jean', '9782915732894', '10/2015 (Parution le 08/10/2015)', 228, 'https://www.bedetheque.com/media/Couvertures/Couv_258087.jpg', 'Ce deuxième volume de l''Intégrale Iznogoud réunis 5 albums de l''ignoble vizir écrits et dessinés par Jean Tabary entre 1981 et 1989 : - L''enfance d''Iznogoud - Iznogoud et les femmes - Le complice d''Iznogoud - L''anniversaire d''Iznogoud - Iznogoud, enfin calife ! Avec maestria, Tabary succède à René Goscinny, le co-créateur et auteur des scénarios. Fidèle à l''esprit de son ami disparu en 1977, Tabary imagine pour Iznogoud les stratagèmes les plus atroces, tous voués à l''échec. Alors que les aventures d''Iznogoud se déroulaient en 8 planches, Tabary...');
INSERT INTO public.bd VALUES (1470, 'Iznogoud', 'INT3', '6 histoires de Jean Tabary de 1990 à 2004', 'Tabary, Jean', '9782915732986', '08/2016 (Parution le 25/08/2016)', 200, 'https://www.bedetheque.com/media/Couvertures/Couv_288556.jpg', 'Ce troisième volume de l''Intégrale Iznogoud réuni 4 albums de l''ignoble vizir écrits et dessinés par Jean Tabary entre 1990 et 2004 :');
INSERT INTO public.bd VALUES (1471, 'Iznogoud', 'INT4', '33 histoires de Goscinny et Tabary 1962-1969', 'Goscinny, René', '9782205086652', '10/2021 (Parution le 26/11/2021)', 202, 'https://www.bedetheque.com/media/Couvertures/Couv_437189.jpg', 'Le volume contient les 4 premiers tomes édités par Dargaud ainsi que 12 "retours" placés directement après l''histoire dont ils racontent la suite et qui sont édités par IMAV éditions.');
INSERT INTO public.bd VALUES (1472, 'Iznogoud', 'INT5', '22 histoires de Goscinny et Tabary 1969-1972', 'Goscinny, René', '9782205202755', '06/2023 (Parution le 23/06/2023)', 200, 'https://www.bedetheque.com/media/Couvertures/Couv_477317.jpg', NULL);
INSERT INTO public.bd VALUES (1473, 'Iznogoud', 'PUB', 'Iznogoud et les babouches galopantes', 'Tabary, Jean', '2938223935', '01/2000', 22, 'https://www.bedetheque.com/media/Couvertures/Couv_156561.jpg', NULL);
INSERT INTO public.bd VALUES (1474, 'Gai-Luron', '0RR10', 'Gai-Luron', 'Gotlib', '2742124217', '10/1969', 47, 'https://www.bedetheque.com/media/Couvertures/Couv_40016.jpg', NULL);
INSERT INTO public.bd VALUES (1475, 'Gai-Luron', '1', 'Gai-Luron ... ou la joie de vivre', 'Gotlib', '2209280753', '04/1975', 45, 'https://www.bedetheque.com/media/Couvertures/Gailuron1_22062004.jpg', NULL);
