INSERT INTO public.bd VALUES (1477, 'Gai-Luron', '3', 'Gai-Luron rit de se voir si beau en ce miroir', 'Gotlib', '2286623422', '04/1976', 47, 'https://www.bedetheque.com/media/Couvertures/Couv_36837.jpg', NULL);
INSERT INTO public.bd VALUES (1478, 'Gai-Luron', '4', 'Gai-Luron et Jean-Pierre Liégeois (jeune lecteur du Var)', 'Gotlib', '2950885691', '10/1976', 47, 'https://www.bedetheque.com/media/Couvertures/Gailuron4_22062004.jpg', NULL);
INSERT INTO public.bd VALUES (1479, 'Gai-Luron', '5', 'Gai-Luron fait rien qu''à copier', 'Gotlib', '2281764303', '04/1977', 46, 'https://www.bedetheque.com/media/Couvertures/Gailuron5_22062004.jpg', NULL);
INSERT INTO public.bd VALUES (1480, 'Gai-Luron', '6', 'Gai-Luron ce héros au sourire si doux', 'Gotlib', '2760667928', '01/1978', 46, 'https://www.bedetheque.com/media/Couvertures/Gailuron6_09102006.jpg', NULL);
INSERT INTO public.bd VALUES (1481, 'Gai-Luron', '7', 'Gai-Luron s''en tire par une pirouette', 'Gotlib', '2214429379', '01/1979', 46, 'https://www.bedetheque.com/media/Couvertures/Gailuron7_22062004.jpg', NULL);
INSERT INTO public.bd VALUES (1482, 'Gai-Luron', '8', 'Gai-Luron drague comme une bête', 'Gotlib', '2896183531', '01/1980', 46, 'https://www.bedetheque.com/media/Couvertures/Gailuron8_22062004.jpg', NULL);
INSERT INTO public.bd VALUES (1483, 'Gai-Luron', '9', 'Gai-Luron n''engendre pas la mélancolie !', 'Gotlib', '2809471908', '01/1981', 46, 'https://www.bedetheque.com/media/Couvertures/Gailuron9_22062004.jpg', NULL);
INSERT INTO public.bd VALUES (1484, 'Gai-Luron', '10', 'Gai-Luron tire une tronche pas possible', 'Gotlib', '285815001X', '01/1982', 46, 'https://www.bedetheque.com/media/Couvertures/gailuroncouv10.jpg', NULL);
INSERT INTO public.bd VALUES (1485, 'Gai-Luron', '11', 'La bataille navale ...ou Gai-Luron en slip', 'Gotlib', '2858150966', '05/1986', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_12186.jpg', NULL);
INSERT INTO public.bd VALUES (1486, 'Gai-Luron', 'INT1', 'Tomes 1 à 4', 'Gotlib', '9782352071945', '01/2012 (Parution le 15/02/2012)', 191, 'https://www.bedetheque.com/media/Couvertures/Couv_161038.jpg', NULL);
INSERT INTO public.bd VALUES (1487, 'Gai-Luron', 'INTFL1', 'Gai-Luron ... ou la joie de vivre / Gai-Luron en écrase méchamment', 'Gotlib', '2724255801', '02/1993', 191, 'https://www.bedetheque.com/media/Couvertures/gailuronfljoiedevivre.jpg', NULL);
INSERT INTO public.bd VALUES (1489, 'Doraemon, le Chat venu du Futur', '1', 'Tome 1', 'Fujiko F. Fujio', '287129920X', '01/2006 (Parution le 06/07/2007)', 189, 'https://www.bedetheque.com/media/Couvertures/Couv_67611.jpg', 'Nobita, jeune garçon assez gaffeur et maladroit, voit un jour débarquer chez lui DORAemon, un chat-robot venu du futur. Sa mission : sauver Nobita d''une terrible destinée et donc l''aider dans la vie de tous les jours. Ce n''est pas de tout repos et risque bien d''être drôle !! Doraemon, série culte au Japon arrive enfin en manga ! Une série pour tous les âges à déguster sans modération !');
INSERT INTO public.bd VALUES (1490, 'Doraemon, le Chat venu du Futur', '2', 'Tome 2', 'Fujiko F. Fujio', '2871299382', '05/2007 (Parution le 07/09/2007)', 189, 'https://www.bedetheque.com/media/Couvertures/Couv_67612.jpg', 'Catastrophe ! Nobita n''a pas étudié et deux contrôles sont prévus pour le lendemain ! DORAemon lui vient en aide avec son "rappel-pain",  une invention venue du futur. Mieux qu''un pense-bête, celui qui mange une tranche de ce pain posée sur un cahier se souvient du contenu des pages. Nobita aura-t-il assez d''appétit pour passer ses examens ?');
INSERT INTO public.bd VALUES (1491, 'Doraemon, le Chat venu du Futur', '3', 'Tome 3', 'Fujiko F. Fujio', '9782871299561', '05/2006 (Parution le 02/11/2007)', 189, 'https://www.bedetheque.com/media/Couvertures/Couv_76118.jpg', 'Dans la première histoire, le Lion masqué, le héro de manga préféré de Nobita, est en mauvaise posture ! Quel supplice pour Doraemon et Nobita qui ne peuvent pas se résoudre à patienter jusqu''à la prochaine publication. Doraemon décide de rendre visite à l''auteur de la série. Peine perdue, celui-ci est en panne d''inspiration. Doreamon se rend alors dans le futur pour lire la suite de l''histoire. !! Dans la foulée, nos deux compères testeront, entre autres, le "calendrier modifiable", "l''appareil à mensonges" ou "la machine à échanger les mamans"....');
INSERT INTO public.bd VALUES (1492, 'Doraemon, le Chat venu du Futur', '4', 'Tome 4', 'Fujiko F. Fujio', '9782871299578', '05/2006 (Parution le 11/01/2008)', 189, 'https://www.bedetheque.com/media/Couvertures/Couv_76119.jpg', 'Les aventures de Nobita se poursuivent au rythme des inventions fournies par Doraemon : "l''appareil photo maudit" fera subir bien des tourments à nos amis, quant au "mensonge qui dit vrai", il permettra à Nobita d''épater ses amis !! Découvrez également des petits soldats de plombs chargés de protéger Nobita de Giant et qui se révèleront un peu trop zélés ! Bien d''autres péripéties attendent nos amis dans ce tome hilarant !');
INSERT INTO public.bd VALUES (1493, 'Doraemon, le Chat venu du Futur', '5', 'Tome 5', 'Fujiko F. Fujio', '9782871299585', '05/2006 (Parution le 21/03/2008)', 189, 'https://www.bedetheque.com/media/Couvertures/Couv_76120.jpg', 'Nobita est encore à la traîne pour ses devoirs ! Doraemon lui propose de prendre des médicaments du futur afin d''accélérer son rythme de travail. Nobita demande une démonstration à Doraemon. Découvrez, entre autres, dans ce tome, la peinture de la pesanteur, qui permet de défier la gravité et qui se révèle très utile pour gagner de la place ! Le procédé de fabrication de la terre, un miroir qui fabrique une copie de ce qu''il reflète et le marteau souvenir, pour ne citer qu''eux, feront également vivre d''étonnantes aventures à nos deux amis !!');
INSERT INTO public.bd VALUES (1494, 'Doraemon, le Chat venu du Futur', '6', 'Tome 6', 'Fujiko F. Fujio', '9782505003328', '05/2008 (Parution le 02/05/2008)', 189, 'https://www.bedetheque.com/media/Couvertures/Couv_76121.jpg', 'La nouvelle lubie de Nobita pour profiter un maximum de ses journées est de ne plus dormir ! Pour cela, il prend les pilules 24h et s''il s''ennuie durant la nuit, le bâton de somnambule lui permettra de s''amuser aux dépends des dormeurs !  D''autres aventures vous attendent dans ce tome, parmi celles-ci : le virus de la mode qui permettra à Nobita et Doraemon de jouer avec les tendances et l''appareil de voyage de chambre qui emmènera la famille Nobi aux sources thermales !');
INSERT INTO public.bd VALUES (1495, 'Doraemon, le Chat venu du Futur', '7', 'Tome 7', 'Fujiko F. Fujio', '9782505003199', '07/2008 (Parution le 04/07/2008)', 189, 'https://www.bedetheque.com/media/Couvertures/Couv_76122.jpg', 'Depuis le départ de Doraemon, Nobita est abattu. Pour ne rien arranger, Suneo et Giant prennent un malin plaisir à tourmenter le jeune garçon. Prévoyant, Doraemon a laissé avant de partir une dernière invention pour Nobita: le mensonge 800, des pilules qui provoquent le contraire de ce que dit celui qui les utilise ! Nobita parviendra non seulement à se venger mais également à faire revenir son ami ! Tous deux vivront d''autres aventures au fil de ce volume: des lutins robots qui travaillent durant le sommeil de leur propriétaire aideront Nobita,...');
INSERT INTO public.bd VALUES (1496, 'Doraemon, le Chat venu du Futur', '8', 'Tome 8', 'Fujiko F. Fujio', '9782505003922', '09/2008 (Parution le 05/09/2008)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_82148.jpg', 'Nobita et Doraemon vivent des aventures vraiment délirantes. Doraemon n''est jamais à court d''inventions loufoques pour résoudre les problèmes de son jeune ami !  Mais cette fois encore, malgré le chiffon qui réfléchit à retardement, le sketch-briquet ou la montre folle, nos deux compères devront faire face à de très droles retournements de situation !');
INSERT INTO public.bd VALUES (1497, 'Doraemon, le Chat venu du Futur', '9', 'Tome 9', 'Fujiko F. Fujio', '9782505003939', '11/2008 (Parution le 14/11/2008)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_82149.jpg', 'Quelque soit l''invention que Doraemon ramène du futur pour aider Nobita, il semble qu''entre les mains du jeune garçon, la plus parfaite des machines se détraque et se retourne contre lui ! Pour preuve, l''utilisation du micro émouvant mettra Nobita dans une situation plutôt embarrassante ! Sans parler du cerceau à traverser, des posters du futur ou de la fleur oublie-tout qui tous joueront des mauvais tours à nos deux amis. !');
INSERT INTO public.bd VALUES (1498, 'Doraemon, le Chat venu du Futur', '10', 'Tome 10', 'Fujiko F. Fujio', '9782505005445', '01/2009 (Parution le 20/03/2009)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_113626.jpg', 'L''heure est grave ! Une terrible rumeur circule ! Giant préparerait un récital pour son prochain concert. Un concert de trois heures qu''il compte donner devant tous ses amis ! Nobita et ses amis sont terrorisés à l''idée d''entendre chanter ce petit caïd ! Heureusement, DORAemon a plus d''un tour dans son sac et utilisera des bonbons à retardement pour éviter le pire ! Mais attention aux effets contraires de ces friandises ! Une astuce parmi tant d''autres que DORAemon proposera à Nobita pour s''extirper des situations les plus farfelues !');
INSERT INTO public.bd VALUES (1499, 'Doraemon, le Chat venu du Futur', '11', 'Tome 11', 'Fujiko F. Fujio', '9782505005810', '07/2009 (Parution le 03/07/2009)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_113628.jpg', 'Tous les ans c''est la même chose ! Pour les fêtes du nouvel an, Nobita et ses amis jouent au cerf-volant ou au hanetsuki, mais Nobita ne cesse de perdre. Ce qu''il aimerait que ces jeux n''existent pas ! Une volonté qui sera vite exaucée par son ami Doraemon. Mais cela ne va pas vraiment se passer comme prévu.');
INSERT INTO public.bd VALUES (1500, 'Doraemon, le Chat venu du Futur', '12', 'Tome 12', 'Fujiko F. Fujio', '9782505006978', '11/2009 (Parution le 06/11/2009)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_113627.jpg', 'Nobita et ses amis sont bien embêtés ! Kuro, un chat de gouttière, n’en finit plus de leur voler leur nourriture! C’en est trop pour DORAemon qui décide d’en finir en utilisant un missile télé-guidé impossible à semer. Nobita, qui trouve cet objet bien pratique, choisit également de l’utiliser mais cette fois contre Giant. Aurait-il trouvé l’arme ultime pour se débarrasser de ce caïd ?');
INSERT INTO public.bd VALUES (1534, 'Détective Conan', '1', 'Tome 1', 'Aoyama, Gôshô', '2871291284', '04/1997', 180, 'https://www.bedetheque.com/media/Couvertures/DetectiveConan1a_08122004.jpg', NULL);
INSERT INTO public.bd VALUES (1501, 'Doraemon, le Chat venu du Futur', '13', 'Tome 13', 'Fujiko F. Fujio', '9782505006985', '05/2010 (Parution le 07/05/2010)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_106709.jpg', 'Nobita s’ennuie, il veut de l’aventure, dehors le monde est trop paisible... Trop calme... Doraemon lui propose alors d’enfiler le “manteau qui en fait trop” ! Le quotidien tranquille de Nobita se transforme en véritable jungle, un cafard devient un scorpion, un chien se transforme en lion... Mais Nobita n’est pas aussi courageux qu’il le pense !');
INSERT INTO public.bd VALUES (1502, 'Doraemon, le Chat venu du Futur', '14', 'Tome 14', 'Fujiko F. Fujio', '9782505006992', '11/2010', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_117922.jpg', 'Nobita s’ennuie, il veut de l’aventure, dehors le monde est trop paisible... Trop calme... Doraemon lui propose alors d’enfiler le “manteau qui en fait trop” ! Le quotidien tranquille de Nobita se transforme en véritable jungle, un cafard devient un scorpion, un chien se transforme en lion... Mais Nobita n’est pas aussi courageux qu’il le pense !');
INSERT INTO public.bd VALUES (1503, 'Doraemon, le Chat venu du Futur', '15', 'Tome 15', 'Fujiko F. Fujio', '9782505007005', '05/2011 (Parution le 06/05/2011)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_126820.jpg', 'Nobita est un jeune garçon assez irresponsable, complètement gaffeur et maladroit. Il est, de plus, régulièrement grondé par sa mère et ses professeurs à cause des mauvais plans qu''il imagine souvent. Un jour, pourtant, débarque dans sa vie un chat-robot venu du futur. Il se nomme DORAemon, porte toujours une clochette autour du coup et a la particularité d''avoir des mains toutes rondes. DORAemon est en fait envoyé par le futur petit-fils de Nobita. Sa mission sur Terre : sauver Nobita de ses échecs successifs et donc sauver la famille de la déchéance....');
INSERT INTO public.bd VALUES (1504, 'Doraemon, le Chat venu du Futur', '16', 'Tome 16', 'Fujiko F. Fujio', '9782505012436', '10/2011 (Parution le 07/10/2011)', 184, 'https://www.bedetheque.com/media/Couvertures/141726_c.jpg', 'Nobita est un jeune garçon assez irresponsable, complètement gaffeur et maladroit. Il est, de plus, régulièrement grondé par sa mère et ses professeurs à cause des mauvais plans qu''il imagine souvent. Un jour, pourtant, débarque dans sa vie un chat-robot venu du futur. Il se nomme DORAemon, porte toujours une clochette autour du coup et a la particularité d''avoir des mains toutes rondes. DORAemon est en fait envoyé par le futur petit-fils de Nobita. Sa mission sur Terre : sauver Nobita de ses échecs successifs et donc sauver la famille de la déchéance....');
