INSERT INTO public.bd VALUES (1524, 'Doraemon, le Chat venu du Futur', '36', 'Tome 36', 'Fujiko F. Fujio', '9782505068297', '04/2017 (Parution le 21/04/2017)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_303858.jpg', 'Nobita, jeune garçon assez gaffeur et maladroit, voit un jour débarquer chez lui Doraemon, un chat-robot venu du futur. Sa mission : sauver Nobita d''une terrible destinée et donc l''aider dans la vie de tous les jours. Ce n''est pas de tout repos et risque bien d''être drôle !! Doraemon, série culte au Japon et déjà diffusée en dessin animé chez nous, arrive enfin en manga ! Une série pour tous les âges à déguster sans modération !');
INSERT INTO public.bd VALUES (1525, 'Doraemon, le Chat venu du Futur', '37', 'Tome 37', 'Fujiko F. Fujio', '9782505068303', '06/2017 (Parution le 23/06/2017)', 187, 'https://www.bedetheque.com/media/Couvertures/Couv_306237.jpg', NULL);
INSERT INTO public.bd VALUES (1526, 'Doraemon, le Chat venu du Futur', '38', 'Tome 38', 'Fujiko F. Fujio', '9782505068310', '08/2017 (Parution le 18/08/2017)', 187, 'https://www.bedetheque.com/media/Couvertures/Couv_308727.jpg', NULL);
INSERT INTO public.bd VALUES (1527, 'Doraemon, le Chat venu du Futur', '39', 'Tome 39', 'Fujiko F. Fujio', '9782505068327', '10/2017 (Parution le 06/10/2017)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_313386.jpg', 'Doraemon, le chat du futur, possède toujours une invention loufoque pour aider Nobita à s''amuser. Encore faut-il savoir utiliser ces technologies aux effets surprenants ! Qu''il s''agisse d''une machine à fabriquer les engins, de bonbons éducateurs ou encore de caméra de la victoire, tout présage de nouvelles aventures bien farfelues !');
