INSERT INTO public.bd VALUES (1530, 'Doraemon, le Chat venu du Futur', '42', 'Tome 42', 'Fujiko F. Fujio', '9782505070085', '04/2018 (Parution le 06/04/2018)', 186, 'https://www.bedetheque.com/media/Couvertures/Couv_328655.jpg', 'Doraemon, le chat du futur, possède toujours une invention loufoque pour aider Nobita à s’amuser. Encore faut-il savoir utiliser ces technologies aux effets surprenants ! Qu’il s’agisse d’une machine à fabriquer les engins, de bonbons éducateurs ou encore de caméra de la victoire, tout présage de nouvelles aventures bien farfelues.');
INSERT INTO public.bd VALUES (1531, 'Doraemon, le Chat venu du Futur', '43', 'Tome 43', 'Fujiko F. Fujio', '9782505070092', '06/2018 (Parution le 08/06/2018)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_335816.jpg', 'Suite des aventures humoristiques du chat bleu et rondouillard, dans lesquelles quiproquos et situations cocasses s''enchaînent pour servir la morale finale.');
