INSERT INTO public.bd VALUES (1801, 'DC Comics - Le Meilleur des Super-Héros', 'Premium07', 'Green Lantern - Tome 5 - Sinestro', 'Johns, Geoff', '9792723257854', '02/2021', 282, 'https://www.bedetheque.com/media/Couvertures/Couv_416510.jpg', NULL);
INSERT INTO public.bd VALUES (1802, 'DC Comics - La légende de Batman', '11', 'L''An zéro - 1re partie', 'Snyder, Scott', '2944287788', '08/2017 (Parution le 16/08/2017)', 132, 'https://www.bedetheque.com/media/Couvertures/Couv_309124.jpg', 'Lorsque Bruce Wayne revint à Gotham, il y a quelques années de cela, personne ne pouvait penser que l''héritier Wayne allait tenter de lutter contre le crime. Il a fait face au célèbre gang de Red Hood qui a commencé par de petits larcins et qui petit à petit, sur l''influence de son chef, a su prendre de l''ampleur. Le gang Red Hood s''attaque à un dirigeable où se trouvent des membres de la famille Falcone et Cobblepot...');
