INSERT INTO public.bd VALUES (1906, 'DC Comics - La légende de Batman', 'HS02', 'Batman Eternal - 2e partie', 'Snyder, Scott', '9782756419695', '04/2018', 290, 'https://www.bedetheque.com/media/Couvertures/Couv_329487.jpg', NULL);
