INSERT INTO public.bd VALUES (1917, 'DC Comics - La légende de Batman', 'Premium02', 'Batman - Tome 2 - Le Garde du corps', 'Rucka, Greg', '9782756764023', '03/2019', 270, 'https://www.bedetheque.com/media/Couvertures/Couv_362492.jpg', NULL);
INSERT INTO public.bd VALUES (1918, 'DC Comics - La légende de Batman', 'Premium03', 'Meurtrier', 'Grayson, Devin', '2932851101', '12/2019 (Parution le 01/12/2019)', 451, 'https://www.bedetheque.com/media/Couvertures/Couv_384894.jpg', NULL);
INSERT INTO public.bd VALUES (1919, 'DC Comics - La légende de Batman', 'Premium04', 'Fugitif', 'Rucka, Greg', '2841598179', '10/2020 (Parution le 20/10/2020)', 452, 'https://www.bedetheque.com/media/Couvertures/Couv_416026.jpg', 'Trois mois ont passé depuis le meurtre de Vesper Fairchild, et Bruce Wayne demeure introuvable. Sillonnant les rues à la recherche de nouveaux indices pour innocenter son alter ego, le Chevalier Noir va croiser la route d''Azrael, une rencontre qui lui réserve bien des surprises...');
