INSERT INTO public.bd VALUES (2020, 'Léonard', '23', 'Poil au génie !', 'De Groot, Bob', '2884250047', '09/1993', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_236.jpg', 'Un matin, en essayant une nouvelle solution pour enlever les poils, notre pauvre disciple perd le peu de cheveux qu''il lui reste sur le crâne. Mais les problèmes capillaires chez le génie ne durent jamais très longtemps ! Aussitôt, il trouve une lotion pour les faire repousser. Tout va bien qui finit bien donc ! A moins que...');
INSERT INTO public.bd VALUES (2021, 'Léonard', '24', 'Temps de génie', 'De Groot, Bob', '2884250050', '09/1994', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_613.jpg', NULL);
