INSERT INTO public.bd VALUES (2437, 'Schtroumpfs (Les)', '1', 'Les Schtroumpfs noirs', 'Peyo', '2800101083', '01/1963', 60, 'https://www.bedetheque.com/media/Couvertures/schtroumpfs01_333.jpg', NULL);
INSERT INTO public.bd VALUES (2438, 'Schtroumpfs (Les)', '2', 'Le Schtroumpfissime', 'Peyo', '2800101091', '01/1965', 60, 'https://www.bedetheque.com/media/Couvertures/schtroumpfscou02.jpg', NULL);
INSERT INTO public.bd VALUES (2439, 'Schtroumpfs (Les)', '3', 'La Schtroumpfette', 'Peyo', '2800101105', '01/1967', 60, 'https://www.bedetheque.com/media/Couvertures/SchtroumpfsLes03.jpg', NULL);
INSERT INTO public.bd VALUES (2440, 'Schtroumpfs (Les)', '4', 'L''œuf et les Schtroumpfs', 'Delporte, Yvan', '2238389679', '01/1968', 60, 'https://www.bedetheque.com/media/Couvertures/schtroumpfs04eo_5455.jpg', NULL);
INSERT INTO public.bd VALUES (2448, 'Schtroumpfs (Les)', '12', 'Le bébé schtroumpf', 'Peyo', '2800111488', '10/1984', 44, 'https://www.bedetheque.com/media/Couvertures/SchtroumpfsLes12.jpg', '"Le Bébé Schtroumpf" (20 pl.), "Et Le schtroumpf bricoleur" (8 pl.), "La peinture schtroumpf" (8 pl.) & "Une fête schtroumpfante" (8 pl.).');
INSERT INTO public.bd VALUES (2449, 'Schtroumpfs (Les)', '13', 'Les p''tits Schtroumpfs', 'Peyo', '2800115696', '04/1988', 41, 'https://www.bedetheque.com/media/Couvertures/SchtroumpfsLes13.jpg', '2 histoires (41 planches - Dessin & scénario de Peyo) : "Les p''tits Schtroumpfs" (24 pl.) & "Le Schtroumpf robot" (17 pl.).');
INSERT INTO public.bd VALUES (2450, 'Schtroumpfs (Les)', '14', 'L''aéroschtroumpf', 'Peyo', '2873450002', '03/1990', 40, 'https://www.bedetheque.com/media/Couvertures/SchtroumpfsLes14.jpg', '"L''aéroschtroumpf" (8 pl.), "La gourmandise chez les schtroumpfs" (8 pl.), "Le schtroumpfeur masqué" (8 pl.), "Puppy et les schtroumpfs" (8 pl.) & "Les farces du Schtroumpf farceur" (8 pl.).');
INSERT INTO public.bd VALUES (2451, 'Schtroumpfs (Les)', '15', 'L''Étrange Réveil du Schtroumpf paresseux', 'Peyo', '287345024X', '04/1991', 42, 'https://www.bedetheque.com/media/Couvertures/Couv_46028.jpg', '"L''étrange réveil du Schtroumpf paresseux" (8 pl.), "Le petit train des schtroumpfs" (8 pl.), "Le schtroumpf et son dragon" (8 pl.), "Les schtroumpfs pompiers" (8 pl.) & "Une taupe chez les schtroumpfs" (8 pl.).');
INSERT INTO public.bd VALUES (2452, 'Schtroumpfs (Les)', '16', 'Le schtroumpf financier', 'Culliford, Thierry', '2803610175', '11/1992 (Parution le 25/11/1992)', 44, 'https://www.bedetheque.com/media/Couvertures/SchtroumpfsLes16.jpg', NULL);
INSERT INTO public.bd VALUES (2453, 'Schtroumpfs (Les)', '17', 'Le schtroumpfeur de bijoux', 'Culliford, Thierry', '2803610981', '11/1994', 44, 'https://www.bedetheque.com/media/Couvertures/schtroumpfs17.jpg', 'C’est l’effervescence dans le village des Schtroumpfs à la veille de la fête de l’équinoxe de printemps. Le Grand Schtroumpf envoie le Schtroumpf à Lunettes et le Schtroumpf Farceur chercher des tiges de massettes pour les préparatifs. Mais, arrivés au gué, les deux lutins tombent à l’eau et le Schtroumpf Farceur perd connaissance. Son ami tente de l’aider mais un forain passe au même moment. Son fils découvre le Schtroumpf Farceur et l’emmène. Voici notre lutin soudain condamné à animer des spectacles de rue dans différentes cités de la région....');
INSERT INTO public.bd VALUES (2454, 'Schtroumpfs (Les)', '18', 'Docteur Schtroumpf', 'Culliford, Thierry', '280361216X', '10/1996', 44, 'https://www.bedetheque.com/media/Couvertures/SchtroumpfsLes18.jpg', 'Au village des petits Schtroumpfs, tout le monde vaque à ses occupations. Schtroumpf maladroit vient de se prendre un coup de masse sur la tête, Schtroumpf bricoleur, en face, ne se formalise même plus, après tout, il a schtroumpfement l’habitude ! Le Grand Schtroumpf le soigne … Bref, tout semble respire la quiétude et la tranquillité. Et puis un jour, ne voilà t’il pas qu’un Schtroumpf décide de se schtroumpfer à la médecine… Mais voilà que le grand sSchtroumpf tombe malade… Et que la zizanie se répand dans le village… Parce qu’évidemment on...');
INSERT INTO public.bd VALUES (2455, 'Schtroumpfs (Les)', '19', 'Le Schtroumpf sauvage', 'Culliford, Thierry', '2803613514', '11/1998', 44, 'https://www.bedetheque.com/media/Couvertures/schtroumpfs19.jpg', 'Un incendie de forêt menace de détruire le village des Schtroumpfs. Afin de la sauver, ses habitants décident d’ouvrir le barrage, éteignant ainsi le feu. Hélas, tout est dévasté. Hormis la reconstruction, il faut aussi songer à refaire des réserves de vivres pour l’hiver. La forêt étant calciné autour du village, les Schtroumpfs doivent s’engager dans des bois plus éloignés où ils ne sont jamais allés. Ils vont y découvrir un habitant auquel ils ne s’attendaient pas.');
INSERT INTO public.bd VALUES (2456, 'Schtroumpfs (Les)', '20', 'La menace Schtroumpf', 'Culliford, Thierry', '2803615169', '11/2000', 44, 'https://www.bedetheque.com/media/Couvertures/schtroumpfs20.jpg', NULL);
INSERT INTO public.bd VALUES (2457, 'Schtroumpfs (Les)', '21', 'On ne schtroumpfe pas le progrès', 'Culliford, Thierry', '2803617730', '11/2002', 44, 'https://www.bedetheque.com/media/Couvertures/schtroumpf21.jpg', NULL);
INSERT INTO public.bd VALUES (2458, 'Schtroumpfs (Les)', '22', 'Le Schtroumpf reporter', 'Culliford, Thierry', '2803619008', '11/2003', 44, 'https://www.bedetheque.com/media/Couvertures/schtroumpfs22.jpg', NULL);
INSERT INTO public.bd VALUES (2459, 'Schtroumpfs (Les)', '23', 'Les Schtroumpfs joueurs', 'Parthoens, Luc', '2803620057', '01/2005', 44, 'https://www.bedetheque.com/media/Couvertures/SchtroumpfsLes23_26012005.jpg', 'De retour d''une virée chez les humains, quelques Schtroumpfs reviennent avec une idée complètement saugrenue, inspirée fortement par la bêtise des hommes. Et cette fois-ci, l''exception n''est pas encore de mise. Trois Schtroumpfs ont assisté à un tournoi organisé par un comte dévoré par la passion du jeu, et de retour chez eux, ils commencent à communiquer cette passion à tous les Schtroumpfs. Ce qui n''était qu''un loisir devient vite dangereux, les Schtroumpfs pariant sur tout et n''importe quoi, et certains d''entre eux en viennent vite à accumuler...');
INSERT INTO public.bd VALUES (2460, 'Schtroumpfs (Les)', '24', 'Salade de Schtroumpfs', 'Culliford, Thierry', '9782803621552', '01/2006', 44, 'https://www.bedetheque.com/media/Couvertures/schtroumpfs24.jpg', NULL);
INSERT INTO public.bd VALUES (2461, 'Schtroumpfs (Les)', '25', 'Un enfant chez les Schtroumpfs', 'Culliford, Thierry', '9782803622429', '01/2007', 46, 'https://www.bedetheque.com/media/Couvertures/schtroumpfs25.jpg', 'La Cigogne, qui tentait péniblement de ramener le Grand Schtroumpf au village, est surprise par un orage et blessée. Un fermier des environs du village soigne l''animal. Sa gentillesse est aussi grande que la méchanceté de son neveu est terrible. Jeanty, le neveu, débarque par erreur dans le village des petits lutins bleus et y sème une pagaille incommensurable...');
INSERT INTO public.bd VALUES (2462, 'Schtroumpfs (Les)', '26', 'Les Schtroumpfs et le livre qui dit tout', 'Culliford, Thierry', '9782803623822', '01/2008', 46, 'https://www.bedetheque.com/media/Couvertures/schtroumpfs26.jpg', 'Le Grand Schtroumpf étant absent, le Schtroumpf à lunettes fait le grand ménage dans son laboratoire. Il y découvre un livre qui parle et un livre qui sait tout et dit tout. Il en profite pour mettre les autres Schtroumpfs à ses ordres. Mais voilà, ce livre peut être dangereux et d''ailleurs, beaucoup de bêtises sont commises. Par contre, plus personne ne surveille le barrage et une catastrophe risque d''arriver. Seul le grand Schtroumpf peut les sortir de cette situation. Mais le fera-t-il ?');
INSERT INTO public.bd VALUES (2463, 'Schtroumpfs (Les)', '27', 'Schtroumpf les bains', 'Culliford, Thierry', '9782803625215', '04/2009', 46, 'https://www.bedetheque.com/media/Couvertures/SchtroumpfsLes27_09042009_232457.jpg', NULL);
INSERT INTO public.bd VALUES (2464, 'Schtroumpfs (Les)', '28', 'La Grande Schtroumpfette', 'Jost, Alain', '9782803626489', '04/2010 (Parution le 16/04/2010)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_107065.jpg', 'Ce n’est as tous les jours facile d''être l’élément féminin  dans un monde de Schtroumpfs ! Une série de réflexions malheureuses et la Schtroumpfette réalise  soudain que, si les Schtroumpfs l’adorent, ils ne la prennent pas du tout au sérieux. Pour lui donner l’occasion de s’affirmer, le Grand Schtroumpf annonce qu’il s’absente et qu’il l’a choisie comme remplaçante. Chez les Schtroumpfs, ce choix passe très mal ! Pendant ce temps, une comète chevelue brille au firmament et Gargamel doit passer un examen de sorcellerie. Cela paraît sans rapport...');
INSERT INTO public.bd VALUES (2567, 'Buck Danny', '29', 'Opération "Mercury"', 'Charlier, Jean-Michel', '2201781397', '01/1964', 44, 'https://www.bedetheque.com/media/Couvertures/BuckDannyOperationMercu_16022004.jpg', NULL);
INSERT INTO public.bd VALUES (2568, 'Buck Danny', '30', 'Les voleurs de satellites', 'Charlier, Jean-Michel', '2730104410', '01/1964', 45, 'https://www.bedetheque.com/media/Couvertures/BuckDanny30.jpg', NULL);
INSERT INTO public.bd VALUES (2465, 'Schtroumpfs (Les)', '29', 'Les Schtroumpfs et l''arbre d''or', 'Jost, Alain', '9782803628070', '04/2011 (Parution le 08/04/2011)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_125174.jpg', 'Une nouvelle année démarre chez les Schtroumpfs autour de la traditionnelle fête de l''Arbre d''Or. Mais, la foudre vient réduire le précieux totem en cendres et, à en croire le Schtroumpf Peureux, ce mauvais présage annonce une année de malheur ! La superstition s''empare bien vite du village et chacun y va de son gri-gri, du rituel ancestral et autres prédictions astrales. Le Grand Schtroumpf va devoir trouver un moyen d''inverser la tendance...  Décidément, les lutins de Peyo sont schtroumpfement humains, lorsqu''ils s''y mettent !');
INSERT INTO public.bd VALUES (2466, 'Schtroumpfs (Les)', '30', 'Les Schtroumpfs de l''ordre', 'Jost, Alain', '9782803630523', '03/2012 (Parution le 23/03/2012)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_152802.jpg', 'La vie des Schtroumpfs est très paisible. S''ils se querellent pour des broutilles, c''est peut-être par ennui ? Mais le Grand Schtroumpf est fatigué de devoir régler leurs conflits. Il lui vient l''idée de créer un « Code Schtroumpf », un règlement accepté par tous. Accepté, mais pas appliqué ! Il nomme alors deux Schtroumpfs de l''ordre, chargés de noter les contraventions et de distribuer des amendes. Pauvre Grand Schtroumpf ! Il ne réalise pas que son idée va avoir des conséquences dramatiques...');
INSERT INTO public.bd VALUES (2467, 'Schtroumpfs (Les)', '31', 'Les Schtroumpfs à Pilulit', 'Jost, Alain', '9782803632558', '04/2013 (Parution le 19/04/2013)', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_185273.jpg', 'Le Schtroumpf Poète se lance dans la fiction ! C''est lui qui raconte cette incroyable aventure... Au bord de la rivière, les Schtroumpfs rencontrent un peuple de minuscules cueilleurs de graines : les Pilus. Face à eux, les lutins bleus ont l''impression d''être des géants ! Si les premiers rapports sont un peu tendus, les deux groupes vont vite se lier d''amitié. Bien sûr, les différences de langue, de goûts et de coutumes provoquent quelques accrochages. Mais ça, comme dit le Schtroumpf à Lunettes, c''est le schtroumpf des cultures ! Au moment où...');
INSERT INTO public.bd VALUES (2468, 'Schtroumpfs (Les)', '32', 'Les Schtroumpfs et l''Amour Sorcier', 'Jost, Alain', '9782803634156', '04/2014 (Parution le 04/04/2014)', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_210707.jpg', 'Après avoir évité plusieurs pièges tendus en forêt par Gargamel, Le Grand Schtroumpf s''est mis en tête de trouver une femme pour le sorcier dans l''espoir que ce dernier cesse enfin de chercher querelle aux lutins bleus.. Mais la quête de l''amour comme remède ne va pas tout à fait se passer comme il l''espère ... bien au contraire !');
INSERT INTO public.bd VALUES (2469, 'Schtroumpfs (Les)', '33', 'Schtroumpf le héros', 'Jost, Alain', '9782803635436', '03/2015 (Parution le 13/03/2015)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_231403.jpg', 'Dans un grenier, les Schtroumpfs retrouvent un très vieux livre qui raconte les aventures d''un Schtroumpf aventurier qui se rend au lointain Mont du Dragon. Après s''être baigné dans l''eau rouge d''une source, il devient une sorte de Surschtroumpf, insensible à la peur, à la fatigue et à la douleur. Trois Schtroumpfs, fatigués des moqueries dont ils sont victimes, décident de se rendre à la source pour devenir eux aussi des héros !');
INSERT INTO public.bd VALUES (2470, 'Schtroumpfs (Les)', '34', 'Les Schtroumpfs et le demi-génie', 'Jost, Alain', '9782803636907', '04/2016 (Parution le 01/04/2016)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_277300.jpg', 'Au fond d''un étang, le Schtroumpf Costaud et le Schtroumpf à Lunettes découvrent une vieille amphore bouchée à la cire. En la vidant, ils ne trouvent que quelques cailloux gris. Mais elle contient aussi une petite perle d''où surgit un génie ! Hélas, ce génie qui doit maintenant exaucer leurs vœux a perdu la mémoire. Et, surtout, il fait tout à moitié ! Les Schtroumpfs vont bientôt comprendre pourquoi...');
INSERT INTO public.bd VALUES (2471, 'Schtroumpfs (Les)', '35', 'Les Schtroumpfs et les haricots mauves', 'Jost, Alain', '9782803671144', '08/2017 (Parution le 18/08/2017)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_309115.jpg', 'Suite à des récoltes désastreuses, les Schtroumpfs ont frôlé la famine en hiver. Le Mage Homnibus leur procure de petits haricots mauves venus d''un pays lointain, qui poussent à profusion par tous les temps. Le Schtroumpf Paysan les plante en secret et obtient une récolte phénoménale. Mais les Schtroumpfs voudront-ils se nourrir de haricots secs ? Le Schtroumpf Cuisinier leur mijote quelques plats raffinés et le succès est total ! À tel point que, bientôt, les Schtroumpfs mangent des haricots à tous les repas et ne cultivent plus rien d''autre....');
INSERT INTO public.bd VALUES (2472, 'Schtroumpfs (Les)', '36', 'Les Schtroumpfs et le dragon du lac', 'Jost, Alain', '9782803672844', '03/2018 (Parution le 02/03/2018)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_324703.jpg', 'Le Schtroumpf Costaud, qui fait de l''aviron sur le lac du barrage, aperçoit dans la brume la silhouette d''un monstre. Est-ce une hallucination ? Non ! Les Schtroumpfs rencontrent bientôt cette créature, un dragon, qui est d''ailleurs une de leurs vieilles connaissances.');
INSERT INTO public.bd VALUES (2473, 'Schtroumpfs (Les)', '37', 'Les Schtroumpfs et la machine à rêver', 'Jost, Alain', '9782803673131', '04/2019 (Parution le 05/04/2019)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_363098.jpg', 'Alors que les Schtroumpfs récoltent baies et champignons dans les bois, trois d''entre eux disparaissent. Ils rentrent tard le soir, dans un état bizarre. Le lendemain, la même situation se répète et ils sont six ! Le Schtroumpf à Lunettes perce le mystère : dans un arbre creux, ils ont découvert une plaque de cristal de roche qui leur permet, à l''aide de lunettes, de vivre leurs rêves les plus fous. Le Grand Schtroumpf pense qu''il s''agit d''un piège. Mais Gargamel n''est pas capable d''utiliser une telle magie... sauf s''il s''est trouvé un complice...');
INSERT INTO public.bd VALUES (2474, 'Schtroumpfs (Les)', '38', 'Les Schtroumpfs et le vol des cigognes', 'Jost, Alain', '9782803677153', '04/2020 (Parution le 12/06/2020)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_389767.jpg', 'Depuis très longtemps, les cigognes transportent les Schtroumpfs lors de leurs déplacements lointains. Cette fois encore, trois d''entre elles se dévouent pour conduire une délégation de Schtroumpfs chez le mage Homnibus à l''occasion de son anniversaire. Mais, pour le retour, les cigognes d''habitude si ponctuelles ne sont pas au rendez-vous...');
INSERT INTO public.bd VALUES (2475, 'Schtroumpfs (Les)', '39', 'Les schtroumpfs et la tempête blanche', 'Jost, Alain', '9782803680047', '10/2021 (Parution le 08/10/2021)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_432330.jpg', 'Comme chaque année, les premiers frimas sont attendus de pied ferme par les Schtroumpfs, qui se sont bien préparés. Mais personne ne s''attendait à un tel blizzard ! Partis tester une nouvelle luge, les Schtroumpfs Farceur, à Lunettes et Bricoleur se retrouvent coupés d''un village qui s''organise tant bien que mal. Ils trouvent refuge chez un sourcier acariâtre, qui a pourtant tout fait pour fuir la vie en communauté. Et si le salut des uns schtroumpfait par celui des autres ?');
INSERT INTO public.bd VALUES (2534, 'Astérix', '38', 'La Fille de Vercingétorix', 'Ferri, Jean-Yves', '9782864973423', '10/2019 (Parution le 24/10/2019)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_375114.jpg', 'Effervescence et chamboulements en perspective ! La fille du célèbre chef gaulois Vercingétorix, traquée par les Romains, trouve refuge dans le village des irréductibles gaulois, seul endroit dans la Gaule occupée à pouvoir assurer sa protection. Et le moins que l’on puisse dire, c’est que la présence de cette ado pas comme les autres va provoquer moult bouleversements intergénérationnels…');
INSERT INTO public.bd VALUES (2476, 'Schtroumpfs (Les)', '40', 'Les Schtroumpfs et les enfants perdus', 'Jost, Alain', '9782808203449', '10/2022 (Parution le 14/10/2022)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_455585.jpg', 'Y''aurait-il quelque chose de schtroumpf au royaume des Schtroumpfs ? Le Grand Schtroumpf est-il vraiment à la tête d''un trafic de sel de contrebande ?! Il a bel et bien plaidé coupable mais il faut se schtroumpfer des apparences... Si les lutins bleus ont agi ainsi, c''est pour protéger un groupe d''orphelins exploités par un couple peu scrupuleux. Et à présent, ils vont devoir trouver un moyen de confondre les véritables coupables sans priver leurs nouveaux amis du seul toit qu''ils aient.');
INSERT INTO public.bd VALUES (2477, 'Schtroumpfs (Les)', '41', 'Gargamel, l''ami des Schtroumpfs', 'Jost, Alain', '9782808211017', '10/2023 (Parution le 13/10/2023)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_483716.jpg', 'Coup de théâtre ! Gargamel a compris qu''il faisait fausse route et que capturer les Schtroumpfs ne lui permettrait pas de produire la pierre philosophale. Après une brève déprime bien compréhensible, le sorcier choisit de carrément retourner sa robe et d''aider les lutins bleus face à un nouveau péril : Georges-Louis Bouffon, un biologiste désireux d''étudier les Schtroumpfs... par tous les moyens. Mais peuvent-ils vraiment faire confiance à Gargamel...?');
INSERT INTO public.bd VALUES (2478, 'Schtroumpfs (Les)', '42', 'Les Schtroumpfs et la cape magique', 'Jost, Alain', '9782808213097', '10/2024 (Parution le 25/10/2024)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_506912.jpg', 'Un matin, après avoir été victime d''une mauvaise blague du Schtroumpf Farceur, le Schtroumpf Peureux se réveille en ne craignant plus rien ni personne. Quelques instants plus tard, c''est le Schtroumpf Gourmand qui perd l''appétit, et ensuite le Schtroumpf Paresseux qui devient hyperactif... Tous ont porté pendant quelques instants une vieille cape poussiéreuse trouvée dans une malle. Cette cape magique va très vite semer la zizanie dans le village !');
INSERT INTO public.bd VALUES (2479, 'Schtroumpfs (Les)', '43', 'Le trophée des schtroumpfs', 'Culliford, Thierry', '9782808214957', '08/2025 (Parution le 29/08/2025)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_523966.jpg', 'Le Schtroumpf discret en a assez de passer inaperçu ! Il aimerait qu''on le remarque dans le village. Lorsque le Grand Schtroumpf annonce le début d''une grande compétition intitulée ''''Trophée des Schtroumpfs'''', il décide de tenter sa chance afin d''être enfin reconnu à sa juste valeur. Mais la route est semée d''embûches et la concurrence est rude. Parviendra-t-il à devenir le Champion des Schtroumpfs ?');
INSERT INTO public.bd VALUES (2480, 'Schtroumpfs (Les)', 'HS', 'Le trésor des Schtroumpfs', '<Indéterminé>', '2828350088', '01/1961', 12, 'https://www.bedetheque.com/media/Couvertures/Couv_154352.jpg', NULL);
INSERT INTO public.bd VALUES (2481, 'Schtroumpfs (Les)', 'HS1', 'Les schtroumpfeurs de flûte', 'Culliford, Thierry', '9782803624720', '10/2008', 44, 'https://www.bedetheque.com/media/Couvertures/schtroumpfs_hs_01_sctroumpferdeflute_78618.jpg', 'Afin de guérir un paysan atteint de "Langueur Monotone", le sorcier Aldéric demande au Grand Schtroumpf de confectionner une flûte magique dont la mélodie pourra le sortir de cet état. Après avoir été guéri, le médecin du Bourg, jaloux du fait que la réputation du magicien l''éclipserait auprès de la population, vole l''objet. Il se met à en jouer pour faire accuser Aldéric de sorcellerie ...');
INSERT INTO public.bd VALUES (2482, 'Schtroumpfs (Les)', 'HS2', 'L''Encyclopédie des Schtroumpfs', 'Murray, Matt', '9782803628209', '11/2011 (Parution le 04/11/2011)', 128, 'https://www.bedetheque.com/media/Couvertures/Couv_144409.jpg', 'Quand les Schtroumpfs ont fait leur apparition dans une bande dessinée belge, en octobre 1958, personne n''aurait imaginé la renommée mondiale qui serait un jour la leur. La popularité des lutins bleus n''a fait que croître en Europe grâce aux albums et aux figurines, mais ce n''est que dans les années 80 que l''Amérique entière est tombée sous le charme, quand ils se sont affirmés comme les stars du samedi matin sur les écrans de la chaîne NBC. Plus de vingt ans après, les voici qui reviennet sur le grand écran dans un film en 3D où les images de...');
INSERT INTO public.bd VALUES (2483, 'Schtroumpfs (Les)', 'HS3', 'Édition Royale', 'Peyo', '9782810422067', '03/2017 (Parution le 29/03/2017)', 110, 'https://www.bedetheque.com/media/Couvertures/Couv_303345.jpg', NULL);
INSERT INTO public.bd VALUES (2484, 'Schtroumpfs (Les)', 'MBD07', 'Les Schtroumpfs - Le Monde de la BD - 07', 'Peyo', '2747419827', '12/2003 (Parution le 05/12/2003)', 199, 'https://www.bedetheque.com/media/Couvertures/Schtroumpfs_Pub_DH.jpg', NULL);
INSERT INTO public.bd VALUES (2485, 'Schtroumpfs (Les)', 'Pir', 'Benco et les Schtroumpfs', 'Peyo', '9782205008142', '02/2015', 32, 'https://www.bedetheque.com/media/Couvertures/Couv_243325.jpg', NULL);
INSERT INTO public.bd VALUES (2486, 'Schtroumpfs (Les)', 'Pir1', 'Les Schtroumpfs et le Bougloubou', 'Peyo', '280013190X', '01/2001', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_5453.jpg', '6 histoires : Les Schtroumpfs et le Bougloubou : Un gros oiseau exotique, le Bougloubou, sème la panique chez les Schtroumpfs une nuit. Le lendemain, il s’installe sur la cheminée de Gargamel, ce qui n’est pas pour plaire au méchant sorcier. Ce dernier se met en quête pour le déloger. - Olaf, le petit viking - La maman des Schtroumpfs - La course de cochons d''Inde - les Schtroumpfs et les petits fantômes - Gargamel et le crocodile -');
INSERT INTO public.bd VALUES (2487, 'Schtroumpfs (Les)', 'Pir2', 'Les P''tits Schtroumpfs sur la Lune', 'Peyo', '2800131918', '01/2001', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_5452.jpg', NULL);
INSERT INTO public.bd VALUES (2488, 'Schtroumpfs (Les)', 'Pir3', 'La Schtroumpfette et le Chevalier', 'Peyo', '2800132140', '07/2001', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_5454.jpg', NULL);
INSERT INTO public.bd VALUES (2489, 'Schtroumpfs (Les)', 'Pir4', 'La Piscine des Schtroumpfs', 'Peyo', '2800132159', '07/2001', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_6816.jpg', NULL);
INSERT INTO public.bd VALUES (2490, 'Schtroumpfs (Les)', 'Pub', 'Le Schtroumpf de l''espace', 'Peyo', '2830134745', '01/1996', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_46263.jpg', 'Le schtroumpf de l''espace, le schtroumpf menteur, football schtroumpf, le schtroumpf marin au pays des foumpfs, et le grand cirque des schtroumpfs');
INSERT INTO public.bd VALUES (2491, 'Schtroumpfs (Les)', 'Pub', 'Schtroumpfonie en Ut', 'Peyo', '9782800384078', '12/2015', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_299662.jpg', NULL);
