INSERT INTO public.bd VALUES (2576, 'Buck Danny', '38', 'La vallée de la mort verte', 'Charlier, Jean-Michel', '280010337X', '01/1973', 45, 'https://www.bedetheque.com/media/Couvertures/BuckDanny38f_23022005.jpg', NULL);
