INSERT INTO public.bd VALUES (2698, 'Michel Vaillant', 'sp04', 'Spécial 20e anniversaire', 'Graton, Jean', '2205011499', '01/1979', 80, 'https://www.bedetheque.com/media/Couvertures/mv20ans.jpg', NULL);
