INSERT INTO public.bd VALUES (2700, 'Inu Yasha', '2', 'Tome 2', 'Takahashi, Rumiko', '2871294054', '02/2002', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_23611.jpg', NULL);
INSERT INTO public.bd VALUES (2701, 'Inu Yasha', '3', 'Tome 3', 'Takahashi, Rumiko', '2871294186', '04/2002', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_23612.jpg', NULL);
INSERT INTO public.bd VALUES (2702, 'Inu Yasha', '4', 'Tome 4', 'Takahashi, Rumiko', '2871294283', '06/2002', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_23613.jpg', NULL);
INSERT INTO public.bd VALUES (2703, 'Inu Yasha', '5', 'Tome 5', 'Takahashi, Rumiko', '2871294348', '09/2002', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_23614.jpg', NULL);
INSERT INTO public.bd VALUES (2704, 'Inu Yasha', '6', 'Tome 6', 'Takahashi, Rumiko', '2871294453', '11/2002', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_23615.jpg', NULL);
INSERT INTO public.bd VALUES (2705, 'Inu Yasha', '7', 'Tome 7', 'Takahashi, Rumiko', '2871294933', '02/2003', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_23616.jpg', NULL);
INSERT INTO public.bd VALUES (2706, 'Inu Yasha', '8', 'Tome 8', 'Takahashi, Rumiko', '2871295220', '05/2003', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_25701.jpg', NULL);
INSERT INTO public.bd VALUES (2707, 'Inu Yasha', '9', 'Tome 9', 'Takahashi, Rumiko', '2871295433', '09/2003', 186, 'https://www.bedetheque.com/media/Couvertures/Couv_29455.jpg', NULL);
INSERT INTO public.bd VALUES (2708, 'Inu Yasha', '10', 'Tome 10', 'Takahashi, Rumiko', '2871295611', '12/2003', 184, 'https://www.bedetheque.com/media/Couvertures/Couv_31484.jpg', NULL);
INSERT INTO public.bd VALUES (2709, 'Inu Yasha', '11', 'Tome 11', 'Takahashi, Rumiko', '287129609X', '02/2004 (Parution le 07/02/2004)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_33220.jpg', 'Le petit frère de Sango que l''on croyait mort est, en fait, toujours vivant... L''ignoble Naraku, que rien n''arrête, s''apprête de nouveau à piéger Inu-Yasha. Inu-Yasha est en colère !!');
INSERT INTO public.bd VALUES (2710, 'Inu Yasha', '12', 'Tome 12', 'Takahashi, Rumiko', '2871296200', '04/2004 (Parution le 03/04/2004)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_34480.jpg', 'L''ignoble Naraku joue avec la sensibilité des gens pour les conduire dans des pièges machiavéliques. Contre cette incarnation du mal, Inu-Yasha fait exploser sa colère avec son Tessaïga!');
INSERT INTO public.bd VALUES (2711, 'Inu Yasha', '13', 'Tome 13', 'Takahashi, Rumiko', '2871296324', '06/2004 (Parution le 19/06/2004)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_36787.jpg', 'Kagome a réussi à blesser le maléfique Naraku à l''aide de son arc! Kikyô rôde dans les parages! Et un nouveau danger menace Inu-Yasha et ses amis!  Inu-Yasha va-t-il réussir à déployer la véritable puissance de son sabre magique, le Tessaïga.?!');
INSERT INTO public.bd VALUES (2712, 'Inu Yasha', '14', 'Tome 14', 'Takahashi, Rumiko', '287129643X', '08/2004 (Parution le 28/08/2004)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_38628.jpg', 'Un jeune chef d''une bande de démons, un certain Kôga, vient de kidnapper Kagome avec pour projet d''en faire son épouse. Inu-Yasha est furieux !');
INSERT INTO public.bd VALUES (2713, 'Inu Yasha', '15', 'Tome 15', 'Takahashi, Rumiko', '2871296545', '10/2004', 186, 'https://www.bedetheque.com/media/Couvertures/Couv_40281.jpg', NULL);
INSERT INTO public.bd VALUES (2714, 'Inu Yasha', '16', 'Tome 16', 'Takahashi, Rumiko', '2871296642', '11/2005', 186, 'https://www.bedetheque.com/media/Couvertures/Couv_51729.jpg', NULL);
INSERT INTO public.bd VALUES (2715, 'Inu Yasha', '17', 'Tome 17', 'Takahashi, Rumiko', '2871297142', '12/2005', 184, 'https://www.bedetheque.com/media/Couvertures/Couv_52367.jpg', NULL);
INSERT INTO public.bd VALUES (2716, 'Inu Yasha', '18', 'Tome 18', 'Takahashi, Rumiko', '2871297673', '02/2006', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_54928.jpg', NULL);
INSERT INTO public.bd VALUES (2717, 'Inu Yasha', '19', 'Tome 19', 'Takahashi, Rumiko', '2871297886', '04/2006', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_54929.jpg', NULL);
INSERT INTO public.bd VALUES (2722, 'Inu Yasha', '24', 'Tome 24', 'Takahashi, Rumiko', '2505000441', '02/2007 (Parution le 02/02/2007)', 186, 'https://www.bedetheque.com/media/Couvertures/Couv_62251.jpg', 'Kagome et ses amis poursuivent leurs intenses combats, lorsqu''un jour, ils font la rencontre de trois adorables petits singes. Étourdis, maladroits et impatients, ces derniers ont tout pour agacer ! Pourtant, ils sont si attachants que personne ne peut sérieusement leur en vouloir.');
INSERT INTO public.bd VALUES (2723, 'Inu Yasha', '25', 'Tome 25', 'Takahashi, Rumiko', '9782505000846', '04/2007 (Parution le 20/04/2007)', 182, 'https://www.bedetheque.com/media/Couvertures/Couv_63229.jpg', 'Les nouveaux adversaires d''Inu-Yasha sont de sinistres revenants qui se font appeler la bande des sept ! Ces fantômes multiplient les attaques sournoises et mettent sérieusement en danger la vie de nos héros !! D''autant que derrière ce nouvel obstacle se profile encore l''influence maléfique de Naraku !');
INSERT INTO public.bd VALUES (2724, 'Inu Yasha', '26', 'Tome 26', 'Takahashi, Rumiko', '9782505001119', '06/2007 (Parution le 01/06/2007)', 184, 'https://www.bedetheque.com/media/Couvertures/Couv_63551.jpg', 'Inu-Yasha et ses amis continuent à traquer Naraku ! En chemin, ils se font attaquer par la redoutable bande des sept. Et maintenant, ils vont faire connaissance avec le mystérieux chef de la bande !');
INSERT INTO public.bd VALUES (2725, 'Inu Yasha', '27', 'Tome 27', 'Takahashi, Rumiko', '9782505001621', '08/2007 (Parution le 24/08/2007)', 188, 'https://www.bedetheque.com/media/Couvertures/Couv_66160.jpg', 'La seule évocation du mont Harurei-zan rempli d''effroi. On soupçonne même Naraku de s''y dissimuler ! D''ailleurs, la bande des sept intensifie les combats contre Inu-Yasha dès qu''il s''en approche !');
INSERT INTO public.bd VALUES (2726, 'Inu Yasha', '28', 'Tome 28', 'Takahashi, Rumiko', '9782505001850', '11/2007 (Parution le 26/10/2007)', 188, 'https://www.bedetheque.com/media/Couvertures/Couv_68320.jpg', 'Le combat qui oppose Inu-Yasha et ses compagnons à la bande des sept est sur le point de se terminer. Nos amis sortiront-ils indemnes de cet affrontement ?');
INSERT INTO public.bd VALUES (2727, 'Inu Yasha', '29', 'Tome 29', 'Takahashi, Rumiko', '9782505002055', '12/2007 (Parution le 07/12/2007)', 182, 'https://www.bedetheque.com/media/Couvertures/Couv_73272.jpg', 'Inu-Yasha est pris au piège dans les entrailles du mont Harurei-zan !  Profitant de la situation, Naraku, métamorphosé, apparaît alors pour s''emparer des morceaux de la perle de Shikon. Nos amis sont dans une très mauvaise posture !');
INSERT INTO public.bd VALUES (2728, 'Inu Yasha', '30', 'Tome 30', 'Takahashi, Rumiko', '9782505002772', '02/2008 (Parution le 01/02/2008)', 184, 'https://www.bedetheque.com/media/Couvertures/Couv_71247.jpg', 'Naraku envoie son fils illégitime Hakudôshi à la poursuite d''Inu-Yasha. Son idée est simple : récupérer le dernier morceau de la perle de Shikon qu''Inu-Yasha continue à chercher avec ses amis !');
INSERT INTO public.bd VALUES (2729, 'Inu Yasha', '31', 'Tome 31', 'Takahashi, Rumiko', '9782505003366', '04/2008 (Parution le 11/04/2008)', 182, 'https://www.bedetheque.com/media/Couvertures/Couv_79588.jpg', 'Nous voici à la frontière entre notre monde et l''au-delà, là où se trouverait le dernier morceau de la perle de Shikon. L''unique chemin pour s''y rendre passe par la montagne de feu. Est-ce encore un piège tendu par Naraku ?!');
INSERT INTO public.bd VALUES (2730, 'Inu Yasha', '32', 'Tome 32', 'Takahashi, Rumiko', '9782505003052', '06/2008 (Parution le 06/06/2008)', 180, 'https://www.bedetheque.com/media/Couvertures/Couv_79589.jpg', 'Kohaku a perdu la mémoire et se fait manipuler par Naraku. Il va retrouver sa sœur Sango dans le château qui héberge l''enfant du maléfique Naraku. Comment vont se passer ces retrouvailles ?!');
INSERT INTO public.bd VALUES (2731, 'Inu Yasha', '33', 'Tome 33', 'Takahashi, Rumiko', '9782505003748', '08/2008 (Parution le 29/08/2008)', 184, 'https://www.bedetheque.com/media/Couvertures/Couv_79590.jpg', 'La tombe du père d''Inu-Yasha se trouve à la frontière qui relie notre monde à l''au-delà. Toujours à la recherche du dernier morceau de la perle de Shikon, nos amis vont de nouveau affronter Naraku.');
INSERT INTO public.bd VALUES (2732, 'Inu Yasha', '34', 'Tome 34', 'Takahashi, Rumiko', '9782505004318', '10/2008 (Parution le 17/10/2008)', 186, 'https://www.bedetheque.com/media/Couvertures/Couv_79591.jpg', 'La meute de souris se déchaîne ! Les relations entre Sango et Kohaku sont plus que jamais tendues. Quant à Inu-Yasha, il fonce sans réfléchir et se retrouve face à Kikyô !!');
INSERT INTO public.bd VALUES (2733, 'Inu Yasha', '35', 'Tome 35', 'Takahashi, Rumiko', '9782505004103', '12/2008 (Parution le 05/12/2008)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_84322.jpg', 'Inu-Yasha et ses amis sont à la recherche du cœur de Naraku qui se présente sous la forme d''un nourrisson. Lorsque soudain, un étrange personnage appelé Goryômaru fait son apparition ! Cet homme dont l''un des bras a été remplacé par celui d''un monstre est-il un ennemi ou un ami ?!');
INSERT INTO public.bd VALUES (2734, 'Inu Yasha', '36', 'Tome 36', 'Takahashi, Rumiko', '9782505005360', '03/2009 (Parution le 06/03/2009)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_84712.jpg', 'Le coeur de Naraku se présente devant Inu-Yasha et ses amis.! Vont-ils profiter de cette aubaine pour tuer Naraku ? Ou bien est-ce une autre surprise qui les attend ?');
INSERT INTO public.bd VALUES (2735, 'Inu Yasha', '37', 'Tome 37', 'Takahashi, Rumiko', '9782505005919', '06/2009 (Parution le 12/06/2009)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_88545.jpg', 'Goryômaru vient de s''échapper de la prison de Naraku. Il se dirige alors vers une nouvelle cible. Son but est de dérober les quatre morceaux de la perle de Shikon que détient Kagome !');
INSERT INTO public.bd VALUES (2736, 'Inu Yasha', '38', 'Tome 38', 'Takahashi, Rumiko', '9782505007081', '08/2009 (Parution le 04/09/2009)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_93487.jpg', 'Après avoir trahi Naraku et Hakudôshi, Kagura se met à protéger Kohaku ! Évidemment, Naraku ne lui pardonnera pas cette terrible trahison... Que va devenir Kagura?!');
INSERT INTO public.bd VALUES (2737, 'Inu Yasha', '39', 'Tome 39', 'Takahashi, Rumiko', '9782505007470', '12/2009', 184, 'https://www.bedetheque.com/media/Couvertures/Couv_100685.jpg', NULL);
INSERT INTO public.bd VALUES (2738, 'Inu Yasha', '40', 'Tome 40', 'Takahashi, Rumiko', '9782505008941', '04/2010 (Parution le 02/04/2010)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_105638.jpg', 'Le forgeur de sabres Tôshû, manipulé par Ryûjin, vient de faire  volte-face ! Les sabres magiques Datsuki et Tessaïga se livrent une lutte sans merci. Est-ce qu''Inu-Yasha sera capable avec son sabre de vaincre le sabre Datsuki et ainsi dévoiler les véritables intentions de Mouriômaru ?!');
INSERT INTO public.bd VALUES (2739, 'Inu Yasha', '41', 'Tome 41', 'Takahashi, Rumiko', '9782505008958', '08/2010 (Parution le 20/08/2010)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_113569.jpg', 'Inu-Yasha vient de récupérer un nouveau sabre, le Tessaïga de Ryûrin… Toutefois cette arme contient des pouvoirs qu’il n’est pas encore capable d’exploiter. Quant à Mouriômaru, il tend un piège à nos amis afin de lutter contre eux sans trop d’efforts. Il joue gros dans cet ultime combat dans lequel interviendront Kikyô et même Sesshômaru !');
INSERT INTO public.bd VALUES (2740, 'Inu Yasha', '42', 'Tome 42', 'Takahashi, Rumiko', '9782505010043', '12/2010', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_118980.jpg', 'Naraku, pour parvenir à ses fins, pousse Inu-Yasha et Mouriômaru à la confrontation… Son idée est de profiter d''un moment de faiblesse de l''un ou de l''autre…');
INSERT INTO public.bd VALUES (2867, 'Bastard!!', '18', 'Crimes et châtiments - Le Fragment', 'Hagiwara, Kazushi', '2723428699', '09/1999', 176, 'https://www.bedetheque.com/media/Couvertures/Couv_21599.jpg', NULL);
INSERT INTO public.bd VALUES (2868, 'Bastard!!', '19', 'Les Lois immorales - 1ère partie', 'Hagiwara, Kazushi', '2723429245', '01/2000', 180, 'https://www.bedetheque.com/media/Couvertures/Couv_39549.jpg', NULL);
INSERT INTO public.bd VALUES (2741, 'Inu Yasha', '43', 'Tome 43', 'Takahashi, Rumiko', '9782505010791', '04/2011 (Parution le 01/04/2011)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_122529.jpg', 'Kagome, jeune Japonaise de 15 ans, mène une vie paisible au sein de sa famille auprès d''un temple de Tokyo jusqu''au jour où tombant dans un puits, elle fait un bond dans le temps et se retrouve à l''époque Sengoku dans un Japon où monstres et esprits malins abondent. Elle fait alors la rencontre d''Inu-Yasha, un être hybride tenant à la fois de l''humain, du chien et du démon. Celui-ci est à la recherche de la perle de Shikon. A la suite de péripéties, la perle de Shikon est éclatée et Kagome se retrouve en la possession d''un de ses fragments... Kagome...');
INSERT INTO public.bd VALUES (2742, 'Inu Yasha', '44', 'Tome 44', 'Takahashi, Rumiko', '9782505012115', '08/2011 (Parution le 26/08/2011)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_138374.jpg', 'Kagome, jeune Japonaise de 15 ans, mène une vie paisible au sein de sa famille auprès d''un temple de Tokyo jusqu''au jour où tombant dans un puits, elle fait un bond dans le temps et se retrouve à l''époque Sengoku dans un Japon où monstres et esprits malins abondent. Elle fait alors la rencontre d''Inu-Yasha, un être hybride tenant à la fois de l''humain, du chien et du démon. Celui-ci est à la recherche de la perle de Shikon. A la suite de péripéties, la perle de Shikon est éclatée et Kagome se retrouve en la possession d''un de ses fragments... Kagome...');
INSERT INTO public.bd VALUES (2743, 'Inu Yasha', '45', 'Tome 45', 'Takahashi, Rumiko', '9782505012788', '12/2011 (Parution le 02/12/2011)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_147738.jpg', 'Kagome, jeune Japonaise de 15 ans, mène une vie paisible au sein de sa famille auprès d''un temple de Tokyo jusqu''au jour où tombant dans un puits, elle fait un bond dans le temps et se retrouve à l''époque Sengoku dans un Japon où monstres et esprits malins abondent. Elle fait alors la rencontre d''Inu-Yasha, un être hybride tenant à la fois de l''humain, du chien et du démon. Celui-ci est à la recherche de la perle de Shikon. A la suite de péripéties, la perle de Shikon est éclatée et Kagome se retrouve en la possession d''un de ses fragments... Kagome...');
INSERT INTO public.bd VALUES (2744, 'Inu Yasha', '46', 'Tome 46', 'Takahashi, Rumiko', '9782505014225', '03/2012 (Parution le 16/03/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_158562.jpg', 'Nouveau rebondissement !! Le nouveau Naraku se fait plus que jamais menaçant, toujours prêt à harceler nos amis de ses funestes intentions !');
INSERT INTO public.bd VALUES (2745, 'Inu Yasha', '47', 'Tome 47', 'Takahashi, Rumiko', '9782505014713', '01/2012 (Parution le 08/06/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_164900.jpg', 'Voici venu le moment du dernier combat ?! Une flèche qui enferme toute l''énergie de Kikyô vient d''être tirée sur Naraku !! Un duel à l''issue incertaine s''engage entre l''énergie maléfique de Naraku et celle contenue dans la flèche purifiée par Kikyô... Qui survivra à ce combat à mort ?!');
INSERT INTO public.bd VALUES (2746, 'Inu Yasha', '48', 'Tome 48', 'Takahashi, Rumiko', '9782505015390', '09/2012 (Parution le 07/09/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_170833.jpg', 'Kagome, jeune Japonaise de 15 ans, mène une vie paisible au sein de sa famille auprès d''un temple de Tokyo jusqu''au jour où tombant dans un puits, elle fait un bond dans le temps et se retrouve à l''époque Sengoku dans un Japon où monstres et esprits malins abondent. Elle fait alors la rencontre d''Inu-Yasha, un être hybride tenant à la fois de l''humain, du chien et du démon. Celui-ci est à la recherche de la perle de Shikon. A la suite de péripéties, la perle de Shikon est éclatée et Kagome se retrouve en la possession d''un de ses fragments... Kagome...');
INSERT INTO public.bd VALUES (2747, 'Inu Yasha', '49', 'Tome 49', 'Takahashi, Rumiko', '9782505015833', '12/2012 (Parution le 07/12/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_177813.jpg', 'Enfin l''épilogue du combat acharné qu''Inu-Yasha mène contre Kanna !! Mais qu''est-ce qui attend nos héros à l''issue de ce dernier affrontement ?!');
INSERT INTO public.bd VALUES (2748, 'Inu Yasha', '50', 'Tome 50', 'Takahashi, Rumiko', '9782505018124', '03/2013 (Parution le 15/03/2013)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_185278.jpg', 'Un mystérieux monstre vient à la rencontre de Sesshômaru... Il prétend connaître les secrets du sabre Tenseiga !! Quelles vérités seront révélées à l''issue du combat qui s''annonce sans pitié ?!');
INSERT INTO public.bd VALUES (2749, 'Inu Yasha', '51', 'Tome 51', 'Takahashi, Rumiko', '9782505018131', '06/2013 (Parution le 21/06/2013)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_191694.jpg', 'Sesshômaru veut savoir qui est le véritable héritier du sabre magique Tessaïga. Pour satisfaire sa curiosité, il engage un combat sans merci contre Inu-Yasha !');
INSERT INTO public.bd VALUES (2750, 'Inu Yasha', '52', 'Tome 52', 'Takahashi, Rumiko', '9782505018148', '09/2013 (Parution le 06/09/2013)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_196441.jpg', NULL);
