INSERT INTO public.bd VALUES (2755, 'Revue dessinée (La)', '1', '#01', 'Rescan, Manon', '9782754810142', '09/2013 (Parution le 12/09/2013)', 228, 'https://www.bedetheque.com/media/Couvertures/Couv_196359.jpg', '- "Belge Congo", reportage de Jean-Philippe Stassen - "La sémantique, c''est élastique", chronique langagière de James - "Le Prix de la terre", enquête de Manon Rescan, Damien Brunon et Sébastien Vassant - "Passion byte", l''informatique chroniquée par Hervé Bourhis et Adrien Ménielle - "Marins d''eaux dures", récit de Christian Cailleaux dans les eaux de l''hémisphère sud à bord de la frégate Floréal - "Face B", chronique musicale d''Arnaud Le Gouëfflec et Nicolas Moog - "Derrière les grilles du zoo", reportage de Marion Montaigne - "Le futur est pour...');
INSERT INTO public.bd VALUES (2756, 'Revue dessinée (La)', '2', '#02', 'Lepage, Emmanuel (1)', '9782754810722', '12/2013 (Parution le 06/12/2013)', 228, 'https://www.bedetheque.com/media/Couvertures/Couv_201351.jpg', '- "Un VRP de guerre", enquête de David Servenay et Alain Kokor, - "Mister Éco", la macro chroniquée par Le Binôme, - "Dans les pas des soigneurs de ménagerie", reportage de Marion Montaigne, - "La sémantique, c''est élastique", chronique langagière de James, - "Lybie : les écoutes made in France", enquête de Jean-Marc Manach, dessinée par Nicoby, - "Passion byte", l''informatique chroniquée par Hervé Bourhis et Adrien Ménielle, - "Le futur est pour bientôt", une chronique prospective d''Olivier Jouvray et Maëlle Schaller, - "Gaz de schiste : opération...');
INSERT INTO public.bd VALUES (2807, 'Revue dessinée (La)', 'HS2015/11', 'Face B', 'Le Gouëfflec, Arnaud', '9791092530025', '11/2015 (Parution le 20/11/2015)', 94, 'https://www.bedetheque.com/media/Couvertures/Couv_265016.jpg', 'Face B d''Arnaud Le Gouëfflec et Nicolas Moog met en lumière les grands artistes musicaux « méconnus » de l''histoire du Rock. Les Résidents, MoonDog, Captain Beefheart, Nico et tant d''autres qui ont tellement apporté à la musique d''aujourd''hui. Une discographie sélective dessinée est proposée avec chaque sujet, histoire de ne rien rater d''essentiel sur ces grands artistes maudits. Yeah !');
INSERT INTO public.bd VALUES (2757, 'Revue dessinée (La)', '3', '#03', 'Psaïla, Philippe', '9782754810890', '03/2014 (Parution le 13/03/2014)', 226, 'https://www.bedetheque.com/media/Couvertures/Couv_212493.jpg', '- "La Guerre des mouches", un reportage de Pedro Lima, Philippe Psaïla et Jean-Paul Krassinsky, - "Passion byte", l''informatique chroniquée par Hervé Bourhis, - "Le Vrai faux modèle allemand", un récit de Mathilde Ramadier et Pochep, - "La sémantique, c''est élastique", la chronique langagière de James, - "Guillotine", un documentaire de Marie Gloris dessiné par Rica, - "Mi-temps", chronique sportive de Pochep, - "Énergies : le grand bluff", une enquête de Sylvain Lapoix et Daniel Blancou, - "Face B", la chronique musicale d''Arnaud Le Gouëfflec...');
INSERT INTO public.bd VALUES (2758, 'Revue dessinée (La)', '4', '#04', 'Untersinger, Martin', '9782754811156', '06/2014 (Parution le 13/06/2014)', 162, 'https://www.bedetheque.com/media/Couvertures/Couv_218384.jpg', NULL);
