INSERT INTO public.bd VALUES (2760, 'Revue dessinée (La)', '6', '#06', 'Pellicer, Raynal', '9782754811453', '12/2014 (Parution le 12/12/2014)', 228, 'https://www.bedetheque.com/media/Couvertures/Couv_232297.jpg', 'Contenu : - 48h à la Crim'', un reportage de Raynal Pellicer et Titwane, - La sémantique, c''est élastique, la chronique langagière de James, - Affaires Sarkozy, une enquête de Fabrice Tassel et Benjamin Adam, - La Revue des cinés, un film choisi et commenté par Chloé Cruchaudet, - Rue de l''intérim, un récit d''Olivier Courtois et Phicil, - Passion byte, l''informatique chroniquée par Hervé Bourhis, - Esquisse d''un meurtrier, un portrait de Clara Beaudoux et Cyrille Pomès, - Mi-temps, l''expérience sportive de Marion Montaigne, - Triste béton, état...');
INSERT INTO public.bd VALUES (2761, 'Revue dessinée (La)', '7', '#07', 'Collombat, Benoît', '9782754812009', '03/2015 (Parution le 12/03/2015)', 188, 'https://www.bedetheque.com/media/Couvertures/Couv_239538.jpg', NULL);
