INSERT INTO public.bd VALUES (2763, 'Revue dessinée (La)', '9', '#09', 'Gorius, Aurore', '9782754812023', '09/2015 (Parution le 10/09/2015)', 191, 'https://www.bedetheque.com/media/Couvertures/Couv_254741.jpg', 'Contenu : - Le World Wild Web - Un sujet de Martin Untersinger et Thibaut Soulcié, - La Revue des cinés - Alfred fait son cinéma, - La sémantique, c''est élastique - Les mots décortiqués par James, - À l''oreille des politiques - Une enquête d''Aurore Gorius et Vincent Sorel, - Face B - La Chronique musicale d''Arnaud Le Gouëfflec et Nicolas Moog, - La Foire aux bestiaux - Le Business de la viande par Gabriel Blaise, Aude Vidal et Guillaume Trouillard, - Instantané - Une photo analysée par Jean-Michel Billioud et Rudy Spiessert, - Passion byte - L''Informatique...');
