INSERT INTO public.bd VALUES (2843, 'Prison School', '23', 'Tome 23', 'Hiramoto, Akira', '9782302080607', '01/2020 (Parution le 15/01/2020)', 180, 'https://www.bedetheque.com/media/Couvertures/Couv_381476.jpg', 'Kiyoshi intègre un ancien lycée pour filles. Cette année est la première dans l''histoire de l''école où les garçons peuvent y accéder. À sa grande surprise, Kiyoshi se rend compte qu''il n''y a que quatre autres garçons dans le lycée, soit un garçon pour 200 filles ! Ils sont pleins d''espoir mais les filles les ignorent totalement... Alors qu''ils s''adonnent à une séance de voyeurisme, ils se font surprendre et séquestrer dans les sous-sols de l''établissement. Leur cauchemar ne fait alors que commencer !');
INSERT INTO public.bd VALUES (2844, 'Prison School', '24', 'Tome 24', 'Hiramoto, Akira', '9782302081840', '01/2020 (Parution le 17/06/2020)', 180, 'https://www.bedetheque.com/media/Couvertures/Couv_389734.jpg', 'Meiko Shiraki est enfin de retour parmi les puissants ?! Revenue d’entre les morts, va-t-elle pouvoir faire basculer le destin en faveur des prisonniers ?');
INSERT INTO public.bd VALUES (2845, 'Prison School', '25', 'Tome 25', 'Hiramoto, Akira', '9782302083394', '09/2020 (Parution le 16/09/2020)', 180, 'https://www.bedetheque.com/media/Couvertures/Couv_401505.jpg', 'Alors que le duel de cavalerie humaine touchait à sa fin, l''hélicoptère à bord duquel se trouve le proviseur est sur le point de se crasher !');
INSERT INTO public.bd VALUES (2846, 'Prison School', '26', 'Tome 26', 'Hiramoto, Akira', '9782302090521', '12/2020 (Parution le 30/12/2020)', 180, 'https://www.bedetheque.com/media/Couvertures/Couv_408934.jpg', 'Kiyoshi intègre un ancien lycée pour filles. Cette année est la première où les garçons peuvent y accéder. Il n''y a que cinq garçons dans le lycée, soit un garçon pour 200 filles ! Ils sont pleins d''espoir mais les filles les ignorent... Alors qu''ils s''adonnent à une séance de voyeurisme, ils se font surprendre et séquestrer dans les sous-sols de l''établissement. C''est le début de leur cauchemar !');
INSERT INTO public.bd VALUES (2847, 'Prison School', '27', 'Tome 27', 'Hiramoto, Akira', '9782302093089', '03/2021 (Parution le 10/03/2021)', 180, 'https://www.bedetheque.com/media/Couvertures/Couv_417399.jpg', 'Le grand jour est enfin arrivé ! Garçons et filles s’apprêtent à participer au grand barbecue pour fêter la sortie de prison de la présidente ainsi que l’anniversaire de Chiyo ! Mais si vous pensiez que tout allait se passer comme prévu, c’est vraiment que vous n’avez pas lu les vingt-six premiers volumes...');
INSERT INTO public.bd VALUES (2848, 'Prison School', '28', 'Tome 28', 'Hiramoto, Akira', '9782302094253', '06/2021 (Parution le 23/06/2021)', 202, 'https://www.bedetheque.com/media/Couvertures/Couv_423748.jpg', 'Kiyoshi est bien décidé à déclarer sa flamme à la jolie Chiyo... Mais lorsqu’il arrive sur le lieu de rendez-vous, Hana est déjà sur place et semble vouloir lui casser son coup ! Que va-t-elle révéler à Chiyo ? Cette dernière saura- t-elle lui pardonner toutes ses erreurs et ses perversités ?!? Qu’attendez- vous pour lire cette conclusion pour le moins... explosive ?!?');
INSERT INTO public.bd VALUES (2849, 'Prison School', 'HS', 'Les dessous de Meiko', 'ReDrop', '9782302076747', '07/2019 (Parution le 14/08/2019)', 170, 'https://www.bedetheque.com/media/Couvertures/Couv_373047.jpg', NULL);
