INSERT INTO public.bd VALUES (3132, 'Chick Bill', '16', 'Le trésor du gros magot', 'Greg (1)', '2875562118', '03/1974', 60, 'https://www.bedetheque.com/media/Couvertures/Couv_131493.jpg', 'Grâce aux dons médiumniques involontaires de Kid Ordinn, Chick Bill, Petit Caniche, Dog Bull et son adjoint se lancent à la recherche d''une cité mongole perdue... au coeur de l''Afrique. Guidés par Ladislas Lotofjunk, ils devront affronter de nombreux périls avant de découvrir le Kah-Meh-Loht.');
