INSERT INTO public.bd VALUES (3138, 'Chick Bill', '22', 'Les Millions de Kid Ordinn', 'Greg (1)', '2242992929', '04/1977', 60, 'https://www.bedetheque.com/media/Couvertures/Couv_276658.jpg', 'Kid Ordinn et Dog Bull viennent en aide au maharadjah du Sassayfehpour dont le trône est mis en danger par une secte terroriste. Ils partent en Inde pour essayer de remettre en route les mines de diamant qui permettraient de sauver le pays. Bien évidemment, la route n''est pas sans danger.');
