INSERT INTO public.bd VALUES (3726, 'P''tits diables (Les)', '3D2', 'Les p''tits diables contre-attaquent !', 'Dutto, Olivier', '9782302018389', '11/2011 (Parution le 23/11/2011)', 38, 'https://www.bedetheque.com/media/Couvertures/Couv_279366.jpg', NULL);
INSERT INTO public.bd VALUES (3727, 'P''tits diables (Les)', '3D3', 'Compil''3D', 'Dutto, Olivier', '9782302022744', '08/2012 (Parution le 22/08/2012)', 38, 'https://www.bedetheque.com/media/Couvertures/Couv_218028.jpg', NULL);
INSERT INTO public.bd VALUES (3728, 'P''tits diables (Les)', '3D4', 'Spéciale Grippy', 'Dutto, Olivier', '9782302052017', '06/2016 (Parution le 29/06/2016)', 38, 'https://www.bedetheque.com/media/Couvertures/Couv_286724.jpg', 'Après le succès des trois premiers tomes, retrouvez les meilleurs gags de Tom & Nina en compagnie de leur chat préféré. Avec en plus de nouvelles lunettes collector''s super miaou !');
INSERT INTO public.bd VALUES (3729, 'P''tits diables (Les)', 'BO2006', 'Best of', 'Dutto, Olivier', '2845659997', '06/2006', 30, 'https://www.bedetheque.com/media/Couvertures/Couv_56601.jpg', NULL);
INSERT INTO public.bd VALUES (3730, 'P''tits diables (Les)', 'BO2021', 'Frère et sœur à la folie !', 'Dutto, Olivier', '9782383110002', '06/2021 (Parution le 20/03/2013)', 35, 'https://www.bedetheque.com/media/Couvertures/Couv_429213.jpg', NULL);
INSERT INTO public.bd VALUES (3731, 'P''tits diables (Les)', 'Compil1', 'Morceaux Choisis !', 'Dutto, Olivier', '9782302011878', '06/2010', 30, 'https://www.bedetheque.com/media/Couvertures/Couv_310958.jpg', NULL);
INSERT INTO public.bd VALUES (3732, 'P''tits diables (Les)', 'Compil2', 'Vive les vacances !', 'Dutto, Olivier', '9782302070103', '05/2018 (Parution le 30/05/2018)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_335294.jpg', 'Pas de trêve entre frères et soeurs, même pendant les congés !');
INSERT INTO public.bd VALUES (3733, 'P''tits diables (Les)', 'Compil3', 'Goût vacances !', 'Dutto, Olivier', '9782302076808', '05/2019 (Parution le 29/05/2019)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_369637.jpg', 'L''école est finie : l''occasion pour nos P''tits Diables de faire encore plus de bêtises ! Ce best of regroupe une sélection de gags parus dans différents albums de la série.');
INSERT INTO public.bd VALUES (3734, 'P''tits diables (Les)', 'HS2013', 'Ça va être ta fête maman!', 'Dutto, Olivier', '9782302024960', '05/2013 (Parution le 02/05/2013)', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_210145.jpg', 'Quoi de plus important pour des enfants que leur maman ? Et comment montrer à sa maman qu''on l''aime ? En lui faisant sa fête, bien sûr !!! Une compilation de gags jubilatoires pour souhaiter une belle fête des Mères. À toutes les mamans du monde... et pour les prévenir de ce que leur réserve leurs chers P''tits Diables !');
INSERT INTO public.bd VALUES (3735, 'P''tits diables (Les)', 'HS2015', 'Ça va être ta fête Papa !', 'Dutto, Olivier', '9782302046481', '06/2015 (Parution le 03/06/2015)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_249108.jpg', 'Quoi de plus important pour des enfants que leur papa ?');
INSERT INTO public.bd VALUES (3817, 'Cédric', '32', 'C''est pas du jeu !', 'Cauvin, Raoul', '9782800173979', '11/2018 (Parution le 01/11/2018)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_349578.jpg', 'Les assiettes volent, les jurons pleuvent... Ce n''est pas l''ambiance qui manque, dans la famille de Cédric ! Mais derrière chaque dispute, derrière chaque coup dur, il y a toujours la solidarité entre copains ou l''affection de l''entourage.');
INSERT INTO public.bd VALUES (3736, 'P''tits diables (Les)', 'HS2018', 'Les P''tits Diables - Crée ta BD', 'Dutto, Olivier', '9782302069497', '06/2018 (Parution le 13/06/2018)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_337318.jpg', 'Apprendre à dessiner ses héros préférés et imaginer des histoires, accompagné d''anecdotes et de secrets d''Olivier Dutto ! Le cahier contient : des pas-à-pas de dessin (Nina, Tom, Grippy, leurs copains, leurs parents...), un contenu évolutif (apprendre à dessiner les personnages, puis un décor, une scène, et enfin une planche), des idées pour imaginer un scénario, des tutoriels avec des jeux pour s''entraîner (qu''est-ce que le lettrage ? les onomatopées ? l''encrage ?), les secrets de fabrication d''Olivier Dutto, de jolis pochoirs en PVC coloré, encartés...');
INSERT INTO public.bd VALUES (3737, 'P''tits diables (Les)', 'HS2021/01', 'La compil'' des champions !', 'Dutto, Olivier', '2700671538', '01/2021 (Parution le 06/01/2021)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_413212.jpg', NULL);
INSERT INTO public.bd VALUES (3738, 'P''tits diables (Les)', 'HS2021/06', 'Un petit rafraichissement?', 'Dutto, Olivier', '9782302083257', '06/2021 (Parution le 09/06/2021)', 43, 'https://www.bedetheque.com/media/Couvertures/Couv_430843.jpg', 'Une sélection des meilleurs gags de LA série des frères et soeurs ! Qui sera le champion ? Tom ou Nina ?');
INSERT INTO public.bd VALUES (3739, 'P''tits diables (Les)', 'HS2022', 'Compil'' - Un été d''enfer !', 'Dutto, Olivier', '9782302098299', '06/2022 (Parution le 15/06/2022)', 43, 'https://www.bedetheque.com/media/Couvertures/Couv_449823.jpg', NULL);
INSERT INTO public.bd VALUES (3740, 'P''tits diables (Les)', 'INTFL2', 'Intégrale', 'Dutto, Olivier', '9782298026429', '09/2009', 140, 'https://www.bedetheque.com/media/Couvertures/Couv_258697.jpg', NULL);
INSERT INTO public.bd VALUES (3741, 'Sisters (Les)', '1', 'Un air de famille', 'Cazenove, Christophe', '9782350784953', '05/2008', 44, 'https://www.bedetheque.com/media/Couvertures/SistersLes1_07112008_022303.jpg', 'Du rififi chez les filles : découvrez le quotidien savoureux de deux soeurs volcaniques ! Wendy, c''est ma grande sister. Moi, du coup, j''suis la plus petite. Si qu''on m''avait demandé mon avis, j''aurais préféré être l''aînée des deux. Ben oui quoi, moi je saurai jamais ce que ça fait d''avoir un p''tite soeur qui fait tout pareil que moi, qui essaie par tous les moyens de forcer le cadenas de mon journal intime, qui écoute à la porte de ma chambre quand je parle des garçons avec mes meilleures cop''s, qui fait rien qu''à me piquer mes fringues dès que...');
INSERT INTO public.bd VALUES (3742, 'Sisters (Les)', '2', 'À la mode de chez nous', 'Cazenove, Christophe', '9782350785493', '10/2008', 46, 'https://www.bedetheque.com/media/Couvertures/SistersLes2_07112008_021000.jpg', NULL);
INSERT INTO public.bd VALUES (3743, 'Sisters (Les)', '3', 'C''est elle qu''a commencé', 'Cazenove, Christophe', '9782350786568', '05/2009 (Parution le 06/05/2009)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_88316.jpg', NULL);
INSERT INTO public.bd VALUES (3744, 'Sisters (Les)', '4', 'C''est nikol crème !', 'Cazenove, Christophe', '9782350787824', '11/2009 (Parution le 04/11/2009)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_99077.jpg', 'Yipeeee ! Il a encore neigé tout plein ! Avec ma sister Wendy, on va se taper des méga grosses batailles de boules de neige, creuser des « ziglous » partout dans le jardin, et faire des super bonshommes de neige ! Mais ça, à la limite, je m’en fiche parce que moi j’en fais toute l’année des bonshommes, en terre, comme ça, ça me fait gagner du temps pour l’hiver. Et encore plus géant, Papy et Mamy ont un petit chien tout craquounet. Il s’appelle Darwin et on va pouvoir le garder quelques jours. C’est les vacances, il neige, et on a un chien … C’est...');
INSERT INTO public.bd VALUES (3745, 'Sisters (Les)', '5', 'Quelle chouchoute !', 'Cazenove, Christophe', '9782818901625', '11/2010', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_117162.jpg', 'Ouf ! Wendy va enfin pouvoir souffler un peu. Sa petite soeur Marine, la tornade blonde, a une jambe dans le plâtre. Pendant quelques semaines, elle ne pourra plus dévaler les escaliers comme une dingue ou venir la réveiller en sautant sur son lit comme une balle américaine. Fini le trampoline sur le canapé, les courses d''obstacles autour de la table du jardin, l''escalade des rideaux de la maison. Hélas, Wendy va vite s''apercevoir qu''un simple plâtre ne suffira pas à transformer sa sister en petit ange tout sage. Marine a des ressources, et ce...');
INSERT INTO public.bd VALUES (3746, 'Sisters (Les)', '6', 'Un Namour de Sister', 'Cazenove, Christophe', '9782818907900', '11/2011 (Parution le 09/11/2011)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_145734.jpg', 'Marine n''avait jamais pensé que ce serait si compliqué d''être la petite sister de Wendy INSERT INTO public.bd VALUES (3747, 'Sisters (Les)', '7', 'Mon coup d''soleil, c''est toi', 'Cazenove, Christophe', '9782818922026', '11/2012 (Parution le 31/10/2012)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_175317.jpg', 'Coup de soleil, coups d''éclats et éclats de rire : les Sisters sont en mode vacances !   Wendy adore l''été, la plage et le soleil. Idéal pour prendre des couleurs !Mais dès que sa petite sister est dans les parages avec ses blagues à deux balles, sa capacité à toujours se mêler de tout, ce sont plutôt des colères que prendrait Wendy ! Mais une balade en mer sur le bateau d''Alain, l''ami de papa et maman, leur fait vite oublier toute dispute. Une séance de bronzette sur la plus belle plage du monde et zou ! Les revoilà complices comme au premier...');
INSERT INTO public.bd VALUES (3748, 'Sisters (Les)', '8', 'Tout pour lui plaire !', 'Cazenove, Christophe', '9782818925324', '11/2013 (Parution le 30/10/2013)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_200229.jpg', 'C''est l''année du dépaysement pour Wendy ! Il y a tout d''abord son correspondant italien qui vient passer quelques jours à la maison. Et puis, ce qui la fait rêver depuis tant d''années, ces vacances aux États-Unis que ses parents lui ont promises ! Et pourtant, Wendy n''a pas besoin de parcourir des milliers de kilomètres, ni de traverser des océans pour découvrir des contrées inconnues, il lui suffit de pousser la porte de la chambre de sa petite sister Marine pour entrer dans le pays de la dinguerie et de l''agitation permanente ! En plus, les cocktails...');
INSERT INTO public.bd VALUES (3749, 'Sisters (Les)', '9', 'Toujours dans les pattes !', 'Cazenove, Christophe', '9782818932056', '11/2014 (Parution le 29/10/2014)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_229499.jpg', NULL);
INSERT INTO public.bd VALUES (3750, 'Sisters (Les)', '10', 'Survitaminées !', 'Cazenove, Christophe', '9782818934487', '10/2015 (Parution le 30/09/2015)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_256603.jpg', 'Les Sisters participent à la Portnawak Run, une course qui se déroule dans les bois pas loin de la maison et qui regroupe tout un tas d''épreuves complètement dingos ! Courir dans la boue, grimper à des arbres ou encore bondir d''un rocher à l''autre : la petite sister Marine fait déjà ça tous les jours quand elle court sur le canapé, qu''elle grimpe sur l''armoire ou qu''elle bondit d''un fauteuil à l''autre ! Quant à Wendy, elle n''a pas besoin de s''entraîner puisque elle aurait droit à un bisou-qui-donne-des-ailes de Maxence avant chaque épreuve !');
INSERT INTO public.bd VALUES (3751, 'Sisters (Les)', '11', 'C''est dans sa nature', 'Cazenove, Christophe', '9782818940372', '10/2016 (Parution le 02/11/2016)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_293196.jpg', NULL);
INSERT INTO public.bd VALUES (3752, 'Sisters (Les)', '12', 'Attention tornade', 'Cazenove, Christophe', '9782818943502', '11/2017 (Parution le 02/11/2017)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_314884.jpg', NULL);
INSERT INTO public.bd VALUES (3818, 'Cédric', '33', 'Sans les mains', 'Cauvin, Raoul', '9791034737024', '11/2019', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_380059.jpg', NULL);
INSERT INTO public.bd VALUES (3753, 'Sisters (Les)', '13', 'Kro d''la chance !', 'Cazenove, Christophe', '9782818947173', '11/2018 (Parution le 31/10/2018)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_346510.jpg', 'Les deux tornades font souffler un vent de folie sur la BD ! Marine a une nouvelle lubie. Elle s''est mise en tête de mettre le sort à rude épreuve. Elle se lance dans la quête du trèfle à quatre feuilles afin de vérifier si oui ou non elle a de la chance. De son côté, Wendy semble ne plus en avoir. Elle est persuadée que Maxence ne l''aime plus et qu''il lui préfère Sammie, sa meilleure amie. Et ça, Wendy, ça la met même dans une colère noire, presque autant que quand sa Sister lui pique son journal intime. Il va encore y avoir des étincelles dans...');
INSERT INTO public.bd VALUES (3754, 'Sisters (Les)', '14', 'Juré, craché, menti !', 'Cazenove, Christophe', '9782818967362', '11/2019 (Parution le 13/11/2019)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_378436.jpg', 'Marine découvre qu''il est très facile de mentir. Tant qu''elle ment sur le lavage de dents, ce n''est pas trop grave. Mais quand elle invente des trucs de plus en plus énormes.');
INSERT INTO public.bd VALUES (3755, 'Sisters (Les)', '15', 'Fallait pas me chercher !', 'Cazenove, Christophe', '9782818976791', '10/2020 (Parution le 28/10/2020)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_402415.jpg', NULL);
INSERT INTO public.bd VALUES (3756, 'Sisters (Les)', '16', 'Cap ou pas cap ?', 'Cazenove, Christophe', '9782818984093', '11/2021 (Parution le 03/11/2021)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_436554.jpg', 'Cap’ ou pas cap’ ? Voici le nouveau jeu préféré de tous les temps de Marine qu''elle dégaine à tout moment de la journée. Cap'' ou pas cap'' de passer une heure dans le frigo sans toucher au cake au citron de maman ? Cap'' ou pas cap'' d''aller au skate-park, déguisée en licorne ? Cap'' ou pas cap'' de me laisser lire ton journal intime ? La vraie question cependant est de savoir si Wendy sera Cap'' ou pas cap'' de supporter sa sister encore longtemps sans lui barbouiller la chevelure de crème d''anchois !');
INSERT INTO public.bd VALUES (3757, 'Sisters (Les)', '17', 'Dans tes rêves !', 'Cazenove, Christophe', '9782818994436', '11/2022 (Parution le 02/11/2022)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_458509.jpg', 'Les deux tornades font souffler un vent de folie sur la BD !Depuis qu''on a accroché un attrape-rêve dans sa chambre, Marine n''a plus que cette idée en tête : les attraper tous. Et si elle peut les choper pour les collectionner, il faut qu''elle s''entraîne à rêver les trucs les plus mieux du monde. De son côté, Wendy tente d''organiser une pyjama party. Mais avec le crampon qui traîne dans les parages, pour elle, la soirée va vite virer au cauchemar. Les deux Sisters reviennent mettre le bazar dans les librairies. Une chose est sûre : elles sont en...');
INSERT INTO public.bd VALUES (3758, 'Sisters (Les)', '18', 'Tu veux ma photo ?', 'Cazenove, Christophe', '9791041101283', '11/2023 (Parution le 02/11/2023)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_486197.jpg', 'Les deux tornades font souffler un vent de folie sur la BD ! Opération rangement chez les Sisters. Les parents chargent Wendy et Marine de faire du tri dans leurs affaires avant que leurs chambres n''explosent. Les filles trouvent la corvée beaucoup plus amusante lorsque, dans le garage, elles tombent sur des photos de jeunesse de papa et maman, et se prennent carrément pour des archéologues en retrouvant des cassettes vidéo du siècle dernier ! Cette opération rangement sera un vrai carton, d''ailleurs il y en a partout dans la maison !!!');
INSERT INTO public.bd VALUES (3759, 'Sisters (Les)', '19', 'Ça déménage !', 'Cazenove, Christophe', '9791041103355', '10/2024 (Parution le 30/10/2024)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_506840.jpg', 'Les deux tornades font souffler un vent de folie sur la BD ! Ce n''est pas pour rien que dans le précédent album papa et maman demandaient aux filles de trier leurs affaires... Ils savaient, eux, qu''ils allaient tous déménager ! Aussi, quelle surprise pour Marine et Wendy de découvrir leurs nouvelles chambres, leur nouvelle maison, bref, leur nouvel espace de complicité et de disputes. De toute façon, du moment que l''on continue de voir ses amies, son petit copain et que l''on peut chiper le journal de nintime de sa Sister, peu importe la maison...');
INSERT INTO public.bd VALUES (3760, 'Sisters (Les)', '20', 'Moi d''abord !', 'Cazenove, Christophe', '9791041112197', '10/2025 (Parution le 29/10/2025)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_528379.jpg', 'Les deux tornades font souffler un vent de folie sur la BD ! Marine a un travail fou à la maison. Elle doit gérer le moral de Wendy qui a glissé dans ses chaussettes et s''occuper de son animalerie en peluches. Ça en fait de la charge de cervelle ! Alors, c''est sûr qu''avec tout ça, elle n''a vraiment pas le temps d''être la petite sister parfaite. Le mieux, c''est encore qu''elle reste comme elle est, c''est-à-dire turbulente, bondissante, kro adorable et surtout, qu''elle puisse continuer de faire ce qu''elle a veut. « Moi d''abord ! C''est pourtant clair,...');
INSERT INTO public.bd VALUES (3761, 'Sisters (Les)', '3D', 'Délires, dégâts et disputes', 'Cazenove, Christophe', '9782818926529', '02/2014 (Parution le 05/02/2014)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_234256.jpg', NULL);
INSERT INTO public.bd VALUES (3762, 'Sisters (Les)', 'Audio', 'Les sisters', 'Cazenove, Christophe', '9791041114382', '08/2025 (Parution le 27/08/2025)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_529489.jpg', 'La BD à lirécouter ! Envie de rire aux éclats avec les Sisters ? Cet album est fait pour vous ! Oubliez la lecture ennuyeuse, ici c''est interactif ! Scannez le QR code avec votre smartphone et laissez-vous transporter par l''appli gratuite. Plongez eu coeur de votre série préférée grâce aux dialogues des acteurs de la série TV, aux bruitages et aux musiques. A vous les bagarres d''anthologie entre les deux tornades !');
INSERT INTO public.bd VALUES (3763, 'Sisters (Les)', 'BO1', 'Le Best Of', 'Cazenove, Christophe', '9782756775241', '12/2013', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_207516.jpg', 'N’hésitez pas à plonger dans ces instantanés de la vie des Sisters pour découvrir le rêve d’I-Pod de Wendy, ou comment fonctionne un journal intime. Vous connaîtrez tous les secrets d’une pyjama party réussie, et les meilleures recettes pour faire tourner sa sister en bourrique ! Sans oublier l’entraînement intense de Marine pour être en forme pour la rentrée scolaire et des infos sur le clonage des grandes sœurs. Du vrai, du qui-bouge, bref, du Sisters pur jus !');
INSERT INTO public.bd VALUES (3764, 'Sisters (Les)', 'BO4', 'Best of', 'Cazenove, Christophe', '9782818987742', '06/2021 (Parution le 01/11/2004)', 38, 'https://www.bedetheque.com/media/Couvertures/Couv_429782.jpg', NULL);
INSERT INTO public.bd VALUES (3765, 'Sisters (Les)', 'BOSP', 'Les Secrets des Sisters', 'Cazenove, Christophe', '9782818932872', '04/2015 (Parution le 01/04/2015)', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_258268.jpg', 'Les petits (et grands) secrets des Sisters dévoilés dans cette compilation ! Tout, tout, tout, vous saurez tout sur les Sisters ! Quelles sont leurs passions ? Leurs plus grands rêves ? Leurs meilleurs souvenirs de vacances ? Vous découvrirez aussi leurs pires moments de honte et leurs plus mémorables embrouilles. Quant à savoir quelle est la chipie préférée de Wendy et la râleuse favorite de Marine, il semble que vous connaissez déjà la réponse !');
INSERT INTO public.bd VALUES (3766, 'Sisters (Les)', 'HS', 'Tonnerre de tendresse', 'Cazenove, Christophe', '9782818924686', '09/2013 (Parution le 28/08/2013)', 92, 'https://www.bedetheque.com/media/Couvertures/Couv_196365.jpg', NULL);
INSERT INTO public.bd VALUES (3767, 'Sisters (Les)', 'HS01', 'Mode d''emploi', 'Cazenove, Christophe', '9782350789514', '06/2010 (Parution le 09/06/2010)', 95, 'https://www.bedetheque.com/media/Couvertures/Couv_122322.jpg', 'Les Sisters : mode d’emploi, c’est un vrai guide de survie avec sa sister !');
INSERT INTO public.bd VALUES (3768, 'Sisters (Les)', 'HS02', 'Mon journal intime', 'Cazenove, Christophe', '9782818909829', '09/2012 (Parution le 05/09/2012)', 192, 'https://www.bedetheque.com/media/Couvertures/Couv_171672.jpg', 'On le sait, Wendy et Marine sont les vraies filles du dessinateur William. Mais quoi d’autre est vrai dans la BD ? Toutes leurs copines existent-elles ? Et les bêtises racontées, les ont-elles toutes faites ? Ce livre vous propose de découvrir tous les secrets des Sisters, et bien plus encore ! Car les filles vous invitent aussi à venir fouiner avec elles dans le carton à dessin de leur talentueux papa ! L’univers des Sisters ne se limite pas à leur chambre, loin de là…');
INSERT INTO public.bd VALUES (3769, 'Sisters (Les)', 'HS03', 'Les toutous des Sisters', 'Cazenove, Christophe', '9782818924051', '06/2013 (Parution le 29/05/2013)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_189733.jpg', NULL);
INSERT INTO public.bd VALUES (3770, 'Sisters (Les)', 'HS04', 'La cuisine des sisters', 'Cazenove, Christophe', '9782818931059', '06/2014 (Parution le 11/06/2014)', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_218499.jpg', NULL);
INSERT INTO public.bd VALUES (3771, 'Sisters (Les)', 'HS05', 'En route pour les vacances', 'Cazenove, Christophe', '9782818936252', '07/2016 (Parution le 29/06/2016)', 88, 'https://www.bedetheque.com/media/Couvertures/Couv_293195.jpg', NULL);
INSERT INTO public.bd VALUES (3772, 'Sisters (Les)', 'HS06', 'Les Sisters en 3D - Délires, dégâts et disputes', 'Cazenove, Christophe', '9782818946428', '04/2018 (Parution le 04/04/2018)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_331108.jpg', 'Accrochez-vous, leurs aventures en plein air vont démarrer à fond les manettes ! Et, grâce aux lunettes fournies avec cette BD, vous plongerez au coeur des 48 pages de gags et de belles illustrations. Délires, dégâts et disputes : des Sisters plus vraies que nature !');
INSERT INTO public.bd VALUES (3773, 'Sisters (Les)', 'HS07', 'La nature, c''est kro bien!', 'Cazenove, Christophe', '9782818978924', '06/2020', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_398332.jpg', NULL);
INSERT INTO public.bd VALUES (3774, 'Sisters (Les)', 'HS08', 'Les Sisters en 3D spécial vacances', 'Cazenove, Christophe', '9782818977682', '06/2020 (Parution le 10/06/2020)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_398333.jpg', 'En 3D, les Sisters sont encore plus délirantes et déchaînées. Ça saute aux yeux!');
INSERT INTO public.bd VALUES (3775, 'Sisters (Les)', 'HS09', 'Spécial jeux vidéo', 'Cazenove, Christophe', '9782818980095', '06/2021 (Parution le 02/06/2021)', 52, 'https://www.bedetheque.com/media/Couvertures/Couv_426276.jpg', 'Après avoir fait souffler un vent de folie sur la bande dessinée, Wendy et Marine s’attaquent au monde ludique avec un jeu vidéo dont elles sont les super héroïnes. Revivez tous les gags qui ont donné naissance aux mini-jeux de Show devant avec cet album best-of 100 % hilarant, agrémenté de making-of du jeu, de nombreuses interviews des créateurs et d’une tornade de dessins préparatoires.');
INSERT INTO public.bd VALUES (3776, 'Sisters (Les)', 'INT2', 'La compil'' 2', 'Cazenove, Christophe', '9782818934241', '09/2015 (Parution le 30/09/2015)', 288, 'https://www.bedetheque.com/media/Couvertures/Couv_257888.jpg', 'Faites le plein d''aventures avec la 2e compilation des Sisters regroupant 3 romans de la collection. Au programme : des histoires d''amitié, de bagarre entre soeurs et de réconciliation à dévorer à partir de 7 ans.');
INSERT INTO public.bd VALUES (3777, 'Sisters (Les)', 'Poche1', 'Le chat a la bandouliere', 'Cazenove, Christophe', '9782818921449', '09/2012 (Parution le 29/08/2012)', 93, 'https://www.bedetheque.com/media/Couvertures/Couv_225261.jpg', NULL);
INSERT INTO public.bd VALUES (3778, 'Sisters (Les)', 'Poche2', 'La foire aux secrets', 'Cazenove, Christophe', '97828189256614', '02/2014', 92, 'https://www.bedetheque.com/media/Couvertures/Couv_225260.jpg', NULL);
INSERT INTO public.bd VALUES (3779, 'Sisters (Les)', 'Poche3', 'Amnésique et périls', 'Vodarzac, François', '9782818974698', '08/2019 (Parution le 28/08/2019)', 90, 'https://www.bedetheque.com/media/Couvertures/Couv_379145.jpg', 'Parce qu''elle a cassé le téléphone portable de sa soeur et qu''elle a peur de finir en purée de Sister, Marine ne trouve pas d''autres moyens que de faire croire à tout le monde qu''elle est devenue amnésique. D''abord amusée, Wendy va vite se rendre compte que c''est grave et elle va tout faire pour lui faire recouvrer la mémoire. Et pour une Sister, tout faire, ça veut dire VRAIMENT tout faire !');
INSERT INTO public.bd VALUES (3780, 'Sisters (Les)', 'PUB', 'Best of', 'Cazenove, Christophe', '9782723657617', '01/2015', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_244843.jpg', NULL);
INSERT INTO public.bd VALUES (3781, 'Sisters (Les)', 'RJ1', 'Exposé grandeur nature', 'Cazenove, Christophe', '9782350789200', '04/2010', 87, 'https://www.bedetheque.com/media/Couvertures/Couv_184301.jpg', NULL);
INSERT INTO public.bd VALUES (3782, 'Sisters (Les)', 'RJ2', 'Le parc à quoi tik', 'Cazenove, Christophe', '9782818902677', '02/2011', 91, 'https://www.bedetheque.com/media/Couvertures/Couv_184304.jpg', NULL);
INSERT INTO public.bd VALUES (3783, 'Sisters (Les)', 'RJ3', 'Le lapin des neiges', 'Cazenove, Christophe', '9782818908457', '02/2012 (Parution le 15/02/2012)', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_184218.jpg', 'Rien que pour les batailles de neige il faudrait que ce soit l''hiver tous les jours ! Une paire de gants, un bonnet, une écharpe, un bon stock de poudreuse et un buisson derrière lequel s''abriter, c''est vraiment le jeu le plus simple au monde. Excepté lorsqu''arrive le moment de faire les équipes ! Car Wendy refuse que ses copines se retrouvent aux côtés de sa petite sister Marine. Et Marine menace des pires représailles ses amies qui iraient grossir les rangs de sa grande sister Wendy. Du coup, la bataille risque bien de démarrer plus tôt que prévu....');
INSERT INTO public.bd VALUES (3784, 'Sisters (Les)', 'RJ5', 'Les sisters olympiques', 'Cazenove, Christophe', '9782818922279', '02/2013 (Parution le 06/02/2013)', 89, 'https://www.bedetheque.com/media/Couvertures/Couv_184220.jpg', 'Les Sisters reviennent en roman jeunesse ! Le « Jour des Concours », ça c’est une chouette journée ! Organisée par les grands du quartier, tous les enfants peuvent participer aux différentes épreuves afin de remporter les nombreux trophées. Il y a le concours du meilleur gâteau, du plus beau déguisement, de la meilleure crêpe, du cadre photo le plus original… Cette année, c’est avec beaucoup d’assurance que Marine s’inscrit à chaque épreuve car elle est certaine de remporter tous les prix ! Non pas grâce à ses talents de pâtissière ou de couturière,...');
INSERT INTO public.bd VALUES (3785, 'Sisters (Les)', 'SP', 'Les sisters fêtent leur anniv'' avec leurs ami(e)s', 'Cazenove, Christophe', '9791041101382', '05/2023', 47, 'https://www.bedetheque.com/media/Couvertures/Couv_474620.jpg', 'Les Sisters : 15 ans d''éditions, ça se fête !');
INSERT INTO public.bd VALUES (3786, 'Cédric', '1', 'Premières classes', 'Cauvin, Raoul', '2800116366', '02/1989', 45, 'https://www.bedetheque.com/media/Couvertures/cedric01.jpg', NULL);
INSERT INTO public.bd VALUES (3787, 'Cédric', '2', 'Classes de neige', 'Cauvin, Raoul', '2800116730', '08/1989', 46, 'https://www.bedetheque.com/media/Couvertures/cedric02.jpg', NULL);
INSERT INTO public.bd VALUES (3788, 'Cédric', '3', 'Classe tous risques', 'Cauvin, Raoul', '2800117397', '05/1990', 46, 'https://www.bedetheque.com/media/Couvertures/cedric03.jpg', NULL);
INSERT INTO public.bd VALUES (3789, 'Cédric', '4', 'Papa a de la classe', 'Cauvin, Raoul', '2800118164', '03/1991', 46, 'https://www.bedetheque.com/media/Couvertures/cedric04.jpg', NULL);
INSERT INTO public.bd VALUES (3844, 'Cédric', 'Kalorik', 'Recueil de gags', 'Cauvin, Raoul', '2220842630', '01/2002', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_234257.jpg', NULL);
INSERT INTO public.bd VALUES (3845, 'Cédric', 'McDo', 'Belles bulles', 'Laudec', '9782800559612', '01/2009', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_531071.jpg', NULL);
INSERT INTO public.bd VALUES (3846, 'Cédric', 'McDo1', 'ça roule!', 'Cauvin, Raoul', '9782723657648', '01/2009', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_313752.jpg', NULL);
INSERT INTO public.bd VALUES (3790, 'Cédric', '5', 'Quelle mouche le pique ?', 'Cauvin, Raoul', '2800119055', '02/1992', 46, 'https://www.bedetheque.com/media/Couvertures/cedric05.jpg', 'L''ambiance n''est pas au beau fixe à la maison. Les parents de Cédric se sont disputés et ne s''adressent plus la parole. Cela met alors en colère le grand père qui explique à son petit fils ce qu''est le chemin de la vie. Celui-ci compte bien le suivre, mais il doit d''abord s''occuper de ses petits problèmes quotidiens comme rendre un devoir pour Mademoiselle Nelly, combattre les poux, convaincre son père de lui acheter un chien ou un skate board, obtenir de l''argent pour aller au cinéma, et j''en passe. Et par dessus tout, il doit combattre sa jalousie....');
INSERT INTO public.bd VALUES (3791, 'Cédric', '6', 'Chaud et froid', 'Cauvin, Raoul', '280011990X', '01/1993', 44, 'https://www.bedetheque.com/media/Couvertures/cedric06.jpg', NULL);
