INSERT INTO public.bd VALUES (3793, 'Cédric', '8', 'Comme sur des roulettes', 'Cauvin, Raoul', '2800121718', '11/1994', 45, 'https://www.bedetheque.com/media/Couvertures/cedric08.jpg', NULL);
