INSERT INTO public.bd VALUES (3895, 'Berserk', '10', 'Tome 10', 'Miura, Kentaro', '2723451003', '10/2005 (Parution le 19/10/2005)', 231, 'https://www.bedetheque.com/media/Couvertures/Berserk10_18102005.jpg', NULL);
INSERT INTO public.bd VALUES (3896, 'Berserk', '11', 'Tome 11', 'Miura, Kentaro', '2723451011', '01/2006 (Parution le 18/01/2006)', 227, 'https://www.bedetheque.com/media/Couvertures/Berserk11_17012006.jpg', NULL);
INSERT INTO public.bd VALUES (3897, 'Berserk', '12', 'Tome 12', 'Miura, Kentaro', '272345102X', '03/2006 (Parution le 15/03/2006)', 221, 'https://www.bedetheque.com/media/Couvertures/Berserk12_14032006.jpg', NULL);
INSERT INTO public.bd VALUES (3898, 'Berserk', '13', 'Tome 13', 'Miura, Kentaro', '2723454126', '05/2006 (Parution le 03/05/2006)', 231, 'https://www.bedetheque.com/media/Couvertures/Berserk13_02052006.jpg', NULL);
INSERT INTO public.bd VALUES (3899, 'Berserk', '14', 'Tome 14', 'Miura, Kentaro', '2723454371', '07/2006 (Parution le 12/07/2006)', 234, 'https://www.bedetheque.com/media/Couvertures/Berserk14_17072006.jpg', NULL);
INSERT INTO public.bd VALUES (3900, 'Berserk', '15', 'Tome 15', 'Miura, Kentaro', '272345438X', '09/2006 (Parution le 06/09/2006)', 226, 'https://www.bedetheque.com/media/Couvertures/Couv_57778.jpg', NULL);
INSERT INTO public.bd VALUES (3901, 'Berserk', '16', 'Tome 16', 'Miura, Kentaro', '2723454398', '11/2006 (Parution le 08/11/2006)', 227, 'https://www.bedetheque.com/media/Couvertures/Couv_59134.jpg', NULL);
INSERT INTO public.bd VALUES (3902, 'Berserk', '17', 'Tome 17', 'Miura, Kentaro', '2723454401', '01/2007 (Parution le 03/01/2007)', 231, 'https://www.bedetheque.com/media/Couvertures/Berserk17_30122006.jpg', NULL);
INSERT INTO public.bd VALUES (3903, 'Berserk', '18', 'Tome 18', 'Miura, Kentaro', '9782723454414', '03/2007 (Parution le 07/03/2007)', 231, 'https://www.bedetheque.com/media/Couvertures/Couv_61237.jpg', NULL);
INSERT INTO public.bd VALUES (3904, 'Berserk', '19', 'Tome 19', 'Miura, Kentaro', '9782723457989', '05/2007 (Parution le 06/06/2007)', 220, 'https://www.bedetheque.com/media/Couvertures/berserk19_63343.jpg', NULL);
INSERT INTO public.bd VALUES (3905, 'Berserk', '20', 'Tome 20', 'Miura, Kentaro', '9782723458108', '07/2007 (Parution le 11/07/2007)', 219, 'https://www.bedetheque.com/media/Couvertures/Berserk20_11072007_235411.jpg', NULL);
INSERT INTO public.bd VALUES (3906, 'Berserk', '21', 'Tome 21', 'Miura, Kentaro', '9782723458191', '09/2007 (Parution le 19/09/2007)', 231, 'https://www.bedetheque.com/media/Couvertures/Berserk21_19092007_213446.jpg', NULL);
INSERT INTO public.bd VALUES (3907, 'Berserk', '22', 'Tome 22', 'Miura, Kentaro', '9782723458283', '11/2007 (Parution le 28/11/2007)', 209, 'https://www.bedetheque.com/media/Couvertures/Berserk22_28112007_210600.jpg', NULL);
INSERT INTO public.bd VALUES (3908, 'Berserk', '23', 'Tome 23', 'Miura, Kentaro', '9782723459631', '01/2008 (Parution le 30/01/2008)', 198, 'https://www.bedetheque.com/media/Couvertures/Berserk23_30012008_195316.jpg', NULL);
INSERT INTO public.bd VALUES (3909, 'Berserk', '24', 'Tome 24', 'Miura, Kentaro', '9782723459648', '03/2008 (Parution le 19/03/2008)', 197, 'https://www.bedetheque.com/media/Couvertures/Berserk24_21032008_130302.jpg', NULL);
INSERT INTO public.bd VALUES (3910, 'Berserk', '25', 'Tome 25', 'Miura, Kentaro', '9782723459617', '05/2008 (Parution le 04/06/2008)', 208, 'https://www.bedetheque.com/media/Couvertures/Berserk25_07062008_110341.jpg', 'Guts et sa bande se sont rendus au village d’Inock, assiégé par une horde de trolls, pour en sauver les habitants. Grâce à Schierke, la petite magicienne envoyée par la sorcière de la forêt pour leur prêter main forte, l’église du village est protégée d’une barrière enchantée qui empêche toute intrusion ennemie. Mais une créature monstrueuse fait son arrivée : un ogre ! Et rien ne semble pouvoir stopper l’inexorable avancée des trolls. Bientôt, la ville devient le théâtre d’une lutte sans merci…');
INSERT INTO public.bd VALUES (3911, 'Berserk', '26', 'Tome 26', 'Miura, Kentaro', '9782723459624', '07/2008 (Parution le 09/07/2008)', 211, 'https://www.bedetheque.com/media/Couvertures/Berserk26_11072008_165404.jpg', 'Guts parvient à sauver Farnese et Casca des griffes des trolls, mais une vieille connaissance fait son apparition : Slan, l''une des cinq « God Hands » ! Celle-ci est irrésistiblement attirée par la rage et la hargne de Guts dont elle veut se repaître, et notre héros ne doit son salut qu''à l''arrivée du chevalier squelette. Grièvement blessé, Guts est reconduit au village de Schierke, attaqué par l''un de ses anciens compagnons d''armes ! Il n''a plus qu''un espoir : revêtir l''armure maudite du Berserk…');
INSERT INTO public.bd VALUES (3924, 'Berserk', '39', 'Tome 39', 'Miura, Kentaro', '9782344027417', '01/2018 (Parution le 17/01/2018)', 161, 'https://www.bedetheque.com/media/Couvertures/Couv_320501.jpg', 'Ayant triomphé de la menace du Dieu marin, le groupe de Guts arrive à destination et débarque à Skellig, alias Elf Helm, mais ils sont confrontés à des sortilèges et des pièges destinés à éloigner les visiteurs. Ils pénètrent plus loin dans les terres tout en contournant ces nouveaux obstacles. Casca sera-t-elle réellement en sécurité en ces lieux ? Et pourront-ils obtenir une audience avec le roi des pétales virevoltants, capable paraît-il de rendre la raison à la jeune femme ?');
INSERT INTO public.bd VALUES (3912, 'Berserk', '27', 'Tome 27', 'Miura, Kentaro', '9782723464727', '09/2008 (Parution le 24/09/2008)', 206, 'https://www.bedetheque.com/media/Couvertures/berserk27_78321.jpg', 'Pendant que l’armure du Berserk dévore la vie de Guts tout en lui conférant une force surhumaine, le royaume de Windham est le théâtre d’affrontements ahurissants entre l’armée du Faucon et l’empereur des Kushan. Celui-ci s’adonne à des expériences contre-nature pour créer des enfants démons, et il ne rêve que d’affronter Griffith. Ce volume marque un tournant majeur de Berserk de par son inventivité visuelle, son audace thématique et la maestria de ses scènes de batailles. Une véritable claque !');
INSERT INTO public.bd VALUES (3913, 'Berserk', '28', 'Tome 28', 'Miura, Kentaro', '9782723464734', '11/2008 (Parution le 18/11/2008)', 227, 'https://www.bedetheque.com/media/Couvertures/79753_c.jpg', 'Guts est désormais en possession de l''armure du Berserk, mais le chevalier squelette le met en garde : s''il persiste à en faire usage, il finira par y perdre ses sens et son humanité. La petite Schierke a beau promettre qu''elle ne laissera plus celui-ci l''utiliser, un monstre abominable fait son apparition et pousse le guerrier dans ses derniers retranchements. Prisonnier d''une armure qui lui dévore la vie tout en lui octroyant une force surhumaine, Guts ne trouve plus le moyen de s''en défaire…');
INSERT INTO public.bd VALUES (3914, 'Berserk', '29', 'Tome 29', 'Miura, Kentaro', '9782723464741', '01/2009 (Parution le 28/01/2009)', 200, 'https://www.bedetheque.com/media/Couvertures/81470_c.jpg', NULL);
INSERT INTO public.bd VALUES (3915, 'Berserk', '30', 'Tome 30', 'Miura, Kentaro', '9782723464758', '03/2009 (Parution le 11/03/2009)', 199, 'https://www.bedetheque.com/media/Couvertures/83819_c.jpg', 'Serpico tente tant bien que mal d’empêcher Guts d’atteindre Farnèse, mais l’épéiste, aussi génial et doué soit-il, ne peut que s’incliner devant la puissance de son adversaire. Toutefois, leur répit est de courte durée : de gigantesques tigres ont fait irruption dans la salle de bal, où les Vandimion célèbrent le début de la guerre sainte. Les Kushans ont encerclé la ville et s’adonnent à un véritable massacre ! Guts, aidé des siens, se lance alors dans une lutte sans merci contre un Makara monstrueux…');
INSERT INTO public.bd VALUES (3916, 'Berserk', '31', 'Tome 31', 'Miura, Kentaro', '9782723467223', '05/2009 (Parution le 20/05/2009)', 181, 'https://www.bedetheque.com/media/Couvertures/berserck31_87022.jpg', 'Face à une horde de monstres déchaînés, Guts et les siens n’ont d’autre option que le repli. Alors qu’ils essaient de prendre le large à bord d’un bateau, ils sont attaqués en pleine mer par un puissant sorcier Kushan, Dhaiva. Celui-ci use de sa magie, mais grâce à l’aide de Schierke, dont l’esprit s’est retrouvé prisonnier de l’armure du Berserk, Guts parvient à lui tenir tête. Jusqu’à ce qu’arrive le terrible empereur Ganishka, qui, découvrant la valeur de Guts, lui propose d’intégrer son armée…');
INSERT INTO public.bd VALUES (3917, 'Berserk', '32', 'Tome 32', 'Miura, Kentaro', '9782723467230', '07/2009 (Parution le 01/07/2009)', 213, 'https://www.bedetheque.com/media/Couvertures/88461_c.jpg', 'Zodd et Guts, ennemis de jadis, s’allient temporairement pour repousser le terrifiant empereur Ganishka. Et la guerre opposant ce dernier à Griffith s’accentue lors d’une confrontation directe entre les deux chefs d’armée. Pour la première fois, Ganishka est tétanisé devant son adversaire qui atteint une forme de consécration : le pape lui-même s’agenouille devant lui.');
INSERT INTO public.bd VALUES (3918, 'Berserk', '33', 'Tome 33', 'Miura, Kentaro', '9782723477123', '01/2011 (Parution le 26/01/2011)', 214, 'https://www.bedetheque.com/media/Couvertures/119460_c.jpg', 'La petite troupe de Guts a enfin largué les amarres en direction d''Elf Helm. Mais Guts a été gravement blessé dans son duel à mort contre l''empereur Ganishka. Il a ressenti la présence de Griffith, mais a décidé, dans son intérêt et celui de ses compagnons, de quitter le port. Ce voyage en bateau leur offre à tous un repos momentané, et tout en profitant de la vie à bord, chacun fait de son mieux pour achever son objectif. Mais voilà que le navire est attaqué par des pirates !');
INSERT INTO public.bd VALUES (3919, 'Berserk', '34', 'Tome 34', 'Miura, Kentaro', '9782723480741', '01/2011 (Parution le 20/04/2011)', 220, 'https://www.bedetheque.com/media/Couvertures/124775_c.jpg', 'Ayant subi une seconde transcendance dans le but de surpasser les God Hands, Ganishka, changé en bête maléfique si énorme qu''elle atteint le ciel, apparaît devant Griffith. Alors qu''il avance en piétinant ses troupes, tous les membres de la Nouvelle Troupe du Faucon, jugeant qu''il s''agit de la "bête démoniaque de la fin" ou "l''avatar de tous les maux", ont foi en un miracle du Faucon de Lumière. La bataille commence pour Griffith, les humains et guerriers-démons de la Nouvelle Troupe du Faucon !');
INSERT INTO public.bd VALUES (3920, 'Berserk', '35', 'Tome 35', 'Miura, Kentaro', '9782723484077', '07/2011 (Parution le 29/06/2011)', 196, 'https://www.bedetheque.com/media/Couvertures/129744_c.jpg', 'Le monde a changé. Ce monde nouveau, où monstres et créatures hier encore imaginaires ont pris vie, s''est étendu jusqu''aux confins de la Terre. Et en son cœur est apparue l''immense et majestueuse capitale du Faucon, Falconia. Alors que Griffith, qui a réalisé son rêve, et sa nouvelle troupe du Faucon entrent dans leur palais, ce nouvel univers se met en marche. Et ce monde qui a changé s''en prend à Guts et les siens, en route pour l''île de Skellig où se trouve Elf Helm : ils sont attaqués par un légendaire vaisseau fantôme !');
INSERT INTO public.bd VALUES (3921, 'Berserk', '36', 'Tome 36', 'Miura, Kentaro', '9782723491129', '01/2013 (Parution le 03/01/2013)', 191, 'https://www.bedetheque.com/media/Couvertures/Couv_178973.jpg', 'Le Sea Horse sur lequel Guts et les siens ont embarqué a accosté dans l''antre d''un maléfique "dieu des mers" ! À part une jeune fille prénommée Isma, les habitants de cette île désolée sont devenus des tentacules du dieu et c''est sous cette forme sinistre qu''ils attaquent la troupe de Guts. Le dieu marin ayant révélé son vrai visage, Guts a deviné que lui et ses compagnons ne pourraient quitter l''île. Afin d''éliminer l''ennemi et sans se soucier des souffrances qu''il va une nouvelle fois endurer, il revêt l''armure du Berserk. Mais malgré la puissance...');
INSERT INTO public.bd VALUES (3922, 'Berserk', '37', 'Tome 37', 'Miura, Kentaro', '9782723495943', '07/2014 (Parution le 02/07/2014)', 205, 'https://www.bedetheque.com/media/Couvertures/Couv_218524.jpg', 'Accompagnée de Schierke qui a pris son corps de lumière, Berserk a plongé dans les entrailles du dieu des mers qui apparaît tout en faisant s’écrouler l’île isolée ! Mais une fois à l’intérieur, ils sont attaqués par des bancs de poissons monstrueux et le battement du cœur géant du dieu, qui rend fou ceux qui l’écoutent. Pendant ce temps, les sirènes amies d’Isma se sont regroupées autour de la créature. Le temps est venu pour le long combat entre ces deux adversaires de prendre fin. Que va-t-il advenir de Guts et de Schierke, qui sont sur le fil...');
INSERT INTO public.bd VALUES (3923, 'Berserk', '38', 'Tome 38', 'Miura, Kentaro', '9782344009420', '01/2017 (Parution le 18/01/2017)', 185, 'https://www.bedetheque.com/media/Couvertures/Couv_297042.jpg', 'Rickert et Erika, partis à la recherche d''un endroit sûr dans le monde métamorphosé, sont attaqués par des démons et sauvés par la nouvelle troupe du Faucon ! Celle-ci les escorte jusqu''à Falconia où règne Griffith, le faucon blanc. Rickert est en proie à des sentiments contradictoires envers Griffith et le troupe du Faucon... Pendant ce temps, pour mettre Casca en sécurité et dans l''espoir qu''elle guérisse, Guts et les siens, ayant échappé au dieu marin, font route en direction d''Elf Helm, la patrie de Puck.');
INSERT INTO public.bd VALUES (3925, 'Berserk', '40', 'Tome 40', 'Miura, Kentaro', '9782344033845', '04/2019 (Parution le 17/04/2019)', 151, 'https://www.bedetheque.com/media/Couvertures/Couv_364752.jpg', NULL);
INSERT INTO public.bd VALUES (3926, 'Berserk', '41', 'Tome 41', 'Miura, Kentaro', '9782344053416', '07/2022 (Parution le 06/07/2022)', 151, 'https://www.bedetheque.com/media/Couvertures/Couv_449425.jpg', 'Les seinen manga s''adressent à de jeunes adultes. Les personnages sont souvent complexes et moins idéalistes (voire moins idéalisés) que dans les shônen. Les récits, plus mûrs et plus profonds sont également plus sombres.');
INSERT INTO public.bd VALUES (3927, 'Berserk', '42', 'Tome 42', 'Studio Gaga', '9782344063644', '07/2024 (Parution le 10/07/2024)', 170, 'https://www.bedetheque.com/media/Couvertures/Couv_500143.jpg', 'Guts et Casca ont échappé au sort des porteurs de la marque et coulent des jours tranquilles à Elf Helm. Mais au moment où le jeune garçon aux cheveux noirs perd son apparence innocente, cette paix trop brève s''écroule. Casca pousse un hurlement ! Guts brandit son épée géante ! Nouveau désastre, confrontation au désespoir. Les ténèbres galopantes qui jaillissent engloutissent tout sur leur passage !Après plus d''un an, voici enfin la suite de Berserk. Kentaro Miura étant décédé, c''est désormais son meilleur ami, Koji Mori, au fait de toutes les...');
INSERT INTO public.bd VALUES (3928, 'Berserk', 'HS2009', 'Illustrations file', 'Miura, Kentaro', '9782723468046', '01/2009 (Parution le 11/02/2009)', 128, 'https://www.bedetheque.com/media/Couvertures/82418_c.jpg', 'Les amoureux d’heroic fantasy et de la titanesque saga de Kentarô Miura se régaleront en parcourant cet ouvrage luxueux, qui compile, entre autres, les remarquables illustrations couleurs de Berserk dans un grand format aussi somptueux qu’inédit. Le trait virtuose du dessinateur se révèle ici sous son meilleur jour. Le livre offre en outre une passionnante plongée dans les arcanes de la série, avec une série d’interviews qui en disent long sur le degré de perfectionnisme de l’auteur. Ainsi plus richement doté qu’un simple art-book, Art of Berserk...');
INSERT INTO public.bd VALUES (3929, 'Berserk', 'HS2017', 'Official Guidebook', 'Miura, Kentaro', '9782344023921', '11/2017 (Parution le 22/11/2017)', 128, 'https://www.bedetheque.com/media/Couvertures/Couv_317456.jpg', NULL);
INSERT INTO public.bd VALUES (3930, 'Berserk', 'INT01', 'Tome 1', 'Miura, Kentaro', '9782344067802', '06/2025 (Parution le 04/06/2025)', 464, 'https://www.bedetheque.com/media/Couvertures/Couv_522921.jpg', 'On ne présente plus Guts, le guerrier solitaire à l’épée démesurée. Marqué par un terrible passé, il parcourt le monde en semant la mort sur son passage. Un jour, il vient en aide à Puck, un elfe facétieux et volubile qui décide de l’accompagner dans son voyage. Traqué par des forces obscures, Guts tente de devenir maître de son destin pour regagner sa liberté et accomplir sa vengeance…');
INSERT INTO public.bd VALUES (3931, 'Berserk', 'INT02', 'Tome 2', 'Miura, Kentaro', '9782344067819', '06/2025 (Parution le 18/06/2025)', 480, 'https://www.bedetheque.com/media/Couvertures/Couv_523418.jpg', 'Guts, le guerrier noir, promène son imposante silhouette de routes en villages. Sur son passage, les cadavres s''amoncellent et il laisse derrière lui des torrents de sang. Le corps vêtu de noir, il porte sur son dos une épée aussi haute qu''un homme. Sur son cou, une marque mystérieuse le condamne à être poursuivi jour et nuit par des démons. Puck, l''elfe facétieux, croise un jour le chemin de cette machine à tuer. Quelles horreurs a-t-il pu connaître pour être animé d''une telle soif de vengeance ? Alors que le monde sombre inextricablement dans...');
INSERT INTO public.bd VALUES (3932, 'Berserk', 'INT03', 'Tome 3', 'Miura, Kentaro', '9782344067826', '11/2025 (Parution le 13/11/2025)', 464, 'https://www.bedetheque.com/media/Couvertures/Couv_530500.jpg', 'Les seinen manga s''adressent à de jeunes adultes. Les personnages sont souvent complexes et moins idéalistes (voire moins idéalisés) que dans les shônen. Les récits, plus mûrs et plus profonds sont également plus sombres.');
INSERT INTO public.bd VALUES (3933, 'Berserk', 'INT04', 'Tome 4', 'Miura, Kentaro', '9782344067833', '02/2026 (Parution le 18/02/2026)', 464, 'https://www.bedetheque.com/media/Couvertures/Couv_533346.jpg', 'Partie intégrante de l''armée régulière du royaume de Midland, la Troupe du Faucon et son leader Griffith accumulent les succès dans la campagne pour conquérir la paix. Dans la bataille finale face à Tudor, la troupe brille par ses exploits. Mais Guts et Casca se retrouvent précipités au fond d''un précipice. Soignée par Guts de la fièvre qui la frappe, Casca se livre et lui raconte son histoire : comment elle rejoignit la Troupe du Faucon, comment elle fut sauvée par Griffith et quels sont ses sentiments pour lui... De retour sur le front, ils participent...');
INSERT INTO public.bd VALUES (3934, 'Berserk', 'Roman', 'Le chevalier du dragon des flammes', 'Miura, Kentaro', '2344031200', '04/2019 (Parution le 17/04/2019)', 464, 'https://www.bedetheque.com/media/Couvertures/Couv_388794.jpg', 'Avec la sortie du 40e volume de Berserk, voici enfin la première novelisation officielle ! Elle dévoile une partie inédite de l’univers du manga. Makoto Fukami raconte avec passion la vie de Grunbeld, membre de la Nouvelle Troupe du Faucon, qui a pendant dix ans résisté à l’invasion de l’empire Tudor ! Ne manquez pas d''approfondir votre exploration du monde de Berserk, grâce notamment aux nombreuses illustrations de Kentaro Miura !');
INSERT INTO public.bd VALUES (3935, 'Profs (Les)', '1', 'Interro surprise', 'Erroc', '2912715121', '06/2000', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_12445.jpg', NULL);
INSERT INTO public.bd VALUES (3936, 'Profs (Les)', '2', 'Loto et colles', 'Erroc', '2912715245', '06/2001', 46, 'https://www.bedetheque.com/media/Couvertures/profscouv02.jpg', NULL);
INSERT INTO public.bd VALUES (3937, 'Profs (Les)', '3', 'Tohu-bahut', 'Erroc', '2912715326', '11/2001', 46, 'https://www.bedetheque.com/media/Couvertures/profs03.jpg', NULL);
INSERT INTO public.bd VALUES (3938, 'Profs (Les)', '4', 'Rentrée des artistes', 'Erroc', '2912715512', '08/2002', 44, 'https://www.bedetheque.com/media/Couvertures/lesprofs4_14092002.jpg', NULL);
INSERT INTO public.bd VALUES (3939, 'Profs (Les)', '5', 'Chute des cours', 'Erroc', '2912715903', '08/2003', 44, 'https://www.bedetheque.com/media/Couvertures/profscou05.JPG', NULL);
INSERT INTO public.bd VALUES (3940, 'Profs (Les)', '6', 'Classe touriste', 'Erroc', '2915309159', '08/2004', 44, 'https://www.bedetheque.com/media/Couvertures/profs06.jpg', 'Bien requinqués par deux mois de vacances au soleil, les Profs de Pica et Erroc sont de retour hyper-motivés pour préparer... les vacances d''été suivantes ! En effet, pas facile de retrouver ces braves cancres qui excellent dans la production de copies «nullissimes». Ou plutôt «positivement nulles» : comme dit le proviseur, il faut savoir positiver pour tenir toute l''année ! Bienvenue dans les aventures décapodélirantes du prof d''histoire débutant, de la prof de français sexy, du prof de philo blasé et de l''inévitable cancre sympa. Bref, bienvenue...');
INSERT INTO public.bd VALUES (3941, 'Profs (Les)', '7', 'Mise en examen', 'Erroc', '2915309701', '03/2005', 44, 'https://www.bedetheque.com/media/Couvertures/ProfsLes7_08032005.jpg', NULL);
INSERT INTO public.bd VALUES (3942, 'Profs (Les)', '8', 'Fenêtre sur cours', 'Erroc', '291530971X', '09/2005', 44, 'https://www.bedetheque.com/media/Couvertures/profs08.jpg', NULL);
INSERT INTO public.bd VALUES (3943, 'Profs (Les)', '9', 'Rythme scolaire', 'Erroc', '2350781194', '09/2006', 41, 'https://www.bedetheque.com/media/Couvertures/profs09.jpg', NULL);
INSERT INTO public.bd VALUES (3944, 'Profs (Les)', '10', 'Motivation : 10/10', 'Erroc', '9782350782966', '08/2007', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_66064.jpg', NULL);
INSERT INTO public.bd VALUES (3945, 'Profs (Les)', '11', 'Tableau d''horreur', 'Erroc', '9782350784540', '08/2008', 44, 'https://www.bedetheque.com/media/Couvertures/profs11_77369.jpg', NULL);
INSERT INTO public.bd VALUES (3974, 'Profs (Les)', 'HS01', 'Best of 10 ans bamboo', 'Erroc', '9782350784854', '01/2008', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_75460.jpg', NULL);
INSERT INTO public.bd VALUES (3946, 'Profs (Les)', '12', 'Grève party', 'Erroc', '9782350786438', '10/2009 (Parution le 07/10/2009)', 44, 'https://www.bedetheque.com/media/Couvertures/profs_12_96223.jpg', 'Du neuf au lycée, Julien jeune enseignant en mathématiques rejoint l''équipe des Profs. Un poil angoissé, le novice va offrir quelques fous rires aux élèves et aux lecteurs. Par ailleurs, M. Polochon, fameux professeur d''histoire, est nommé maître de stage. Il est chargé d''encadrer la sémillante Mlle Doucet, dont le regard de biche bouleverse l''établissement. Enfin, les profs sont au regret d''annoncer le décès du vénérable catalogue Camif. Il est remplacé par Shopping prof.com, plus moderne et plus loufoque.');
INSERT INTO public.bd VALUES (3947, 'Profs (Les)', '13', 'Devoir surveillé', 'Erroc', '9782818900369', '10/2010', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_116130.jpg', NULL);
INSERT INTO public.bd VALUES (3948, 'Profs (Les)', '14', 'Buzz scolaire', 'Erroc', '9782818906996', '11/2011 (Parution le 03/11/2011)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_145260.jpg', 'Oubliez Brad Pitre et Angelina Jaunie, et retrouvez les vraies stars du monde réel : les Profs ! Grâce à la fonction vidéo des smartphones dernier cri, les plus grands instants de l''Éducation nationale peuvent désormais être immortalisés, du cours honteusement raté  aux petits flirts entre professeurs. Ne manquez pas le buzz scolaire de la rentrée avec ce 14e tome des aventures hilarantes des Profs !');
INSERT INTO public.bd VALUES (3949, 'Profs (Les)', '15', 'Bulletin météo', 'Erroc', '9782818921364', '11/2012 (Parution le 07/11/2012)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_175882.jpg', 'Les Profs, la BD recommandée anti-morosité par l’Éducation nationale ! Suivez le prof d’histoire débutant, le prof de gym sur-vitaminé, la prof de français sexy, le prof de philo blasé et la prof d’anglais peau de vache dans leur croisade contre l’ignorance et le poil dans la main ! Plus forts que Zorro, plus courageux qu’Indiana Jones et bien moins payés que James Bond, ils pénètrent dans la jungle étouffante des lycées pour affronter les tribus d’élèves hostiles. Puis, épuisés, ils se réfugient dans leur oasis : la salle des profs ! Là, entre...');
INSERT INTO public.bd VALUES (3950, 'Profs (Les)', '16', '1, 2, 3 rentrée !', 'Erroc', '9782818925317', '11/2013 (Parution le 20/11/2013)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_199158.jpg', 'Après leur triomphe au cinéma, les Profs reviennent dans une BD au top de l’humour ! Ça ne tourne plus rond chez les Profs ! La nouvelle proviseure essaie toujours de réformer le lycée, mais le corps enseignant est un peu fatigué, voire fatigant. Boulard, le cancre de classe internationale, continue de repousser les limites de la glande et un nouveau prof d’EPS vient bousculer ce pauvre Éric. Et pour couronner le tout, voici qu’un réalisateur débarque avec l’idée saugrenue de faire un film sur les Profs ! Ne manquez pas le nouvel épisode de cette...');
INSERT INTO public.bd VALUES (3951, 'Profs (Les)', '17', 'Sortie scolaire', 'Erroc', '9782818933541', '05/2015 (Parution le 27/05/2015)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_245244.jpg', 'Quand les Profs ne font pas leur cinéma, ils s’agitent dans une BD au top de l’humour ! Et si les seuls vrais aventuriers modernes, c’était les profs ? Plus forts que Zorro, plus courageux qu’Indiana Jones et bien moins payés que James Bond, ces enseignants de choc n’hésitent pas à braver quotidiennement la jungle étouffante des lycées peuplés de tribus d’élèves hostiles. Suivez le prof d’histoire débutant, le prof de gym sur-vitaminé, la prof de français sexy, le prof de philo blasé et la prof d’anglais peau de vache dans leur croisade contre...');
INSERT INTO public.bd VALUES (3952, 'Profs (Les)', '18', 'Hors-sujet', 'Erroc', '9782818940365', '11/2016 (Parution le 16/11/2016)', 42, 'https://www.bedetheque.com/media/Couvertures/Couv_292963.jpg', NULL);
INSERT INTO public.bd VALUES (3953, 'Profs (Les)', '19', 'Note to be', 'Erroc', '9782818942543', '08/2017 (Parution le 06/09/2017)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_310883.jpg', 'Rien ne va plus au lycée Fanfaron. Tout le monde voit des complots partout, le journal Tohu Bahut colporte les pires ragots, les manifs tombent à l''eau et même Serge est plein d''entrain pour faire cours. La proviseure n''a plus le choix : elle doit mettre en application sa toute nouvelle formation pour gérer');
INSERT INTO public.bd VALUES (3954, 'Profs (Les)', '20', 'Lycée Boulard', 'Erroc', '9782818943489', '11/2017 (Parution le 15/11/2017)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_315680.jpg', NULL);
INSERT INTO public.bd VALUES (3955, 'Profs (Les)', '21', 'Rentrée des clashs', 'Erroc', '9782818946800', '08/2018 (Parution le 22/08/2018)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_341979.jpg', NULL);
INSERT INTO public.bd VALUES (3956, 'Profs (Les)', '22', 'Tour de contrôles', 'Erroc', '9782818967171', '08/2019 (Parution le 21/08/2019)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_371305.jpg', 'Le retour des Profs à la rentrée ! Après leur triomphe au cinéma et leur succès jamais démenti en librairie, Les Profs reviennent avec un nouveau tome en août. Simon Léturgie, après avoir succédé à Pica au dessin en 2016, propose avec Erroc & Sti un nouveau florilège de gags toujours aussi hilarants. Cette fois, c''est le branle-bas de combat au lycée Fanfaron : le ministre de l''Éducation nationale va venir. Pour faire bonne impression, on ne veut que des élèves modèles et propre sur eux ! Du coup c''est comme en boite : chemise et pantalon de costume,...');
INSERT INTO public.bd VALUES (3957, 'Profs (Les)', '23', 'Heure de cool', 'Erroc', '9782818975961', '11/2020 (Parution le 28/10/2020)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_402416.jpg', 'Combat de cancres au bahut ! Après leur triomphe au cinéma et leur succès jamais démenti en librairie, Les Profs reviennent avec un nouveau tome en août. Simon Léturgie, après avoir succédé à Pica au dessin en 2016, propose avec Erroc & Sti un nouveau florilège de gags toujours aussi hilarants. Cette fois, rien ne va plus au lycée Fanfaron : Boulard a une rivale au bahut. Deux cancres, ça risque de faire beaucoup beaucoup trop pour la sympathique équipe éducative."');
INSERT INTO public.bd VALUES (3958, 'Profs (Les)', '24', 'Oral de rattrapage', 'Erroc', '9782818986424', '11/2021 (Parution le 03/11/2021)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_433421.jpg', 'Suite à une énième explosion due à au prof de chimie, le lycée Fanfaron est inopérationnel… Mais pas question pour la fine fleur professorale que leurs élèves n’aient pas de continuité pédagogique… Visioconférences gênées par les pleurs du bébé Polochon que même ses baby-sitters Boulard et Louise n’arrivent pas à calmer, cours dans le parc municipal ou le bistrot du coin, ils ne les lâcheront pas, quitte à aller les rechercher à la fête foraine qui vient de s’installer en ville… Ah les élèves veulent un tour gratuit ? Eh bien, ça sera avec Gladys…...');
INSERT INTO public.bd VALUES (3959, 'Profs (Les)', '25', 'Carte scolaire', 'Erroc', '9782818994870', '09/2022 (Parution le 28/09/2022)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_454738.jpg', 'La BD anti-morosité recommandée par l''Éducation nationale ! Pour nos Profs, cette nouvelle année est une année banale: donc c''est de pire en pire! Les restrictions de budget sont de plus en plus démentes et les profs n''ont plus droit qu''à une demi-photocopie chacun! Le rectorat impose un protocole de sécurité délirant qui change tout le temps et le ministre a des idées géniales, genre équiper les profs de casques antibruit pour qu''ils n''entendent pas leurs élèves dire n''importe quoi! Au milieu de tout ça, Boulard est toujours amoureux de Louise...');
INSERT INTO public.bd VALUES (3975, 'Profs (Les)', 'HS02', 'Les inédits', 'Erroc', '2244298620', '01/2006', 30, 'https://www.bedetheque.com/media/Couvertures/ProfsLestl_18032006.jpg', NULL);
INSERT INTO public.bd VALUES (3960, 'Profs (Les)', '26', 'Job dating', 'Erroc', '9791041100286', '11/2023 (Parution le 02/11/2023)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_485841.jpg', 'Devenir prof ? Vous n’y pensez pas ! Jamais de la vie. Alors que la profession souffre d’un désintérêt profond, et que cette année encore, des centaines de postes ne sont pas pourvus, le rectorat sort une nouvelle idée de génie de ses dossiers. Ce sera aux équipes éducatives de se charger du recrutement. À elles de trouver les perles rares pour compléter l’équipe pédagogique. Au lycée Fanfaron, c’est parti pour des séances de Job Dating pour trouver les futurs profs. Mais le pizzaiolo du coin fera-t-il un bon prof d’italien ? L’ancien militaire...');
INSERT INTO public.bd VALUES (3961, 'Profs (Les)', '27', 'Retraite à point', 'Erroc', '9791041103379', '10/2024 (Parution le 30/10/2024)', 56, 'https://www.bedetheque.com/media/Couvertures/Couv_506838.jpg', 'La BD anti-morosité recommandée par l''Éducation nationale !  L''heure de la retraite a sonné pour Maurice. Après de si nombreuses années à transmettre le savoir philosophique à une meute d''ados qui s''en fiche, à lui la belle vie ! Mais peut-on vivre normalement aussi loin de la photocopieuse, de la machine à café, des classes qui sentent la craie et de la salle des profs quand on a toujours connu ça. Parce qu''après tout, le lycée, ça vous remplit l''existence. N''est-ce pas, Boulard ?');
INSERT INTO public.bd VALUES (3962, 'Profs (Les)', '28', 'Carnet de potes', 'Erroc', '9791041112173', '10/2025 (Parution le 29/10/2025)', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_528378.jpg', 'La BD anti-morosité recommandée par l''Éducation nationale !  La nouvelle circulaire imposant la tenue unique pour tous les élèves met le lycée Fanfaron en émoi. Une tenue unique, d''accord, mais laquelle ? Cette décision ministérielle pousse même nos Profs à se replonger dans le passé. Une bonne occasion de découvrir comment Polochon, Amina, Gladys et même Serge ont découvert leur vocation pour l''enseignement. Mais avec les Profs, on est loin du « C''était mieux avant... ». D''ailleurs un nouveau prof (d''arts plastiques) hyper motivé, hyper connecté...');
INSERT INTO public.bd VALUES (3963, 'Profs (Les)', 'BO', 'Best or - Shopping prof', 'Erroc', '9791041101184', '06/2023 (Parution le 02/06/2023)', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_475462.jpg', 'Vous êtes prof et vous rêvez d''une machine à corriger les copies à grande vitesse ? Vous avez besoin d''urgence d''un simulateur de panne de photocopieur ? La réunion parents/profs vous stresse et vous voulez vous procurer le neutralisateur de parents ? Pas de panique, dans cet album best of, vous trouverez tous les meilleurs articles vendus par Shopping Prof. Des articles qui n''ont qu''un seul et unique but : aider les profs à survivre à leurs études.');
INSERT INTO public.bd VALUES (3964, 'Profs (Les)', 'BO1', 'Gladys, prof d''anglais', 'Erroc', '9782818903391', '04/2011 (Parution le 13/04/2011)', 38, 'https://www.bedetheque.com/media/Couvertures/Couv_123990.jpg', '"Vous êtes nuls à bouffer vos copies !" Après la langue de Shakespeare, découvrez la langue fleurie de Gladys, la prof d''anglais peau de vache !');
INSERT INTO public.bd VALUES (3965, 'Profs (Les)', 'BO2', 'Boulard, super cancre !!!', 'Erroc', '9782818907337', '09/2011 (Parution le 07/09/2011)', 32, 'https://www.bedetheque.com/media/Couvertures/Couv_138810.jpg', 'Une salle de classe sans Thierry Boulard, ce serait comme un cours de Monsieur Polochon sans une citation de Napoléon : une morne plaine. Redoublant à vie et abonné aux notes catastrophiques, Boulard vient au lycée parce que c''est bien chauffé, mais aussi pour voir les copains et les décolletés de la prof de français. Celui qui plafonne à 2 sur 20 - et qui pense pouvoir faire encore pire - vous donne rendez-vous au fond de la classe, près du radiateur pour un moment de franche poilade dans ce best of qui redouble d''efforts pour votre bonne humeur...');
INSERT INTO public.bd VALUES (3966, 'Profs (Les)', 'BO3', 'En vacances', 'Erroc', '9782818909775', '06/2012 (Parution le 06/06/2012)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_181514.jpg', 'Tous les deux mois en moyenne, le moral des Profs remonte en flèche... Par quel mystère ? Revalorisation salariale ? Un élève qui les écoute enfin ? Que nenni ! Grâce aux vacances scolaires ! Pendant cette période tant attendue, nos enseignants préférés débordent d’énergie pour vous proposer des gags plein de soleil... sauf la prof d’anglais qui n’a pas compris qu’elle pouvait partir ailleurs qu’en Angleterre. Alors retrouvez Maurice, Antoine, Amina, Gladys et leurs doigts de pieds en éventail dans cette compilation spéciale vacances des Profs.');
INSERT INTO public.bd VALUES (3967, 'Profs (Les)', 'BO4', 'La salle des profs', 'Erroc', '9782818932049', '11/2014 (Parution le 29/10/2014)', 39, 'https://www.bedetheque.com/media/Couvertures/Couv_231615.jpg', 'Classes difficiles, élèves aux abonnés absents façon Boulard… Et si le bonheur, pour Antoine, Amina ou Maurice, était dans la salle des profs ? Dans cette oasis où se dresse l’indispensable machine à café, nos enseignants peuvent se serrer les coudes, refaire le monde de l’éducation et des plans pour les vacances. Mais il s’en passe aussi des belles dans cette zone à l’abri des regards indiscrets, c’est ce que vous allez découvrir dans cette compilation dédiée à la salle des profs !');
INSERT INTO public.bd VALUES (3968, 'Profs (Les)', 'BO5', 'Eric, prof de sport', 'Erroc', '9791041103317', '06/2024 (Parution le 26/06/2024)', 37, 'https://www.bedetheque.com/media/Couvertures/Couv_508707.jpg', 'Avec Éric, le prof de sport, vous allez être musclé jusqu''aux zygomatiques ! Préparez les baskets, le survêt'', la bouteille d''eau (et le courage) car Éric, le plus original des profs d''EPS va vous entraîner sur tous les terrains pour un best of de compétition. Retrouvez tous les meilleurs gags de la série Les Profs et préparez-vous à être plié en deux (ou même en quatre) ! Ça va être du sport, on vous dit !');
INSERT INTO public.bd VALUES (3969, 'Profs (Les)', 'Compil2', 'Le best of', 'Erroc', '9782205996432', '09/2013', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_207229.jpg', 'Suivez le prof d’histoire débutant, le prof de gym sur-vitaminé, la prof de français sexy, le prof de philo blasé et la prof d’anglais peau de vache dans leur croisade contre l’ignorance et le poil dans la main ! Plus forts que Zorro, plus courageux qu’Indiana Jones et bien moins payés que James Bond, ils pénètrent dans la jungle étouffante des lycées pour affronter les tribus d’élèves hostiles. Puis, épuisés, ils se réfugient dans leur oasis : la salle des profs ! Là, entre la machine à café en panne et les 150 copies à corriger pour demain, ils...');
INSERT INTO public.bd VALUES (3970, 'Profs (Les)', 'Compil3', 'Le Best Of', 'Erroc', '978235758017q', '06/2014', 43, 'https://www.bedetheque.com/media/Couvertures/Couv_253037.jpg', 'Classes difficiles, élèves aux abonnés absents façon Boulard… Et si le bonheur, pour Antoine, Amina ou Maurice, était dans la salle des profs ? Dans cette oasis où se dresse l’indispensable machine à café, nos enseignants peuvent se serrer les coudes, refaire le monde de l’éducation et des plans pour les vacances. Mais il s’en passe aussi des belles dans cette zone à l’abri des regards indiscrets, c’est ce que vous allez découvrir dans cette compilation dédiée à la salle des profs !');
INSERT INTO public.bd VALUES (3971, 'Profs (Les)', 'Compil5', 'Best of Prof d''histoire-géo', 'Pica', '9782818926017', '08/2013', 32, 'https://www.bedetheque.com/media/Couvertures/Couv_403884.jpg', NULL);
INSERT INTO public.bd VALUES (3972, 'Profs (Les)', 'FL01', 'Best of', 'Pica', '9782298049527', '10/2011', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_150763.jpg', NULL);
INSERT INTO public.bd VALUES (3973, 'Profs (Les)', 'HS', 'Agenda 2003-2004', 'Erroc', '2712472810', NULL, 44, 'https://www.bedetheque.com/media/Couvertures/CouvProfsAgenda_27092003.jpg', NULL);
