INSERT INTO public.bd VALUES (3977, 'Profs (Les)', 'HS03Pub', 'Cérébral Quiz "échantillon gratuit"', '<Collectif>', '9782205068221', '06/2008', 12, 'https://www.bedetheque.com/media/Couvertures/Couv_157164.jpg', 'Cet été, préparez-vous pour le grand défi cérébral des Profs : Cérébral Quiz.');
