INSERT INTO public.bd VALUES (3979, 'Profs (Les)', 'HS06', 'Best ouf ! Les gendarmes Les pompiers', 'Erroc', '9782818940624', '08/2016', 32, 'https://www.bedetheque.com/media/Couvertures/Couv_300526.jpg', NULL);
INSERT INTO public.bd VALUES (3980, 'Profs (Les)', 'HS10', 'tablo nwè', 'Erroc', '9782917623084', '09/2009', 52, 'https://www.bedetheque.com/media/Couvertures/Couv_463417.jpg', NULL);
INSERT INTO public.bd VALUES (3981, 'Profs (Les)', 'HS10', 'Les strips inédits', 'Erroc', '9782818987896', '08/2021', 30, 'https://www.bedetheque.com/media/Couvertures/Couv_431879.jpg', 'Strips inédits dont 3 de Simon Léturgie.');
INSERT INTO public.bd VALUES (3982, 'Profs (Les)', 'HS11', 'Les Strips inédits, Tome 2 !', 'Erroc', '9782818997093', '08/2022 (Parution le 28/05/2020)', 29, 'https://www.bedetheque.com/media/Couvertures/Couv_454855.jpg', NULL);
INSERT INTO public.bd VALUES (3983, 'Profs (Les)', 'HS7', 'L''album des 20 ans', 'Erroc', '9782818977309', '05/2020', 82, 'https://www.bedetheque.com/media/Couvertures/Couv_396284.jpg', 'En 2000 sortait le premier tome des Profs chez Bamboo. 20 ans et plusieurs millions d’albums vendus plus tard, après deux films au cinéma, on peut sans problème dire que les personnages de Pica et Erroc font partie du patrimoine de la bande dessinée. Pour fêter cet anniversaire, quoi de mieux qu’un album unique. Au sommaire : 22 planches commentées par les auteurs ; une histoire inédite de 20 pages écrites par Erroc et Sti et dessinées par 20 dessinateurs ; des interviews exceptionnelles des auteurs ; 20 ans d’actualités revues par les Profs ;...');
INSERT INTO public.bd VALUES (3984, 'Profs (Les)', 'HS8', 'Salle trop classe', 'Erroc', '9782818978917', '06/2020', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_397879.jpg', NULL);
INSERT INTO public.bd VALUES (3985, 'Profs (Les)', 'HS9', 'Les profs quiz !', '<Collectif>', '9782818978788', '08/2020 (Parution le 25/06/2008)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_400885.jpg', 'Jouez au grand quiz cérébral des Profs, avec plus de 300 questions pour se remuer les méninges en s''amusant. Quel que soit votre niveau, du primaire à la terminale, testez vos connaissances en maths, sciences plysiques, français, géographie, histoire ou sport ... Et vous serez incollable à la rentrée !');
INSERT INTO public.bd VALUES (3986, 'Profs (Les)', 'Quick1', 'Boulard', 'Erroc', '9782818992296', '01/2022', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_458984.jpg', NULL);
