INSERT INTO public.bd VALUES (3992, 'Gendarmes (Les)', '2', 'Procès vert pâle !', 'Sulpice, Olivier', '2912715067', '11/1999', 46, 'https://www.bedetheque.com/media/Couvertures/gendarmescouv02.jpg', NULL);
