INSERT INTO public.bd VALUES (3994, 'Gendarmes (Les)', '4', 'Amende honorable !', 'Sulpice, Olivier', '2912715334', '11/2001', 46, 'https://www.bedetheque.com/media/Couvertures/gendarmes04.jpg', NULL);
