INSERT INTO public.bd VALUES (3996, 'Gendarmes (Les)', '6', 'Un P.V. dans la mare !', 'Cazenove, Christophe', '2912715946', '11/2003', 46, 'https://www.bedetheque.com/media/Couvertures/gendarmescouv06.jpg', NULL);
