INSERT INTO public.bd VALUES (4023, 'Gendarmes (Les)', 'INT05', 'Intégrale 5', 'Cazenove, Christophe', '9782818924815', '11/2013', 92, 'https://www.bedetheque.com/media/Couvertures/Couv_370471.jpg', NULL);
INSERT INTO public.bd VALUES (4024, 'Gendarmes (Les)', 'INT06', 'Intégrale 6', 'Sulpice, Olivier', '9782818924822', '11/2013', 92, 'https://www.bedetheque.com/media/Couvertures/Couv_392989.jpg', NULL);
INSERT INTO public.bd VALUES (4025, 'Gendarmes (Les)', 'INT07', 'Intégrale 7', 'Sulpice, Olivier', '9782818924839', '11/2013', 90, 'https://www.bedetheque.com/media/Couvertures/Couv_370472.jpg', 'Et voici nos gendarmes partis pour une nouvelle mission qui va s’avérer particulièrement chaude. Non pas qu’elle soit dangereuse ou qu’elle implique des personnalités haut placées, mais parce qu’elle se déroule dans le midi de la France en pleine canicule.');
INSERT INTO public.bd VALUES (4026, 'Gendarmes (Les)', 'Pub', 'Le Best Of', 'Sulpice, Olivier', '978235902918', '08/2011', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_137531.jpg', NULL);
