INSERT INTO public.bd VALUES (4037, 'Élève Ducobu (L'')', '11', 'Peut mieux faire!', 'Zidrou', '2803620774', '08/2005', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_48926.jpg', NULL);
INSERT INTO public.bd VALUES (4038, 'Élève Ducobu (L'')', '12', '280 de Q.I. !', 'Zidrou', '2803621800', '08/2006', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_57670.jpg', NULL);
INSERT INTO public.bd VALUES (4039, 'Élève Ducobu (L'')', '13', 'Pas vu, pas pris !', 'Zidrou', '9782803622948', '08/2007', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_66080.jpg', NULL);
INSERT INTO public.bd VALUES (4040, 'Élève Ducobu (L'')', '14', 'Premier de la classe (en commençant par la fin)', 'Zidrou', '9782803624379', '08/2008', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_77528.jpg', NULL);
INSERT INTO public.bd VALUES (4041, 'Élève Ducobu (L'')', '15', 'Ça sent les vacances !', 'Zidrou', '9782803625543', '06/2009 (Parution le 05/06/2009)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_88792.jpg', 'Qui a eu cette idée folle, un jour d’inventer l’école ? Sûrement pas Ducobu qui, lorsqu’il voyage dans le temps en pensée, n’a qu’une obsession: retrouver Charlemagne et l’empêcher de commettre l’irréparable. Mais, dans l’ombre de tout cancre, il y a toujours une première de la classe... Résolu, notre trublion jaune et noir s’en retourne aux bonnes vieilles habitudes. Et, croyez-nous, quand il s’agit d’inventer de nouvelles manières de tricher, son imagination est sans limites…');
INSERT INTO public.bd VALUES (4042, 'Élève Ducobu (L'')', '16', 'Confisqués !', 'Zidrou', '9782803626403', '06/2010 (Parution le 04/06/2010)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_111106.jpg', 'Après 15 albums passés à rendre chèvre Monsieur Latouche et profiter placidement de la chaleur du coin au fond de la classe, ça devait finir par arriver : Ducobu s’est vu confisquer son « Rik Spoutnik Magazine » ! Mais, tel est pris qui croyait prendre ! Il n’aura suffi que de quelques pages feuilletées pour rendre Monsieur Latouche définitivement accro. Et encore, personne ne se doute du secret que renferme la caverne sous l’école Saint- Potache…Voici entre autres ce que nous réservent Godi et Zidrou pour les 16es aventures du cancre le plus irrécupérable...');
INSERT INTO public.bd VALUES (4043, 'Élève Ducobu (L'')', '17', 'Silence, on copie!', 'Zidrou', '9782803628254', '06/2011 (Parution le 10/06/2011)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_131130.jpg', 'Vous l''avez deviné : M. Latouche a une nouvelle fois cédé à ses plus bas instincts : sa dictée mycologique favorite est de retour ! Mais, Ducobu ne l''entend pas de cette oreille. L''union faisant la force, notre potache préféré a décidé de fédérer les apprentis cancres du monde entier, au sein du C.U.L. (Cancres Unis dans la Lutte). Conseils de triche ou séminaires sur les passe-temps possibles durant les heures de cours, il ne reculera devant rien... Une révolution ? Meuh nan, sire, juste une petite révolte de bon aloi ! Une révolution ? Meuh nan,...');
INSERT INTO public.bd VALUES (4044, 'Élève Ducobu (L'')', '18', 'Révise un max !', 'Zidrou', '9782803630516', '04/2012 (Parution le 13/04/2012)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_161182.jpg', 'Dans ce nouvel album, Ducobu donne le meilleur de lui-même pour conserver le titre d''Empereur des tricheurs et faire contre mauvaise fortune bons points. S''il ne sait toujours pas combien font 6 x7, il ne manque pas d''intelligence ni d''un sens personnel et aiguisé de la rhétorique pour déstabiliser ce bon vieux Latouche qui en perdrait presque son latin, Latouche qui semble d''autant plus troublé du fait de la présence à Saint-Potache de sa fragile collègue Mademoiselle Rateau.');
INSERT INTO public.bd VALUES (4045, 'Élève Ducobu (L'')', '19', 'Ducobu, élève modèle', 'Zidrou', '9782803632800', '05/2013 (Parution le 03/05/2013)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_186598.jpg', 'Ducobu ne recule devant rien pour changer d''image et passer pour un élève modèle : il fait appel aux services de Mme Futurina voyante aux prédictions concoctées par lui-même,  pose pour une photo avec Léonie, il joue même au ping-pong avec M. Latouche. Mais il n''en oublie pas pour autant d''inventer de nouveaux procédés pour tricher en toute discrétion et copier les réponses de sa chère voisine.');
INSERT INTO public.bd VALUES (4046, 'Élève Ducobu (L'')', '20', '0+0=Duco!', 'Zidrou', '9782803634477', '06/2014 (Parution le 13/06/2014)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_218414.jpg', NULL);
INSERT INTO public.bd VALUES (4047, 'Élève Ducobu (L'')', '21', 'In-cu-ra-ble !', 'Zidrou', '9782803635443', '05/2015 (Parution le 22/05/2015)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_245739.jpg', 'Le cancre le plus inventif du monde atteint de nouveaux sommets dans l''art de la triche.');
INSERT INTO public.bd VALUES (4048, 'Élève Ducobu (L'')', '22', 'Système D', 'Zidrou', '9782803636976', '05/2016 (Parution le 20/05/2016)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_279625.jpg', 'Contrairement à Léonie Gratin et Monsieur Latouche, Ducobu attend les vacances avec impatience ! C''est logique, car s''il y a bien une chose que Ducobu est capable de réussir, ce sont ses vacances ! Il en profite d''ailleurs pour développer de nouvelles compétences de triche afin de conserver de manière plus que méritée son titre d'' « empereur des tricheurs » !');
INSERT INTO public.bd VALUES (4252, 'Scrameustache (Le)', '24', 'Le cristal des Atlantes', 'Gos', '2800120010', '10/1993', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_10100.jpg', NULL);
INSERT INTO public.bd VALUES (4049, 'Élève Ducobu (L'')', '23', 'Profession : tricheur !', 'Zidrou', '9782803670505', '09/2017 (Parution le 08/09/2017)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_310393.jpg', 'En bon cancre, Ducobu n''en aime pas moins la langue française et ses figures de style quand elles lui permettent de parvenir à ses fins. Pour rendre chèvre l''instit Latouche, il n''hésite pas à faire montre d''un sens de la dialectique propre à en décourager plus d''un. Et quand il est question de changer la sacrosainte dictée de « La cueillette aux champignons » pour la remplacer par une pièce inédite rédigée par Léonie Gratin, il se montre le plus fervent défenseur des allitérations. Ducobu, un tricheur ? Ne serait-ce pas un pléonasme ?');
INSERT INTO public.bd VALUES (4050, 'Élève Ducobu (L'')', '24', 'Attention, école !', 'Zidrou', '9782803672493', '08/2019 (Parution le 23/08/2019)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_372460.jpg', 'Lire ou conduire, il faut choisir ! Quand Monsieur Latouche se pique de donner des cours de sécurité routière, il vaut mieux s''accrocher. Même si Ducobu se fera un malin plaisir à accumuler les sorties de route... Qui a dit qu''on ne pouvait pas faire du tennis en classe ? Ou y proposer un débit de boissons ? Le combat sera rude entre Léonie et Ducobu pour être le premier sur la ligne d''arrivée.');
INSERT INTO public.bd VALUES (4051, 'Élève Ducobu (L'')', '25', 'L''Idole des écoles !', 'Zidrou', '9782803677146', '02/2020 (Parution le 07/02/2020)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_384829.jpg', 'Puisque la musique adoucit les moeurs, Ducobu pourrait bien en user pour amadouer sa célèbre voisine de classe… Encore un nouveau moyen imparable de tricher ! Même si cela ne plaira certainement pas à Mademoiselle Rateau qui prodigue ses cours de musique avec entrain…');
INSERT INTO public.bd VALUES (4052, 'Élève Ducobu (L'')', '26', 'Votez Ducobu !', 'Zidrou', '9782803680276', '07/2022 (Parution le 01/07/2022)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_449476.jpg', NULL);
INSERT INTO public.bd VALUES (4053, 'Élève Ducobu (L'')', '27', 'Fini de rire !', 'Zidrou', '9782808210980', '02/2023 (Parution le 24/02/2023)', 52, 'https://www.bedetheque.com/media/Couvertures/Couv_466915.jpg', 'C''est la rentrée des classes ! Tragédie s''il en est pour l''infortuné Ducobu mais qui dit rentrée dit nouveaux élèves ! Ainsi, la classe de Monsieur Latouche accueille « Jojo la perlouze », un cambrioleur qui s''est un peu égaré en creusant le tunnel qui devait le mener à la liberté. Comme quoi, ça sert d''étudier les points cardinaux… car Latouche a tout du maton pas commode. Heureusement pour Jojo, le parrain des cancres de cette prison qu''est Saint-Potache va le prendre sous son aile !');
INSERT INTO public.bd VALUES (4054, 'Élève Ducobu (L'')', '28', 'En vert et contre tous !', 'Zidrou', '9782808213080', '03/2024 (Parution le 29/03/2024)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_493626.jpg', 'L''école est plus que jamais au centre de toutes les préoccupations morales et politiques : ça commence avec deux grenouilles de bénitier qui entendent séparer garçons et filles. Ça continue avec un ministre de l''Éducation Nationale qui impose le retour aux matinées entières de dictées sept jours sur sept... Ducobu va devoir déployer des trésors d''ingéniosité pour continuer de paresser joyeusement aux côtés de sa première de classe favorite !');
INSERT INTO public.bd VALUES (4055, 'Élève Ducobu (L'')', '29', 'Dernier de cordée !', 'Zidrou', '9782808214940', '04/2025 (Parution le 04/04/2025)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_518811.jpg', NULL);
INSERT INTO public.bd VALUES (4056, 'Élève Ducobu (L'')', 'BOBD', 'Le best of de la BD - 8', 'Zidrou', '2740151241', '08/2005', 94, 'https://www.bedetheque.com/media/Couvertures/eleveducobubestofdelabd_48873.jpg', NULL);
INSERT INTO public.bd VALUES (4057, 'Élève Ducobu (L'')', 'Compil', 'La compil'' de Noël', 'Zidrou', '9782803673018', '11/2018 (Parution le 30/11/2018)', 62, 'https://www.bedetheque.com/media/Couvertures/Couv_355456.jpg', NULL);
INSERT INTO public.bd VALUES (4058, 'Élève Ducobu (L'')', 'HS1', 'Attention! Cancre', 'Zidrou', '2803621223', '08/2005', 25, 'https://www.bedetheque.com/media/Couvertures/Couv_50285.jpg', NULL);
INSERT INTO public.bd VALUES (4059, 'Élève Ducobu (L'')', 'HS2', 'Le meilleur des pires plans-triche', 'Zidrou', '9782803623624', '11/2007', 60, 'https://www.bedetheque.com/media/Couvertures/EleveDucobuL010_02122007_160345.jpg', NULL);
INSERT INTO public.bd VALUES (4060, 'Élève Ducobu (L'')', 'HS3', 'Le guide Ducobu de l''école', 'Zidrou', '9782215047124', '08/2008', 224, 'https://www.bedetheque.com/media/Couvertures/Couv_201243.jpg', 'Avec Ducobu, toute la vie de l''école ! Plus de 100 mots pour découvrir sous un autre jour la vie d''écolier. Tout l''univers de l''école de A à Z pour y réussir et y être à l''aise. En plus du dico un carnet de poche de 24 pages reprenant les savoirs indispensable');
INSERT INTO public.bd VALUES (4061, 'Élève Ducobu (L'')', 'HS4', 'L''instit'' Latouche - Le best of', 'Zidrou', '9782803629640', '10/2011 (Parution le 04/11/2011)', 56, 'https://www.bedetheque.com/media/Couvertures/Couv_146000.jpg', 'LE PLUS BEAU METIER DU MONDE...... sauf quand on a Ducobu dans sa classe ! Et pourtant, Gustave Latouche ne démérite pas ! De ses mémorables dictées champignonnesques à ses plus retentissants « Au coin ! », cette compilation reprend ses meilleurs coups d''éclat et nous en apprend encore plus sur cette personnalité complexe.');
INSERT INTO public.bd VALUES (4062, 'Élève Ducobu (L'')', 'HS5', 'Liberté, solidarité, récré !', 'Zidrou', '9782803635320', '11/2014', 118, 'https://www.bedetheque.com/media/Couvertures/Couv_314220.jpg', NULL);
INSERT INTO public.bd VALUES (4063, 'Élève Ducobu (L'')', 'PUB1', 'Zéro/10', 'Zidrou', '2809653607', '01/1999', 16, 'https://www.bedetheque.com/media/Couvertures/Couv_205118.jpg', 'BD et jeux');
