INSERT INTO public.bd VALUES (4068, 'Élève Ducobu (L'')', 'Quick1', 'Leçon de triche', 'Zidrou', '2803620359', '06/2004', 50, 'https://www.bedetheque.com/media/Couvertures/EleveDucobuLeconDeTricheQuick.jpg', NULL);
INSERT INTO public.bd VALUES (4069, 'Élève Ducobu (L'')', 'Quick2', 'Premier en triche !', 'Zidrou', '9782803628872', '10/2010', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_125855.jpg', NULL);
INSERT INTO public.bd VALUES (4070, 'Élève Ducobu (L'')', 'Récré1', 'Le Récréalbum de Ducobu 1', 'Zidrou', '9782205219425', '06/2011', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_205750.jpg', NULL);
INSERT INTO public.bd VALUES (4071, 'Élève Ducobu (L'')', 'Récré2', 'Le Récréalbum de Ducobu 2', 'Zidrou', '9782723381222', '06/2011', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_236530.jpg', NULL);
INSERT INTO public.bd VALUES (4072, 'Élève Ducobu (L'')', 'RécréT', 'Le Récréalbum de Ducobu (Tremplin vacances)', 'Zidrou', '2901584519', '06/1999', 64, 'https://www.bedetheque.com/media/Couvertures/Couv_454124.jpg', NULL);
INSERT INTO public.bd VALUES (4073, 'Yakari', '1', 'Yakari', 'Job (1)', '2943534013', '04/1973', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_36260.jpg', NULL);
INSERT INTO public.bd VALUES (4074, 'Yakari', '2', 'Yakari et le bison blanc', 'Job (1)', '2293677214', '11/1976', 44, 'https://www.bedetheque.com/media/Couvertures/Yakari2c_19032005.jpg', NULL);
INSERT INTO public.bd VALUES (4075, 'Yakari', '3', 'Yakari chez les castors', 'Job (1)', '2203303034', '08/1977', 44, 'https://www.bedetheque.com/media/Couvertures/yakari03couv.jpg', NULL);
INSERT INTO public.bd VALUES (4076, 'Yakari', '4', 'Yakari et Nanabozo', 'Job (1)', '2203303042', '09/1978', 46, 'https://www.bedetheque.com/media/Couvertures/yakari04.jpg', 'Comme convenu, Yakari attend son amie Arc-en-Ciel au pied du Rocher de l''Ours. Soudain, d''immenses oreilles s''agitent à l''horizon. Ce sont celles de Nanabozo, le Grand Lapin. Ce facétieux magicien apprend à Yakari qu''il est le totem d''Arc-en-Ciel, à qui il a offert des mocassins magiques pour qu''elle puisse se rendre au pays où les ours sont blancs comme la neige. La fillette, impatiente, est déjà partie. Il faut la rejoindre !');
INSERT INTO public.bd VALUES (4077, 'Yakari', '5', 'Yakari et le grizzly', 'Job (1)', '2203303050', '10/1979', 46, 'https://www.bedetheque.com/media/Couvertures/yakari05.jpg', NULL);
INSERT INTO public.bd VALUES (4078, 'Yakari', '6', 'Le secret de Petit Tonnerre', 'Job (1)', '2203303069', '04/1981', 46, 'https://www.bedetheque.com/media/Couvertures/yakari06.jpg', NULL);
INSERT INTO public.bd VALUES (4079, 'Yakari', '7', 'Yakari et l''étranger', 'Job (1)', '2203303077', '05/1982', 46, 'https://www.bedetheque.com/media/Couvertures/Yakari7_28062005.jpg', NULL);
INSERT INTO public.bd VALUES (4080, 'Yakari', '8', 'Au pays des loups', 'Job (1)', '2203303085', '04/1983', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_19586.jpg', 'Loup Tourmenté, un guerrier de la tribu de Yakari, est en proie à une idée fixe : se venger du loup qui l’a attaqué et blessé trois hivers auparavant. Ce loup boite. Yakari a croisé Trois-Pattes. Il a peur, mais un rêve et l’intervention de Grand Aigle, son totem, l’encouragent à partir chez les loups. Il gagnera la confiance du chef de la meute. Les loups ont tendu un piège au guerrier vengeur. Ce dernier n’en réchappera que s’il fait acte de soumission face à la meute. Yakari parviendra à convaincre Loup Tourmenté d’accomplir ce geste humiliant,...');
INSERT INTO public.bd VALUES (4081, 'Yakari', '9', 'Les prisonniers de l''île', 'Job (1)', '2203303093', '09/1983', 46, 'https://www.bedetheque.com/media/Couvertures/yakari09.jpg', 'Surpris par un orage, Yakari, Arc-en-Ciel et Petit Tonnerre doivent se réfugier dans une caverne. Quand ils peuvent enfin quitter leur abri, la colline où ils se trouvent est entourée par les eaux en crue. Ils resteront sur cette îles. Alors qu’ils cherchent du bois de feu, Yakari découvre Pousse-de-Bouleau, un jeune élan blessé et menacé par un horrible prédateur : le glouton. Soudain apparaissent au loin, dans un canoë, les pères à la recherche de leurs enfants. Yakari est partagé : faut-il les rejoindre ou sauver le petit orignal ? Grand Aigle,...');
INSERT INTO public.bd VALUES (4082, 'Yakari', '10', 'Le grand terrier', 'Job (1)', '2203303107', '09/1984', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_20461.jpg', NULL);
INSERT INTO public.bd VALUES (4083, 'Yakari', '11', 'Yakari et la toison blanche', 'Job (1)', '2203303115', '09/1985', 46, 'https://www.bedetheque.com/media/Couvertures/yakari11.jpg', 'Décidé à capturer un superbe mustang noir, Corbeau Hardi viole le territoire de chasse d''un aigle qui l''attaque. Le chasseur téméraire se fait enlever son talisman par le rapace et se trouve plongé dans une mystérieuse léthargie. Si Yakari comprend l''erreur du chasseur, il trouve le châtiment trop dur et entre en scène. Il va braver mille périls, tout en rencontrant d''étonnants animaux : le wapiti, les marmottes, les mouflons et, surtout, les chèvres des montagnes, de fameuses varappeuses qui l''adopteront et le conduiront à l''aire de l''aigle ravisseur...');
INSERT INTO public.bd VALUES (4084, 'Yakari', '12', 'Yakari et le coyote', 'Job (1)', '2203303123', '09/1986', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_19590.jpg', 'L’été commence bien pour Yakari : les petits castors lui ont offert un vieux canoë qui s’est échoué contre leur barrage. Il le rafistole, aidé par Arc-en-Ciel et Graine de Bison. Les trois Papooses testent avec succès leur embarcation en descendant un rapide. «L’eau, ça creuse !» Graine-de-Bison va donc chasser tandis qu’Arc-en-Ciel et Yakari font la connaissance d’une sympathique famille de coyotes et d’un corbeau farceur...');
INSERT INTO public.bd VALUES (4085, 'Yakari', '13', 'Les seigneurs des plaines', 'Job (1)', '2203303131', '09/1987', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_226285.jpg', NULL);
INSERT INTO public.bd VALUES (4086, 'Yakari', '14', 'Le vol des corbeaux', 'Job (1)', '220330314X', '09/1988', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_20463.jpg', 'Élan Lent, le plus inoffensif des guerriers sioux, s’aventure dans le territoire des Grands Corbeaux. Il tombe sous la coupe de Mic-Mac. Ce volatile est complètement cinglé. Il a une obsession : faire voler Élan Lent, qui deviendra ainsi le premier homme de l’espace ! Imitant Mic-Mac, quelques jeunes corbeaux malmènent Yakari et Arc-en-Ciel, partis au secours du pauvre ensorcelé. Heureusement, Grand Aigle intervient et Élan Lent s’arrêtera à temps au bord du redoutable précipice. Et le noir Mic-Mac ? N’ayant pas réussi à se blanchir, il devra subir...');
INSERT INTO public.bd VALUES (4087, 'Yakari', '15', 'La rivière de l''oubli', 'Job (1)', '2203303158', '09/1989', 46, 'https://www.bedetheque.com/media/Couvertures/Yakari15_25092002.jpg', 'N’écoutant que son cœur, Yakari tente de secourir un ourson en mauvaise posture sur une branche. Ils tombent tous deux dans les flots d’une rivière torrentueuse. Yakari se réveille, amnésique, dans les bras d’une ourse, la mère de l’ourson. Affreusement coupable de ne pas avoir été assez vigilante, la grande ourse prend le pauvre Yakari pour son fils Rayon-de-Miel. Elle impute ce changement d’apparence à l’esprit des ours, le Gros Noir des Forêts...');
INSERT INTO public.bd VALUES (4088, 'Yakari', '16', 'Le premier galop', 'Job (1)', '2203303166', '09/1990', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_20464.jpg', NULL);
INSERT INTO public.bd VALUES (4089, 'Yakari', '17', 'Le monstre du lac', 'Job (1)', '2203303174', '09/1991', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_19588.jpg', NULL);
INSERT INTO public.bd VALUES (4090, 'Yakari', '18', 'L''oiseau de neige', 'Job (1)', '2203303182', '08/1992', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_37346.jpg', 'Une pluie d’orage s’abat enfin sur la Prairie torride. Bien à l’abri dans leur tipi, Yakari et son amie Arc-en-Ciel s’amusent avec leurs jouets. Soudain, la terre tremble, le tipi décolle, prend de l’altitude et met le cap sur la toundra. A l’initiative de Nanabozo, le Grand Lapin magicien, les deux Papooses s’aventurent dans les terres boréales où le soleil ne se couche jamais l’été. Ils découvrent une faune inconnue : les caribous, les lemmings, les bœufs musqués...');
INSERT INTO public.bd VALUES (4091, 'Yakari', '19', 'la barrière de feu', 'Job (1)', '2203303190', '08/1993', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_19587.jpg', 'Par une nuit sans lune, tous les chevaux de la tribu de Yakari ont été volés. Tous, à l''exception de l''indomptable Petit Tonnerre. Grâce à son poney, le courageux petit Sioux trouvera le camp des voleurs. Mais comment affronter des ennemis en si grand nombre ? Yakari usera de ruses, recourra aux services du polatouche(un charmant écureuil volant), avant de découvrir les vertus du fameux «baumes des Sénécas», qui guérit les plaies des animaux et soulage des humains...');
INSERT INTO public.bd VALUES (4092, 'Yakari', '20', 'Le diable des bois', 'Job (1)', '2203303204', '08/1994', 46, 'https://www.bedetheque.com/media/Couvertures/yakari20.jpg', NULL);
INSERT INTO public.bd VALUES (4134, 'Légendaires (Les)', '4', 'Le réveil du Kréa-Kaos', 'Sobral, Patrick', '2847899219', '10/2005 (Parution le 26/09/2005)', 46, 'https://www.bedetheque.com/media/Couvertures/legendaires04.jpg', 'En buvant le philtre des Zari-kos, Elysio est redevenu Dark-hell, le sorcier noir. Mais mû par une force intérieure sans égale, il réussit à expulser le ?côté obscur de la Force?. Elysio est sauvé, mais le sorcier toujours en liberté. Fort heureusement, certains de ses pouvoirs sont encore en la possession du jeune garçon. Cela suffira-t-il à anéantir Darkhell ?');
INSERT INTO public.bd VALUES (4093, 'Yakari', '21', 'Le souffleur de nuages', 'Job (1)', '2203303212', '08/1995', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_32891.jpg', 'La décrue s’amorce enfin, après de terribles inondations. Yakari est inquiet pour ses amis les animaux. Avec Petit Tonnerre, il va voir comment ils ont supporté la montée des eaux. Une nuit, le petit Sioux est réveillé par un cri : « Pilipi ! » L’appel d’un oiseau ? Mystère... Au matin, de petits nuages apparaissent au-dessus de l’eau. Yakari veut en avoir le cœur net. Il plonge... et le voilà qui chevauche un béluga ! Cet espiègle souffleur de nuages vient du lointain océan glacial. Comment pourrait-il y retourner sans l’idée des ingénieux castors?');
INSERT INTO public.bd VALUES (4094, 'Yakari', '22', 'La fureur du ciel', 'Job (1)', '2203303220', '08/1996', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_19529.jpg', NULL);
INSERT INTO public.bd VALUES (4095, 'Yakari', '23', 'Yakari et les cornes fourchues', 'Job (1)', '2203303239', '08/1997', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_15144.jpg', 'Pour la première fois, Yakari rencontre l''animal le plus rapide des Grandes Plaines : l''antilope à cornes fourchues, appelée aussi pronhorn. Un sinistre matin, le feu ravage la Prairie, semant la panique parmi les antilopes. Un faon a disparu et c''est l''affolement. Il sera sauvé par un porc-épic…');
INSERT INTO public.bd VALUES (4096, 'Yakari', '24', 'Yakari et l''ours fantôme', 'Job (1)', '2203303247', '08/1998', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_46203.jpg', 'Alors qu''il vient de débarquer de son canoë, Yakari aperçoit une forme blafarde qui s''évanouit dans la forêt. Elle a l''apparence d''un ours… Le petit Sioux est terrorisé : si c''était un fantôme ? Mais c''est bel et bien un ours qui rôde, et on ne peut plus blanc ! Il ne s''agit toutefois pas d''un ours polaire… Quelle espèce d''ours, alors ? Et d''où vient-il ?');
INSERT INTO public.bd VALUES (4097, 'Yakari', '25', 'Le mystère de la falaise', 'Job (1)', '2803614472', '11/1999', 46, 'https://www.bedetheque.com/media/Couvertures/yakari25.jpg', 'La tribu de Yakari campe sur une des voies de migration des oies sauvages et celles-ci ont choisi une falaise toute proche comme aire de repos. Pour le jeune Indien et son poney Petit Tonnerre, c''est l''occasion de bavarder avec ces messagères du printemps. L''une d''elles se tient inexplicablement à l''écart de la conversation. A quelle étrange besogne se livre-t-elle parmi les rochers? L''ayant rejointe, Yakari n''en croit pas ses yeux: à coups de bec, elle a dégagé le squelette fossilisé d''un oiseau gigantesque! Pour leur expliquer l''origine de ce...');
INSERT INTO public.bd VALUES (4098, 'Yakari', '26', 'La vengeance du carcajou', 'Job (1)', '2803615088', '09/2000', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_20469.jpg', 'Aussi dénommé glouton, le carcajou est un animal qui jouit d''une discutable réputation de férocité. Ayant vu voltiger des polatouches (écureuils volants), celui dont ce 26e épisode des aventures de Yakari raconte l''histoire, n''a qu''une obsession : planer ! Hélas, ce goinfre insatiable accuse un poids beaucoup trop lourd pour se livrer à ce périlleux exercice. Sur les conseils de Feu-Follet, un espiègle polatouche, il se soumet alors à une sévère cure d''amaigrissement. En vain ! Toutes ses tentatives se terminent par de pitoyables vols planés. De...');
INSERT INTO public.bd VALUES (4099, 'Yakari', '27', 'Yakari et Longues-oreilles', 'Job (1)', '2803616572', '09/2001', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_20470.jpg', 'Au cours de ses galopades, Yakari a déjà conversé familièrement avec une bonne quarantaine d''espèces à poils et à plumes. Et voici son nouvel interlocuteur: Longues-Oreilles, un âne dont les ancêtres abordèrent jadis au Nouveau-Monde après avoir navigué dans les cales des caravelles espagnoles. Cet âne garde les chèvres d''un vieux berger qui a trouvé refuge dans les entrailles de la Terre-Mère, plus précisément au cœur le plus sauvage d''un canyon du Colorado. Ses hi-hans tonitruants, accompagnés au besoin de franches ruades, éloignent les prédateurs,...');
INSERT INTO public.bd VALUES (4100, 'Yakari', '28', 'Le chêne qui parlait', 'Job (1)', '2803617641', '09/2002', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_20471.jpg', 'Qu’arrive-t-il donc à Yakari ? Comme tous les animaux qu’il rencontre, ne voilà-t-il pas que les arbres se mettent également à parler au plus fameux des petits Sioux... L’univers de la grande prairie à travers lequel galope Yakari, est décidément plein de surprises et d’enchantements. En chevauchant Petit Tonnerre, son fidèle mustang, et en dialoguant familièrement avec ses z’amis z’animaux (une bonne quarantaine d’espèces à poils et à plumes), l’illustre petit Indien nous a déjà fait partager bien des émerveillements, mais voici qu’il découvre...');
INSERT INTO public.bd VALUES (4101, 'Yakari', '29', 'Le réveil du géant', 'Job (1)', '2803618915', '09/2003', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_30162.jpg', 'Le long de la Yellowstone, la rivière qui donnera son nom au premier parc national créé dans le monde, Yakari et son amie Arc-en-Ciel accompagnent des chasseurs partis à la recherche de l’obsidienne, une roche vitreuse servant à fabriquer des pointes de flèches et de lances. S’étant écartés du groupe, les deux papooses rencontrent un wapiti. Ce cerf coiffé de bois impressionnants sera leur guide tout au long d’une randonnée inoubliable au coeur de cette région volcanique. Ils apprendront que des roches en fusion bouillonnent sous leurs mocassins,...');
INSERT INTO public.bd VALUES (4102, 'Yakari', '30', 'Le marcheur de nuit', 'Job (1)', '2803619970', '09/2004', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_39435.jpg', 'Dans la tribu de Yakari, chacun sait qu''Oil-de Bouillon passe ses nuits - et ses journées - à dormir. S''il lui arrive d''esquisser quelques pas, c''est pour aussitôt s''affaler, à bout de forces, contre son tipi. Comme le constatent Yakari et son amie Arc-en-Ciel, «moins il se dépense, plus il a besoin de repos» ! Voici pourtant qu''une nuit de pleine lune, notre inoffensif chasseur se met carrément à marcher. Tout en dormant, il quitte le campement et s''aventure au loin. Seule une chouette est témoin de cette périlleuse escapade nocturne. Oil-de Bouillon...');
INSERT INTO public.bd VALUES (4103, 'Yakari', '31', 'Yakari et les Appaloosas', 'Job (1)', '2803620804', '09/2005', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_50474.jpg', 'Fini le temps où Arc-Tendu, le chasseur enragé, collectionnait les fourrures couleur de neige pour en décorer son tipi ! Sa nouvelle obsession: La robe sombre comme la nuit et parsemée d''étoiles d''un étalon sauvage...');
INSERT INTO public.bd VALUES (4104, 'Yakari', '32', 'Les griffes de l''ours', 'Job (1)', '2803621924', '09/2006', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_58277.jpg', '"Qui sait jouer avec le vent est dispensé de ramer" sur ce conseil du vénérable Roc Tranquille, Yakari s''initie à la navigation à voile. A bord de son canoë, il part au fil de l''eau, accompagné d''Oreille Tombante, un chien plutôt culotté. Le vent pousse nos marins d''eau douce jusqu''aux abords d''un mystérieux rocher, farouchement gardé par un ours noir. Le petit bout de Sioux n''échappera à ce féroce cerbère qu''en escaladant ce qu''on appellera plus tard la Tour du Diable. Et grâce à Grand Aigle, son totem, Yakari connaitra la légende des Sept Sœurs.');
INSERT INTO public.bd VALUES (4135, 'Légendaires (Les)', '5', 'Cœur du passé', 'Sobral, Patrick', '2756000906', '03/2006', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_54300.jpg', 'Le prince Halan, ex-fiancé de Jadina, demande aux cinq justiciers de l’accompagner jusqu’à l’ancienne demeure du sorcier Darkhell. On y a, en effet, remarqué une inquiétante concentration de magie ? Amical en apparence, le prince cache ses intentions malveillantes : il a besoin du bâton-aigle de Jadina pour remonter dans le temps et la convaincre de l’épouser.');
INSERT INTO public.bd VALUES (4105, 'Yakari', '33', 'Le marais de la peur', 'Job (1)', '9782803623082', '09/2007', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_66462.jpg', 'Un petit bison qui charge sa bisonne de mère avant de la terrasser. Un heyoka (un «contraire») qui monte face à la croupe de son cheval et dit «Au revoir !» pour «Bonjour !». Un renard qui grimpe aux arbres et saute de branche en branche. Des nuées de pigeons migrateurs éclipsant le soleil. Un coucou coureur de route courant au secours de malheureux ratons laveurs menacés par un lézard géant armé de terribles dents. Yakari, le bout d''Sioux, se souviendra longtemps encore de ce qu''il a vécu, en compagnie de sa fidèle amie Arc-en-Ciel, tout au long...');
INSERT INTO public.bd VALUES (4106, 'Yakari', '34', 'Le retour du lapin magicien', 'Job (1)', '9782803624294', '09/2008', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_77999.jpg', 'Nanabozo, le lapin magique totem d''Arc-en-Ciel, est de retour dans la grande plaine ! Comme à l''accoutumée, son arrivée fait rimer sagesse avec liesse. Car si le lapin géant prodigue de bons conseils, il aime aussi captiver son public avec ses tours extraordinaires. Sa plus grande surprise reste à découvrir: une authentique fresque rupestre témoignant de l''époque où existaient des castors géants !');
INSERT INTO public.bd VALUES (4107, 'Yakari', '35', 'L''escapade de l''ourson', 'Job (1)', '9782803625765', '10/2009', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_95369.jpg', 'Rayon-de-Miel, l’ourson que Yakari avait sauvé des eaux tumultueuses de la Rivière de l’oubli (tome 15), retrouve son ami le papoose. Il vient de quitter sa mère. Pourquoi ? Il n’en pouvait plus d’être chouchouté, dorloté, cajolé. Bref, il étouffait et aspirait à prendre un peu d’air. Et voilà – ô surprise ! – que cette mère abusive accepte que son rejeton adoré s’en aille, à condition toutefois de ne pas s’absenter trop longtemps. Sans quoi, elle dépérirait de chagrin… Mais, Rayon-de-Miel tarde à revenir auprès de sa génitrice, car Arc-Tendu,...');
INSERT INTO public.bd VALUES (4108, 'Yakari', '36', 'Le lézard de l''ombre', 'Job (1)', '9782803628094', '04/2011 (Parution le 22/04/2011)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_125244.jpg', 'Pourquoi Roc Tranquille a-t-il quitté en catimini la tribu de Yakari ? Parvenu à un très grand âge, estimait-il qu''il devenait une charge pour les siens ? Yakari refuse d''admettre que son vénérable ami soit parti pour aller mourir, tout seul, quelque part dans la vaste Prairie. Il y a peu, ne l''a-t-il pas vu grimper dans un arbre afin de mettre sa vieille carcasse à l''épreuve ? Le bout d''Sioux part donc à la recherche de Roc Tranquille qu''il trouvera couché dans l''herbe, à bout de forces. Il apprend la raison pour laquelle le vieillard s''en est...');
INSERT INTO public.bd VALUES (4109, 'Yakari', '37', 'Le mangeur d''étoiles', 'Job (1)', '9782803631063', '10/2012 (Parution le 26/10/2012)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_174716.jpg', NULL);
INSERT INTO public.bd VALUES (4110, 'Yakari', '38', 'Yakari et la Tueuse des mers', 'Job (1)', '9782803632886', '03/2014 (Parution le 14/03/2014)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_212134.jpg', NULL);
INSERT INTO public.bd VALUES (4111, 'Yakari', '39', 'Le jour du silence', 'Chamblain, Joris', '9782803636747', '10/2016 (Parution le 14/10/2016)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_289385.jpg', 'Quand Yakari se montre colérique et injuste vis-à-vis de Petit-Tonnerre, il va vite découvrir que ses actes ont des conséquences et que rien n''est jamais acquis dans la vie. Ni les dons précieux, ni l''amitié... Face à un grizzly qui ne semble pas dans son état normal, Yakari devra faire preuve d''encore plus d''ingéniosité que d''habitude pour aider ses amis animaux et pour regagner la confiance de son fidèle compagnon d''aventure... et celle de Grand Aigle !');
INSERT INTO public.bd VALUES (4112, 'Yakari', '40', 'L''Esprit des chevaux', 'Chamblain, Joris', '9782803673735', '10/2019 (Parution le 11/10/2019)', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_375111.jpg', 'C''est l''hiver. Yakari et son village doivent changer de campement et migrer vers le sud.');
INSERT INTO public.bd VALUES (4113, 'Yakari', '41', 'Le fils de l''aigle', 'Giacometti, Xavier', '9782803678921', '10/2020 (Parution le 02/10/2020)', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_402355.jpg', 'Depuis qu''il est un jeune papoose, Yakari a toujours pu compter sur le soutien de Grand-Aigle, son animal-totem. Aujourd''hui c''est Grand-Aigle qui appelle son ami à l''aide. La vie d''un petit aiglon est menacée. Et seul Yakari est en mesure de le sauver !');
INSERT INTO public.bd VALUES (4114, 'Yakari', '42', 'La colère de Thathanka', 'Giacometti, Xavier', '9782803680306', '05/2022 (Parution le 13/05/2022)', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_447549.jpg', 'Un peu trop désireux de prouver sa valeur à ses amis, Graine-de-Bison a pris des risques inconsidérés, et fait une très mauvaise chute. Pour sauver son esprit, Yakari décide de demander de l''aide à l''animal-totem de son ami. Le seul problème, c''est qu''il s''agit de Thathanka, le terrible bison ! Et, tout comme Graine-de-Bison, il est impétueux et têtu. Yakari parviendra-t-il à convaincre le fougueux animal de pardonner ses défauts à ce jeune papoose qui lui ressemble un peu trop…?');
INSERT INTO public.bd VALUES (4115, 'Yakari', 'Cat', 'Les Suisses à la rencontre des Amérindiens', 'Job (1)', '9782940531127', '10/2015 (Parution le 15/10/2015)', 62, 'https://www.bedetheque.com/media/Couvertures/Couv_293804.jpg', NULL);
INSERT INTO public.bd VALUES (4116, 'Yakari', 'FL1', 'Yakari et Grand Aigle / Yakari et le bison blanc', 'Job (1)', '2724217810', '10/1983', 89, 'https://www.bedetheque.com/media/Couvertures/Couv_138490.jpg', NULL);
INSERT INTO public.bd VALUES (4117, 'Yakari', 'HS', 'L''album posters', 'Job (1)', '9782803625833', '10/2009', 24, 'https://www.bedetheque.com/media/Couvertures/yakarihs_96343.jpg', '24 posters.');
INSERT INTO public.bd VALUES (4118, 'Yakari', 'HS', 'L''encyclopédie à la découverte de la faune et des tribus d''Amérique du Nord', 'Maurel, Antoine', '9782374931203', '08/2020', 176, 'https://www.bedetheque.com/media/Couvertures/Couv_404998.jpg', 'Chevaux, ours, bisons, castors mais encore tatou, chien de prairie, aigle... La Prairie est grande quand on est un jeune Sioux comme Yakari, et il y rencontre des des dizaines d''animaux. Découvre avec le jeune indien qui a le don de parler aux créatures toute la faune de la Grande Plaine des Etats Unis, et apprend avec lui à connaître les tribus indiennes et leurs traditions, avant l''établissement des colons venus d''Europe. Une magnifique encyclopédie illustré par les splendides dessins de Derib.');
INSERT INTO public.bd VALUES (4119, 'Yakari', 'pub2', 'Le tomahawk sacré', 'Lambert, Christophe (1)', '9791036312052', '06/2017', 61, 'https://www.bedetheque.com/media/Couvertures/Couv_521518.jpg', NULL);
INSERT INTO public.bd VALUES (4120, 'Nombrils (Les)', '1', 'Pour qui tu te prends ?', 'Dubuc, Maryse', '280013772X', '02/2006', 44, 'https://www.bedetheque.com/media/Couvertures/NombrilsLes01.jpg', 'Jenny et Vicky sont les pires chipies que la Terre ait portées. Elles se prennent pour le nombril du monde et pour peu, elles le seraient vraiment. Avec leurs vêtements sexy, leur maquillage provocateur et leur coiffure toujours impeccable, partout où elles vont, les regards sont hypnotisés, la musique s''arrête. On ne voit et on n''entend plus qu''elles. Et heureusement ! Parce que Jenny et Vicky sont prêtes à tout pour être le centre d''attraction. Leur amie, la trop grande Karine, l''apprend à ses dépens lorsqu''un certain Dan s''intéresse à elle....');
INSERT INTO public.bd VALUES (4136, 'Légendaires (Les)', '6', 'Main du futur', 'Sobral, Patrick', '2756002925', '10/2006', 46, 'https://www.bedetheque.com/media/Couvertures/LegendairesLes6_05102006.jpg', NULL);
INSERT INTO public.bd VALUES (4253, 'Scrameustache (Le)', '25', 'Le bêtisier galaxien', 'Gos', '2800121092', '04/1994', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_10101.jpg', NULL);
INSERT INTO public.bd VALUES (4121, 'Nombrils (Les)', '2', 'Sale temps pour les moches', 'Dubuc, Maryse', '9782800138749', '01/2007', 46, 'https://www.bedetheque.com/media/Couvertures/nombrils2_60475.jpg', 'Elles sont jeunes, belles... et vaches ! Jenny et Vicky sont les pires chipies que la Terre ait portées. Avec leurs vêtements sexy et leur maquillage provocateur, elles se prennent pour le nombril du monde et sont prêtes à tout pour être le centre d''attraction. Quand elles apprennent que leur amie Karine, gentille mais peu gâtée par la nature, s''apprête à sortir avec le beau Dan, elles décident de réagir et vont faire preuve d''une imagination débordante pour saboter l''idylle naissante. Non pas parce qu''elles ne supportent pas la concurrence (Karine...');
INSERT INTO public.bd VALUES (4122, 'Nombrils (Les)', '3', 'Les liens de l''amitié', 'Dubuc, Maryse', '9782800140315', '03/2008', 44, 'https://www.bedetheque.com/media/Couvertures/nombrils03_72352.jpg', 'Jenny, Vicky (les deux pestes top canons) et Karine (la gentille grande bringue) sont de retour ! Au menu de ce troisième album : des coups bas, quelques beaux gars, de la trahison en veux-tu en voilà, bref de l''amour haine et tout le tralala, des oh et des ah et puis aussi un scoop final à en rester baba ! Pas de doute, avec les Nombrils, on ne s''ennuie pas !');
INSERT INTO public.bd VALUES (4123, 'Nombrils (Les)', '4', 'Duel de belles', 'Dubuc, Maryse', '9782800144122', '09/2009 (Parution le 18/09/2009)', 44, 'https://www.bedetheque.com/media/Couvertures/nombrils04_94376.jpg', 'Karine est désespérée : Dan l''a quittée pour suivre Mélanie en Afrique. Et Jenny et Vicky sont inconsolables depuis la disparition de John John (et surtout de sa merveilleuse moto). Mais leurs épreuves ne sont pas terminées car Mélanie est de retour et n''a pas fini de les faire souffrir. Après avoir volé le mec de Karine, elle s''attaque à ce que Jenny et Vicky ont de plus précieux : leur sacro-sainte popularité auprès de la gent masculine ! Bref, cette fille trop parfaite aux manigances vicieuses va se faire trois ennemies acharnées... et que la...');
INSERT INTO public.bd VALUES (4124, 'Nombrils (Les)', '5', 'Un couple d''enfer', 'Dubuc, Maryse', '9782800150222', '11/2011 (Parution le 04/11/2011)', 48, 'https://www.bedetheque.com/media/Couvertures/141745_c.jpg', 'Karine a pris une grande décision : elle allait CHANGER. Et d''abord de look : le pantalon rose et les barrettes dans les cheveux font place au look gothique et au noir hyper classe. Ensuite de caractère : Karine décide d''apprendre à dire non. Il y aura évidemment des rechutes mais elle peut compter sur Albin, son nouveau petit ami, pour l''aider à tenir ses bonnes résolutions et à prendre confiance en elle. À l''école, tout le monde trouve la nouvelle Karine, sexy et sûre d''elle, beaucoup mieux que l''ancienne. Tout le monde sauf trois personnes :...');
INSERT INTO public.bd VALUES (4125, 'Nombrils (Les)', '6', 'Un été trop mortel', 'Dubuc, Maryse', '9782800157160', '10/2013 (Parution le 04/10/2013)', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_198028.jpg', 'Pour Vicky, l''été s''annonce plutôt bien : vacances, soleil et plage. Mais surtout, surtout, elle a un nouveau voisin hyper-canon. Et pour une fois, elle sent qu''elle a sa chance. Elle en oublierait presque que Jenny lui fait toujours autant d''ombre quand il s''agit de draguer des surfeurs musclés ou que Karine est bien trop occupée à répéter avec le groupe de musique d''Albin pour passer du temps avec elle... Et puis, catastrophe : dénoncée pour tricherie par un camarade de classe, Vicky se voit obligée par son père d''intégrer un camp d''anglais....');
INSERT INTO public.bd VALUES (4126, 'Nombrils (Les)', '7', 'Un bonheur presque parfait', 'Dubuc, Maryse', '9782800163536', '09/2015 (Parution le 04/09/2015)', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_254471.jpg', 'Pour Vicky, le bonheur est total : ses parents la préfèrent enfin ! à son insupportable grande soeur Rebecca, elle sort avec James, beau jeune homme promis au plus bel avenir, et le barbecue familial de fin d''été lui permet d''afficher son insolente réussite à la face de tous les voisins. Quant à Jenny, elle connaît un double bonheur : avec le musculeux Jean-Franky, elle a les tablettes de chocolat ; avec le gentil Hugo, elle a les attentions de chaque instant. Karine, elle, a une nouvelle passion et ce n''est pas un garçon : son groupe de musique...');
INSERT INTO public.bd VALUES (4127, 'Nombrils (Les)', '8', 'Ex, drague et rock''n''roll !', 'Dubuc, Maryse', '9782800171579', '11/2018 (Parution le 09/11/2018)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_350085.jpg', NULL);
INSERT INTO public.bd VALUES (4128, 'Nombrils (Les)', 'HS01', 'Mode d''emploi', 'Dubuc, Maryse', '9782800156910', '11/2012', 32, 'https://www.bedetheque.com/media/Couvertures/Couv_177305.jpg', NULL);
INSERT INTO public.bd VALUES (4129, 'Nombrils (Les)', 'INT1', 'Jeunes, belles et vaches', 'Dubuc, Maryse', '9782800148823', '11/2010 (Parution le 05/11/2010)', 196, 'https://www.bedetheque.com/media/Couvertures/Couv_118638.jpg', 'Elles sont jeunes, belles et vaches... mais elles vous donnent une dernière chance de prendre le train en marche grâce à cette édition intégrale des quatre premiers tomes de la série ! Jenny et Vicky sont les pires chipies que la Terre ait portées. Elles se prennent pour le nombril du monde et pour peu, elles le seraient vraiment. Avec leurs vêtements sexy, leur maquillage provocateur et leur coiffure toujours impeccable, elles attirent tous les regards. Et elles sont prêtes à tout pour être (et rester) le centre d''attraction. Karine, leur amie...');
INSERT INTO public.bd VALUES (4130, 'Nombrils (Les)', 'INT2', 'La revanche des moches', 'Dubuc, Maryse', '9782800168401', '10/2016 (Parution le 07/10/2016)', 160, 'https://www.bedetheque.com/media/Couvertures/Couv_290782.jpg', 'Les 3 pestes les plus populaires de la BD sont de retour avec la première édition en intégrale du cycle 2 comprenant les tomes 5 à 7. Elles sont trois, elles ont quinze ans. Vicky est une peste machiavélique, Jenny une bimbo rousse qui mériterait d''être blonde, Karine une grande bringue pas sûre d''elle. Les Nombrils, c''est l''histoire de leur amitié, à travers leurs aventures sentimentales pleines d''humour et de rebondissements. Mais c''est aussi l''histoire d''une relation qui évolue : suite à une trahison amoureuse et à des accusations injustes,...');
INSERT INTO public.bd VALUES (4131, 'Légendaires (Les)', '1', 'La pierre de Jovénia', 'Sobral, Patrick', '2847894500', '08/2004', 46, 'https://www.bedetheque.com/media/Couvertures/legendaires01couv.jpg', 'Danaël, Gryf, Jadina, Shimy et Razzia, cinq justiciers aux pouvoirs fantastiques, font la fierté du monde d''Alysia. Mais, lors d''un ultime combat les opposant à Darkhell, le Sorcier Noir, une épouvantable malédiction s''abat sur leur monde tous ses habitants - eux compris ! - retrouvent leur apparence d''enfant. Aujourd''hui, rejetés par les leurs, les cinq Légendaires veulent briser le sortilège... L''aventure ne fait que commencer !');
INSERT INTO public.bd VALUES (4132, 'Légendaires (Les)', '2', 'Le Gardien', 'Sobral, Patrick', '2847894772', '11/2004', 46, 'https://www.bedetheque.com/media/Couvertures/LegendairesLes2_20112004.jpg', 'Il semble qu''Elysio, le mystérieux ami des cinq héros retombés en enfance, soit en fait... le grand sorcier Darkhell ! Ce dernier affirme toutefois avoir perdu la mémoire et refuse de s''identifier à ce monstre de cruauté. Les Zar-ikos - des hommes-plantes démoniaques - en ont décidé autrement et entendent bien lui rafraîchir la mémoire. Les Légendaires réussiront-ils à les en empêcher ?');
INSERT INTO public.bd VALUES (4133, 'Légendaires (Les)', '3', 'Frères Ennemis', 'Sobral, Patrick', '2847897615', '05/2005', 46, 'https://www.bedetheque.com/media/Couvertures/LegendairesLes3_10052005.jpg', 'Le peuple des Elfes, victime de la peste maléfique, a besoin d''aide. Pour cette mission, le roi met en concurrence les Légendaires et le Trio des Fabuleux, une nouvelle bande de justiciers. Arrivés sur le terrain, ils sont témoins d''une guerre entre les Elfes et une autre tribu, les Piranhis. Et si Darkhell, le dangereux sorcier noir, était derrière tout ça ?');
INSERT INTO public.bd VALUES (4137, 'Légendaires (Les)', '7', 'Aube et Crépuscule', 'Sobral, Patrick', '9782756005324', '03/2007', 46, 'https://www.bedetheque.com/media/Couvertures/legendaires07c_61356.jpg', 'Les Légendaires ont deux semaines pour inverser les effets de l’accident Jovenia, sous peine de voir leur monde anéanti par les dieux. Seule la Corne de Sygma a le pouvoir escompté, mais celle-ci se trouve dans de lointaines montagnes. Sur le départ, nos héros sont assaillis par une jeune élève qui les supplie de l’emmener avec eux. Alors que tous reprennent la route, Gryf adopte un étrange comportement…');
INSERT INTO public.bd VALUES (4138, 'Légendaires (Les)', '8', 'Griffes et plumes', 'Sobral, Patrick', '9782756005812', '10/2007 (Parution le 24/10/2007)', 46, 'https://www.bedetheque.com/media/Couvertures/LegendairesLes7_24102007_193551.jpg', 'Après l’attaque de Gryf sur les Légendaires, ceux-ci se réveillent prisonniers au cœur de la cité de Jaguarys. Gryf, lui, se retrouve affublé d’un étrange collier et d’un nouveau nom : Prince Anoth. Le souverain des Jaguarians lui révèle alors être son frère et lui raconte l’histoire de son peuple. Bien que l’heure soit aux retrouvailles, Shimmy oscille entre la vie et la mort, et Alysia est toujours menacée de destruction…');
INSERT INTO public.bd VALUES (4139, 'Légendaires (Les)', '9', 'Le Cycle d''Anathos : l''alystory', 'Sobral, Patrick', '9782756011790', '09/2008 (Parution le 10/09/2008)', 46, 'https://www.bedetheque.com/media/Couvertures/legendaires09_78400.jpg', 'Anathos, un dieu maléfique compte se réincarner et celui qu''il a choisi comme enveloppe charnelle est un Légendaire ! L''un d''entre eux est destiné à devenir Anathos... Pour contrecarrer les plans de ce dernier, nos héros doivent s''emparer de L''Alystory, un livre sacré. Mais, en le dérobant, les Légendaires deviendraient les criminels les plus recherchés au monde...');
INSERT INTO public.bd VALUES (4140, 'Légendaires (Les)', '10', 'Le Cycle d''Anathos : La marque du destin', 'Sobral, Patrick', '9782756015880', '03/2009 (Parution le 04/03/2009)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_84470.jpg', 'Shimy a reçu la marque du destin et ses jours sont désormais en danger. Elle peut toujours compter sur l''aide de ses amis, mais tous ignorent quand et comment le maléfique Anathos prendra possession de son corps. Lorsque celui-ci apparaît, les Légendaires demandent un délai de 24 heures. En échange, ils proposent le plus beau des combats : Anathos contre les plus grands héros d''Alysia !');
INSERT INTO public.bd VALUES (4141, 'Légendaires (Les)', '11', 'Le Cycle d''Anathos : Versus Inferno', 'Sobral, Patrick', '9782756015897', '10/2009', 46, 'https://www.bedetheque.com/media/Couvertures/93342_c.jpg', 'Anathos, le dieu maléfique banni par ses pairs, a refait son apparition sur Alysia, incarné dans le corps de Danaël, leader des Légendaires. Ce monstre a entrepris d''exterminer la race humaine. Les victimes se comptent par centaines de milliers. Sous son commandement agissent quatre généraux. On dit qu''ils ont été créés à partir des corps sans vie des Légendaires. On les nomme... LES INFERNAUX !!');
INSERT INTO public.bd VALUES (4142, 'Légendaires (Les)', '12', 'Le Cycle d''Anathos : Renaissance', 'Sobral, Patrick', '9782756019949', '03/2010 (Parution le 24/03/2010)', 46, 'https://www.bedetheque.com/media/Couvertures/105605_c.jpg', 'C''est tout Alysia qui se dresse contre le maléfique Anathos et ses Infernaux. Tous se sont unis pour lever la plus grande des armées et pour stopper les forces du mal. Forts de cet appel, les Légendaires répondent présents. C''est une guerre totale, sur terre, sur mer, dans les airs, qui se prépare. Mais un sacrifice sera nécessaire pour offrir au monde d''Alysia ce qu''il avait cessé d''espérer... une renaissance !');
INSERT INTO public.bd VALUES (4143, 'Légendaires (Les)', '13', 'Sang Royal', 'Sobral, Patrick', '9782756023410', '11/2010', 46, 'https://www.bedetheque.com/media/Couvertures/115957_c.jpg', 'Tandis que les Légendaires célèbrent leur victoire sur Anathos et les Infernaux, la fête est troublée par l''arrivée brutale de soldats. Ils ont pour ordre d''emmener le groupe au chevet de la mère de Jadina qui est mourante. Jadina se prépare dès lors pour son premier retour officiel dans sa cité : elle n''y est pas retournée depuis que ses parents l''ont bannie pour être devenue une Légendaire !');
INSERT INTO public.bd VALUES (4144, 'Légendaires (Les)', '14', 'L''Héritage du mal', 'Sobral, Patrick', '9782756023427', '10/2011', 46, 'https://www.bedetheque.com/media/Couvertures/139579_c.jpg', 'Accablés par la mort de Jadina, les Légendaires ont une autre nouvelle de taille à surmonter : Ténébris les quitte pour succéder à la reine Adeyrid sur le trône d''Orchidia. Est-ce la fin des Légendaires ? Convaincus que derrière ces événements se cachent quelque mystère, Razzia, Gryf et Shimy mènent l''enquête. Leurs recherches les conduiront vers l''homme responsable de tous leurs malheurs...');
INSERT INTO public.bd VALUES (4145, 'Légendaires (Les)', '15', 'Amour mortel', 'Sobral, Patrick', '9782756023434', '10/2012 (Parution le 24/10/2012)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_174732.jpg', 'Shimy est inquiète. Cela fait plus d''une semaine que Gryf aurait dû rentrer. Et s''il lui était arrivé quelque chose ? La réponse ne se fait pas tarder. Le voici qui revient en trombe. Mais quelle n''est pas la surprise de ses amis lorsqu''il présente... sa fiancée ! Et comme une nouvelle ne vient jamais seule, il les avertit d''une terrible catastrophe : la race humaine risque de disparaître d''Alysia...');
INSERT INTO public.bd VALUES (4146, 'Légendaires (Les)', '16', 'L''éternité ne dure qu''un temps', 'Sobral, Patrick', '9782756032634', '10/2013 (Parution le 16/10/2013)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_199456.jpg', 'Invités forcés des Chiridans, des êtres mystérieux morts depuis des siècles à la recherche perpétuelle de corps à posséder, les Légendaires ne tardent pas à découvrir qu''ils retiennent un prisonnier spécial, un dieu nommé Eternity. De son côté , Gryf sera confronté à plusieurs épreuves d''envergure dont libérer ses amis et choisir une bonne fois pour toutes vers qui son coeur penche : Shimy ou Shun-Day ?');
INSERT INTO public.bd VALUES (4147, 'Légendaires (Les)', '17', 'L''Exode de Kalandre', 'Sobral, Patrick', '9782756053585', '10/2014 (Parution le 22/10/2014)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_227926.jpg', 'Kalandre, la femme mystérieuse qui semble tirer les fils du destin, prétend que le monde d''Alysia vit ses derniers instants, empoisonné par les effets secondaires mortels de l''accident Jovénia. Elle dit souhaiter guider les mortels vers la Terre promise, un monde caché où les élus seront guéris de la malédiction. Malgré la méfiance de certains, Danaël pousse les Légendaires à accepter cet exode.');
INSERT INTO public.bd VALUES (4148, 'Légendaires (Les)', '18', 'La fin de l''histoire ?', 'Sobral, Patrick', '9782756053578', '09/2015 (Parution le 07/10/2015)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_256882.jpg', 'C''est l''énigmatique Kalandre qui, depuis le début de la série, provoque et manipule le destin de nos Légendaires. Ce tome 18 sera un épisode éprouvant, dramatique, qui verra les Légendaires malmenés dans leurs corps et dans leurs coeurs comme jamais ils ne l''ont été. Le final sera apocalyptique et meurtrier mais, tel le phénix, ce sera pour mieux faire renaître la série ensuite.');
INSERT INTO public.bd VALUES (4149, 'Légendaires (Les)', '19', 'World Without : Artémus le Légendaire', 'Sobral, Patrick', '9782756053592', '10/2016 (Parution le 26/10/2016)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_288899.jpg', 'Artémus Del Conquisador serait donc le « véritable » héros d''Alysia. Il aurait accompli les grands faits d''armes vécus par ses personnages dans les romans. Aurait, car vivent de par le monde des personnes ressemblant étrangement aux Légendaires portant les mêmes noms, mais menant des vies différentes. On retrouve Danaël et Shimy mariés, menant une vie de fermiers ou encore Jadina, en pirate de l''air.');
INSERT INTO public.bd VALUES (4150, 'Légendaires (Les)', '20', 'World Without : Le Royaume des Larmes', 'Sobral, Patrick', '9782756064765', '10/2017 (Parution le 06/10/2017)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_312707.jpg', 'C’est un grand jour à Orchidia ! Des quatre coins d’Alysia, les grands de ce monde sont venus assister à l’épreuve du bâtonaigle de Jadilyna qui désignera la princesse Shun-Day comme reine du royaume à la place de sa tante, l’impitoyable Invidia. Mais dans l’ombre de cet événement se trame une sombre machination qui pourrait bien finir en tragédie. Mais qui est visé par cet infâme complot ?');
INSERT INTO public.bd VALUES (4151, 'Légendaires (Les)', '21', 'World Without : la Bataille du néant', 'Sobral, Patrick', '9782756064772', '10/2018 (Parution le 31/10/2018)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_349269.jpg', 'Un mystérieux phénomène, le « Néant », menace le monde elfique. Shimy doit aider les elfes à sauver Astria grâce à ses pouvoirs élémentaires naissants. Mais des survivants Galinas n’apprécient pas ce renfort, tout comme ils ne souhaitent pas la disparition de ce très mystérieux « Néant ». Quel noir secret ce dernier renferme-t-il ? Un nouvel épisode bourré d’adrénaline pour nos amis les Légendaires.');
INSERT INTO public.bd VALUES (4152, 'Légendaires (Les)', '22', 'World without - Les Éveillés', 'Sobral, Patrick', '9782413013099', '10/2019 (Parution le 09/10/2019)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_373552.jpg', 'Artémus et ses compagnons sont conduits dans une cité secrète dirigée par Kalandre et le mage écarlate, Elysio. Cette cité est constituée de personnes venant de tout Alysia qui se font appeler « les Éveillés ». Ceux-ci sont persuadés d''être les victimes d''un sortilège et qu''une autre vie existe. Elysio propose à nos amis d''en faire la preuve en les soumettant à l''épreuve du miroir de la vérité !');
INSERT INTO public.bd VALUES (4153, 'Légendaires (Les)', '23', 'World without - Les Cicatrices du monde', 'Sobral, Patrick', '9782413024507', '10/2020 (Parution le 14/10/2020)', 62, 'https://www.bedetheque.com/media/Couvertures/Couv_402393.jpg', 'Artémus ne peut plus nier les faits : c''est bien lui qui a modifié la réalité grâce à son journal et aux pierres divines. Cependant, il refuse de redonner son véritable visage à Alysia alors que les Néants recommencent à proliférer dans le monde. L''heure est grave et le danger si important que les grands souverains d''Alysia se sont réunis à Oroban pour débattre de la meilleure action à entreprendre.');
INSERT INTO public.bd VALUES (4154, 'Légendaires (Les)', 'FL1', 'La pierre de Jovénia / Le gardien', 'Sobral, Patrick', '9782298007633', '02/2008', 97, 'https://www.bedetheque.com/media/Couvertures/LegendairesLesfranceLoisirs12_05092009_180306.jpg', NULL);
INSERT INTO public.bd VALUES (4155, 'Légendaires (Les)', 'FL2', 'Frères ennemis / Le réveil du Kréa-Kaos', 'Sobral, Patrick', '9782298010312', '05/2008', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_103963.jpg', NULL);
INSERT INTO public.bd VALUES (4156, 'Légendaires (Les)', 'FL3', 'Cœur du passé / Main du futur', 'Sobral, Patrick', '9782298013207', '08/2008', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_159787.jpg', NULL);
INSERT INTO public.bd VALUES (4157, 'Légendaires (Les)', 'FL4', 'Aube et crépuscule / Griffes et plumes', 'Sobral, Patrick', '9782298016147', '11/2008', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_103964.jpg', NULL);
INSERT INTO public.bd VALUES (4158, 'Légendaires (Les)', 'FL5', 'L''Alystory / La Marque du destin', 'Sobral, Patrick', '9782298031362', '05/2010', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_159807.jpg', NULL);
INSERT INTO public.bd VALUES (4159, 'Légendaires (Les)', 'FL6', 'Versus inferno / Renaissance', 'Sobral, Patrick', '9782298040777', '03/2011', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_159811.jpg', NULL);
INSERT INTO public.bd VALUES (4160, 'Légendaires (Les)', 'FL7', 'Sang Royal / L''héritage du mal', 'Sobral, Patrick', '9782298058598', '08/2012', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_175883.jpg', NULL);
INSERT INTO public.bd VALUES (4161, 'Légendaires (Les)', 'HS', 'The art of Les Légendaires', 'Bouyssou, Laureen', '9782413085751', '11/2024 (Parution le 13/11/2024)', 200, 'https://www.bedetheque.com/media/Couvertures/Couv_508766.jpg', 'Lorsque le premier tome des Légendaires débarque en librairie en août 2004, personne n''imaginait le succès que cette série et son auteur allaient rencontrer. Avec aujourd''hui plus de 50 tomes parus, Les Légendaires représentent plus de dix millions d''exemplaires vendus. Rien de mieux qu''un superbe ouvrage regroupant des centaines d''illustrations pour marquer ces 20 ans et faire plaisir aux Légenfans.');
INSERT INTO public.bd VALUES (4162, 'Légendaires (Les)', 'HS1', 'Cherche... les légendaires', 'Sobral, Patrick', '9782756086637', '11/2016 (Parution le 23/11/2016)', 32, 'https://www.bedetheque.com/media/Couvertures/Couv_298754.jpg', 'Dans douze décors emblématiques de la BD, les lecteurs devront réussir à retrouver les différents membres des Légendaires, ainsi que de nombreux objets et accessoires ! Des illustrations très grand format, richement détaillées et colorées, pour des heures d''amusement.');
INSERT INTO public.bd VALUES (4163, 'Légendaires (Les)', 'HS2', 'L''Album de coloriage', '<Art Book>', '9782756099019', '05/2017 (Parution le 31/05/2017)', 32, 'https://www.bedetheque.com/media/Couvertures/Couv_306380.jpg', 'À l''heure pour les vacances d''été, un album de coloriages pour s''amuser des heures avec les magnifiques illustrations de Patrick Sobral ! Plus de 40 coloriages et plein d''autocollants !');
INSERT INTO public.bd VALUES (4164, 'Légendaires (Les)', 'HS3', 'Mon cahier de jeux', 'Sobral, Patrick', '9782756096025', '05/2017 (Parution le 31/05/2017)', 32, 'https://www.bedetheque.com/media/Couvertures/Couv_306439.jpg', 'Retrouvez la troupe des Légendaires, ainsi que leurs ennemis dans ce grand cahier de jeux : énigmes, labyrinthes, fils emmêlés... Les enfants jouent des heures avec ce grand cahier et ses autocollants.');
INSERT INTO public.bd VALUES (4165, 'Légendaires (Les)', 'RJ1', 'Les Légendaires Aventures : Sang Royal', 'Jarry, Nicolas', '9782756083896', '03/2017 (Parution le 01/03/2017)', 90, 'https://www.bedetheque.com/media/Couvertures/Couv_451041.jpg', 'Accablés par la nouvelle de la mort de Jadina, les Légendaires ont un autre problème de taille à surmonter : Ténébris les quitte pour succéder à la reine Adeyrid sur le trône d''Orchidia. Est-ce la fin des Légendaires ?');
INSERT INTO public.bd VALUES (4166, 'Légendaires (Les)', 'RJ2', 'Les Légendaires Aventures : L''héritage du Mal', 'Jarry, Nicolas', '9782756083902', '03/2017 (Parution le 01/03/2017)', 90, 'https://www.bedetheque.com/media/Couvertures/Couv_451042.jpg', 'La suite des aventures des Légendaires sous la plume de Nicolas Jarry.');
INSERT INTO public.bd VALUES (4167, 'Légendaires (Les)', 'RJ3', 'Les Légendaires Aventures : Amour mortel', 'Jarry, Nicolas', '9782756094236', '05/2017 (Parution le 03/05/2017)', 90, 'https://www.bedetheque.com/media/Couvertures/Couv_308194.jpg', 'ROMAN.Shimy est inquiète. Cela fait plus d''une semaine que Gryf aurait dû rentrer. Et s''il lui était arrivé quelque chose ? La réponse ne se fait pas tarder. Le voici qui revient en trombe. Mais quelle n''est pas la surprise de ses amis lorsqu''il présente... sa fiancée ! Et comme une nouvelle ne vient jamais seule, il les avertit d''une terrible catastrophe : la race humaine risque de disparaître d''Alysia...');
INSERT INTO public.bd VALUES (4168, 'Légendaires (Les)', 'RJ4', 'Les Légendaires Aventures : l''éternité ne dure qu''un temps', 'Jarry, Nicolas', '9782756094243', '05/2017 (Parution le 03/05/2017)', 90, 'https://www.bedetheque.com/media/Couvertures/Couv_308195.jpg', 'ROMAN. Invités forcés des Chiridans, des êtres mystérieux morts depuis des siècles à la recherche de corps à posséder, les Légendaires ne tardent pas à découvrir qu''ils retiennent un prisonnier spécial, un dieu nommé Éternity. Tandis que ses amis servent d''hôtes à des esprits malfaisants, Gryf devra choisir vers qui son coeur penche : Shimy ou Shun-Day...');
INSERT INTO public.bd VALUES (4169, 'Légendaires (Les)', 'Roman1', 'A la poursuite de l''artismage', 'Sobral, Patrick', '9782756094892', '05/2018 (Parution le 09/05/2018)', 90, 'https://www.bedetheque.com/media/Couvertures/Couv_334504.jpg', 'Cette nouvelle aventure inédite des Légendaires se déroule lors du premier cycle. Les cinq héros échouent à Sabledoray après une terrible tempête, et se retrouvent convoqués de force par le Prince Halan. Celuici est prisonnier d''une peinture magique ! Impossible pour lui d''en sortir ! Afin d''éviter un accident diplomatique, les Légendaires décident de lui venir en aide, et partent à la poursuite des artismages, de mystérieux sorciers qui utilisent la peinture pour des sortilèges de magie noire... Réussiront-ils leur mission ? Tout dépendra du lecteur...');
INSERT INTO public.bd VALUES (4170, 'Légendaires (Les)', 'Roman2', 'L''île de la sorcière pourpre', 'Sobral, Patrick', '9782413019954', '10/2019 (Parution le 09/10/2019)', 224, 'https://www.bedetheque.com/media/Couvertures/Couv_438151.jpg', 'Cette nouvelle aventure inédite des Légendaires se déroule lors du premier cycle. Convoqués par le roi de Larbos, les Légendaires ont pour mission de protéger l''acheminement d''un cristal qui alimentera une machine pouvant inverser l''effet Jovénia. Mais sur le chemin, de terribles créatures, les Sanguinaigles, s''en emparent et l''emportent sur la terrible île de Kelkarnaj où la sorcière Sanguinara fait régner la terreur... Les cinq héros n''ont plus le choix : direction l''île de la sorcière pourpre pour tenter de récupérer le cristal... Réussiront-ils...');
INSERT INTO public.bd VALUES (4171, 'Légendaires (Les)', 'Roman3', 'Les Légendaires - Odyssée - Cœur de pirate', 'Bouyssou, Laureen', '9782413043980', '06/2022 (Parution le 15/06/2022)', 312, 'https://www.bedetheque.com/media/Couvertures/Couv_449833.jpg', 'Une aventure inédite ! Après la bataille d''Oroban (tome 23), l''effet Jovénia s''est dissipé et les Légendaires ont retrouvé leur apparence adulte. Un an s''est écoulé depuis qu''Artémus, à l''origine des déchirures dans la réalité, s''est sacrifié pour sauver les deux mondes. Se pourrait-il vraiment que ces brèches se soient rouvertes ? Les héros vont devoir s''allier à l''insaisissable pirate Dasyatis...');
INSERT INTO public.bd VALUES (4172, 'Légendaires (Les)', 'Roman4', 'Les Légendaires - Odyssée - Le mystère de Kasimos', 'Bouyssou, Laureen', '9782413076667', '10/2023 (Parution le 18/10/2023)', 0, 'https://www.bedetheque.com/media/Couvertures/Couv_484742.jpg', 'Une île située au coeur d''un petit archipel, a mystérieusement disparu et sa disparition a réveillé l''animosité des deux grandes îles voisines qui, depuis près de deux siècles, se disputent ce territoire.... Les Légendaires ont été dépêchés pour enquêter et découvrir ce qu''il est advenu du prince et de la princesse, et empêcher que ce conflit ne dégénère en guerre qui s''étendrait aux continents...');
INSERT INTO public.bd VALUES (4173, 'Petits hommes (Les)', '0', 'Alerte à Eslapion', 'Desprechins, Albert', '2285014120', '01/1972', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_4219.jpg', NULL);
INSERT INTO public.bd VALUES (4174, 'Petits hommes (Les)', '1', 'L''exode', 'Desprechins, Albert', '2800103450', '01/1974', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_822.jpg', 'Des petits hommes ! Pourquoi ? Comment est-ce arrivé ??? C''est simple, tout a commencé à Rajevols et tout le monde y était de taille normale, quand un beau matin... pas de doute, un jeune chercheur venait de découvrir, dans son jardin, un fragment de météorite, qu''il apporta à un ami savant. Et c''est le lendemain que tout à commencé... c''était l''épidémie !!! Les premiers qui avaient touché la météorite furent réduits en miniatures, d''autres touchèrent les petits hommes, et par simple contact lors d''une poignée de main par exemple, lors d''un baiser...');
INSERT INTO public.bd VALUES (4175, 'Petits hommes (Les)', '2', 'Des petits hommes au brontoxique', 'Seron, Pierre', '2800103469', '01/1974', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_823.jpg', NULL);
INSERT INTO public.bd VALUES (4176, 'Petits hommes (Les)', '3', 'Les guerriers du passé', 'Hao', '2800104120', '01/1975', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_830.jpg', NULL);
