INSERT INTO public.bd VALUES (4185, 'Petits hommes (Les)', '12', 'Le guêpier', 'Seron, Pierre', '2800107677', '10/1981', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_5003.jpg', NULL);
INSERT INTO public.bd VALUES (4186, 'Petits hommes (Les)', '13', 'Les prisonniers du temps', 'Seron, Pierre', '2800109041', '04/1982', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_5294.jpg', NULL);
INSERT INTO public.bd VALUES (4187, 'Petits hommes (Les)', '14', 'Petits hommes et des hommes-singes', 'Seron, Pierre', '2800109726', '04/1983', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_841.jpg', 'Depuis que Renaud et ses amis ont fait une excursion un peu forcée dans la vallée des prisonniers du temps, les scientifiques d''Eslapion 2 font régulièrement des excursions dans la vallée à des fins d''études. Dimanche et Cédille font cette fois-ci parti de l''aventure. Au cours de cette excursion, Renaud et Dimanche laissent les scientifiques esclapionnais se rendre dans la demeure des prisonniers du temps que Renaud, Lapaille et Lapoutre avaient délivrés dans l''épisode précédent, tandis qu''eux partent à la recherche du village des hommes singes...');
INSERT INTO public.bd VALUES (4188, 'Petits hommes (Les)', '15', 'Mosquito 417', 'Hao', '2800110260', '04/1984', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_5295.jpg', '4 aventures des Petits Hommes : Mosquito 417, dans laquelle Boisjoli, une jeune qui revenait tout juste à Rajevols quant la météorite est tombée. Depuis ce jour, il rêve de partir à la recherche de son père, qui se serait écrasé en Norvège suite à une mission... Renaud accepte de l''aider et ils partent à la recherche de la vérité... Le manoir de la dent verte, une histoire qui commence de façon bien étrange. Lapoutre venait rendre visite à Renaud, mais en venant, il est passé au manoir de la dent verte, qui normalement est inhabité. Or il y avait...');
INSERT INTO public.bd VALUES (4246, 'Scrameustache (Le)', '18', 'D''où viens-tu Scrameustache?', 'Gos', '280011651X', '04/1989', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_10094.jpg', NULL);
INSERT INTO public.bd VALUES (4247, 'Scrameustache (Le)', '19', 'Les Figueuleuses', 'Gos', '2800117001', '11/1989', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_10095.jpg', NULL);
INSERT INTO public.bd VALUES (4248, 'Scrameustache (Le)', '20', 'Le sosie', 'Walt', '2800117699', '07/1990', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_10096.jpg', NULL);
INSERT INTO public.bd VALUES (4189, 'Petits hommes (Les)', '16', 'La planète Ranxérox', 'Seron, Pierre', '2800110759', '01/1985', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_842.jpg', 'Maintenant que le peuple d''Eslapion 2 est libéré de la menace des hommes singes, Renaud peut tenir sa promesse et se rendre sur la planète de nos trois amis qui furent prisonniers du temps (cf Tome 13 et 14). Voici donc Renaud, Dimanche et ... Lapoutre partis pour la planète Ranxérox... Mais Lapoutre ne voulait pas venir ...pas tellement pour la durée du voyage, mais parce que sa douce amie Cédille est restée sur terre. Nos amis de Ranxérox proposent donc à Lapoutre de le renvoyer auprès de sa douce avec la navette de secours... Voilà Lapoutre...');
INSERT INTO public.bd VALUES (4190, 'Petits hommes (Les)', '17', 'Le trou blanc', 'Seron, Pierre', '2800111674', '07/1985', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_5296.jpg', NULL);
