INSERT INTO public.bd VALUES (4407, 'Garfield (Dargaud)', 'HS09', '30 ans de rires et de lasagnes', 'Davis, Jim', '2205062549', '11/2008', 285, 'https://www.bedetheque.com/media/Couvertures/Couv_150893.jpg', NULL);
INSERT INTO public.bd VALUES (4408, 'Garfield (Dargaud)', 'HS10', 'Garfield s''emballe', 'Davis, Jim', '9782205070590', '11/2012 (Parution le 23/11/2012)', 72, 'https://www.bedetheque.com/media/Couvertures/Couv_179064.jpg', NULL);
INSERT INTO public.bd VALUES (4409, 'Garfield (Dargaud)', 'HS11', 'Cool comme garfield', 'Davis, Jim', '9782810422371', '10/2017', 72, 'https://www.bedetheque.com/media/Couvertures/Couv_442731.jpg', NULL);
INSERT INTO public.bd VALUES (4410, 'Garfield (Dargaud)', 'HS12', 'Joyeux Channiversaire', 'Davis, Jim', '9782205078374', '08/2018 (Parution le 17/08/2018)', 43, 'https://www.bedetheque.com/media/Couvertures/Couv_343510.jpg', '40 ans d’humour corrosif et de ton impertinent, ça se fête !');
INSERT INTO public.bd VALUES (4411, 'Garfield (Dargaud)', 'HS13', 'Garfield en fait tout un plat', 'Davis, Jim', '9782205203134', '08/2022', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_474039.jpg', 'S''il est une chose que Garfield aime autant que dormir, c''est manger. Pas n''importe quoi, attention ! Jon sait comme il est risqué de lui proposer ces infâmes croquettes pour chat. Donnez-lui plutôt des lasagnes, des pizzas, des muffins ou des cookies. Voilà une nourriture digne d''un chat qui se respecte ! D''ailleurs, Garfield vous donne ici ses propres recettes, comme ça vous pourrez faire comme lui : une bouchée, un éclat de rire (prenez le temps d''avaler entre les deux ? quoique, ça pourrait être drôle aussi)...');
INSERT INTO public.bd VALUES (4412, 'Garfield (Dargaud)', 'Pub', 'Garfield se jette à l''eau', 'Davis, Jim', '2205049348', '06/1999', 48, 'https://www.bedetheque.com/media/Couvertures/garfieldesso_07062003.jpg', NULL);
