INSERT INTO public.bd VALUES (4431, 'Superman Saga', '15', 'Numéro 15', 'Johns, Geoff', '9782365777261', '03/2015 (Parution le 13/03/2015)', 143, 'https://www.bedetheque.com/media/Couvertures/Couv_240668.jpg', NULL);
INSERT INTO public.bd VALUES (4432, 'Superman Saga', '16', 'Numéro 16', 'Johns, Geoff', '9782365777308', '04/2015 (Parution le 08/04/2015)', 127, 'https://www.bedetheque.com/media/Couvertures/Couv_243144.jpg', 'DOOMED continue ! Charles SOULE et Greg PAK poursuivent la saga tonitruante qui voit l’Homme d’Acier infecté par son ennemi mortel, Doomsday ! Superman enquête sur les origines d’Ulysse, Geoff JOHNS et John ROMITA Jr ! Lord Satanus continue de perturber la réalité de Superman et Batman, par Greg PAK et Diogenes Neves !');
INSERT INTO public.bd VALUES (4433, 'Superman Saga', '17', 'Numéro 17', 'Snyder, Scott', '9782365777339', '05/2015 (Parution le 07/05/2015)', 131, 'https://www.bedetheque.com/media/Couvertures/Couv_245692.jpg', NULL);
INSERT INTO public.bd VALUES (4434, 'Superman Saga', '18', 'Numéro 18', 'Snyder, Scott', '9782365777360', '06/2015 (Parution le 12/06/2015)', 119, 'https://www.bedetheque.com/media/Couvertures/Couv_249005.jpg', 'DERNIER ÉPISODE DE SUPERMAN UNCHAINED, PAR SCOTT SNYDER ET JIM LEE ! Geoff JOHNS et John ROMITA Jr opposent Superman et Ulysse au Machiniste ! Supergirl rencontre Red Hood par Tony BEDARD et Jonboy MEYERS ! Smallville assaillie par les zombies par Greg PAK et Aaron KUDER ! Et final de l''arc de Greg PAK contant les aventures de Superman et Batman amnésiques !');
INSERT INTO public.bd VALUES (4435, 'Superman Saga', '19', 'Numéro 19', 'Johns, Geoff', '9782365777407', '07/2015 (Parution le 11/07/2015)', 111, 'https://www.bedetheque.com/media/Couvertures/Couv_251745.jpg', NULL);
