INSERT INTO public.bd VALUES (4437, 'Superman Saga', '21', 'Numéro 21', 'Johns, Geoff', '9782365777469', '09/2015 (Parution le 10/09/2015)', 116, 'https://www.bedetheque.com/media/Couvertures/Couv_255672.jpg', 'De Superman et Ulysse, qui sera l''Homme de Demain ? Par Geoff JOHNS et John ROMITA Jr. !');
INSERT INTO public.bd VALUES (4438, 'Superman Saga', '22', 'Numéro 22', 'Johns, Geoff', '9782365777506', '10/2015 (Parution le 08/10/2015)', 107, 'https://www.bedetheque.com/media/Couvertures/Couv_257780.jpg', NULL);
INSERT INTO public.bd VALUES (4439, 'Superman Saga', '23', 'Numéro 23', 'Romita Jr., John', '9782365777537', '11/2015 (Parution le 05/11/2015)', 117, 'https://www.bedetheque.com/media/Couvertures/Couv_261934.jpg', NULL);
INSERT INTO public.bd VALUES (4440, 'Superman Saga', '24', 'Numéro 24', 'Parker, Jeff', '9782365777568', '12/2015 (Parution le 04/12/2015)', 121, 'https://www.bedetheque.com/media/Couvertures/Couv_264872.jpg', 'Pour deux numéros : la série ADVENTURES OF SUPERMAN investit les pages du magazine !');
INSERT INTO public.bd VALUES (4441, 'Superman Saga', '25', 'Numéro 25', 'Edmondson, Nathan', '9782365777889', '01/2016 (Parution le 08/01/2016)', 120, 'https://www.bedetheque.com/media/Couvertures/Couv_268380.jpg', 'Pour deux numéros : la série ADVENTURES OF SUPERMAN investit les pages du magazine !');
INSERT INTO public.bd VALUES (4442, 'Superman Saga', '26', 'Numéro 26', 'Jurgens, Dan', '9782365777926', '02/2016 (Parution le 12/02/2016)', 120, 'https://www.bedetheque.com/media/Couvertures/Couv_271882.jpg', '3 récits complets de l''événement CONVERGENCE, par Jeff KING, Dan JURGENS, Marv WOLFMAN, Ethan VAN SCIVER, Lee WEEKS et Andy OWENS ! Lors de l''événement DOOMED, Superman s''est retrouvé prisonnier d''un trou noir : le mystère de son retour relié aux événements de CONVERGENCE est enfin dévoilé ! Le couple Superman et Lois Pre-Flashpoint et la Famille Superman Pre-Crisis s''acclimatent à la vie sous le dôme.');
INSERT INTO public.bd VALUES (4443, 'Superman Saga', 'HS01', 'Le retour de Krypton', '<Collectif>', '9782365775601', '08/2014 (Parution le 25/07/2014)', 135, 'https://www.bedetheque.com/media/Couvertures/Couv_221881.jpg', NULL);
INSERT INTO public.bd VALUES (4444, 'Superman Saga', 'HS02', 'Supergirl rejoint les Red Lantern', 'Bedard, Tony', '9782365776134', '02/2015 (Parution le 30/01/2015)', 120, 'https://www.bedetheque.com/media/Couvertures/Couv_236130.jpg', 'LE RETOUR DE SUPERGIRL !');
INSERT INTO public.bd VALUES (4445, 'Superman Saga', 'HS03', 'Supergirl au sein des Red Lantern', 'Bedard, Tony', '9782365777599', '04/2015 (Parution le 28/04/2015)', 140, 'https://www.bedetheque.com/media/Couvertures/Couv_244362.jpg', 'SUPERGIRL AU SEIN DES RED LANTERN ! Tony BEDARD et Charles SOULE dynamitent la petite vie tranquille de la jeune Kryptonienne en l’associant aux féroces Red Lantern ! Désormais protecteurs de notre secteur spatial, les hommes de Guy Gardner accueillent avec méfiance cette nouvelle recrue !');
INSERT INTO public.bd VALUES (4446, 'Batman Saga', '1', 'La renaissance des super-héros DC', 'Snyder, Scott', '9782365770774', '05/2012 (Parution le 25/05/2012)', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_164490.jpg', NULL);
INSERT INTO public.bd VALUES (4447, 'Batman Saga', '2', 'Numéro 2', 'Snyder, Scott', '9782365770781', '07/2012 (Parution le 27/06/2012)', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_167917.jpg', NULL);
INSERT INTO public.bd VALUES (4448, 'Batman Saga', '3', 'Numéro 3', 'Snyder, Scott', '9782365770798', '07/2012 (Parution le 12/07/2012)', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_168356.jpg', 'Batman écume les bas-fonds de Gotham pour en apprendre davantage sur la Cour des Hiboux, par SCOTT SNYDER et GREG CAPULLO. Le justicier tente également de sauver le commissaire Gordon du Taxidermiste, par TONY DANIEL, tandis que Damian fait cavalier seul dans Batman & Robin, par PETER TOMASI et PATRICK GLEASON! Enfin Batgirl retrouve Nightwing pour un rendez-vous loin d’être galant, par GAIL SIMONE et ARDIAN SYAF !');
INSERT INTO public.bd VALUES (4449, 'Batman Saga', '4', 'Numéro 4', 'Snyder, Scott', '9782365770804', '08/2012 (Parution le 31/08/2012)', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_171077.jpg', 'Batman révèle à Nightwing son enquête passée sur la Cour des Hiboux, par SCOTT SNYDER et GREG CAPULLO ! Une assemblée de Jokers s’attaque à Batman, par TONY DANIEL ! Batman et Robin sont tombés dans les griffes de Personne… Sa vengeance est enfin proche, par PETER TOMASI et PATRICK GLEASON ! Et une nouvelle ennemie pour Batgirl, par GAIL SIMONE et ARDIAN SYAF !');
INSERT INTO public.bd VALUES (4450, 'Batman Saga', '5', 'Numéro 5', 'Snyder, Scott', '9782365770811', '10/2012 (Parution le 05/10/2012)', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_172996.jpg', 'Perdu dans le labyrinthe de la Cour des Hiboux, Batman sombre dans la folie pure, par SCOTT SNYDER et GREG CAPULLO ! Double-ration de Batman par TONY DANIEL : face au retour du Pingouin et de Catwoman ! Les origines de la rivalité entre Bruce Wayne et Morgan Ducard, enfin dévoilées, par PETER TOMASI et PATRICK GLEASON ! Barbara Gordon retrouve sa mère, tandis que Batgirl affronte Gretel, par GAIL SIMONE et ARDIAN SYAF !');
INSERT INTO public.bd VALUES (4451, 'Batman Saga', '6', 'Numéro 6', 'Snyder, Scott', '9782365771122', '11/2012 (Parution le 26/10/2012)', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_175149.jpg', 'Battu et humilié, le Batman tente d’échapper vivant au jugement de la Cour des Hiboux, par SCOTT SNYDER et GREG CAPULLO ! Le Pingouin revient également pour de nouvelles manigances au sein de la pègre de Gotham, par TONY DANIEL ! Querelle de famille entre Batman et Damian, un duel père contre fils par PETER TOMASI et PATRICK GLEASON! Et round final entre Batgirl et Gretel, pour sauver Bruce Wayne, par GAIL SIMONE et ARDIAN SYAF !');
INSERT INTO public.bd VALUES (4452, 'Batman Saga', '7', 'Numéro 7', 'Snyder, Scott', '9782365771160', '12/2012 (Parution le 30/11/2012)', 96, 'https://www.bedetheque.com/media/Couvertures/Couv_177642.jpg', 'Hiboux par SCOTT SNYDER et GREG CAPULLO ! Il vole ensuite au secours de sa petite amie piégée par le Pingouin, parTONY DANIEL ! Dernière confrontation entre Bruce et Morgan Ducard pour la survie de Damian, par PETER TOMASI et PATRICK GLEASON! Black Canary fait son retour dans la vie de son ex partenaire, Batgirl, par GAIL SIMONE et ARDIAN SYAF !');
INSERT INTO public.bd VALUES (4453, 'Batman Saga', '8', 'Numéro 8', 'Snyder, Scott', '9782365771191', '01/2013 (Parution le 21/12/2012)', 112, 'https://www.bedetheque.com/media/Couvertures/Couv_179418.jpg', 'LE PRÉLUDE À LA NUIT DES HIBOUX ! Le crossover qui oppose Batman à ses adversaires les plus coriaces débute ici, avec l’attaque du Manoir Wayne par les Ergots ! Par SCOTT SNYDER et GREG CAPULLO ! Catwoman sous la coupe de la toxine terreur, Par Tony DANIEL ! Dernier acte de l’affrontement Damian / Personne / Bruce Wayne ! Par PETER TOMASI et PATRICK GLEASON ! Enfin Batgirl s’oppose à Grotesque, par GAIL SIMONE et ARDIAN SYAF ! En compléments des back-ups signées SCOTT SNYDER, JAMES TYNION IV, RAFAEL ALBUQUERQUE, TONY DANIEL et SZYMON KUDRANSKI');
INSERT INTO public.bd VALUES (4454, 'Batman Saga', '9', 'Numéro 9', 'Snyder, Scott', '9782365771313', '02/2013 (Parution le 25/01/2013)', 112, 'https://www.bedetheque.com/media/Couvertures/Couv_182245.jpg', 'Première salve d’épisodes de la Nuit des Hiboux : les Ergots attaquent les pontes de Gotham City et l’armée personnelle de Batman se met en branle pour les contrer ! Scott SNYDER, Greg CAPULLO, Peter TOMASI, Gail SIMONE, Ardian SYAF, Kyle HIGGINS, Eddy BARROWS et RAFAEL ALBUQUERQUE nous tiennent éveillés durant cette nuit sans fin ! Pendant ce temps, Double-Face refait des siennes, par Tony DANIEL et Szymon KUDRANSKI');
INSERT INTO public.bd VALUES (4455, 'Batman Saga', '10', 'Numéro 10', 'Snyder, Scott', '9782365771320', '02/2013 (Parution le 22/02/2013)', 112, 'https://www.bedetheque.com/media/Couvertures/Couv_183836.jpg', 'Suite et fin de la Nuit des Hiboux : la Bat-Famille parviendra-t-elle à survivre à l’attaque des Ergots ? Seuls Judd WINICK, David FINCH, Tony DANIEL, Kyle HIGGINS et Eddy BARROWS connaissent la réponse ! Et le grand retour de Mr Freeze dans l’univers de la renaissance DC, par Scott SNYDER, James TYNION IV et Jason FABOK');
INSERT INTO public.bd VALUES (4456, 'Batman Saga', '11', 'Numéro 11', 'Snyder, Scott', '9782365771337', '04/2013 (Parution le 29/03/2013)', 136, 'https://www.bedetheque.com/media/Couvertures/Couv_186059.jpg', 'Batman Incorporated de Grant MORRISON fait une entrée fracassante dans le magazine, quand Batman et Batgirl enquêtent sur une école privée bien étrange, Cameron STEWART signe l’épisode ! Après la Nuit des Hiboux, Scott SNYDER et Greg CAPULLO font monter d’un cran le combat entre Batman et les maîtres des Ergots ! Tony DANIEL oppose le Chevalier Noir à un nouveau super-vilain et poursuit avec Szymon KUDRANSKI le retour de Double-Face ! Enfin, Damian Wayne lance un défi aux anciens Robin, par Peter TOMASI et Patrick GLEASON');
INSERT INTO public.bd VALUES (4457, 'Batman Saga', '12', 'Numéro 12', 'Snyder, Scott', '9782365771344', '04/2013 (Parution le 26/04/2013)', 128, 'https://www.bedetheque.com/media/Couvertures/Couv_186922.jpg', 'Scott SNYDER et Greg CAPULLO orchestrent une révélation surprenante pour Batman : à ne pas manquer ! Mr Toxic contre Batman par Tony DANIEL et Ed BENES ! Double-Face refait surface par Tony DANIEL et Szymon KUDRANSKI ! Damian a défié ses prédécesseurs et il débute son tournoi avec Jason Todd, le Red Hood, par Peter TOMASI et Patrick GLEASON ! Et les membres de Batman Incorporated découvrent enfin qui se cache derrière Leviathan, par Grant MORRISON et Chris BURNHAM !');
INSERT INTO public.bd VALUES (4458, 'Batman Saga', '13', 'Numéro 13', 'Snyder, Scott', '9782365771351', '05/2013 (Parution le 31/05/2013)', 128, 'https://www.bedetheque.com/media/Couvertures/Couv_188508.jpg', 'Découvrez Harper Row, une nouvelle venue dans l’univers de Batman par Scott SNYDER, James TYNION IV, Becky CLOONAN et Andy CLARKE ! Tony DANIEL dévoile le secret de Hugh Marder! Terminus affronte Batman et les Robins, par Peter TOMASI et Patrick GLEASON ! Deux épisodes de Batgirl, qui mène l’enquête sur Knightfall et rencontre Batwoman par Gail SIMONE et Ardian SYAF ! Et les prémices du retour du Joker par James TYNION IV et Szymon KUDRANSKI !');
INSERT INTO public.bd VALUES (4459, 'Batman Saga', '14', 'Numéro 14', 'Snyder, Scott', '9782365771368', '06/2013 (Parution le 28/06/2013)', 144, 'https://www.bedetheque.com/media/Couvertures/Couv_189839.jpg', NULL);
INSERT INTO public.bd VALUES (4460, 'Batman Saga', '15', 'Numéro 15', 'Snyder, Scott', '9782365771375', '07/2013 (Parution le 26/07/2013)', 136, 'https://www.bedetheque.com/media/Couvertures/Couv_190251.jpg', 'Premier partie du crossover Death of the Family');
INSERT INTO public.bd VALUES (4588, 'Ric Hochet', '37', 'Le maléfice vaudou', 'Duchâteau, André-Paul', '2803604183', '10/1983', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1691.jpg', NULL);
INSERT INTO public.bd VALUES (4589, 'Ric Hochet', '38', 'Face au crime', 'Duchâteau, André-Paul', '2803604418', '03/1984', 46, 'https://www.bedetheque.com/media/Couvertures/richochet38.jpg', NULL);
INSERT INTO public.bd VALUES (4590, 'Ric Hochet', '39', 'Le disparu de l''enfer', 'Duchâteau, André-Paul', '2803604639', '10/1984', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1693.jpg', NULL);
INSERT INTO public.bd VALUES (4461, 'Batman Saga', '16', 'Numéro 16', 'Snyder, Scott', '9782365771382', '08/2013 (Parution le 30/08/2013)', 136, 'https://www.bedetheque.com/media/Couvertures/Couv_194318.jpg', 'LE DEUIL DE LA FAMILLE – 2E PARTIE ! Scott SNYDER, Greg CAPULLO et JOCK décrivent l’engrenage maléfique élaboré par le Joker ! Batgirl tente de sauver une personne proche des sbires du Clown du Crime ! Ann NOCENTI et Rafa SANDOVAL relatent sa confrontation avec Catwoman ! Jonathan LAYMAN, Jason FABOK et Andy CLARKE remettent sur le devant de la scène Poison Ivy et Gueule d’Argile ! Et Batman part à la recherche de Robin dans les égouts, par Peter TOMASI, Tomas GIORELLO et Patrick GLEASON !');
INSERT INTO public.bd VALUES (4462, 'Batman Saga', '17', 'Numéro 17', 'Snyder, Scott', '9782365771399', '10/2013 (Parution le 27/09/2013)', 136, 'https://www.bedetheque.com/media/Couvertures/Couv_198139.jpg', NULL);
