INSERT INTO public.bd VALUES (4476, 'Batman Saga', '31', 'Numéro 31', 'Snyder, Scott', '9782365774598', '12/2014 (Parution le 25/11/2014)', 110, 'https://www.bedetheque.com/media/Couvertures/Couv_231517.jpg', NULL);
INSERT INTO public.bd VALUES (4477, 'Batman Saga', '32', 'Numéro 32', 'Snyder, Scott', '9782365774604', '01/2015 (Parution le 19/12/2014)', 119, 'https://www.bedetheque.com/media/Couvertures/Couv_233369.jpg', 'LA REPRISE DE DETECTIVE COMICS PAR FRANCIS MANAPUL ET BRIAN BUCCELLATO ! Le tandem de FLASH lance le plus grand détective du monde sur une nouvelle enquête! Troisième et dernier acte de Batman L’An Zéro par Scott SNYDER et Greg CAPULLO : le Sphinx devient le maître d’une Gotham devenue une véritable jungle urbaine ! Peter TOMASI et Patrick GLEASON confrontent Batman, Wonder Woman et Frankenstein à Ra’s al Ghul dans deux épisodes ! Et Batgirl face à une menace surnaturelle, par Marguerite BENNETT et Roberto GILL !');
INSERT INTO public.bd VALUES (4478, 'Batman Saga', '33', 'Numéro 33', 'Snyder, Scott', '9782365777223', '02/2015 (Parution le 30/01/2015)', 124, 'https://www.bedetheque.com/media/Couvertures/Couv_236132.jpg', 'LA REPRISE DE DETECTIVE COMICS PAR FRANCIS MANAPUL ET BRIAN BUCCELLATO !');
