INSERT INTO public.bd VALUES (4489, 'Batman Saga', '44', 'Numéro 44', 'Stambecco', '9782365777575', '12/2015 (Parution le 10/12/2015)', 135, 'https://www.bedetheque.com/media/Couvertures/Couv_264681.jpg', NULL);
INSERT INTO public.bd VALUES (4490, 'Batman Saga', '45', 'Convergence à Gotham City', 'Marz, Ron', '9782365777896', '02/2016 (Parution le 29/01/2016)', 118, 'https://www.bedetheque.com/media/Couvertures/Couv_270749.jpg', '3 récits complets de l''événement CONVERGENCE, par Len WEIN, Ron MARZ, Marc ANDREYKO, Denys COWAN et Carlos D''ANDA ! Alors que les villes de différentes Terres parallèles sont sélectionnées et intégrées à un champ de bataille, les héros de toutes ces dimensions sont amenés à s''affronter ! Batman et Robin versions Dick Grayson et Damian Wayne, Huntress et Robin de Terre-2 et Les Outsiders de l''ère Pre-Crisis se retrouvent piégés par un dôme qui annihile leurs pouvoirs !');
INSERT INTO public.bd VALUES (4491, 'Batman Saga', 'HS01', 'Les origines de Gotham City par Scott Snyder', 'Snyder, Scott', '9782365771214', '11/2012 (Parution le 26/10/2012)', 105, 'https://www.bedetheque.com/media/Couvertures/Couv_175176.jpg', NULL);
INSERT INTO public.bd VALUES (4591, 'Ric Hochet', '40', 'Le double qui tue', 'Duchâteau, André-Paul', '2803604833', '03/1985', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1694.jpg', NULL);
INSERT INTO public.bd VALUES (4676, 'Moky et Poupy', '31', 'Le mystère de la falaise', 'Bussemey, Roger', '2244140121', '01/1966', 20, 'https://www.bedetheque.com/media/Couvertures/Couv_119302.jpg', NULL);
INSERT INTO public.bd VALUES (4492, 'Batman Saga', 'HS02', 'Batman Incorporated', 'Morrison, Grant', '9782365771740', '07/2013 (Parution le 12/07/2013)', 128, 'https://www.bedetheque.com/media/Couvertures/Couv_192062.jpg', 'BATMAN INCORPORATED REVIENT ! Maintenant que Léviathan est identifié, Batman et son organisation internationale vont devoir tout mettre en oeuvre pour déjouer les plans machiavéliques de ce génie du crime. Grant MORRISON, Chris BURNHAM et Frazer IRVING sont aux commandes de cette nouvelle mouture qui clôturera une saga gigantesque ! De nombreux coups de théâtre sont à prévoir !');
INSERT INTO public.bd VALUES (4493, 'Batman Saga', 'HS03', 'Batman Incorporated', 'Morrison, Grant', '9782365773201', '11/2013 (Parution le 13/11/2013)', 128, 'https://www.bedetheque.com/media/Couvertures/Couv_201537.jpg', NULL);
