INSERT INTO public.bd VALUES (4495, 'Batman Saga', 'HS05', 'Forever evil : Gotham City assiégée !', 'Morrison, Grant', '9782365775052', '06/2014 (Parution le 28/05/2014)', 132, 'https://www.bedetheque.com/media/Couvertures/Couv_217616.jpg', NULL);
INSERT INTO public.bd VALUES (4496, 'Batman Saga', 'HS06', 'Le fils de Batman', 'Kubert, Andy', '9782365775694', '11/2014 (Parution le 14/11/2014)', 95, 'https://www.bedetheque.com/media/Couvertures/Couv_231022.jpg', NULL);
INSERT INTO public.bd VALUES (4497, 'Batman Saga', 'HS07', 'Futures End : Le Batman de demain !', 'Pak, Greg', '9782365777605', '06/2015 (Parution le 07/05/2015)', 120, 'https://www.bedetheque.com/media/Couvertures/Couv_245686.jpg', NULL);
INSERT INTO public.bd VALUES (4498, 'Batman Saga', 'HS08', 'Batman ''66', 'Parker, Jeff', '9782365775649', '11/2015 (Parution le 23/10/2015)', 120, 'https://www.bedetheque.com/media/Couvertures/Couv_260037.jpg', 'BATMAN''66 : L''ADAPATION DE LA SÉRIE CULTE DES ANNÉES SOIXANTE ! Jeff PARKER, Jonathan CASE, Ty TEMPLETON, Joe QUINONES et Sandy JARRELL présentent un voyage dans le temps à l''époque de la série TV culte BATMAN : retrouvez le Joker, le Sphinx, Catwoman, le Pingouin mais également Tête d''oeuf, le Chapelier Fou et Mister Freeze dans des enquêtes inédites !');
INSERT INTO public.bd VALUES (4499, 'Spider-Man (L''Intégrale)', '1', '1962-1963', 'Lee, Stan', '2845380763', '01/2002 (Parution le 08/02/2002)', 180, 'https://www.bedetheque.com/media/Couvertures/Couv_455975.jpg', 'Piqué par une araignée radioactive au cours d''une expérience, le jeune Peter Parker en hérite les caractéristiques. Suite à la mort de son oncle, il décide de consacrer sa vie à combattre le crime sous le costume de...Spiderman !');
