INSERT INTO public.bd VALUES (4507, 'Spider-Man (L''Intégrale)', '9', '1971', 'Lee, Stan', '2845385986', '12/2005 (Parution le 01/12/2005)', 268, 'https://www.bedetheque.com/media/Couvertures/Couv_456015.jpg', NULL);
INSERT INTO public.bd VALUES (4508, 'Spider-Man (L''Intégrale)', '10', '1972', 'Lee, Stan', '2845387296', '06/2006', 250, 'https://www.bedetheque.com/media/Couvertures/Couv_56736.jpg', NULL);
INSERT INTO public.bd VALUES (4509, 'Spider-Man (L''Intégrale)', '11', '1973', 'Lee, Stan', '2845388101', '10/2006', 304, 'https://www.bedetheque.com/media/Couvertures/Couv_58515.jpg', NULL);
INSERT INTO public.bd VALUES (4510, 'Spider-Man (L''Intégrale)', '12', '1974', 'Lee, Stan', '284538923X', '03/2007', 306, 'https://www.bedetheque.com/media/Couvertures/SpidermanLintegrale12int_23032007.jpg', NULL);
INSERT INTO public.bd VALUES (4511, 'Spider-Man (L''Intégrale)', '13', '1975', 'Conway, Gerry', '9782809400502', '08/2007', 298, 'https://www.bedetheque.com/media/Couvertures/Couv_66245.jpg', NULL);
INSERT INTO public.bd VALUES (4512, 'Spider-Man (L''Intégrale)', '14', '1976', 'Wein, Len', '9782809401301', '12/2007', 248, 'https://www.bedetheque.com/media/Couvertures/Couv_70490.jpg', NULL);
INSERT INTO public.bd VALUES (4513, 'Spider-Man (L''Intégrale)', '15', '1977', 'Wein, Len', '9782809402469', '05/2008', 255, 'https://www.bedetheque.com/media/Couvertures/Couv_74732.jpg', NULL);
INSERT INTO public.bd VALUES (4514, 'Spider-Man (L''Intégrale)', '16', '1978', 'Wein, Len', '9782809406719', '03/2009', 208, 'https://www.bedetheque.com/media/Couvertures/SpidermanLintegrale17int_09042009_092454.gif', NULL);
INSERT INTO public.bd VALUES (4515, 'Spider-Man (L''Intégrale)', '17', '1979', 'Wolfman, Marv', '9782809408720', '11/2009', 242, 'https://www.bedetheque.com/media/Couvertures/Couv_102421.jpg', NULL);
INSERT INTO public.bd VALUES (4516, 'Spider-Man (L''Intégrale)', '18', '1980', '<Collectif>', '9782809414110', '10/2010', 296, 'https://www.bedetheque.com/media/Couvertures/Couv_116667.jpg', NULL);
INSERT INTO public.bd VALUES (4517, 'Spider-Man (L''Intégrale)', '19', '1981', 'O''Neil, Dennis', '9782809424089', '07/2012 (Parution le 04/07/2012)', 300, 'https://www.bedetheque.com/media/Couvertures/Couv_167925.jpg', NULL);
INSERT INTO public.bd VALUES (4518, 'Spider-Man (L''Intégrale)', '20', '1982', 'Stern, Roger', '9782809442069', '10/2014', 180, 'https://www.bedetheque.com/media/Couvertures/Couv_227331.jpg', NULL);
INSERT INTO public.bd VALUES (4519, 'Spider-Man (L''Intégrale)', '21', '1983', 'Stern, Roger', '9782809450354', '09/2015 (Parution le 09/09/2015)', 320, 'https://www.bedetheque.com/media/Couvertures/Couv_255116.jpg', 'Cet album présente douze aventures de Spider-Man imaginées par le scénariste Roger Stern et le dessinateur John Romita Jr en 1983. Le Tisseur va notamment affronter le Super-Bouffon, Tarentule, l''Homme aux Échasses, le Vautour, le Penseur Fou ainsi que... J. Jonah Jameson ! Découvrez aussi un annual inédit où s''opposent Peter Parker et le Caïd.');
INSERT INTO public.bd VALUES (4520, 'Spider-Man (L''Intégrale)', '22', '1984', 'Stern, Roger', '9782809456974', '10/2016 (Parution le 05/10/2016)', 320, 'https://www.bedetheque.com/media/Couvertures/Couv_290059.jpg', NULL);
INSERT INTO public.bd VALUES (4521, 'Spider-Man (L''Intégrale)', '23', '1985', 'Simonson, Louise', '9782809466966', '11/2017 (Parution le 02/11/2017)', 320, 'https://www.bedetheque.com/media/Couvertures/Couv_315090.jpg', 'Après une terrible bataille contre le Super-Bouffon, Spider-Man va devoir faire face à un autre adversaire encore beacoup plus puissant : Firelord, le nouvel héraut de Galactus !');
INSERT INTO public.bd VALUES (4522, 'Spider-Man (L''Intégrale)', '24', '1986', 'DeFalco, Tom', '9782809477993', '07/2019 (Parution le 03/07/2019)', 320, 'https://www.bedetheque.com/media/Couvertures/Couv_370836.jpg', 'L''année 1986 de Spider-Man est marquée par des épisodes en lien avec Secret Wars II. On retrouve aussi par ses combats contre le Super-Bouffon, la présence de X-Factor');
INSERT INTO public.bd VALUES (4523, 'Spider-Man (L''Intégrale)', '25', '1987', 'DeFalco, Tom', '9782809486544', '03/2020 (Parution le 04/03/2020)', 304, 'https://www.bedetheque.com/media/Couvertures/Couv_387682.jpg', 'La guerre des gangs atteint son paroxysme dans les pages d''Amazing spider-man en 1987 ! Le Punisher, Daredevil, le Faucon, la Chatte Noire ou encore le Caïd sont tous présents pour un final… explosif.');
INSERT INTO public.bd VALUES (4524, 'Spider-Man (L''Intégrale)', '26', '1987-1988', 'Michelinie, David', '9782809491869', '02/2021 (Parution le 10/03/2021)', 360, 'https://www.bedetheque.com/media/Couvertures/Couv_417187.jpg', 'Spider-Man vs Kraven ! Le Tisseur va vivre l''un de ses plus terribles affrontements, face à cet ennemi déterminé à en finir une fois pour toutes avec le héros. Mais ça n''est que le début d''une suite d''aventures qui ont marqué la longue carrière de l''icône Marvel. Un tome très important pour les fans puisqu''il se conclut avec la première apparition de Venom ! Ce 49ème tome de l''INTÉGRALE consacrée à Spider-Man, est sans aucun doute l''un des plus essentiels puisqu''il fait le pont entre la saga culte La dernière chasse de Kraven et les premiers épisodes...');
INSERT INTO public.bd VALUES (4525, 'Spider-Man (L''Intégrale)', '27', '1988-1989', 'Michelinie, David', '9791039114417', '03/2023 (Parution le 01/03/2023)', 312, 'https://www.bedetheque.com/media/Couvertures/Couv_468973.jpg', 'Après l''incident Venom, Peter Parker remet son costume rouge et bleu pour affronter le crime. Il aura fort à faire face à Silver Sable, l''Homme-Sable, Black Fox et bien d''autres, mais on peut faire confiance au Tisseur pour tenir tête à ses ennemis. En plus des victoires de Spider-Man, Peter sort un livre et nage dans le bonheur avec Mary Jane... Mais est-ce que cette allégresse va durablement s''installer dans la vie du héros ?Voici une période essentielle pour Spider-Man, puisque c''est celle où émerge, aux côtés de David Michelinie, le dessinateur...');
INSERT INTO public.bd VALUES (4526, 'Spider-Man (L''Intégrale)', '28', '1989', 'Michelinie, David', '9791039123051', '03/2024 (Parution le 13/03/2024)', 320, 'https://www.bedetheque.com/media/Couvertures/Couv_495485.jpg', 'Quand le Bouffon Vert affronte le Super-Bouffon, Spider-Man se retrouve au milieu du combat ! Le Lézard, Hydro-Man, Venom et le Scorpion font partie des autres ennemis qui mèneront la vie dure à Spidey ! La mythique association entre David Michelinie et Todd McFarlane (créateur de Spawn, qui montera ensuite Image Studios avec Jim Lee et d''autres superstars du dessin) se poursuit dans ce nouvel album riche en sensations fortes. Les fans y trouveront également des histoires inédites tirées de l''Annual 89 de la série Amazing Spider-Man, ainsi qu''un...');
INSERT INTO public.bd VALUES (4527, 'Spider-Man (L''Intégrale)', '29', '1989-1990', 'Michelinie, David', '9791039127523', '12/2024 (Parution le 03/12/2024)', 360, 'https://www.bedetheque.com/media/Couvertures/Couv_511442.jpg', 'Le crépuscule de la décennie marque également la fin du cycle de David Michelinie et Todd McFarlane sur Amazing Spider-Man, au terme d’un succès hors du commun. Spider-Man participe en outre au crossover Acts of Vengeance, réalisé en collaboration avec Gerry Conway, Sal Buscema et Alex Saviuk.');
INSERT INTO public.bd VALUES (4528, 'Spider-Man (L''Intégrale)', '30', '1990', 'Michelinie, David', '9791039132213', '03/2025 (Parution le 11/03/2025)', 296, 'https://www.bedetheque.com/media/Couvertures/Couv_518062.jpg', 'Lors de la première partie de 1990, David Michelinie et Erik Larsen réalisent des histoires dans lesquelles Spider-Man est confronté au retour de Venom, tandis que les trois Annuals des séries donnent vie à un mini-crossover qui envoie notre héros dans le Microvers.');
INSERT INTO public.bd VALUES (4529, 'Spider-Man (L''Intégrale)', '31', '1990-1991', 'McFarlane, Todd', '9791039134859', '06/2025 (Parution le 11/06/2025)', 296, 'https://www.bedetheque.com/media/Couvertures/Couv_523355.jpg', 'En tant que Spider-Man, Peter Parker s''est toujours montré compatissant envers le Dr Curt Connors, devenu le Lézard à la suite d''une expérience qui a mal tourné. Mais quand la créature se livre à un carnage dans les rues de New York, le Tisseur va-t-il pouvoir tolérer une telle soif de sang ?');
INSERT INTO public.bd VALUES (4530, 'Spider-Man (L''Intégrale)', '32', '1990-1991 (II)', 'Michelinie, David', '9791039138505', '12/2025 (Parution le 10/12/2025)', 352, 'https://www.bedetheque.com/media/Couvertures/Couv_532628.jpg', NULL);
INSERT INTO public.bd VALUES (4531, 'Spider-Man (L''Intégrale)', '33', '1991', 'Michelinie, David', '9791039141468', '02/2026 (Parution le 04/02/2026)', 311, 'https://www.bedetheque.com/media/Couvertures/Couv_535012.jpg', NULL);
INSERT INTO public.bd VALUES (4532, 'Captain America (L''intégrale)', '1', '1964-1966', 'Lee, Stan', '9782809419375', '07/2011', 260, 'https://www.bedetheque.com/media/Couvertures/Couv_313214.jpg', NULL);
INSERT INTO public.bd VALUES (4533, 'Captain America (L''intégrale)', '2', '1967-1968', 'Lee, Stan', '9782809424065', '06/2012 (Parution le 20/06/2012)', 296, 'https://www.bedetheque.com/media/Couvertures/Couv_455423.jpg', NULL);
INSERT INTO public.bd VALUES (4534, 'Captain America (L''intégrale)', '3', '1968-1969', 'Lee, Stan', '9782809430790', '09/2013 (Parution le 11/09/2013)', 300, 'https://www.bedetheque.com/media/Couvertures/Couv_455424.jpg', NULL);
INSERT INTO public.bd VALUES (4535, 'Captain America (L''intégrale)', '4', '1970', 'Lee, Stan', '9782809436730', '03/2014 (Parution le 12/03/2014)', 248, 'https://www.bedetheque.com/media/Couvertures/Couv_455425.jpg', 'Découvrez le quatrième volume des aventures de Captain America, entièrement réalisé par Stan Lee et Gene Colan ! Des épisodes inoubliables dans lesquels Steve Rogers est opposé à de nombreux ennemis, notamment le Scorpion, M.O.D.O.K., Diamondhead et Crâne Rouge.');
INSERT INTO public.bd VALUES (4536, 'Captain America (L''intégrale)', '5', '1971', 'Lee, Stan', '9782809446456', '02/2015 (Parution le 04/02/2015)', 264, 'https://www.bedetheque.com/media/Couvertures/Couv_455428.jpg', 'Dans ce cinquième volume, Captain America et le Faucon affrontent de nombreux adversaires dont le redoutable M.O.D.O.K. et la Gargouille Grise ainsi que... Spider-Man ?!');
INSERT INTO public.bd VALUES (4537, 'Captain America (L''intégrale)', '6', '1972', 'Friedrich, Gary', '9782809454673', '04/2016 (Parution le 20/04/2016)', 264, 'https://www.bedetheque.com/media/Couvertures/Couv_455560.jpg', 'Dans ce nouvel opus des aventures de Captain America & The Falcon, les deux héros affrontent les membres de l’Hydra mais aussi Batroc, l’Étranger ou encore Crâne Rouge. Steve Rogers fait aussi face à… Captain America ?');
INSERT INTO public.bd VALUES (4538, 'Captain America (L''intégrale)', '7', '1973', 'Englehart, Steve', '9782809460056', '02/2017 (Parution le 08/02/2017)', 256, 'https://www.bedetheque.com/media/Couvertures/Couv_455690.jpg', NULL);
INSERT INTO public.bd VALUES (4539, 'Captain America (L''intégrale)', '8', '1974', 'Englehart, Steve', '9782809467741', '02/2018 (Parution le 07/02/2018)', 240, 'https://www.bedetheque.com/media/Couvertures/Couv_323317.jpg', NULL);
INSERT INTO public.bd VALUES (4540, 'Captain America (L''intégrale)', '9', '1975', 'Englehart, Steve', '9782809477061', '04/2019 (Parution le 10/04/2019)', 214, 'https://www.bedetheque.com/media/Couvertures/Couv_364289.jpg', 'La prestation de Steve Englehart touche à sa fin et pour ses derniers épisodes, il ramène Crâne Rouge ! Retrouvez également un épisode inédit en France signé Marv Wolfman.');
INSERT INTO public.bd VALUES (4541, 'Captain America (L''intégrale)', '10', '1976', 'Kirby, Jack', '9782809486759', '04/2020 (Parution le 10/06/2020)', 288, 'https://www.bedetheque.com/media/Couvertures/Couv_396529.jpg', 'Le run culte de Jack Kirby débarque dans les Intégrales ! Une prestation globalement inédite en France.');
INSERT INTO public.bd VALUES (4542, 'Captain America (L''intégrale)', '11', '1976-1977', 'Kirby, Jack', '9782809494938', '07/2021 (Parution le 15/07/2021)', 304, 'https://www.bedetheque.com/media/Couvertures/Couv_429117.jpg', 'Captain America, sauveur de l''univers ? Steve Rogers et son camarade Sam Wilson, alias le Faucon, se retrouvent confrontés à des menaces d''autres dimensions dans des aventures très spéciales. Bien sûr, il faut compter aussi sur les ennemis habituels, comme Crâne Rouge et Arnim Zola ! Attention, événement ! Ce volume de CAPTAIN AMERICA : L''INTÉGRALE n''a pas comme seul argument d''être totalement réalisé par Jack Kirby... Il est entièrement composé d''épisodes jamais publiés en France ! Des histoires que les fans rêvent de découvrir depuis des décennies....');
INSERT INTO public.bd VALUES (4543, 'Captain America (L''intégrale)', '12', '1941', 'Kirby, Jack', '9782809494921', '07/2021 (Parution le 15/07/2021)', 288, 'https://www.bedetheque.com/media/Couvertures/Couv_429118.jpg', 'Avant l''ère moderne des super-héros, avant les Quatre Fantastiques, avant Spider-Man, avant les Avengers, avant Marvel... il y avait déjà des comics Captain America ! Transformé par le sérum du Super-Soldat, le chétif Steve Rogers devient un symbole du patriotisme, de l''espoir et de la persévérance dans des aventures palpitantes, qui l''opposent au terrible Crâne Rouge, avec son partenaire Bucky Barnes ! Avant que Marvel ne s''appelle Marvel et que Stan Lee ne crée les super-héros qui ont fait la renommée de la Maison des Idées, en 1941, Captain...');
INSERT INTO public.bd VALUES (4544, 'Captain America (L''intégrale)', '13', '1977-1979', 'Thomas, Roy', '9791039107471', '09/2022 (Parution le 06/09/2022)', 312, 'https://www.bedetheque.com/media/Couvertures/Couv_455339.jpg', 'Captain America doit affronter une version gigantesque de lui-même : prenez garde à l''Améridroïde ! Et quand Crâne Rouge fait son grand retour, la Légende Vivante est bien heureuse de recevoir le soutien de Nick Fury et de ses agents du S.H.I.E.L.D. !');
INSERT INTO public.bd VALUES (4545, 'Captain America (L''intégrale)', '14', '1941 (II)', 'Lee, Stan', '9791039107488', '09/2022 (Parution le 28/09/2022)', 280, 'https://www.bedetheque.com/media/Couvertures/Couv_457415.jpg', NULL);
INSERT INTO public.bd VALUES (4546, 'Captain America (L''intégrale)', '15', '1979-1980', 'McKenzie, Roger', '9791039112437', '01/2023 (Parution le 01/02/2023)', 328, 'https://www.bedetheque.com/media/Couvertures/Couv_467717.jpg', 'Captain America continue de défendre les valeurs d''ouverture de l''Amérique face à un groupe haineux appelé la Force Nationale. Il déménage également pour s''installer à Brooklyn, et y rencontre le Punisher, entre autres histoires passionnantes survenues lors du changement de décennie.');
INSERT INTO public.bd VALUES (4547, 'Captain America (L''intégrale)', '16', '1941-1942', 'Simon, Joe', '9791039119337', '10/2023 (Parution le 11/10/2023)', 280, 'https://www.bedetheque.com/media/Couvertures/Couv_485176.jpg', 'Les aventures de l''âge d''or de Captain America, imaginées par Joe Simon et Jack Kirby, se poursuivent dans ce troisième volume. Nous vous présentons en annexe des récits consacrés à d''autres héros dont le Farfadet, Ouragan, Père Temps et le Reporter de l''impossible');
INSERT INTO public.bd VALUES (4548, 'Captain America (L''intégrale)', '17', '1980-1981', 'Stern, Roger', '9791039128452', '07/2024 (Parution le 10/07/2024)', 328, 'https://www.bedetheque.com/media/Couvertures/Couv_501655.jpg', NULL);
INSERT INTO public.bd VALUES (4549, 'Captain America (L''intégrale)', '18', '1942', 'Lee, Stan', '9791039124973', '07/2024 (Parution le 10/07/2024)', 272, 'https://www.bedetheque.com/media/Couvertures/Couv_501656.jpg', NULL);
INSERT INTO public.bd VALUES (4550, 'Captain America (L''intégrale)', '19', '1981-1982', 'DeMatteis, John Marc', '9791039132176', '02/2025 (Parution le 12/02/2025)', 253, 'https://www.bedetheque.com/media/Couvertures/Couv_514687.jpg', NULL);
INSERT INTO public.bd VALUES (4551, 'Captain America (L''intégrale)', '20', '1942 (II)', 'Avison, Al', '9791039132169', '02/2025 (Parution le 19/02/2025)', 280, 'https://www.bedetheque.com/media/Couvertures/Couv_516363.jpg', 'Captain America et Bucky s''élancent dans de nouvelles aventures dans l''univers Marvel des années 40 ! Que ce soit face à la Cinquième Colonne ou à des super-vilains comme Ergot Noir, nos camarades auront bien besoin de l''aide de la Torche Humaine et du Prince des Mers !');
INSERT INTO public.bd VALUES (4552, 'Ric Hochet', '1', 'Traquenard au Havre', 'Duchâteau, André-Paul', '276142915X', '09/1963', 60, 'https://www.bedetheque.com/media/Couvertures/Couv_20201.jpg', NULL);
INSERT INTO public.bd VALUES (4553, 'Ric Hochet', '2', 'Mystère à Porquerolles', 'Duchâteau, André-Paul', '2929164875', '09/1964', 60, 'https://www.bedetheque.com/media/Couvertures/Couv_32431.jpg', NULL);
INSERT INTO public.bd VALUES (4554, 'Ric Hochet', '3', 'Défi à Ric Hochet', 'Duchâteau, André-Paul', '284071471X', '09/1965', 60, 'https://www.bedetheque.com/media/Couvertures/Couv_20202.jpg', 'Rémy Valloire, un industriel spécialisé dans la construction de moteurs d’avions, est l’objet d’un accident aéronautique. Ric, qui pilotait un autre aéroplane vient lui porter secours. Le rescapé lui fait part des ses soupçons quant au sabotage de son appareil. De plus, depuis quelques jours, il reçoit des appels téléphoniques anonymes le menaçant de mort. Qui, dans l’entourage professionnel ou dans son cercle d’amis, a intérêt à vouloir faire disparaître l’industriel ? Ne serait-ce pas plutôt un coup monté de toute pièce sachant que Valloire semble...');
INSERT INTO public.bd VALUES (4555, 'Ric Hochet', '4', 'L''ombre de Cameleon', 'Duchâteau, André-Paul', '274631956X', '09/1966', 60, 'https://www.bedetheque.com/media/Couvertures/Couv_20203.jpg', NULL);
INSERT INTO public.bd VALUES (4556, 'Ric Hochet', '5', 'Piège pour Ric Hochet', 'Duchâteau, André-Paul', '2969994615', '09/1967', 60, 'https://www.bedetheque.com/media/Couvertures/Couv_20204.jpg', 'Ce soir-là, après avoir participé à une émission de télévision pour parler de la sortie de son livre, Ric rejoint le commissaire Bourdon dans un petit village de la Marne, à « l''Auberge des trois clefs", où son ami passe son congé de convalescence, près de sa soeur et de ses petits-neveux. Sur la route, il assiste, impuissant, à un accident : le neveu de M. Bourdon est renversé par une voiture qui prend immédiatement la fuite. Transporté à l''hôpital, le jeune garçon ne peut malheureusement identifier le chauffard. Ric Hochet décide de prendre les...');
INSERT INTO public.bd VALUES (4557, 'Ric Hochet', '6', 'Rapt sur le France', 'Duchâteau, André-Paul', '2289520241', '03/1968', 60, 'https://www.bedetheque.com/media/Couvertures/Couv_20205.jpg', 'Le commissaire Bourdon reçoit l''ordre d’accompagner le savant Hermelin, un lors de sa traversée sur le France, car il a reçu des menaces de mort. Ric Hochet couvre le fait pour le journal. Des gangsters ont déjà essayé d''empêcher le professeur de monter à bord du paquebot. N''ayant pas réussi leur coup, les gangsters montent à bord du France en se faisant passer pour des passagers. Tout au long de la croisière, Ric reste attentif...');
INSERT INTO public.bd VALUES (4558, 'Ric Hochet', '7', 'Suspense à la télévision', 'Duchâteau, André-Paul', '2738196993', '09/1968', 43, 'https://www.bedetheque.com/media/Couvertures/Couv_20206.jpg', NULL);
INSERT INTO public.bd VALUES (4559, 'Ric Hochet', '8', 'Ric Hochet face au serpent', 'Duchâteau, André-Paul', '2867846765', '03/1969', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_20207.jpg', 'Une organisation criminelle internationale, dirigée par « le Serpent », menace de sabotage plusieurs grandes entreprises européennes. Celles qui refusent de payer, sous la forme de titres de la société, sont victimes d''attentats. Les dirigeants de l''une de ces entreprises, basée à Amsterdam, contactent Ric Hochet par des moyens peu ordinaires (envoi d''un message dans l''appartement de Ric tiré d''une flèche depuis la rue) et lui demandent de venir à Amsterdam. Sans savoir ce qu''on va lui dire ou lui demander, Ric se rend au mystérieux rendez-vous....');
INSERT INTO public.bd VALUES (4560, 'Ric Hochet', '9', 'Alias Ric Hochet', 'Duchâteau, André-Paul', '2248454724', '09/1969', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_20208.jpg', 'Ric Hochet et le commissaire Bourdon ont un rendez-vous dans un magasin de jouets. Bourdon en est surpris. Il s''agit en fait d''une planque pour le nouveau laboratoire du professeur Hermelin qui travaille sur un nouveau laser. Ric Hochet doit couvrir l''article pour La rafale mais Bourdon doit se charger de la sécurité du professeur. Les deux hommes ne s''entendent pas bien. Des espions tentent de voler les dossiers d''études du professeur Hermelin. Ric Hochet les en empêche mais un des bandits paraît très attentionné quant à la vie de Ric. Après de...');
INSERT INTO public.bd VALUES (4671, 'Moky et Poupy', '26', 'Moky et Poupy ont perdu Nestor', 'Bussemey, Roger', '2783642840', '01/1965', 20, 'https://www.bedetheque.com/media/Couvertures/Couv_65592.jpg', NULL);
INSERT INTO public.bd VALUES (4561, 'Ric Hochet', '10', 'Les 5 revenants', 'Duchâteau, André-Paul', '2760275302', '03/1970', 44, 'https://www.bedetheque.com/media/Couvertures/richochet10eo.jpg', 'Après une journée de travail à «La Rafale», alors qu’il s’apprête à sortir, Ric Hochet est appelé par «Le marquis», un homme d’affaires spécialisé dans le sport. Parmi les champions qu’il a encouragés beaucoup ont réussi et d’autres ont, malheureusement, échoué. C’est pourquoi il voudrait faire quelque chose pour cinq garçons, notamment, qui ont complètement disparu de la circulation...');
INSERT INTO public.bd VALUES (4562, 'Ric Hochet', '11', 'Cauchemar pour Ric Hochet', 'Duchâteau, André-Paul', '2231398214', '09/1970', 44, 'https://www.bedetheque.com/media/Couvertures/richochet11couv.jpg', NULL);
INSERT INTO public.bd VALUES (4563, 'Ric Hochet', '12', 'Les spectres de la nuit', 'Duchâteau, André-Paul', '2803600838', '03/1971', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9812.jpg', NULL);
INSERT INTO public.bd VALUES (4564, 'Ric Hochet', '13', 'Les compagnons du diable', 'Duchâteau, André-Paul', '2803600846', '09/1971', 44, 'https://www.bedetheque.com/media/Couvertures/RicHochet13eo.jpg', NULL);
INSERT INTO public.bd VALUES (4565, 'Ric Hochet', '14', 'Ric Hochet contre le bourreau', 'Duchâteau, André-Paul', '2244926028', '02/1972', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1668.jpg', NULL);
INSERT INTO public.bd VALUES (4566, 'Ric Hochet', '15', 'Le Monstre de Noireville', 'Duchâteau, André-Paul', '2964145458', '01/1972', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1669.jpg', NULL);
INSERT INTO public.bd VALUES (4567, 'Ric Hochet', '16', 'Requiem pour une idole', 'Duchâteau, André-Paul', '2253215694', '03/1973', 44, 'https://www.bedetheque.com/media/Couvertures/richochetcou16.jpg', NULL);
INSERT INTO public.bd VALUES (4568, 'Ric Hochet', '17', 'Épitaphe pour Ric Hochet', 'Duchâteau, André-Paul', '2837730858', '10/1973', 44, 'https://www.bedetheque.com/media/Couvertures/richochet17.jpg', 'À la clinique de Thoriac dans le département de l''Ardèche, un accidenté de la route sort du coma dans un état d''amnésie totale. À son chevet, le médecin qui le soigne et le gendarme qui le veille lui apprennent qu''il se nomme Walter Wolzak et qu''il est à l''origine, avec son frère, de nombreuses agressions criminelles. Interloqué par ce terrible passé dévoilé, l''amnésique est en proie à toutes les questions. Lors de son évasion de l''établissement hospitalier, il tombe en face du vrai Wolzak dont il a vu la photo auparavant. De fait, plus aucun doute...');
INSERT INTO public.bd VALUES (4569, 'Ric Hochet', '18', 'Enquête dans le passé', 'Duchâteau, André-Paul', '2740916957', '01/1974', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1672.jpg', NULL);
INSERT INTO public.bd VALUES (4570, 'Ric Hochet', '19', 'Les signes de la peur', 'Duchâteau, André-Paul', '2819395228', '10/1974', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1673.jpg', 'Alors que le Commissaire Bourdon passe ses vacances à Belzas dans le Var, plusieurs attentats dont un mortel sont commis. En compagnie de Ric Hochet, il se fait un devoir de découvrir le ou les coupables de ces infâmes agissements. Ils découvrent que la population y est un tantinet superstitieuse et que le ou les criminels se servent de l''horoscope du journal local pour menacer certains résidents et mettre à exécution les prévisions défavorables. Quelles sont les réelles intentions de ces intimidations et ne cachent-elles pas une affaire plus sournoise...');
INSERT INTO public.bd VALUES (4571, 'Ric Hochet', '20', 'L''homme qui portait malheur', 'Duchâteau, André-Paul', '2205009362', '04/1975', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1674.jpg', NULL);
INSERT INTO public.bd VALUES (4572, 'Ric Hochet', '21', 'Le trio maléfique', 'Duchâteau, André-Paul', '2910601153', '09/1975', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9816.jpg', NULL);
INSERT INTO public.bd VALUES (4573, 'Ric Hochet', '22', 'Alerte ! Extra-terrestres !', 'Duchâteau, André-Paul', '2803600927', '01/1976', 44, 'https://www.bedetheque.com/media/Couvertures/RicHochet22a_14112004.jpg', NULL);
INSERT INTO public.bd VALUES (4574, 'Ric Hochet', '23', 'La ligne de mort', 'Duchâteau, André-Paul', '2291057065', '01/1976', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_68189.jpg', NULL);
INSERT INTO public.bd VALUES (4575, 'Ric Hochet', '24', 'La piste rouge', 'Duchâteau, André-Paul', '2205010743', '02/1977', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1678.jpg', NULL);
INSERT INTO public.bd VALUES (4576, 'Ric Hochet', '25', 'Coups de griffes chez Bouglione', 'Duchâteau, André-Paul', '2803600951', '09/1977', 44, 'https://www.bedetheque.com/media/Couvertures/richochet25.jpg', NULL);
INSERT INTO public.bd VALUES (4577, 'Ric Hochet', '26', 'L''ennemi à travers les siècles', 'Duchâteau, André-Paul', '2205012207', '02/1978', 44, 'https://www.bedetheque.com/media/Couvertures/richochet26.jpg', NULL);
INSERT INTO public.bd VALUES (4578, 'Ric Hochet', '27', 'L''épée sur la gorge', 'Duchâteau, André-Paul', '2234934214', '01/1978', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1681.jpg', NULL);
INSERT INTO public.bd VALUES (4579, 'Ric Hochet', '28', 'Hallali pour Ric Hochet', 'Duchâteau, André-Paul', '2205015125', '01/1979', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1682.jpg', NULL);
INSERT INTO public.bd VALUES (4580, 'Ric Hochet', '29', 'Opération 100 milliards', 'Duchâteau, André-Paul', '2205015451', '01/1979', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1683.jpg', 'Tommy Carat, vedette du show business, vient de disparaître tragiquement à la suite d''un accident de la route. L''affliction générale qui s''en suit enflamme les ventes de souvenirs au point de générer des bénéfices énormes. Patrick Lafond qui a vu et photographié l''accident contacte Ric Hochet pour lui faire part de son témoignage qui n''est pas du goût de certains individus ombrageux. Le témoin étant menacé, le journaliste en conclue que la mort de Carat a été programmée. Mais par qui ?');
INSERT INTO public.bd VALUES (4581, 'Ric Hochet', '30', 'Le fantôme de l''alchimiste', 'Duchâteau, André-Paul', '2205017144', '02/1980', 44, 'https://www.bedetheque.com/media/Couvertures/richochet30dargaud_1684.jpg', NULL);
INSERT INTO public.bd VALUES (4582, 'Ric Hochet', '31', 'K.O. en 9 rounds', 'Duchâteau, André-Paul', '2231340194', '08/1980', 78, 'https://www.bedetheque.com/media/Couvertures/RicHochet31weo_06022005.jpg', 'Comprend 9 histoires courtes:');
INSERT INTO public.bd VALUES (4583, 'Ric Hochet', '32', 'Tribunal noir', 'Duchâteau, André-Paul', '2720852376', '01/1981', 44, 'https://www.bedetheque.com/media/Couvertures/RicHochet32_1686.jpg', NULL);
INSERT INTO public.bd VALUES (4584, 'Ric Hochet', '33', 'Le scandale Ric Hochet', 'Duchâteau, André-Paul', '2803601028', '09/1981', 44, 'https://www.bedetheque.com/media/Couvertures/richochet33.jpg', NULL);
INSERT INTO public.bd VALUES (4585, 'Ric Hochet', '34', 'La nuit des vampires', 'Duchâteau, André-Paul', '2934663183', '01/1982', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1688.jpg', 'Voilà Ric Hochet, notre bon reporter français, qui doit se rendre en Angleterre sur la demande de Lord Chapman, petit-fils d’un romancier célèbre. Mais s’il a fait venir Ric Hochet, ce n’est pas par hasard, c’est pour élucider une histoire de vampire, une certaine malédiction qui doit se reproduire le lendemain soir… Entre les miroirs qui explosent, ceux qui ne renvoient pas de reflet de certaines personnes, les traces de morsures et cet individu, comédien, qui semble si à l’aise dans son rôle de Dracula… Pas facile de distinguer le vrai du faux…');
INSERT INTO public.bd VALUES (4586, 'Ric Hochet', '35', 'La mort noire', 'Duchâteau, André-Paul', '2803600374', '09/1982', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1689.jpg', 'Incroyable ! Une chambre d''hôtel et ses occupantes se sont mystérieusement volatilisées. Ric Hochet met tout en œuvre pour résoudre ce phénomène hallucinant. Mais autour de lui rode "La mort noire"...');
INSERT INTO public.bd VALUES (4587, 'Ric Hochet', '36', 'La flèche de sang', 'Duchâteau, André-Paul', '2803604027', '06/1983', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1690.jpg', NULL);
INSERT INTO public.bd VALUES (4592, 'Ric Hochet', '41', 'La maison de la vengeance', 'Duchâteau, André-Paul', '280360521X', '10/1985', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1695.jpg', 'Ric hochet, accompagné par le commissaire bourdon, a été invité par isabelle Sully afin de savoir si sa maison est réellement hantée. Ils arrivent un soir de tempête et des leur arrivé, les éléments étranges se multiplient … un volet qui s''arrache du mur, le feu qui sort de la cheminée et qui enflamme les vêtements d''isabelle Sully, des ombres sur le toit de la maison, des objets déplacés, … Albéric Lemoine, le régisseur du domaine, explique à ric que la maison est hantée par Frédéric Sully, l''homme qui fait construire et lancé une malédiction...');
INSERT INTO public.bd VALUES (4593, 'Ric Hochet', '42', 'La liste mortelle', 'Duchâteau, André-Paul', '2803605643', '06/1986', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1696.jpg', 'Alors qu''il sort des locaux de la Rafale, Ric est accosté par une jeune femme qui lui remet une valise. Intrigué par ce geste, il se débarrasse prestement de ce bagage qui explose. Peu de temps après, le reporter est victime d''un nouvel attentat à son appartement. Revendiquées par le Groupe Noir et son représentant Raphaël, ces agressions criminelles sont réitérées sur la personne d''Aubanet, célèbre éditorialiste. Serge Baguet, unique témoin de la scène, permet à la police de dresser un portrait-robot de Raphaël. Menaçant directement au sein de...');
INSERT INTO public.bd VALUES (4594, 'Ric Hochet', '43', 'Les messagers du trépas', 'Duchâteau, André-Paul', '280360616X', '05/1987', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1697.jpg', NULL);
INSERT INTO public.bd VALUES (4595, 'Ric Hochet', '44', 'Ric Hochet contre Sherlock', 'Duchâteau, André-Paul', '2803606356', '11/1987', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1698.jpg', 'Alors qu’il participe à une séance de spiritisme, Ric Hochet est soumis à l’énigme la plus complexe de sa carrière : un mystérieux Anglais vient en effet d’adresser un message selon lequel un crime impossible, donc parfait, sera commis à la prochaine réunion du club des spirites ! Ceux-ci lancent le reporter contre Sherlock Holmes en invoquant l’esprit du héros de Conan Doyle.');
INSERT INTO public.bd VALUES (4596, 'Ric Hochet', '45', 'Le triangle Attila', 'Duchâteau, André-Paul', '2803606976', '06/1988', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1699.jpg', NULL);
INSERT INTO public.bd VALUES (4597, 'Ric Hochet', '46', 'Les témoins de Satan', 'Duchâteau, André-Paul', '280360714X', '01/1989', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1700.jpg', 'Voilà notre célèbre journaliste au prise avec une bien étrange histoire à couvrir. En effet, un crime vient d’avoir lieu, mais tout semble trop parfaitement accabler une femme, qui se dit évidemment innocente. De plus, tous les témoignages se recoupent, accablant la jeune femme, qui évidemment, ne maque pas d’alibi pour le meurtre. Ric Hochet est partagé entre croire et ne pas croire, lorsque arrive celui qu’on surnomme L’avocat de Satan, le maître Ivan Brunet, qui ne recule devant rien pour gagner ses procès… L’enquête s’annonce pimentée, surtout...');
INSERT INTO public.bd VALUES (4598, 'Ric Hochet', '47', 'Les jumeaux diaboliques', 'Duchâteau, André-Paul', '2803607824', '09/1989', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1701.jpg', NULL);
INSERT INTO public.bd VALUES (4599, 'Ric Hochet', '48', 'Le secret d''Agatha', 'Duchâteau, André-Paul', '2803608103', '05/1990', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1702.jpg', NULL);
INSERT INTO public.bd VALUES (4600, 'Ric Hochet', '49', 'L''exécuteur des ténèbres', 'Duchâteau, André-Paul', '2803608553', '04/1991', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1703.jpg', 'Richard, le père de Ric Hochet, et quelques copains se sont regroupés en une amicale d''anciens malfrats repentis, mais un énigmatique "exécuteur des ténèbres" s''évertue à perturber leurs réunions, tout en n''étant aucunement invité...');
INSERT INTO public.bd VALUES (4601, 'Ric Hochet', '50', 'Le crime de l''an 2000', 'Duchâteau, André-Paul', '280360955X', '10/1991', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1704.jpg', NULL);
INSERT INTO public.bd VALUES (4602, 'Ric Hochet', '51', 'La bête de l''apocalypse', 'Duchâteau, André-Paul', '2803610027', '09/1992', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1705.jpg', 'Un "corbeau" tourmente les habitants d''une petite ville. Tous ses messages reproduisent "la bête de l''apocalypse" représentée sur la fameuse tapisserie d''Angers et un mystérieux "aveugle" agresse sauvagement les personnes concernées. Ric Hochet tente de déjouer cette machination diabolique.');
INSERT INTO public.bd VALUES (4603, 'Ric Hochet', '52', 'Le maître de l''illusion', 'Duchâteau, André-Paul', '2803610337', '05/1993', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1706.jpg', NULL);
INSERT INTO public.bd VALUES (4604, 'Ric Hochet', '53', 'Meurtre à l''impro', 'Duchâteau, André-Paul', '2803610744', '03/1994', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9819.jpg', 'Inventées au Québec, les ligues d''improvisation opposent en des joutes gestuelles et verbales, des équipes de comédiens sur des thèmes imposés. Ces jeux qui développent l''inventivité et l''esprit de répartie connaissent partout une grande popularité. Cette année, la ligue française fête ses dix ans d''existence et la Coupe du Monde se dispute dès lors à Paris. Pour célébrer à sa manière ce double événement, un psychopathe qui se fait appeler "L''Improvisateur", a kidnappé plusieurs des participants et il les contraints à exécuter des cascades périlleuses....');
INSERT INTO public.bd VALUES (4605, 'Ric Hochet', '54', 'Le masque de la terreur', 'Duchâteau, André-Paul', '2803611031', '11/1994', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_1708.jpg', NULL);
INSERT INTO public.bd VALUES (4606, 'Ric Hochet', '55', 'Qui a peur d''Hitchcock ?', 'Duchâteau, André-Paul', '2803611589', '10/1995', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9820.jpg', 'Selon un scénario ancien écrit à la va-vite par Alfred Hitchcock, un inconnu s''en prend à Roland Raynal, pilote d''avions et cinéaste amateur en lui adressant une cassette vidéo sur laquelle il se voit commettre un hold-up et exhiber un chèque d''une somme colossale. Ne souhaitant pas faire intervenir la police et assurant que ce n''est pas elle sur le film, la victime fait appel à Ric Hochet afin de trouver celui ou celle qui cherche à le compromettre. Le reporter accepte la mission et trouve un appui en la personne de Carson Brady, comédien américain...');
INSERT INTO public.bd VALUES (4607, 'Ric Hochet', '56', 'Un million sans impôts', 'Duchâteau, André-Paul', '2803612062', '05/1996', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9821.jpg', 'Les dispositions testamentaires du sénateur Van Burg ne satisfont pas les membres de sa famille. Pour "un million sans impôts" que ne ferait-on pas ? Ric Hochet plonge la main dans ce nœud de vipères...');
INSERT INTO public.bd VALUES (4608, 'Ric Hochet', '57', 'L''heure du kidnapping', 'Duchâteau, André-Paul', '2803612283', '10/1996', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9822.jpg', 'Au château des « Van Burg », rien ne va plus. À la suite de l’assassinat d’Anne-Elisabeth, le Commissaire Brébant et le reporter Ric Hochet poursuivent leurs investigations pour contrer le tueur présumé Daniel Maynard. Alors que ce dernier se donne la mort lors d’une course-poursuite, le jeune Jackie disparaît pendant une cérémonie familiale. Une lettre anonyme informe la famille Van Burg que l’adolescent a été enlevé par Maynard lui-même et sera restitué contre rançon. Intox ou réalité, Brébant et Ric Hochet orientent leur enquête dans le cercle...');
INSERT INTO public.bd VALUES (4672, 'Moky et Poupy', '27', 'Moky et Poupy et l''attaque des diligences', 'Bussemey, Roger', '293129800X', '01/1966', 20, 'https://www.bedetheque.com/media/Couvertures/Couv_149633.jpg', NULL);
INSERT INTO public.bd VALUES (4673, 'Moky et Poupy', '28', 'Quelle corrida..!', 'Bussemey, Roger', '2750366984', '01/1965', 19, 'https://www.bedetheque.com/media/Couvertures/Couv_54051.jpg', NULL);
INSERT INTO public.bd VALUES (4609, 'Ric Hochet', '58', 'Premières armes', 'Duchâteau, André-Paul', '2803612461', '05/1997', 57, 'https://www.bedetheque.com/media/Couvertures/Couv_5496.jpg', 'Cet comprend 12 histoires courtes: - Ric Hochet mène le jeu (5 planches) - Le mauvais oeil (5 planches) - Enquête chez les “Timbrés” (5 planches) - Ric Hochet contre “l’ombre” (5 planches) - L’énigme des photos express (5 planches) - La première enquête de Ric Hochet (1 planche) - L’affaire de la case mystérieuse (4 planches, collaboration de Didier Desmit au dessin) - Seul coupable (3 planches, scénario de Tibet, collaboration de Didier Desmit au dessin) - Il est minuit docteur Jekyll ! (6 planches) - Ici, le chauffard ! (8 planches) - Ecrit sur...');
INSERT INTO public.bd VALUES (4610, 'Ric Hochet', '59', 'La main de la mort', 'Duchâteau, André-Paul', '280361264X', '01/1998', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9823.jpg', 'Ric Hochet se bat, au péril de sa vie, pour retrouver son père... Frété par Richard, le père de Ric Hochet, le yacht «Cœur de Lion» est retrouvé abandonné en pleine mer... Nulle trace à bord des passagers ni de l''équipage! Cependant, un pavillon noir flotte à l''un des mâts et une main de squelette est dessinée sur la cabine de pilotage. Cette «Main de la Mort» est la signature de «Sinister», un criminel dont personne ne connaît le visage ! Richard et ses hôtes ont-ils été victimes d''une sorte de pirate des temps modernes ?...');
INSERT INTO public.bd VALUES (4611, 'Ric Hochet', '60', 'Crime sur internet', 'Duchâteau, André-Paul', '2803613484', '09/1998', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9824.jpg', 'Dans la rubrique nécrologique de la Rafale, un entrefilet publié par "Sinister" annonce de façon morbide le décès du journaliste Ric Hochet. Trois mois après sa disparition, Nadine et le Commissaire Bourdon restent inconsolables, surtout qu''Ursula Gabler et Clauwitz demeurent impunis. Mais la vie continue et une nouvelle affaire se présente. En effet, un commissaire-priseur proposant aux enchères le code secret permettant d''accéder à un site Internet sur lequel se trouve la représentation d''un tableau unique réalisé par Félix, peintre farfelu,...');
INSERT INTO public.bd VALUES (4612, 'Ric Hochet', '61', 'Le jeu de la potence', 'Duchâteau, André-Paul', '2803613999', '05/1999', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9825.jpg', 'Sous une Tour Eiffel brillant de tous ses feux, le magicien Cagliostro exécute son numéro d''illusionnisme avec la femme-obus. Alors que le coup de canon a retenti, son assistante et sa complice disparaissent mystérieusement. Un message représentant le jeu du pendu écrit par le dénommé Houbino présage un kidnapping en règle. Qui se cache derrière ces enlèvements crapuleux qui font suite à celui perpétré quelques jours plus tôt sur Monique Laniel et qui concerne de belles jeunes filles blondes ? Ric va devoir encore une fois faire don de sa personne...');
INSERT INTO public.bd VALUES (4613, 'Ric Hochet', '62', 'B.D. meurtres', 'Duchâteau, André-Paul', '2803614790', '01/2000', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9826.jpg', 'e monde éditorialiste de la BD est en émoi. Des attentats touchant des immeubles en rapport avec cette profession sont gravement endommagés au sein de la Capitale. Le "lieutenant" Ledru, fraîchement promu, soupçonne le journaliste véreux Lambert et son acolyte Groof d''être à l''origine de ces catastrophes au motif de se créer leurs propres scoops. En parallèle, le journaliste Ric Hochet oriente ses investigations sur les excentricités d''une association d''amateurs de BD dont l''un des membres est suspecté par un individu anonyme d''être à l''origine...');
INSERT INTO public.bd VALUES (4614, 'Ric Hochet', '63', 'La sorcière... ...mal aimée', 'Duchâteau, André-Paul', '2803615185', '10/2000', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9790.jpg', 'Lors de l''émission de télé "Erreur judicaire", la voyante Hélène Malcolm avertit Ric Hochet par caméra interposée qu''il a commis une erreur dans l''une de ses enquêtes passées. A ce titre, la cartomancienne l''invite dans son manoir des Ardennes belges pour participer au "Sabbat des Macrales" et lui faire part de son émoi concernant une vision sur la dernière affaire traitée par le reporter. Contre toute attente, le club des amateurs de BD est également de la partie tout comme le tueur Olinsky qui s''est évadé de prison. Il est à prévoir du rififi...');
INSERT INTO public.bd VALUES (4615, 'Ric Hochet', '64', 'Le contrat du siècle', 'Duchâteau, André-Paul', '2803616343', '06/2001', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_9791.jpg', 'Le conseil d''administration du journal "La Rafale" auquel participe Ric Hochet est en pleine effervescence. En effet, ce quotidien est menacé d''une O.P.A. lancée par le groupe croqueur de médias de la Barnex. Lors de cette réunion extraordinaire, surgit un homme cagoulé qui, ne pouvant mettre à exécution ses menaces, s''enfuit en prenant une femme en otage. Ces évènements n''ont pas échappé à un petit photographe qui se retrouve entraîné malgré lui dans l''aventure. Où se trouve l''otage emmené par le forcené ? Qu''est devenu le témoin photographe qui...');
INSERT INTO public.bd VALUES (4616, 'Ric Hochet', '65', 'Panique sur le web', 'Duchâteau, André-Paul', '2803617455', '02/2002', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_8507.jpg', 'Le journaliste Ric Hochet est persuadé que Barnex, le roi des médias, est à l''origine d''une série d''assassinats liée au lancement d''une O.P.A. musclée sur le journal "La Rafale". Celui-ci, qui réfute publiquement ces allégations, est de son côté, dénigré par son associé de l''ombre, le Bourreau (B.), criminel notoire. Compte tenu de ce premier échec, B. décide de passer à l''étape supérieure de son plan démoniaque en faisant pression sur un pirate informatique, Deus. Ce dernier doit injecter sur le Web un virus mortel qui pourrait menacer directement...');
INSERT INTO public.bd VALUES (4617, 'Ric Hochet', '66', 'Penthouse Story', 'Duchâteau, André-Paul', '2803617706', '10/2002', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_19704.jpg', 'Lors de l’émission télévisée "Penthouse Story", l’un des jeunes participants s’écroule raide mort devant les caméras. L’enquête policière qui en découle n’ayant rien donnée, l’affaire est rapidement classée. Quelques mois plus tard, la firme de production Allbright souhaite, par l’intermédiaire de son réalisateur Lamberto Alfredi renouveler l’opération. Hélas, Lulli-Lulla, la vedette du show précédent qui doit animer ce nouveau penthouse a disparu. Alfredi appelle à la rescousse Ric Hochet pour qu’il la retrouve. Cette disparition a-t-elle un lien...');
INSERT INTO public.bd VALUES (4618, 'Ric Hochet', '67', 'Le nombre maudit', 'Duchâteau, André-Paul', '2803618710', '05/2003', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_25787.jpg', 'À la suite de la divulgation d''un pastiche d''une bande dessinée propre à une aventure de Ric Hochet, un député est assassiné. Après ces évènements, Bertrand, l''ami libraire spécialisé dans le neuvième art, disparaît non sans avoir tenter d''assassiner le journaliste. Par ailleurs, un ancien détenu est abattu alors qu''il attentait à la vie de Nadine. Ces trois affaires ont, en fait, un lien commun, celui d''avoir été perpétrées par un justicier se surnommant 666. Ric, le Commissaire Bourdon et Ledru vont tenter d''identifier cet individu qui semble...');
INSERT INTO public.bd VALUES (4619, 'Ric Hochet', '68', 'Le collectionneur de crimes', 'Duchâteau, André-Paul', '2803619709', '01/2004', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_32198.jpg', 'Soupçonnées d''escroquerie, de corruption et d''usurpation, des personnalités en vue ont été assassinées. Ric Hochet continue de chercher à identifier le mystérieux justicier «666» qui revendique cette série de meurtres...');
INSERT INTO public.bd VALUES (4674, 'Moky et Poupy', '29', 'Moky et Poupy aux jeux olympiques', 'Bussemey, Roger', '2239445696', '01/1966', 20, 'https://www.bedetheque.com/media/Couvertures/Couv_156791.jpg', NULL);
INSERT INTO public.bd VALUES (4620, 'Ric Hochet', '69', 'L''homme de glace', 'Duchâteau, André-Paul', '2803619822', '09/2004', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_38940.jpg', 'Se prétendant le descendant du moine Raspoutine, l''âme damnée du dernier Tsar de Russie, un certain Zizanov règne en tyran sur un commando d''hommes nouveaux, des «hommes de glace» invincibles et supérieurs. Malheur à qui n''obéit pas à ses ordres ! Suite à une tentative de meurtre sur une ex-adepte en fuite, Ric Hochet et le commissaire Bourdon mènent leur enquête sur ce gourou accusé d''avoir utilisé des enfants pour des expériences de clonage...');
INSERT INTO public.bd VALUES (4621, 'Ric Hochet', '70', 'Silence de mort', 'Duchâteau, André-Paul', '2803620685', '05/2005', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_46485.jpg', 'Le commissaire Bourdon a reçu des DVD montrant plusieurs meurtres. Les images révèlent que le meurtrier utilise des cartouches d''un tout nouvel explosif silencieux. Aucun cadavre n''ayant été découvert et aucune disparition n''ayant été signalée, l''identité des victimes reste cependant un mystère? Ric Hochet enquête sur ce serial killer que les médias surnomment le «Dr. Euthanasy» du fait qu''il est déguisé en chirurgien et qu''il prétend «suicider» des jeunes femmes en détresse. La présence en Europe du cinéaste américain Alex Wooley va peut-être...');
INSERT INTO public.bd VALUES (4622, 'Ric Hochet', '71', 'La dernière impératrice', 'Duchâteau, André-Paul', '2803621584', '01/2006', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_53397.jpg', 'Héritier d''une illustre famille de constructeurs d''automobiles et d''un véritable empire industriel, Marco Agnellys a été enlevé alors qu''il testait un prototype avec sa fiancée. Surnommée «la dernière impératrice», sa mère charge Ric Hochet de négocier avec les ravisseurs... Selon elle, le journaliste de «La Rafale» est le seul capable de mener à bien les transactions. Associé malgré lui à son père Richard, Ric se rend au rendez-vous fixé par les ravisseurs. Retrouvé vivant, Marco n''est cependant plus l''homme résolu et chaleureux qu''il était avant...');
INSERT INTO public.bd VALUES (4623, 'Ric Hochet', '72', 'Le trésor des Marolles', 'Duchâteau, André-Paul', '2803621843', '09/2006', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_57965.jpg', 'Ric Hochet serait-il devenu fou ? Parti chiner sur la place du quartier des Marolles, à Bruxelles, il se retrouve embarqué dans une «flash mob», un rassemblement éclair mais massif organisé par internet. Cette fois, le but est d''investir le palais de justice en brandissant un pinceau imbibé de peinture rouge ! Mais si Ric s''y intéresse, c''est parce que les «amis de Pitje Snot», une société secrète consacrée à la résolution d''un vol de bijoux datant de 1893, y voient une occasion de faire avancer leur enquête séculaire . Le tragique rejoint l''incongru...');
INSERT INTO public.bd VALUES (4624, 'Ric Hochet', '73', 'On tue au théâtre ce soir', 'Duchâteau, André-Paul', '9782803622634', '05/2007', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_62773.jpg', 'Le talent de Ric Hochet connaît décidément peu de limites ! Habitué des planches de bande dessinée, il s''offre un petit détour par celles du théâtre pour interpréter son propre rôle - dans une pièce policière, évidemment. Mais son vieil ennemi, le Bourreau, a décidé de modifier quelque peu le script et le casting en invitant Angel, un tueur psychopathe, dans la troupe.');
INSERT INTO public.bd VALUES (4625, 'Ric Hochet', '74', 'Puzzle mortel', 'Duchâteau, André-Paul', '9782803623723', '01/2008', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_70497.jpg', 'Ric Hochet est aux abois ! Le Bourreau, son ennemi mortel, détient sa mère, Allégria, reporter au long cours disparue en Irak. Le temps semble compté et ni Richard, son père, ni le commissaire Bourdon ne semblent très coopératifs. Tout cela, sans mentionner la possible implication des frères Basberg, les mercenaires les plus redoutables (et les plus laids) qui soient... Une chose est certaine: les affaires de la famille Hochet n''ont rien d''une sinécure ! Tibet et Duchâteau signent ici le 2e acte de «On tue au Théâtre ce Soir» et la fin d''un diptyque...');
INSERT INTO public.bd VALUES (4626, 'Ric Hochet', '75', 'Code pour l''au-delà', 'Duchâteau, André-Paul', '9782803624423', '04/2008', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_77421.jpg', 'Ayant été menacé par un message établi selon un code mis au point par Houdini, le magicien Harry Dihouny fait appel à Ric Hochet pour assurer sa protection. Alors qu''il se rend à une conférence, l''illusionniste disparaît pour réapparaître amnésique. Ce dernier étant dans l''impossibilité de reproduire les numéros de son maître à penser et compte tenu de son désarroi, Ric Hochet dirige son enquête autour des proches de Dihouny. Qui cherche à soutirer les secrets ancestraux du magicien et pour quelles raisons fumeuses ? Entre faux semblants et mensonges,...');
INSERT INTO public.bd VALUES (4627, 'Ric Hochet', '76', 'Dernier duel', 'Duchâteau, André-Paul', '9782803625284', '05/2009', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_87457.jpg', 'Bob Drumont a disparu. L''ami de Ric Hochet avait décidé de collecter de l''argent pour des bonnes oeuvres en faisant chanter des célébrités dont les crimes étaient restés impunis...');
INSERT INTO public.bd VALUES (4628, 'Ric Hochet', '77', '"Ici 77 !"...', 'Duchâteau, André-Paul', '9782803626540', '03/2010 (Parution le 19/03/2010)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_106067.jpg', 'Il n''est pas toujours facile d''être un célèbre héros de bande dessinée. Ric Hochet va l''apprendre à ses dépens ! Pour fêter sa 77e enquête, voilà qu''un fou furieux s''est mis en tête de devenir le scénariste du «Démon de Minuit», un feuilleton policier déjà plombé par les ego de ses participants. Ric n''était pas très partant pour en être une des vedettes et voilà qu’une menace d''attentats aveugles l''oblige à rester, jusqu''à trouver le coupable. Car il n''y a que deux hommes qui peuvent prétendre écrire son destin: ils s''appellent Tibet et André-Paul...');
INSERT INTO public.bd VALUES (4629, 'Ric Hochet', '78', 'À la poursuite du Griffon d''or', 'Duchâteau, André-Paul', '9782803627219', '10/2010 (Parution le 29/10/2010)', 54, 'https://www.bedetheque.com/media/Couvertures/Couv_116228.jpg', 'LE DERNIER POLAR DU REGRETTÉ TIBET Les balades en forêt ne sont plus ce qu''elles étaient ! Cette fois, Ric et Nadine y ont trouvé un homme ligoté et ceinturé d''explosifs qu''une balle, signée Monsieur Bombe, a déclenchés sous leurs yeux. Mais qui pouvait donc en vouloir à ce point à Calewski, célèbre chasseur de trésors engagé dans le « jeu du griffon d''or », consistant à retrouver la précieuse statuette cachée par le Baron Barney ? Le gouvernement chinois, légitime propriétaire de l''artefact ? Un concurrent jaloux ? Pour le savoir, Ric n''a d''autre...');
INSERT INTO public.bd VALUES (4630, 'Ric Hochet', 'HS01', 'Premières enquêtes', 'Duchâteau, André-Paul', '2872650075', '01/1991', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_1709.jpg', NULL);
INSERT INTO public.bd VALUES (4631, 'Ric Hochet', 'HS03', 'Dossier Ric Hochet', 'Duchâteau, André-Paul', '2733177311', '01/1991', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_48766.jpg', NULL);
INSERT INTO public.bd VALUES (4632, 'Ric Hochet', 'HS05', 'Intrigue au "Ji Butch"', 'Duchâteau, André-Paul', '2777214263', '01/1998', 26, 'https://www.bedetheque.com/media/Couvertures/richocheths05intrigue_70892.jpg', 'Intrigue au « Ji Butch » est une enquête de Ric Hochet de 26 bandes publicitaires réalisées en 1968 pour le compte des magasins Ji Butch.');
INSERT INTO public.bd VALUES (4633, 'Ric Hochet', 'HS06', 'Monsieur X frappe à minuit', 'Duchâteau, André-Paul', '2960052129', '04/2006', 30, 'https://www.bedetheque.com/media/Couvertures/richochethsmonsieurxcouv_83290.jpg', NULL);
INSERT INTO public.bd VALUES (4675, 'Moky et Poupy', '30', 'Moky et Poupy à la recherche du père Lapioche', 'Bussemey, Roger', '2820264050', '01/1966', 20, 'https://www.bedetheque.com/media/Couvertures/Couv_119303.jpg', NULL);
INSERT INTO public.bd VALUES (4634, 'Ric Hochet', 'HS07', 'Reconnaissance de meurtres', 'Duchâteau, André-Paul', '9782803626526', '03/2010 (Parution le 19/03/2010)', 147, 'https://www.bedetheque.com/media/Couvertures/106702_c.jpg', 'Après 77 albums, Ric Hochet et ses lecteurs commencent un peu à se connaître. Dès lors, il est peut-être temps de briser un grand tabou du 9e Art en dévoilant les origines du célèbre héros ! Pour l''occasion, André-Paul Duchâteau bouscule encore un peu plus les règles du jeu en nous proposant un roman dont le narrateur est Ric lui-même. Nous y découvrirons la première enquête du journaliste, opposé à un mystérieux bandit dont les crimes ressemblent étrangement aux idées qu''un éditeur de polars dispense à ses jeunes auteurs. Une chose est sûre: il...');
INSERT INTO public.bd VALUES (4635, 'Ric Hochet', 'HS08', 'Enigmes', 'Duchâteau, André-Paul', '9782930571058', '05/2011 (Parution le 23/09/2011)', 32, 'https://www.bedetheque.com/media/Couvertures/Couv_143130.jpg', NULL);
INSERT INTO public.bd VALUES (4636, 'Ric Hochet', 'HS09', 'Enigmes 2', 'Duchâteau, André-Paul', '9782930571157', '04/2013 (Parution le 01/03/2012)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_193808.jpg', NULL);
INSERT INTO public.bd VALUES (4637, 'Ric Hochet', 'HS10', '30e anniversaire', '<Collectif>', '9782723247856', '12/2014', 47, 'https://www.bedetheque.com/media/Couvertures/Couv_233008.jpg', NULL);
INSERT INTO public.bd VALUES (4638, 'Ric Hochet', 'Int', 'Enquêtes surnaturelles', 'Duchâteau, André-Paul', '9782803628766', '04/2011 (Parution le 15/04/2011)', 144, 'https://www.bedetheque.com/media/Couvertures/125241_c.jpg', NULL);
INSERT INTO public.bd VALUES (4639, 'Ric Hochet', 'MBD01', 'Ric Hochet - Le Monde de la BD - 01', 'Duchâteau, André-Paul', '2736936035', '09/2003 (Parution le 28/10/2003)', 177, 'https://www.bedetheque.com/media/Couvertures/richochetmondedelabd_28102003.jpg', NULL);
INSERT INTO public.bd VALUES (4640, 'Ric Hochet', 'PAR', 'Main basse sur le plutonium', '<Indéterminé>', '2882595069', '01/1995', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_102159.jpg', NULL);
INSERT INTO public.bd VALUES (4641, 'Ric Hochet', 'Pir2', 'Enquête à Cora', '<Indéterminé>', '2872324631', '09/1995 (Parution le 01/09/1995)', 52, 'https://www.bedetheque.com/media/Couvertures/Couv_430600.jpg', 'Fac similé d''histoires parues dans le journal Tintin. 2 enquêtes de Ric Hochet et 3 "Pêchés de Jeunesse" de Tibet.');
INSERT INTO public.bd VALUES (4642, 'Ric Hochet', 'Pir3', 'La soirée de meurtre', '<Indéterminé>', '2884705341', '09/1995 (Parution le 01/09/1995)', 63, 'https://www.bedetheque.com/media/Couvertures/Couv_430601.jpg', 'Enquête en deux parties. Texte uniquement, quelques illustrations.');
