INSERT INTO public.bd VALUES (4763, 'Sylvain et Sylvette', '28', 'Premier de cordée', 'Pesch, Jean-Louis', '2215004975', '05/1972', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_515416.jpg', 'Contient les épisodes "Premier de cordée" et "Compère ours est mal en point" déjà parus dans la collection Albums Fleurette Nouvelle Série sous les numéros 49 et 50 (épisodes de 20 planches chacun) + 4 pages de jeux');
INSERT INTO public.bd VALUES (4764, 'Sylvain et Sylvette', '29', 'Un nouveau petit chaperon rouge', 'Pesch, Jean-Louis', '2215005351', '05/1983', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_38507.jpg', NULL);
INSERT INTO public.bd VALUES (4765, 'Sylvain et Sylvette', '30', 'Renard fait bande à part', 'Pesch, Jean-Louis', '221500536X', '10/1973', 48, 'https://www.bedetheque.com/media/Couvertures/sylser30_09052003.jpg', NULL);
INSERT INTO public.bd VALUES (4766, 'Sylvain et Sylvette', '31', 'Pauvre compère Renard', 'Pesch, Jean-Louis', '2215006129', '01/1983', 40, 'https://www.bedetheque.com/media/Couvertures/Couv_62998.jpg', NULL);
INSERT INTO public.bd VALUES (4767, 'Sylvain et Sylvette', '32', 'La nouvelle Sidonie', 'Pesch, Jean-Louis', '2215007826', '02/1986', 44, 'https://www.bedetheque.com/media/Couvertures/SylvainEtSylvette32_04102007_202220.jpg', 'Sylvette est tombée malade. Sylvain est donc parti pour la ville à la recherche de médicaments, la laissant seule, alitée, avec les petits animaux de leur ferme. Tout cela n’a pas échappé à Renard qui a tout de suite trouvé un plan qu’il a mis à exécution avec les trois autres compères. Avec un certain succès... vu que ce n’est qu’au tout dernier moment que Sylvain, de retour, a trouvé ses ennemis de toujours à l’intérieur de sa maison, aux prises avec la pauvre Sylvette ! En plus des médicaments, Sylvain a rapporté une oie. Nouvelle et pas habituée...');
INSERT INTO public.bd VALUES (4768, 'Sylvain et Sylvette', '33', 'Sylvain et Sylvette et le dragon volant', 'Pesch, Jean-Louis', '2803607956', '06/1996', 46, 'https://www.bedetheque.com/media/Couvertures/sylvainetsylvettecou33lo.JPG', NULL);
