INSERT INTO public.bd VALUES (4771, 'Sylvain et Sylvette', '36', 'La mystèrieuse invention', 'Pesch, Jean-Louis', '2803610353', '06/1996', 46, 'https://www.bedetheque.com/media/Couvertures/sylvainetsylvettecou36lo.JPG', 'Monsieur Tartalo rend visite à Sylvain et Sylvette. Il recherche un endroit tranquille pour finaliser son invention dont il ne souhaite rien dire tant qu’elle n''est pas terminée. Sylvain lui propose de s’installer au Moulin-Noir, ce qui attire la suspicion des 4 compères qui se demandent quel est donc ce mystérieux projet. Pour le découvrir, ils vont lui jouer quelques mauvais tours mais une menace plus grande encore rode dans les parages…');
INSERT INTO public.bd VALUES (4772, 'Sylvain et Sylvette', '37', 'La grotte de Patatrac', 'Pesch, Jean-Louis', '2803610965', '01/1994', 46, 'https://www.bedetheque.com/media/Couvertures/sylvainetsylvettecou37lo.JPG', NULL);
