INSERT INTO public.bd VALUES (4843, 'Trolls de Troy', 'INT004', 'Intégrale 4 albums sous coffret', 'Arleston, Scotch', '9782302022379', '12/2018 (Parution le 28/11/2012)', 164, 'https://www.bedetheque.com/media/Couvertures/Couv_356258.jpg', NULL);
INSERT INTO public.bd VALUES (4844, 'Trolls de Troy', 'INT005', 'Intégrale 4 albums sous coffret', 'Arleston, Scotch', '9782302066250', '12/2018 (Parution le 12/12/2018)', 182, 'https://www.bedetheque.com/media/Couvertures/Couv_356257.jpg', NULL);
INSERT INTO public.bd VALUES (4845, 'Trolls de Troy', 'INT01', 'Intégrale monovolume sous coffret 01', 'Arleston, Scotch', '2845653204', '06/2002', 200, 'https://www.bedetheque.com/media/Couvertures/Couv_17417.jpg', NULL);
INSERT INTO public.bd VALUES (4846, 'Trolls de Troy', 'INT02', 'Intégrale monovolume sous coffret 02', 'Arleston, Scotch', '9782302002258', '06/2008', 200, 'https://www.bedetheque.com/media/Couvertures/Couv_84380.jpg', NULL);
INSERT INTO public.bd VALUES (4847, 'Trolls de Troy', 'INT03', 'Intégrale monovolume sous coffret 03', 'Arleston, Scotch', '9782302008281', '10/2009', 200, 'https://www.bedetheque.com/media/Couvertures/Couv_98553.jpg', NULL);
INSERT INTO public.bd VALUES (4848, 'Trolls de Troy', 'INT04', 'Intégrale monovolume sous coffret 04', 'Arleston, Scotch', '9782302027169', '11/2012 (Parution le 07/11/2012)', 200, 'https://www.bedetheque.com/media/Couvertures/Couv_176231.jpg', NULL);
INSERT INTO public.bd VALUES (4849, 'Trolls de Troy', 'INT05', 'Intégrale monovolume sous coffret 05', 'Arleston, Scotch', '9782302072626', '11/2018 (Parution le 14/11/2018)', 200, 'https://www.bedetheque.com/media/Couvertures/Couv_353235.jpg', NULL);
INSERT INTO public.bd VALUES (4850, 'Trolls de Troy', 'INT1', 'Intégrale - Tomes 1 à 4', 'Arleston, Scotch', '9782302025226', '06/2002 (Parution le 13/11/2013)', 200, 'https://www.bedetheque.com/media/Couvertures/Couv_231343.jpg', NULL);
INSERT INTO public.bd VALUES (4851, 'Trolls de Troy', 'INT2', 'Intégrale - Tomes 5 à 7', 'Arleston, Scotch', '9782302041059', '11/2014 (Parution le 05/11/2014)', 151, 'https://www.bedetheque.com/media/Couvertures/Couv_280656.jpg', 'Contient : "T.5 - Les Maléfices de la Thaumaturge", "T.6 - Trolls dans la brume" et "T.7 - Plume de Sage".');
INSERT INTO public.bd VALUES (4852, 'Trolls de Troy', 'INT2GF', 'Intégrale T. 5 à 8', 'Arleston, Scotch', '9782302105720', '11/2025 (Parution le 12/11/2025)', 189, 'https://www.bedetheque.com/media/Couvertures/Couv_531763.jpg', NULL);
INSERT INTO public.bd VALUES (4853, 'Trolls de Troy', 'INT3', 'Intégrale - Tomes 8 à 10', 'Arleston, Scotch', '9782302045392', '11/2015 (Parution le 04/11/2015)', 164, 'https://www.bedetheque.com/media/Couvertures/Couv_261747.jpg', 'Troy est un monde fascinant, où la magie intervient dans le quotidien de tous, où chacun possède un pouvoir. On retrouve sur Troy toutes sortes de créatures, mais les plus redoutables pour l''être humain sont les trolls. Pourtant, ces terribles prédateurs sont plutôt sympathiques ! Deux siècles avant l''histoire de Lanfeust, les aventures pleine d''humour d''un troll sauvage et d''une jeune fille.');
INSERT INTO public.bd VALUES (4854, 'Trolls de Troy', 'INT3GF', 'Intégrale T. 9 à 11', 'Arleston, Scotch', '9782302108080', '10/2025 (Parution le 05/02/2026)', 154, 'https://www.bedetheque.com/media/Couvertures/Couv_535599.jpg', NULL);
INSERT INTO public.bd VALUES (4855, 'Trolls de Troy', 'INT4', 'Intégrale - Tomes 11 à 13', 'Arleston, Scotch', '9782302052284', '11/2016 (Parution le 30/11/2016)', 144, 'https://www.bedetheque.com/media/Couvertures/Couv_294755.jpg', NULL);
INSERT INTO public.bd VALUES (4856, 'Trolls de Troy', 'INT5', 'Intégrale - Tomes 14 à 16', 'Arleston, Scotch', '9782302064447', '08/2017 (Parution le 23/08/2017)', 140, 'https://www.bedetheque.com/media/Couvertures/Couv_310099.jpg', 'Le célèbre conservatoire d''Eckmül abrite un département spécialement consacré à l''étude des trolls du monde de Troy. Rysta Fuquatou le vénérable se plonge dans les archives des récits, légendes et anecdotes rassemblés par les différentes équipes de chercheurs au fil des années. Peut-être trouvera-t-il un indice sur cette humaine vivant parmi les trolls ?');
INSERT INTO public.bd VALUES (4857, 'Trolls de Troy', 'INT6', 'Intégrale - Tomes 17 à 19', 'Arleston, Scotch', '9782302066410', '02/2018 (Parution le 21/02/2018)', 140, 'https://www.bedetheque.com/media/Couvertures/Couv_324356.jpg', NULL);
INSERT INTO public.bd VALUES (4858, 'Trolls de Troy', 'INT7', 'Intégrale - Tomes 20 à 22', 'Arleston, Scotch', '9782302078956', '11/2019 (Parution le 20/11/2019)', 140, 'https://www.bedetheque.com/media/Couvertures/Couv_378829.jpg', 'On trouve sur Troy toutes sortes de créatures, mais les plus redoutables pour les humains sont sans nul doute les Trolls…');
INSERT INTO public.bd VALUES (4859, 'Trolls de Troy', 'INT8', 'Intégrale - Tomes 23 à 25', 'Arleston, Scotch', '9782302096370', '11/2022 (Parution le 23/11/2022)', 140, 'https://www.bedetheque.com/media/Couvertures/Couv_460491.jpg', 'Au fil de ces trois épisodes, de très célèbres peintres seront tournés en dérision, on sollicitera un dragon cracheur de glace pour neutraliser une dangereuse météorite incandescente qui pétrifie les habitants du village troll, et un philtre magique rendra le vénérable Rysta Fuquatou amoureux fou de Puitepée, la maman adoptive de notre héroïne Waha.');
INSERT INTO public.bd VALUES (4860, 'Trolls de Troy', 'INTFL1', 'Histoires trolles / Le scalp du vénérable', 'Arleston, Scotch', '2744191167', '05/2006', 96, 'https://www.bedetheque.com/media/Couvertures/TrollsDeTroy01FL.jpg', NULL);
INSERT INTO public.bd VALUES (4861, 'Trolls de Troy', 'INTFL2', 'Comme un vol de pétaures / Le Feu occulte', 'Arleston, Scotch', '2744196509', '11/2006', 96, 'https://www.bedetheque.com/media/Couvertures/TrollsDeTroy_27052007.jpg', NULL);
INSERT INTO public.bd VALUES (4862, 'Petit Spirou (Le)', '1', 'Dis bonjour à la dame !', 'Tome', '2800117273', '03/1990', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_2830.jpg', NULL);
INSERT INTO public.bd VALUES (4863, 'Petit Spirou (Le)', '2', 'Tu veux mon doigt ?', 'Tome', '2800118377', '07/1991', 44, 'https://www.bedetheque.com/media/Couvertures/PetitSpirou02couv.JPG', NULL);
INSERT INTO public.bd VALUES (4864, 'Petit Spirou (Le)', '3', 'Mais ! Qu''est-ce que tu fabriques ?', 'Tome', '2800119268', '06/1992', 44, 'https://www.bedetheque.com/media/Couvertures/PetitSpirou03couv.JPG', 'Chaque année, il y a des évènements incontournables. Noël, les bêtisiers à la télé, l''achat de nouvelles fringues, Vincent Perrot, et surtout, un nouvel opus des aventure du Petit Spirou ! Revoilà donc notre petit garnement préféré dans un décor de vacances mais qui n''a heureusement pas laissé ses mauvais tours et ses histoires à mourir de rire à la maison !');
INSERT INTO public.bd VALUES (4970, 'Calvin et Hobbes', '3', 'On est fait comme des rats !', 'Watterson, Bill', '2258034868', '03/1992', 61, 'https://www.bedetheque.com/media/Couvertures/CalvinEtHobbes3_12112004.jpg', NULL);
INSERT INTO public.bd VALUES (4971, 'Calvin et Hobbes', '4', 'Debout, tas de nouilles !', 'Watterson, Bill', '2258034876', '08/1992', 61, 'https://www.bedetheque.com/media/Couvertures/CalvinEtHobbes4_12112004.jpg', NULL);
INSERT INTO public.bd VALUES (4865, 'Petit Spirou (Le)', '4', 'C''est pour ton bien !', 'Tome', '280012007X', '01/1994', 44, 'https://www.bedetheque.com/media/Couvertures/PetitSpirou04couv.JPG', 'Horreur ! L''heure des vacances chez Tante Phlébite a sonné pour notre garnement en culotte courte ! Un séjour qui lui réserve bien des surprises... Pour le reste,les gags du petit Spirou pleuvent en cascade dans ce nouvel opus de la série. Ponchelo, Vertignasse, Le petit Spirou et ses autres camarades repassent encore une fois à l''attaque pour le plus grand bonheur des lecteurs et le plus grand malheur des grandes personnes.');
INSERT INTO public.bd VALUES (4866, 'Petit Spirou (Le)', '5', '"Merci" qui ?', 'Tome', '2800121203', '07/1994', 44, 'https://www.bedetheque.com/media/Couvertures/PetitSpirou05couv.JPG', 'Tout, tout, tout, vous saurez tout selon Le petit Spirou sur le pourquoi du tyranisme du prof de sport : Mr Mégot, en première partie d''album ! Mais aussi comment entrer dans une société secrète, comment s''amuser sur la plage à peu de frais mais aussi sur le pouvoir terrifiant des armes à feu et bien d''autres gags qui nourrissent ce 5ème album du petit Spirou !');
INSERT INTO public.bd VALUES (4867, 'Petit Spirou (Le)', '6', 'N''oublie pas ta capuche !', 'Tome', '2800122110', '07/1996', 44, 'https://www.bedetheque.com/media/Couvertures/PetitSpirou06couv.JPG', NULL);
INSERT INTO public.bd VALUES (4868, 'Petit Spirou (Le)', '7', 'Demande à ton père !', 'Tome', '280012461X', '11/1997', 44, 'https://www.bedetheque.com/media/Couvertures/PetitSpirou07couv.JPG', 'Le moyen métrage de début est consacré à la difficulté de se débarrasser de ses vieux jouets... Car le petit Spirou collectionne des centaines de jouets en peluche, et sa maman souhaiterait qu''il se sépare d''au moins la moitié d''entre eux. Mais comment choisir ceux dont on va se séparer ??? Ensuite la succession de strips prolonge l''album avec l''apparition de Madame Gourmandine, amie secrète du Pépé du petit Spirou...');
INSERT INTO public.bd VALUES (4869, 'Petit Spirou (Le)', '8', 'T''as qu''à t''retenir !', 'Tome', '2800127678', '05/1999', 44, 'https://www.bedetheque.com/media/Couvertures/PetitSpirou08couv.JPG', 'En premier lieu, comme dans d''autres tomes de la série, le petit Spirou nous conte une "grande aventure". Il s''agit d''une histoire que son Grand papy lui raconte à propos des premiers mots écrits par les ancêtres de la famille Spirou. Se succèdent ensuite une série de Gags axés sur les peurs des enfants et sur leurs épopées !');
INSERT INTO public.bd VALUES (4870, 'Petit Spirou (Le)', '9', 'C''est pas de ton âge !', 'Tome', '2800129611', '06/2000', 44, 'https://www.bedetheque.com/media/Couvertures/PetitSpirou09couv.JPG', 'C''est pas de ton âge ! Tu veux mon doigt ? Demande à ton père... Combien de fois avons-nous entendu ces répliques d''adultes lorsque nous étions nous même enfants ? Un nombre incalculable de fois... Et bien Le petit Spirou les illustre à merveille ! Il nous revient en pleine forme accompagné de ses copains de toujours, des grandes personnes qui l''entourent, et vous mettra sans dessus dessous avec de nouvelles histoires plus palpitantes les unes des autres. Vous retrouverez notamment notre héros dans une aventure palpitante face au "Monsieur qui...');
INSERT INTO public.bd VALUES (4871, 'Petit Spirou (Le)', '10', 'Tu comprendras quand tu s''ras grand!', 'Tome', '2800131136', '11/2001', 44, 'https://www.bedetheque.com/media/Couvertures/petitspirou10.jpg', 'Retrouvez les aventures d''une bande de copains avec, en tête de file, un gamin mieux connu sous ses traits adultes : Le Petit Spirou Il vous entraînera dans de folles aventures et vous pourrez résoudre notamment grâce à ce sympathique personnage, le fabuleux mystère des toilettes séparées !! Vous pourrez également en apprendre plus sur les tendances vestimentaires du moment ou encore pourquoi il ne faut pas jouer avec une lampe de poche...');
INSERT INTO public.bd VALUES (4872, 'Petit Spirou (Le)', '11', 'Tu ne s''ras jamais grand !', 'Tome', '2800132922', '06/2003', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_22175.jpg', 'Le petit Spirou continue de fantasmer sur la magnifique mademoiselle Chiffre, d''écouter bouche bée les histoires de son pépé, et avec ses amis de faire mille et un tour pour pouvoir assister aux derniers essayages de soutien gorge. Mais bon Dieu ce gamin ne grandira t-il jamais ?');
INSERT INTO public.bd VALUES (4873, 'Petit Spirou (Le)', '12', 'C''est du joli !', 'Tome', '2800133627', '11/2005', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_51736.jpg', 'Le petit Spirou c''est le grand Spirou tel qu''il était quand il était petit et ce avant d''être grand... Le petit Spirou ne cesse d''espionner mademoiselle Chiffre. Mais il a fort à faire avec sa grand-mère. En plus, le professeur de sport s''en donne à cœur joie pour l''embêter. Voila une tranche de vie d''un petit écolier qui n''est pas encore grand.');
INSERT INTO public.bd VALUES (4874, 'Petit Spirou (Le)', '13', 'Fais de beaux rêves !', 'Tome', '9782800138596', '09/2007', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_66663.jpg', 'Spirou, avant d''être le héros que l''on connait, était petit et portait un ridicule costume rouge avec un chapeau tout aussi ridicule. Mais quand on est petit, on n''a pas le temps de s''ennuyer. Déjà pendant la journée, il doit déjouer la vigilance de l''abbé Langeluss, ne pas mourir de rire avec son professeur de sport à l''alcoolémie matinale et surtout veiller sur sa grand-mère à la mémoire sélective. Mais c''est surtout la nuit que les dangers sont les plus présents. Ainsi, nul doute que le petit Spirou deviendra un jour l''aventurier que l''on connait.');
INSERT INTO public.bd VALUES (4875, 'Petit Spirou (Le)', '14', 'Bien fait pour toi !', 'Tome', '9782800143248', '01/2009', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_83083.jpg', NULL);
INSERT INTO public.bd VALUES (4876, 'Petit Spirou (Le)', '15', 'Tiens-toi droit !', 'Tome', '9782800147079', '11/2010 (Parution le 05/11/2010)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_117534.jpg', 'Avant de grandir pour devenir l''aventurier que l''on connaît, Spirou a été petit. Et c''était pas triste. Toujours à l''affût d''une blague à faire au curé, l''abbé Langélusse, ou à son professeur de gymnastique, le navrant M. Mégot, le petit Spirou ne cesse ses espiègleries que pour s''intéresser aux douches des filles, à sa copine Suzette ou à sa prof de maths, la captivante Claudia Chiffre...');
INSERT INTO public.bd VALUES (4877, 'Petit Spirou (Le)', '16', 'T''es gonflé !', 'Tome', '9782800151595', '11/2012 (Parution le 02/11/2012)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_174121.jpg', 'Les adultes sont décidément fous à lier, non pas que ce soit une nouveauté, mais il faut reconnaître qu''entre Grand-Papy qui joue à saute-mouton avec Gourmandine en pleine nuit, Grand-Mamy qui fait la gâteuse dans le bus, Langélusse qui joue aux indiens et M. Mégot au séducteur, il y a de quoi avoir le tournis. Heureusement, le Petit Spirou est là pour insuffler un peu de sagesse à tous ces zozos et rappeler quelques vérités simples : avant de devenir curé, Langélusse était un vrai dur, un cow-boy comme on n''en fait plus, M. Mégot a définitivement...');
INSERT INTO public.bd VALUES (4878, 'Petit Spirou (Le)', '17', 'Tout le monde te regarde !', 'Tome', '9782800157702', '11/2015 (Parution le 13/11/2015)', 42, 'https://www.bedetheque.com/media/Couvertures/Couv_257891.jpg', 'Vingt-cinq ans, c’est un cap important dans la vie d’un petit garçon !');
INSERT INTO public.bd VALUES (4879, 'Petit Spirou (Le)', '18', 'La Vérité sur tout !', 'Tome', '9791034731251', '11/2019 (Parution le 15/11/2019)', 43, 'https://www.bedetheque.com/media/Couvertures/Couv_378226.jpg', NULL);
INSERT INTO public.bd VALUES (4972, 'Calvin et Hobbes', '5', 'Fini de rire !', 'Watterson, Bill', '2258036410', '03/1993', 61, 'https://www.bedetheque.com/media/Couvertures/Couv_40209.jpg', NULL);
INSERT INTO public.bd VALUES (4973, 'Calvin et Hobbes', '6', 'Allez, on se tire !', 'Watterson, Bill', '2258038391', '07/1993', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_2369.jpg', NULL);
INSERT INTO public.bd VALUES (4974, 'Calvin et Hobbes', '7', 'Que fait la police ?', 'Watterson, Bill', '2258036429', '01/1994', 61, 'https://www.bedetheque.com/media/Couvertures/Couv_2370.jpg', NULL);
INSERT INTO public.bd VALUES (4880, 'Petit Spirou (Le)', '19', 'On parle pas la bouche pleine !', 'Janry', '9791034749140', '10/2022 (Parution le 14/10/2022)', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_457044.jpg', 'Le Petit Spirou, c''est avant tout une galerie de personnages incroyables : de la grand-mamy en mal d''affection et souffrant d''Alzheimer jusqu''à M. Mégot, le professeur de gym adepte du moindre effort et des fake news, en passant par Suzette, petite amie officielle du petit Spirou, qui a décidé de devenir végane et star des réseaux sociaux en même temps. Mais c''est aussi une série qui a toujours alterné le « pur gag », très écrit ou muet, avec l''émotion à travers des histoires courtes pleines de sensibilité. Ce tome 19 ne fait pas exception à la...');
INSERT INTO public.bd VALUES (4881, 'Petit Spirou (Le)', '20', 'Y a pas de "mais" !', 'Janry', '9782808503679', '11/2024 (Parution le 08/11/2024)', 43, 'https://www.bedetheque.com/media/Couvertures/Couv_507122.jpg', 'Le Petit Spirou, c''est avant tout une galerie de personnages incroyables : de la grand-mamy en mal d''affection et souffrant d''Alzheimer au point de ne plus se souvenir de son propre petit-fils jusqu''à M. Mégot, le professeur de gym adepte du moindre effort et fan de fake news, en passant par Suzette, petite amie officielle du Petit Spirou, qui a décidé de devenir végane et star des réseaux sociaux en même temps : tous les personnages de la série sont inoubliables ! La série a toujours alterné le « pur gag », très écrit ou muet, avec l''émotion à...');
INSERT INTO public.bd VALUES (4882, 'Petit Spirou (Le)', 'BOBD', 'Le best of de la BD - 1', 'Tome', '2255027054', '06/2005', 96, 'https://www.bedetheque.com/media/Couvertures/BestOfDeLaBdDeLaDhLe1_28062005.jpg', NULL);
INSERT INTO public.bd VALUES (4883, 'Petit Spirou (Le)', 'HS2008', 'Mes pires gags La compil'' qui déchire', 'Tome', '9782723986236', '07/2008', 29, 'https://www.bedetheque.com/media/Couvertures/Couv_167177.jpg', NULL);
INSERT INTO public.bd VALUES (4884, 'Petit Spirou (Le)', 'HS2015', 'Sans interdits depuis toujours', 'Tome', '9782800165813', '10/2015 (Parution le 16/10/2015)', 80, 'https://www.bedetheque.com/media/Couvertures/Couv_257599.jpg', 'En vingt-cinq ans, le Petit Spirou n''a pas vieilli. Il n''a perdu ni son sourire ni son innocence, et il reste aujourd''hui encore un modèle d''anticonformisme et d''humour borderline.');
INSERT INTO public.bd VALUES (4885, 'Petit Spirou (Le)', 'HS2017', 'La bd du film', 'Tome', '9782800168449', '09/2017 (Parution le 08/09/2017)', 64, 'https://www.bedetheque.com/media/Couvertures/Couv_310642.jpg', NULL);
INSERT INTO public.bd VALUES (4886, 'Petit Spirou (Le)', 'HS2023', 'Tu racontes n''importe quoi !', 'Janry', '9782808504256', '10/2023 (Parution le 27/10/2023)', 64, 'https://www.bedetheque.com/media/Couvertures/Couv_485735.jpg', 'Cet album de 64 pages reprend neuf histoires courtes du Petit Spirou qui permettent de redécouvrir toute l''émotion et l''intelligence de cette série mythique du catalogue Dupuis.');
INSERT INTO public.bd VALUES (4887, 'Petit Spirou (Le)', 'HS2025', 'Dans tes rêves !', 'Janry', '9782808510257', '11/2025 (Parution le 17/10/2025)', 64, 'https://www.bedetheque.com/media/Couvertures/Couv_530937.jpg', NULL);
INSERT INTO public.bd VALUES (4888, 'Petit Spirou (Le)', 'INT1', 'Un point c''est tout !', 'Tome', '2873930217', '01/2001 (Parution le 13/11/2003)', 64, 'https://www.bedetheque.com/media/Couvertures/Couv_30681.jpg', NULL);
INSERT INTO public.bd VALUES (4889, 'Petit Spirou (Le)', 'INT2', 'On aura tout vu !', 'Tome', '2873930241', '08/2001 (Parution le 13/11/2003)', 64, 'https://www.bedetheque.com/media/Couvertures/Couv_30682.jpg', NULL);
