INSERT INTO public.bd VALUES (4898, 'Spirou et Fantasio', '1', '4 aventures de Spirou ...et Fantasio', 'Franquin, André', '2210123348', '01/1950', 65, 'https://www.bedetheque.com/media/Couvertures/spirouetfantasio01_18732.jpg', 'Spirou et Fantasio se retrouvent tour à tour sur un ring de boxe, sur le dos d''un cheval, à faire la chasse au robot et de la médiation de conflit entre deux tribus hostiles. (Source Dupuis)');
