INSERT INTO public.bd VALUES (4909, 'Spirou et Fantasio', '12', 'Le nid des Marsupilamis', 'Franquin, André', '2959686454', '01/1960', 61, 'https://www.bedetheque.com/media/Couvertures/Couv_32824.jpg', 'Contient "Le nid des marsupilamis" (40 pl.), paru dans Spirou n° #969 (8 novembre 1956) à #991 (11 avril 1957) – "La Foire aux gangsters" (21 pl.), paru dans Spirou n° 1034 (6 février 1958) à #1045 (24 avril 1958).');
INSERT INTO public.bd VALUES (4910, 'Spirou et Fantasio', '13', 'Le voyageur du mésozoïque', 'Greg (1)', '2872771786', '01/1960', 61, 'https://www.bedetheque.com/media/Couvertures/Couv_32854.jpg', 'Plus l''histoire ''''La peur au bout du fil'''' (14 planches)');
INSERT INTO public.bd VALUES (4911, 'Spirou et Fantasio', '14', 'Le prisonnier du Bouddha', 'Greg (1)', '2777941300', '01/1960', 61, 'https://www.bedetheque.com/media/Couvertures/spirouetfantasio14eo.jpg', 'Spirou et Fantasio ont décidé, accompagnés du Marsupilami et de Spip, d''aller rendre visite au comte de Champignac, à l''occasion de la foire aux bestiaux. Mais là, surprise ! La vieille porte vermoulue du château a laissé place à une porte blindée. Un peu déroutés, ils parviennent tout de même, grâce au Marsupilami, à s''introduire chez le comte. L''ambiance est lourde durant la soirée. Champignac est différent, et Fantasio flaire un mystère ! Il ne va pas tarder à en découvrir la nature. Elle se présente suite à une rencontre brutale, sous la forme...');
INSERT INTO public.bd VALUES (4912, 'Spirou et Fantasio', '15', 'Z comme Zorglub', 'Greg (1)', '2910189457', '01/1961', 61, 'https://www.bedetheque.com/media/Couvertures/Spirou&Fantasio15ZcommeZorglubC_15102003.jpg', NULL);
INSERT INTO public.bd VALUES (4913, 'Spirou et Fantasio', '16', 'L''ombre du Z', 'Greg (1)', '2827170817', '01/1962', 61, 'https://www.bedetheque.com/media/Couvertures/spiroucouv16.jpg', NULL);
INSERT INTO public.bd VALUES (4914, 'Spirou et Fantasio', '17', 'Spirou et les hommes-bulles', 'Roba, Jean', '2248414285', '01/1964', 61, 'https://www.bedetheque.com/media/Couvertures/Couv_18743.jpg', NULL);
INSERT INTO public.bd VALUES (4915, 'Spirou et Fantasio', '18', 'QRN sur Bretzelburg', 'Greg (1)', '2893048412', '01/1966', 61, 'https://www.bedetheque.com/media/Couvertures/Couv_18744.jpg', 'Suite à une gaffe du Marsupilami, Spirou et Fantasio sont impliqués dans un conflit entre le roi du Bretzelburg et la présidente du Maquebasta.');
INSERT INTO public.bd VALUES (4916, 'Spirou et Fantasio', '19', 'Panade à Champignac', 'Franquin, André', '2993878743', '01/1969', 60, 'https://www.bedetheque.com/media/Couvertures/SpirouEtFantasio19.jpg', NULL);
