INSERT INTO public.bd VALUES (4924, 'Spirou et Fantasio', '27', 'L''Ankou', 'Fournier, Jean-Claude', '2800105534', '07/1977', 44, 'https://www.bedetheque.com/media/Couvertures/Spiroufantasio27.jpg', NULL);
INSERT INTO public.bd VALUES (4925, 'Spirou et Fantasio', '28', 'Kodo le tyran', 'Fournier, Jean-Claude', '2800106441', '04/1979', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2782.jpg', NULL);
INSERT INTO public.bd VALUES (4926, 'Spirou et Fantasio', '29', 'Des haricots partout', 'Fournier, Jean-Claude', '2800107006', '07/1980', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2783.jpg', NULL);
INSERT INTO public.bd VALUES (4927, 'Spirou et Fantasio', '30', 'La ceinture du grand froid', 'Cauvin, Raoul', '2800109777', '04/1983', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2784.jpg', NULL);
INSERT INTO public.bd VALUES (4928, 'Spirou et Fantasio', '31', 'La boîte noire', 'Cauvin, Raoul', '2800109947', '07/1983', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2785.jpg', 'Spirou et Fantasio possèdent toujours la boite noire des savants récupérée dans le précèdent tome. Toujours sur leur traces leur mystérieux ennemi se relance donc après eux, allant jusqu''à enlever Fantasio ! Spirou, n''écoutant que son courage, part une nouvelle fois à l''aventure.');
INSERT INTO public.bd VALUES (4929, 'Spirou et Fantasio', '32', 'Les faiseurs de silence', 'Cauvin, Raoul', '2800110236', '01/1984', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2786.jpg', NULL);
INSERT INTO public.bd VALUES (4930, 'Spirou et Fantasio', '33', 'Virus', 'Tome', '2800110368', '07/1984', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_37042.jpg', NULL);
INSERT INTO public.bd VALUES (4931, 'Spirou et Fantasio', '34', 'Aventure en Australie', 'Tome', '2800110783', '01/1985', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2788.jpg', NULL);
INSERT INTO public.bd VALUES (4932, 'Spirou et Fantasio', '35', 'Qui arrêtera Cyanure ?', 'Tome', '2800111364', '07/1985', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2789.jpg', NULL);
INSERT INTO public.bd VALUES (4933, 'Spirou et Fantasio', '36', 'L''horloger de la comète', 'Tome', '2800112646', '01/1986', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_42349.jpg', 'Venu à la demeure du comte de Champignac pour la garder, en l’absence de ce dernier, Spirou et Fantasio décident d’assister au passage d’une comète à la périphérie de la Terre. Fantasio, maladroit comme pas deux, renverse un flacon de chloroforme et voilà nos deux amis, ainsi que Spip, plongés bien malgré eux dans les bras de Morphée. A leur réveil, un très étrange appareil s’écrase dans le jardin, et quelle n’est pas leur surprise lorsqu’ils découvrent qui le conduit…');
INSERT INTO public.bd VALUES (4934, 'Spirou et Fantasio', '37', 'Le réveil du Z', 'Tome', '2800113863', '09/1986', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2791.jpg', NULL);
INSERT INTO public.bd VALUES (4935, 'Spirou et Fantasio', '38', 'La jeunesse de Spirou', 'Tome', '2800114207', '01/1987', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_42795.jpg', NULL);
INSERT INTO public.bd VALUES (4936, 'Spirou et Fantasio', '39', 'Spirou à New York', 'Tome', '2800115181', '09/1987', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_19531.jpg', NULL);
INSERT INTO public.bd VALUES (4937, 'Spirou et Fantasio', '40', 'La frousse aux trousses', 'Tome', '2800116196', '10/1988', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2794.jpg', NULL);
INSERT INTO public.bd VALUES (4938, 'Spirou et Fantasio', '41', 'La vallée des bannis', 'Tome', '2800117044', '11/1989', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2795.jpg', 'Après avoir chuté dans le ravin, Spirou, Fantasio et Spip se réveillent dans une jungle bien étrange, où la moindre créature, la plus petite plante ne semble avoir qu’une fonction : tuer l’inattentif voyageur. A peine ont-ils repris leur marche pour retrouver les vestiges de l’expédition Maginot que Fantasio se fait piquer par un moustique. Hélas ! ce moustique est la pire créature de la vallée : il inocule un virus qui rend fou furieux…');
INSERT INTO public.bd VALUES (4939, 'Spirou et Fantasio', '42', 'Spirou à Moscou', 'Tome', '2800117834', '12/1990', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2796.jpg', NULL);
INSERT INTO public.bd VALUES (4940, 'Spirou et Fantasio', '43', 'Vito la déveine', 'Tome', '2800118911', '12/1991', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2797.jpg', NULL);
INSERT INTO public.bd VALUES (4941, 'Spirou et Fantasio', '44', 'Le rayon noir', 'Tome', '2800119608', '04/1993', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2798.jpg', 'Une expérience du comte de Champignac ne tourne pas comme prévu : tous ses cobayes... changent de couleur de peau !');
INSERT INTO public.bd VALUES (4975, 'Calvin et Hobbes', '8', 'Elle est pas belle, la vie ?', 'Watterson, Bill', '2258034329', '08/1994', 61, 'https://www.bedetheque.com/media/Couvertures/Couv_2371.jpg', NULL);
INSERT INTO public.bd VALUES (4976, 'Calvin et Hobbes', '9', 'On n''arrête pas le progrès !', 'Watterson, Bill', '2258000254', '12/1994', 62, 'https://www.bedetheque.com/media/Couvertures/Couv_2376.jpg', NULL);
INSERT INTO public.bd VALUES (4942, 'Spirou et Fantasio', '45', 'Luna fatale', 'Tome', '2800121394', '09/1995', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2799.jpg', 'A New York, la guerre des gangs fait rage entre Chinatown et Little Italy!Un à un, tous les hommes de Vito-la-Déveine tombent amoureux de la même femme, Soupir-de-Jade, une redoutable ennemie. Et pour ses beaux yeux de braise, ils vont jusqu''à s''entretuer! Afin d''enrayer cette épidémie amoureuse, il faut un célibataire endurci, un homme droit et juste... quelqu''un comme Spirou! Afin de le convaincre d''accepter cette périlleuse mission, Vito n''hésite pas à recruter quatre demoiselles aussi belles que dangereuses, menées par la ravissante Luna, sa...');
INSERT INTO public.bd VALUES (4943, 'Spirou et Fantasio', '46', 'Machine qui rêve', 'Tome', '280012394X', '11/1998', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_2800.jpg', 'Spirou, seul contre tous.Spirou, ennemi public n° 1. Spirou, rejeté par tous ses amis. Spirou, poursuivi de toutes parts.Spirou, recherché par toutes les polices. Spirou, l''homme à abattre. À vue. Spirou apparaît aux yeux du monde comme le plus dangereux des malfaiteurs. Pourquoi Spirou est-il poursuivi sans relâche? Pourquoi Spirou ne peut-il compter que sur lui-même pour sauver sa peau? De quoi Spirou est-il coupable? Pourquoi Spirou fait-il peur? Ni un rêve, ni un cauchemar, ni un film, la nouvelle histoire de Spirou est bien réelle. Et c''est...');
INSERT INTO public.bd VALUES (4944, 'Spirou et Fantasio', '47', 'Paris-sous-Seine', 'Morvan, Jean-David', '2800129476', '09/2004', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_38349.jpg', 'Alors qu''il prépare une nouvelle invention sur la dilatation de l''eau, afin d''irriguer les déserts, le Comte de Champignac est enlevé par de mystérieux robots. Peu après, Paris est englouti par un incroybale raz-de marée. Déjouant les barrages policiers, Spirou et Fantasio s''introduisent dans la capitale sinistrée et bientôt désertée, à la recherche de leur ami. Mais le Comte est tombé dans les griffes d''ennemi plus iplaquable que tous ceux affrontés par le passé. Un ennemi qui le connait trés bien , trop bien...');
INSERT INTO public.bd VALUES (4945, 'Spirou et Fantasio', '48', 'L''Homme qui ne voulait pas mourir', 'Morvan, Jean-David', '2800136944', '09/2005', 54, 'https://www.bedetheque.com/media/Couvertures/Couv_50163.jpg', 'Une bâtisse délabrée, perdue en pleine campagne. Déserteoe Pas tant que ça! Trois personnages vont s''y retrouver pour une réunion de famille particulièrement orageuse. Il y a d''abord LE VIEUX : l''oncle TANZAFIO, propriétaire des lieux, que tout le monde croyait mort depuis une éternité. Or ce vieil aventurier à l''âge plus que canonique a fait une découverte fantastique : il a trouvé, lors d''un voyage au Guaracha, une source de jouvence qui lui assure ni plus ni moins que la vie éternelle! Et il revient chez lui justement pour récupérer le plan...');
INSERT INTO public.bd VALUES (4946, 'Spirou et Fantasio', '49', 'Spirou et Fantasio à Tokyo', 'Morvan, Jean-David', '2800138440', '09/2006', 62, 'https://www.bedetheque.com/media/Couvertures/Couv_57818.jpg', 'Nous retrouvons Spirou, Fantasio et Spip à Edo, capitale du Pays du Soleil Levant, de 1603 à 1864. Paradoxe temporel ? Voyage dans le temps ? Rien de tout ça : nos trois amis sont tout simplement invités à la prestigieuse inauguration de "Edo-resort", un gigantesque parc d''attractions qui reconstitue très fidèlement la vie du Japon médiéval. Mais Spirou et ses compagnons ne sont pas là pour le plaisir. Ils sont venus en Extrême-Orient à la demande de leur ami magicien, Itoh Kata, qui leur a confié une mission spéciale : récupérer deux enfants aux...');
INSERT INTO public.bd VALUES (4947, 'Spirou et Fantasio', '50', 'Aux sources du Z', 'Morvan, Jean-David', '9782800140506', '11/2008', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_79695.jpg', 'Entraîné par Zorglub et Champignac, Spirou va tenter de remonter le cours du passé, afin de sauver l''amie des deux savants, Miss Flanner. De l''Afrique à la Palombie, Spirou va revivre le fil de ses aventures pour parvenir enfin à l''époque où Zorglub, Champignac et Miss Flanner étaient alors trois étudiants scientifiques sacrément doués mais terriblement dangereux. Il devra empêcher le pire de se produire dans le passé afin de sauver, aujourd''hui, celle qui n''a cessé de diviser les deux hommes, chacun réclamant les faveurs de la belle et jeune scientifique....');
INSERT INTO public.bd VALUES (4948, 'Spirou et Fantasio', '51', 'Alerte aux Zorkons', 'Vehlmann, Fabien', '9782800144818', '09/2010 (Parution le 03/09/2010)', 54, 'https://www.bedetheque.com/media/Couvertures/Couv_114380.jpg', 'Le célèbre savant Pacôme de Champignac coule des jours paisibles dans son château. Alors qu’il vaque à ses occupations expérimentales, notre ami mycologue reçoit la visite intrigante d’un Zorglub plus altier que jamais... Mais que penser du comportement du Comte qui confond son plus fameux rival avec un vulgaire plombier ? Zorglub aurait-il minutieusement prévu tout ce qui est en train d’arriver ?');
INSERT INTO public.bd VALUES (4949, 'Spirou et Fantasio', '52', 'La face cachée du Z', 'Vehlmann, Fabien', '9782800150642', '10/2011 (Parution le 21/10/2011)', 47, 'https://www.bedetheque.com/media/Couvertures/Couv_139206.jpg', 'Un matin (ou peut-être une nuit) Spirou, Fantasio et Champignac (et Spip) se réveillent... sur la Lune ! Profitant de leur sommeil, Zorglub les a emmenés là-bas afin de leur dévoiler ses nouveaux projets : construire le laboratoire le plus perfectionné du monde ! Et profiter de l''environnement lunaire pour y mener des expériences impossibles à tenter sur Terre. Leur colère et leur stupeur passées, nos amis sont rapidement impressionnés et séduits par l''oeuvre de leur plus fidèle ennemi. Mais il y a une face cachée à la noblesse de ces projets :...');
INSERT INTO public.bd VALUES (4950, 'Spirou et Fantasio', '53', 'Dans les griffes de la Vipère', 'Vehlmann, Fabien', '9782800154343', '01/2013 (Parution le 11/01/2013)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_176024.jpg', 'Catastrophe : Le journal de Spirou est menacé de faillite suite à un procès retentissant ! Le rédacteur en chef, Fantasio, ne veut pas laisser mourir son magazine. Mais il n''est pas le seul : Gil Coeur-Vaillant, le célèbre détective-explorateur et admirateur des exploits de Spirou, va venir à sa rescousse. Il va trouver un fonds d''investissement, la VIPER, qui va renflouer le journal. Ouf ! Le célèbre hebdomadaire est sauvé ! Pas tout à fait, car Spirou est en fait tombé dans les griffes d''un milliardaire sans scrupules. Prisonnier dans une villa...');
INSERT INTO public.bd VALUES (4951, 'Spirou et Fantasio', '54', 'Le Groom de Sniper Alley', 'Vehlmann, Fabien', '9782800160290', '11/2014 (Parution le 21/11/2014)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_226930.jpg', 'Une terrible guerre civile prend fin en Aswana, avec l''élimination physique du dictateur local. Le monde entier se réjouit. Et spécialement don Contralto, un mafieux condamné à 634 années de prison (suite à un regrettable malentendu, bien entendu). Pour occuper ses longues journées dans une prison de haute sécurité de New York, ce détenu modèle s''est trouvé une nouvelle passion : l''archéologie. C''est ainsi que, rien qu''en dévorant des livres, en surfant sur le Net et en examinant des cartes, il a réussi à retrouver pas mal de trésors antiques....');
INSERT INTO public.bd VALUES (4977, 'Calvin et Hobbes', '10', 'Tous aux abris !', 'Watterson, Bill', '225803941X', '04/1995', 62, 'https://www.bedetheque.com/media/Couvertures/Couv_2377.jpg', NULL);
INSERT INTO public.bd VALUES (4978, 'Calvin et Hobbes', '11', 'Chou bi dou wouah !', 'Watterson, Bill', '2258039428', '12/1995', 62, 'https://www.bedetheque.com/media/Couvertures/Couv_2378.jpg', NULL);
INSERT INTO public.bd VALUES (4979, 'Calvin et Hobbes', '12', 'Quelque chose bave sous le lit !', 'Watterson, Bill', '2258039452', '03/1996', 62, 'https://www.bedetheque.com/media/Couvertures/Couv_2379.jpg', NULL);
INSERT INTO public.bd VALUES (4952, 'Spirou et Fantasio', '55', 'La colère du Marsupilami', 'Vehlmann, Fabien', '9782800163673', '03/2016 (Parution le 04/03/2016)', 54, 'https://www.bedetheque.com/media/Couvertures/Couv_271861.jpg', 'Spirou doit se rendre à l''évidence devant les photos du Marsupilami offertes par Don Contralto (à la fin du tome 54) : il n''a aucun souvenir de cette aventure. Et Fantasio pas plus que lui. Quant au comte de Champignac, il entre dans de terribles colères dès qu''on évoque le petit animal à queue préhensile et contondante. Tout ça ne peut avoir qu''une explication : ils ont été zorglondisés pour leur faire oublier qu''ils ont été un jour les amis du Marsupilami. Après une courte enquête, Spirou et Fantasio retrouvent Zantafio, exilé au Canada, et lui...');
INSERT INTO public.bd VALUES (4953, 'Spirou et Fantasio', '56', 'La mort de Spirou', 'Guerrive, Sophie', '9782800173832', '08/2022 (Parution le 26/08/2022)', 57, 'https://www.bedetheque.com/media/Couvertures/Couv_452093.jpg', 'A l''approche du centenaire des Editions Dupuis, Spirou et Fantasio ont la mauvaise idée de disparaître de la surface de la Terre ! Peut-être justement parce qu''ils sont en dessous. Dans la cité sous-marine de Korallion, qu''ils avaient déjà visitée lors d''une précédente et mythique aventure de Franquin : Spirou et les Hommes-Bulles... Merveilleuse passerelle entre le glorieux passé de Spirou et les codes narratifs de l''aventure contemporaine, La Mort de Spirou lui offre une renaissance enivrante, entre grande aventure et réflexion sur notre société.Aux...');
INSERT INTO public.bd VALUES (4954, 'Spirou et Fantasio', '57', 'La mémoire du futur', 'Guerrive, Sophie', '9782808503280', '10/2024 (Parution le 18/10/2024)', 56, 'https://www.bedetheque.com/media/Couvertures/Couv_505775.jpg', 'Alors qu''on pensait Spirou perdu à tout jamais, enseveli sous les eaux, le groom se réveille en 1958, au beau milieu de Spirou et les hommes-bulles, après avoir été assommé dans le salon d''Herbert D''Oups. Dès lors, toutes les aventures vécues depuis sont des chimères et la cité sous-marine de Korallion-la-Ville-Bulle n''a jamais existé. Le voilà de retour dans son âge d''or, l''année de l''Exposition universelle de Bruxelles. On y présente le futur tel qu''on l''imagine à l''époque... Mais le futur, Spirou sait qu''il ne ressemblera pas à cela car lui,...');
INSERT INTO public.bd VALUES (4955, 'Spirou et Fantasio', 'HCourte1', 'Bravo les Brothers', 'Franquin, André', '9782800151687', '04/2012 (Parution le 06/04/2012)', 88, 'https://www.bedetheque.com/media/Couvertures/Couv_160533.jpg', 'Qu''offrir à Fantasio pour son anniversaire ? Gaston a trouvé une réponse à la hauteur de son légendaire talent pour créer des catastrophes : il lui a dégoté un trio de singes savants ! De quoi rendre mémorable cette rencontre rare entre l''univers de Gaston et celui de Spirou et Fantasio. Pour la première fois, "Bravo les Brothers" bénéficie d''une édition digne de "l''histoire favorite d''André Franquin". Une version recolorisée, augmentée de dessins inédits, commentée par José-Louis Bocquet et Sergio Honorez, avec la participation d''Isabelle Franquin,...');
INSERT INTO public.bd VALUES (4956, 'Spirou et Fantasio', 'HCourte2', 'La Foire aux gangsters', 'Franquin, André', '9782800155715', '11/2012', 48, 'https://www.bedetheque.com/media/Couvertures/Couv_251313.jpg', NULL);
INSERT INTO public.bd VALUES (4957, 'Spirou et Fantasio', 'HCourte3', 'La Peur au bout du fil', 'Greg (1)', '9782800148236', '06/2013 (Parution le 21/06/2013)', 64, 'https://www.bedetheque.com/media/Couvertures/Couv_191661.jpg', 'Le comte de Champignac a enfin réussi à extraire le résidu toxique de son fameux élixir X4, celui qui décuple les facultés intellectuelles de celui auquel on l''administre. Très enthousiaste, il appelle dans la minute son ami Spirou pour lui faire part de la nouvelle. Tout à sa conversation, il ne prend pas garde au récipient dont il s''empare, convaincu qu''il s''agit de sa tasse de café... et le boit, avant de se rendre compte, affolé, qu''il vient d''avaler le dangereux liquide. Les effets ne se font pas attendre et se révèlent particulièrement dévastateurs...');
INSERT INTO public.bd VALUES (4958, 'Spirou et Fantasio', 'HCourte4', 'Vacances sans histoires', 'Franquin, André', '9782800161624', '04/2014 (Parution le 04/04/2014)', 82, 'https://www.bedetheque.com/media/Couvertures/Couv_213515.jpg', 'Enfin les vacances ! Descendus sur la côte pour savourer un repos bien mérité, Spirou et Fantasio laissent leur Turbotraction garée devant le casino. Sans se douter que le magnat du pétrole Ibn-Mah-Zoud, non seulement daltonien mais aussi véritable danger public au volant, va prendre leur précieuse auto pour la sienne... Attachez vos ceintures !');
INSERT INTO public.bd VALUES (4959, 'Spirou et Fantasio', 'HCourte5', 'La Quick Super', 'Franquin, André', '9782800162577', '10/2014 (Parution le 03/10/2014)', 68, 'https://www.bedetheque.com/media/Couvertures/Couv_227076.jpg', 'Publié dans Le Journal de Spirou en 1955, ce récit de 18 pages des aventures de Spirou et Fantasio marque une nouvelle fois la rupture entre deux mondes, puisque Franquin y met en scène quelques personnages pas très reluisants croisés trois ans plus tôt dans "Les Voleurs du Marsupilami", et qu''il y décrit les chromes rutilants et modernes d''une voiture "paquebot" débarquée des USA sur notre continent : la Quick Super, symbole de progrès à l''aube des années cinquante et soixante. Une Quick Super prêtée à Spirou et Fantasio pour les besoins de la...');
INSERT INTO public.bd VALUES (4960, 'Spirou et Fantasio', 'HCourte6', 'Spirou et les petits formats', 'Franquin, André', '9782800154114', '11/2021 (Parution le 11/11/2021)', 110, 'https://www.bedetheque.com/media/Couvertures/Couv_436469.jpg', NULL);
INSERT INTO public.bd VALUES (4961, 'Spirou et Fantasio', 'HS01', 'L''héritage', 'Franquin, André', '2800104759', '01/1976', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_2753.jpg', NULL);
INSERT INTO public.bd VALUES (4962, 'Spirou et Fantasio', 'HS02', 'Radar le robot', 'Franquin, André', '2800105089', '01/1976', 41, 'https://www.bedetheque.com/media/Couvertures/spirou02hs.JPG', NULL);
INSERT INTO public.bd VALUES (4963, 'Spirou et Fantasio', 'HS03', 'La Voix sans maître (et 5 autres aventures)', '<Collectif>', '2800134550', '09/2003', 45, 'https://www.bedetheque.com/media/Couvertures/Couv_28782.jpg', NULL);
INSERT INTO public.bd VALUES (4964, 'Spirou et Fantasio', 'HS04', 'Fantasio et le fantôme (et 4 autres aventures)', '<Collectif>', '2800134569', '10/2003', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_29760.jpg', NULL);
INSERT INTO public.bd VALUES (4965, 'Spirou et Fantasio', 'HS05', 'Les Folles Aventures de Spirou', 'Vehlmann, Fabien', '9782800169583', '10/2017 (Parution le 06/10/2017)', 46, 'https://www.bedetheque.com/media/Couvertures/Couv_308316.jpg', 'Les aventures de Spirou et Fantasio ne se déclinent pas que sous la forme d''histoires longues. La série compte aussi des histoires courtes tout à fait réjouissantes où Yoann et Vehlmann donnent libre cours à leur imagination débridée. Les voici enfin réunies dans un album avec un bonus : "Le Spip magazine". Dans "Spirou à la Rédac", notre groom favori plonge au coeur des archives du Journal Spirou et découvre, dans les caves abandonnées de l''hebdomadaire, un ancien combattant de la guerre Tintin-Spirou qui ignore que celle-ci est finie depuis des...');
INSERT INTO public.bd VALUES (4966, 'Spirou et Fantasio', 'PRE1', 'Spirou et l''Aventure', 'Jijé', '2733676628', '01/1948', 127, 'https://www.bedetheque.com/media/Couvertures/spirouhs01_61714.jpg', NULL);
INSERT INTO public.bd VALUES (4967, 'Spirou et Fantasio', 'PRE2', 'Spirou et Fantasio', 'Franquin, André', '270191938X', '01/1948', 104, 'https://www.bedetheque.com/media/Couvertures/spiroudivers1948_28583.jpg', '- Fantasio et son tank');
INSERT INTO public.bd VALUES (4968, 'Calvin et Hobbes', '1', 'Adieu, monde cruel !', 'Watterson, Bill', '2258034310', '04/1991', 61, 'https://www.bedetheque.com/media/Couvertures/Couv_40205.jpg', NULL);
