INSERT INTO public.bd VALUES (4984, 'Calvin et Hobbes', '17', 'La flemme du dimanche soir', 'Watterson, Bill', '2258047781', '01/1999', 122, 'https://www.bedetheque.com/media/Couvertures/Couv_2384.jpg', NULL);
INSERT INTO public.bd VALUES (4985, 'Calvin et Hobbes', '18', 'Gare au psychopathe à rayures !', 'Watterson, Bill', '225805110X', '05/1999', 62, 'https://www.bedetheque.com/media/Couvertures/Couv_2385.jpg', NULL);
