INSERT INTO public.bd VALUES (4990, 'Calvin et Hobbes', '23', 'Y a des jours comme ça !', 'Watterson, Bill', '2258058325', '01/2004', 60, 'https://www.bedetheque.com/media/Couvertures/Couv_32151.jpg', NULL);
INSERT INTO public.bd VALUES (4991, 'Calvin et Hobbes', '24', 'Cette fois, c''est fini !', 'Watterson, Bill', '2258062179', '01/2005', 52, 'https://www.bedetheque.com/media/Couvertures/Couv_42479.jpg', NULL);
INSERT INTO public.bd VALUES (4992, 'Calvin et Hobbes', 'Cat', 'À la recherche de Calvin et Hobbes - Catalogue de l''exposition', 'Watterson, Bill', '9782258117389', '01/2015 (Parution le 15/01/2015)', 52, 'https://www.bedetheque.com/media/Couvertures/Couv_235432.jpg', 'En exclusivité et pour la première fois en Europe, une grande expo inédite du créateur de Calvin et Hobbes se tient à Angoulême en janvier 2015. Le catalogue de l''exposition que publient les éditions Hors Collection nous permet de revisiter l''œuvre de façon originale, en suivant le guide : Bill Watterson lui-même !');
INSERT INTO public.bd VALUES (4993, 'Calvin et Hobbes', 'HS', 'Calvin et Hobbes Collector', 'Watterson, Bill', '9782258116689', '01/2015 (Parution le 15/01/2015)', 208, 'https://www.bedetheque.com/media/Couvertures/Couv_235951.jpg', NULL);
INSERT INTO public.bd VALUES (4994, 'Calvin et Hobbes', 'INT en Cof', 'Intégrale', 'Watterson, Bill', '9782258106116', '11/2013 (Parution le 14/11/2013)', 1456, 'https://www.bedetheque.com/media/Couvertures/Couv_202372.jpg', 'Enfin l''édition INTÉGRALE de toute la série Calvin et Hobbes, dans le format original américain à l''italienne, dans une somptueuse présentation de luxe incluant de nombreux dessins inédits de Watterson, une interview exclusive, et tous les strips en couleur au fil de leur parution. Un événement pour le Neuvième Art !');
INSERT INTO public.bd VALUES (4995, 'Calvin et Hobbes', 'INT01', 'Intégrale 1', 'Watterson, Bill', '2258069963', '01/2006', 124, 'https://www.bedetheque.com/media/Couvertures/CalvinEtHobbes1int_13012006.jpg', NULL);
