INSERT INTO public.bd VALUES (5024, 'Boule et Bill', '17', 'Tu te rappelles, Bill ?', 'Roba, Jean', '2800106891', '04/1980', 44, 'https://www.bedetheque.com/media/Couvertures/Boule_et_Bill_17_5897.jpg', NULL);
INSERT INTO public.bd VALUES (5025, 'Boule et Bill', '18', 'Bill est maboul', 'Roba, Jean', '280010726X', '10/1980', 44, 'https://www.bedetheque.com/media/Couvertures/Boule_et_Bill_18_122.jpg', NULL);
INSERT INTO public.bd VALUES (5026, 'Boule et Bill', '19', 'Boule et Bill globe trotters', 'Roba, Jean', '2800109203', '01/1982', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_3454.jpg', 'Bill accueille Boule tout excité après les cours. Mais qu''à donc notre cocker préféré? La boîte aux lettres? Mais que peut-il y avoir de si important... Une lettre pour Boule!! Ils ont remporté le concours du meilleur ami! Leur prix : un voyage autour du monde... le surlendemain!! Branle-bas de combat! Arrive le jour J, et personne n''est prêt, évidemment. Heureusement, John-Cadre D''Hinnamich, l''accompagnateur de la société Tour-Lourou, veille...');
INSERT INTO public.bd VALUES (5027, 'Boule et Bill', '20', 'Strip-Cocker', 'Roba, Jean', '2800110279', '04/1984', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_5898.jpg', NULL);
INSERT INTO public.bd VALUES (5028, 'Boule et Bill', '21', 'Billets de Bill', 'Roba, Jean', '2800115068', '05/1987', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_5899.jpg', NULL);
INSERT INTO public.bd VALUES (5029, 'Boule et Bill', '22', '22 ! v''la Boule & Bill !', 'Roba, Jean', '2871290482', '11/1988', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_5900.jpg', NULL);
INSERT INTO public.bd VALUES (5030, 'Boule et Bill', '23', '''Faut rigoler!', 'Roba, Jean', '2871290636', '03/1991', 44, 'https://www.bedetheque.com/media/Couvertures/Couv_5901.jpg', NULL);
